class TokenBucket:
    """Token bucket rate limiter."""

    def __init__(self, capacity: int, refill_rate: float):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        if refill_rate < 0:
            raise ValueError("refill_rate must be non-negative")
        self.capacity = capacity
        self.refill_rate = refill_rate
        self._level = float(capacity)
        self._last_time = None

    def _refill(self, current_time: float) -> None:
        if self._last_time is None:
            self._last_time = current_time
            return
        elapsed = current_time - self._last_time
        if elapsed > 0:
            self._level = min(self.capacity, self._level + elapsed * self.refill_rate)
            self._last_time = current_time

    def consume(self, tokens: int, current_time: float) -> bool:
        if tokens < 0:
            raise ValueError("tokens must be non-negative")
        self._refill(current_time)
        if tokens <= self._level:
            self._level -= tokens
            return True
        return False

    def available(self, current_time: float) -> float:
        self._refill(current_time)
        return self._level


class RateLimiter:
    """Applies one TokenBucket per client key."""

    def __init__(self, capacity: int, refill_rate: float):
        self._settings = (capacity, refill_rate)
        self._buckets = {}
        self._rejections = 0

    def _bucket_for(self, key: str) -> TokenBucket:
        bucket = self._buckets.get(key)
        if bucket is None:
            bucket = TokenBucket(*self._settings)
            self._buckets[key] = bucket
        return bucket

    def allow(self, key: str, tokens: int, current_time: float) -> bool:
        granted = self._bucket_for(key).consume(tokens, current_time)
        if not granted:
            self._rejections += 1
        return granted

    def report(self, current_time: float) -> str:
        lines = ["rejected requests: %d" % self._rejections]
        for key in sorted(self._buckets):
            left = self._buckets[key].available(current_time)
            lines.append("%-8s %5.2f/%d tokens left" % (key, left, self._settings[0]))
        return "\n".join(lines)


def main() -> None:
    requests = [
        ("alice", 10, 0.0),
        ("alice", 1, 0.5),
        ("alice", 1, 1.0),
        ("bob", 4, 1.0),
        ("bob", 7, 1.5),
        ("bob", 7, 4.0),
    ]
    limiter = RateLimiter(capacity=10, refill_rate=1.0)
    for key, tokens, when in requests:
        verdict = "OK " if limiter.allow(key, tokens, when) else "DENY"
        print("t=%.1f %-6s wants %2d -> %s" % (when, key, tokens, verdict))
    print(limiter.report(4.0))


if __name__ == "__main__":
    main()

