class GapBuffer:
    """Text buffer split into the part before the cursor and the part after it."""

    def __init__(self):
        self._left = []
        self._right = []

    def insert(self, text: str):
        self._validate_text(text)
        self._left.extend(text)

    def delete(self, count: int):
        removed = self._clamp(count, len(self._left))
        if removed:
            del self._left[len(self._left) - removed:]

    def move_cursor_left(self, count: int):
        moved = self._clamp(count, len(self._left))
        if moved:
            cut = len(self._left) - moved
            chunk = self._left[cut:]
            del self._left[cut:]
            self._right[:0] = chunk

    def move_cursor_right(self, count: int):
        moved = self._clamp(count, len(self._right))
        if moved:
            self._left.extend(self._right[:moved])
            del self._right[:moved]

    def get_text(self) -> str:
        return "".join(self._left) + "".join(self._right)

    def cursor_position(self) -> int:
        return len(self._left)

    def render(self) -> str:
        return "".join(self._left) + "|" + "".join(self._right)

    def _validate_text(self, text):
        if not isinstance(text, str):
            raise TypeError("insert() expects a string")

    def _clamp(self, count, limit):
        if not isinstance(count, int):
            raise TypeError("count must be an integer")
        return max(0, min(count, limit))


class CommandRunner:
    """Applies simple editor commands such as 'insert abc' or 'left 2'."""

    def __init__(self):
        self._buffer = GapBuffer()
        self._actions = {
            "insert": self._buffer.insert,
            "delete": self._as_count(self._buffer.delete),
            "left": self._as_count(self._buffer.move_cursor_left),
            "right": self._as_count(self._buffer.move_cursor_right),
        }

    def run(self, line: str):
        name, arg = self._parse(line)
        action = self._actions.get(name)
        if action is None:
            raise ValueError("unknown command: " + name)
        action(arg)

    def run_all(self, lines):
        for line in lines:
            self.run(line)
        return self._buffer.get_text()

    def status(self) -> str:
        return "{0}  (cursor at {1})".format(self._buffer.render(),
                                             self._buffer.cursor_position())

    def _parse(self, line):
        parts = line.split(None, 1)
        if not parts:
            raise ValueError("empty command")
        return parts[0].lower(), parts[1] if len(parts) > 1 else ""

    def _as_count(self, method):
        return lambda arg: method(int(arg))


def main():
    script = ["insert hello", "left 2", "insert X", "right 1", "delete 1"]
    runner = CommandRunner()
    for command in script:
        runner.run(command)
        print("{0:<14} -> {1}".format(command, runner.status()))
    print("final text:", runner.run_all([]))


if __name__ == "__main__":
    main()

