import math
from collections import deque


class MovingStats:
    """Streaming mean/variance over a sliding window of fixed size."""

    def __init__(self, window_size: int):
        if not isinstance(window_size, int) or isinstance(window_size, bool):
            raise TypeError("window_size must be an int")
        if window_size < 1:
            raise ValueError("window_size must be at least 1")
        self._capacity = window_size
        self._values = deque()
        self._sum = 0.0
        self._sum_sq = 0.0

    def _coerce(self, value) -> float:
        try:
            number = float(value)
        except (TypeError, ValueError):
            raise TypeError("value must be a real number") from None
        if math.isnan(number) or math.isinf(number):
            raise ValueError("value must be finite")
        return number

    def _evict_oldest(self) -> None:
        oldest = self._values.popleft()
        self._sum -= oldest
        self._sum_sq -= oldest * oldest

    def add(self, value: float) -> None:
        number = self._coerce(value)
        if len(self._values) == self._capacity:
            self._evict_oldest()
        self._values.append(number)
        self._sum += number
        self._sum_sq += number * number

    def count(self) -> int:
        return len(self._values)

    def get_mean(self) -> float:
        n = self.count()
        if n == 0:
            return 0.0
        return self._sum / n

    def get_variance(self) -> float:
        n = self.count()
        if n == 0:
            return 0.0
        mean = self._sum / n
        return max(self._sum_sq / n - mean * mean, 0.0)

    def get_stddev(self) -> float:
        return math.sqrt(self.get_variance())


class StatsReporter:
    """Feeds a series through MovingStats and formats a per-step report."""

    def __init__(self, window_size: int):
        self._stats = MovingStats(window_size)
        self._rows = []

    def _record(self, value: float) -> None:
        self._stats.add(value)
        self._rows.append((value, self._stats.get_mean(),
                           self._stats.get_variance(),
                           self._stats.get_stddev()))

    def feed(self, series) -> "StatsReporter":
        for value in series:
            self._record(value)
        return self

    def render(self) -> str:
        header = f"{'value':>8} {'mean':>8} {'var':>8} {'std':>8}"
        lines = [header, "-" * len(header)]
        for value, mean, var, std in self._rows:
            lines.append(f"{value:8.3f} {mean:8.3f} {var:8.3f} {std:8.3f}")
        return "\n".join(lines)


def main() -> None:
    series = [2.0, 4.0, 9.0, 1.0, 5.0, 5.0, 7.0]
    print(StatsReporter(3).feed(series).render())


if __name__ == "__main__":
    main()

