class RingBuffer:
    """Fixed-size circular queue backed by a pre-allocated list."""

    def __init__(self, capacity: int):
        self._validate_capacity(capacity)
        self.capacity = capacity
        self._data = [None] * capacity
        self._head = 0
        self._tail = 0
        self._count = 0

    @staticmethod
    def _validate_capacity(capacity: int) -> None:
        if not isinstance(capacity, int) or isinstance(capacity, bool):
            raise TypeError("capacity must be an int")
        if capacity <= 0:
            raise ValueError("capacity must be positive")

    def _advance(self, index: int) -> int:
        return (index + 1) % self.capacity

    def enqueue(self, item: int) -> bool:
        if self.is_full():
            return False
        self._data[self._tail] = item
        self._tail = self._advance(self._tail)
        self._count += 1
        return True

    def dequeue(self) -> int:
        if self.is_empty():
            raise ValueError("dequeue from an empty buffer")
        item = self._data[self._head]
        self._data[self._head] = None
        self._head = self._advance(self._head)
        self._count -= 1
        return item

    def is_empty(self) -> bool:
        return self._count == 0

    def is_full(self) -> bool:
        return self._count == self.capacity

    def __len__(self) -> int:
        return self._count

    def _snapshot(self) -> list:
        index = self._head
        items = []
        for _position in range(self._count):
            items.append(self._data[index])
            index = self._advance(index)
        return items

    def to_list(self) -> list:
        return self._snapshot()

    def __repr__(self) -> str:
        return "RingBuffer(capacity={}, items={})".format(self.capacity, self._snapshot())


def replay(stream, capacity: int) -> list:
    """Push a stream through a buffer of the given size, draining when full."""
    buffer = RingBuffer(capacity)
    drained = []
    for item in stream:
        if not buffer.enqueue(item):
            drained.append(buffer.dequeue())
            buffer.enqueue(item)
    while not buffer.is_empty():
        drained.append(buffer.dequeue())
    return drained


def main() -> None:
    buffer = RingBuffer(2)
    print(buffer.enqueue(1), buffer.enqueue(2))
    print(buffer.enqueue(3))
    print(buffer.dequeue())
    print(buffer)
    print(replay(range(1, 8), 3))
    try:
        RingBuffer(1).dequeue()
    except ValueError as exc:
        print("error:", exc)


if __name__ == "__main__":
    main()

