class TextEditor:
    """Mutable text buffer with unlimited undo/redo history."""

    def __init__(self):
        self._buffer = ""
        self._undo_stack = []
        self._redo_stack = []

    def _commit(self, new_text: str) -> None:
        """Record the current text as an undo point and move to new_text."""
        self._undo_stack.append(self._buffer)
        self._buffer = new_text
        self._redo_stack.clear()

    @staticmethod
    def _normalize_count(count: int) -> int:
        if isinstance(count, bool) or not isinstance(count, int):
            raise TypeError("count must be an integer")
        if count < 0:
            raise ValueError("count must not be negative")
        return count

    def type_text(self, text: str) -> None:
        if not isinstance(text, str):
            raise TypeError("text must be a string")
        self._commit(self._buffer + text)

    def backspace(self, count: int) -> None:
        kept = len(self._buffer) - self._normalize_count(count)
        self._commit(self._buffer[:kept] if kept > 0 else "")

    def undo(self) -> None:
        if self._undo_stack:
            self._redo_stack.append(self._buffer)
            self._buffer = self._undo_stack.pop()

    def redo(self) -> None:
        if self._redo_stack:
            self._undo_stack.append(self._buffer)
            self._buffer = self._redo_stack.pop()

    def read(self) -> str:
        return self._buffer

    def _apply_command(self, command: str) -> None:
        parts = command.split()
        if not parts:
            raise ValueError("empty command")
        op, args = parts[0].lower(), parts[1:]
        if op == "type":
            self.type_text(" ".join(args))
        elif op == "back":
            self.backspace(int(args[0]))
        elif op == "undo":
            self.undo()
        elif op == "redo":
            self.redo()
        else:
            raise ValueError("unknown command: " + op)

    def run_script(self, commands) -> str:
        for command in commands:
            self._apply_command(command)
        return self.read()

    def describe(self) -> str:
        return "text={0!r} undo={1} redo={2}".format(
            self._buffer, len(self._undo_stack), len(self._redo_stack)
        )


def main() -> None:
    editor = TextEditor()
    editor.type_text("abc")
    editor.undo()
    print("after type+undo:", repr(editor.read()), "|", editor.describe())
    editor.redo()
    print("after redo:", repr(editor.read()), "|", editor.describe())
    script = ["type hello world", "back 6", "type there", "undo", "undo", "redo"]
    print("script result:", repr(editor.run_script(script)))
    print("final state:", editor.describe())


if __name__ == "__main__":
    main()

