        self.undo_stack.append(self.buffer)
        self.buffer = new_text
        self.redo_stack.clear()

    @staticmethod
    def normalize_count(count: int) -> int:
        if isinstance(count, bool) or not isinstance(count, int):
            raise TypeError("count must be an integer")
        if count < 0:
            raise ValueError("count must not be negative")
        return count

    def type_text(self, text: str) -> None:
        if not isinstance(text, str):
            raise TypeError("text must be a string")
        self.commit(self.buffer + text)

    def backspace(self, count: int) -> None:
        kept = len(self.buffer) - self.normalize_count(count)
        self.commit(self.buffer[:kept] if kept > 0 else "")

    def undo(self) -> None:
        if self.undo_stack:
            self.redo_stack.append(self.buffer)
            self.buffer = self.undo_stack.pop()

    def redo(self) -> None:
        if self.redo_stack:
            self.undo_stack.append(self.buffer)
            self.buffer = self.redo_stack.pop()

    def read(self) -> str:
        return self.buffer

    def apply_command(self, command: str) -> None:
        parts = command.split()
        if not parts:
            raise ValueError("empty command")
        op, args = parts[0].lower(), parts[1:]
        if op == "type":
            self.type_text(" ".join(args))
        elif op == "back":
            self.backspace(int(args[0]))
        elif op == "undo":
            self.undo()
        elif op == "redo":
            self.redo()
        else:
            raise ValueError("unknown command: " + op)

    def run_script(self, commands) -> str:
        for command in commands:
            self.apply_command(command)
        return self.read()

    def describe(self) -> str:
        return "text={0!r} undo={1} redo={2}".format(
            self.buffer, len(self.undo_stack), len(self.redo_stack)
        )


def main() -> None:
    editor = TextEditor()
    editor.type_text("abc")
    editor.undo()
    print("after type+undo:", repr(editor.read()), "|", editor.describe())
    editor.redo()
    print("after redo:", repr(editor.read()), "|", editor.describe())
    script = ["type hello world", "back 6", "type there", "undo", "undo", "redo"]
    print("script result:", repr(editor.run_script(script)))
    print("final state:", editor.describe())


if __name__ == "__main__":
    main()

