class VendingMachine:
    """Inventory, pricing and sales manager for a simple coin vending machine."""

    def __init__(self):
        self._prices = {}
        self._stock = {}
        self._balance = 0
        self._revenue = 0

    def _require_positive_int(self, value, label):
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("%s must be an integer" % label)
        if value <= 0:
            raise ValueError("%s must be positive" % label)
        return value

    def _lookup_price(self, code):
        if code not in self._prices:
            raise KeyError("unknown item code: %r" % code)
        return self._prices[code]

    def _decrement_stock(self, code):
        remaining = self._stock[code]
        if remaining <= 0:
            raise ValueError("item %s is sold out" % code)
        self._stock[code] = remaining - 1

    def add_item(self, code: str, price: int, quantity: int):
        self._require_positive_int(price, "price")
        self._require_positive_int(quantity, "quantity")
        self._prices[code] = price
        self._stock[code] = self._stock.get(code, 0) + quantity

    def insert_coin(self, amount: int):
        self._require_positive_int(amount, "coin")
        self._balance += amount
        return self._balance

    def buy_item(self, code: str) -> int:
        price = self._lookup_price(code)
        if self._balance < price:
            raise ValueError("insufficient balance for %s: need %d" % (code, price))
        self._decrement_stock(code)
        self._revenue += price
        change = self._balance - price
        self._balance = 0
        return change

    def refund(self) -> int:
        returned = self._balance
        self._balance = 0
        return returned

    def _format_row(self, code):
        return "%-4s %6d %6d" % (code, self._prices[code], self._stock[code])

    def report(self) -> str:
        header = "%-4s %6s %6s" % ("CODE", "PRICE", "STOCK")
        rows = [self._format_row(code) for code in sorted(self._prices)]
        return "\n".join([header] + rows + ["revenue: %d" % self._revenue])


def main():
    machine = VendingMachine()
    machine.add_item("A", 75, 2)
    machine.add_item("B", 120, 1)
    machine.insert_coin(100)
    print("change from A:", machine.buy_item("A"))
    machine.insert_coin(50)
    try:
        machine.buy_item("B")
    except ValueError as exc:
        print("failed:", exc)
        print("refunded:", machine.refund())
    print(machine.report())


if __name__ == "__main__":
    main()

