from collections import deque


class Matchmaker:
    """Groups queuing players into two-team multiplayer sessions."""

    def __init__(self, team_size: int):
        if not isinstance(team_size, int) or team_size < 1:
            raise ValueError("team_size must be a positive integer")
        self.team_size = team_size
        self._queue = deque()
        self._matches = []

    def _validate_name(self, player_name):
        if not isinstance(player_name, str):
            raise TypeError("player_name must be a string")
        name = player_name.strip()
        if not name:
            raise ValueError("player_name must not be blank")
        return name

    def _take(self, count):
        return [self._queue.popleft() for _ in range(count)]

    def _split(self, players):
        half = self.team_size
        return (players[:half], players[half:])

    def _try_form_match(self):
        needed = self.team_size * 2
        if len(self._queue) >= needed:
            self._matches.append(self._split(self._take(needed)))

    def add_player(self, player_name: str):
        self._queue.append(self._validate_name(player_name))
        self._try_form_match()

    def get_waiting_count(self) -> int:
        return len(self._queue)

    def get_active_matches(self) -> list:
        return list(self._matches)

    def clear_queue(self):
        self._queue.clear()

    def _describe_match(self, index, match):
        team_a, team_b = match
        return "Match {}: {} vs {}".format(
            index, ", ".join(team_a), ", ".join(team_b)
        )

    def format_report(self) -> str:
        lines = ["Team size: {}".format(self.team_size)]
        for number, match in enumerate(self._matches, start=1):
            lines.append(self._describe_match(number, match))
        if not self._matches:
            lines.append("No active matches yet.")
        lines.append("Waiting players: {}".format(self.get_waiting_count()))
        return "\n".join(lines)


def main():
    maker = Matchmaker(2)
    roster = ["ana", "ben", "cleo", "dan", "eve", "finn", "gus"]
    for player in roster:
        maker.add_player(player)
    print(maker.format_report())
    print("Match tuples:", maker.get_active_matches())
    maker.clear_queue()
    print("After clearing, waiting:", maker.get_waiting_count())


if __name__ == "__main__":
    main()

