class OrderMatcher:
    """Continuous limit-order matching engine for a single asset."""

    SIDES = ("BUY", "SELL")

    def __init__(self):
        self._buys = []
        self._sells = []
        self._trades = []
        self._seq = 0

    def add_order(self, side: str, price: float, quantity: int):
        side = self._validate(side, price, quantity)
        self._seq += 1
        order = {"price": float(price), "quantity": int(quantity), "seq": self._seq}
        if side == "BUY":
            self._buys.append(order)
        else:
            self._sells.append(order)
        self._match()

    def get_trades(self) -> list:
        return [(t["price"], t["quantity"]) for t in self._trades]

    def report(self) -> str:
        if not self._trades:
            return "no trades executed"
        lines = [self._format_trade(i, t) for i, t in enumerate(self._trades, 1)]
        lines.append("total volume: %d" % self._total_volume())
        lines.append("pending: %d buy(s), %d sell(s)" % (len(self._buys), len(self._sells)))
        return "\n".join(lines)

    def _validate(self, side, price, quantity):
        normalized = str(side).strip().upper()
        if normalized not in self.SIDES:
            raise ValueError("side must be 'BUY' or 'SELL', got %r" % (side,))
        if float(price) <= 0:
            raise ValueError("price must be positive, got %r" % (price,))
        if int(quantity) <= 0:
            raise ValueError("quantity must be a positive integer, got %r" % (quantity,))
        return normalized

    def _match(self):
        while self._buys and self._sells:
            buy = self._best_buy()
            sell = self._best_sell()
            if buy["price"] < sell["price"]:
                break
            traded = min(buy["quantity"], sell["quantity"])
            buy["quantity"] -= traded
            sell["quantity"] -= traded
            self._trades.append({"price": sell["price"], "quantity": traded})
            self._drop_filled()

    def _best_buy(self):
        return min(self._buys, key=lambda o: (-o["price"], o["seq"]))

    def _best_sell(self):
        return min(self._sells, key=lambda o: (o["price"], o["seq"]))

    def _drop_filled(self):
        self._buys = [o for o in self._buys if o["quantity"] > 0]
        self._sells = [o for o in self._sells if o["quantity"] > 0]

    def _total_volume(self):
        return sum(t["quantity"] for t in self._trades)

    def _format_trade(self, index, trade):
        return "trade %d: %d @ %.2f" % (index, trade["quantity"], trade["price"])


def main():
    book = OrderMatcher()
    book.add_order("BUY", 100.0, 10)
    book.add_order("SELL", 90.0, 5)
    book.add_order("SELL", 99.5, 8)
    book.add_order("BUY", 95.0, 4)
    print(book.get_trades())
    print(book.report())


if __name__ == "__main__":
    main()

