class MultipartDownloader:
    """Assemble a file from fixed-size chunks that may arrive out of order."""

    def __init__(self, total_size: int, chunk_size: int):
        if total_size < 0:
            raise ValueError("total_size must not be negative")
        if chunk_size <= 0:
            raise ValueError("chunk_size must be positive")
        self.total_size = total_size
        self.chunk_size = chunk_size
        self._buffer = bytearray(total_size)
        self._received = set()
        self._bytes_received = 0

    def _chunk_count(self) -> int:
        return (self.total_size + self.chunk_size - 1) // self.chunk_size

    def _expected_length(self, chunk_index: int) -> int:
        offset = chunk_index * self.chunk_size
        return min(self.chunk_size, self.total_size - offset)

    def _validate(self, chunk_index: int, data: bytes) -> None:
        if not 0 <= chunk_index < self._chunk_count():
            raise IndexError("chunk index %d out of range" % chunk_index)
        expected = self._expected_length(chunk_index)
        if len(data) != expected:
            raise ValueError(
                "chunk %d: expected %d bytes, got %d" % (chunk_index, expected, len(data))
            )

    def receive_chunk(self, chunk_index: int, data: bytes) -> bool:
        self._validate(chunk_index, data)
        if chunk_index in self._received:
            return False
        offset = chunk_index * self.chunk_size
        self._buffer[offset:offset + len(data)] = data
        self._received.add(chunk_index)
        self._bytes_received += len(data)
        return True

    def missing_chunks(self):
        return [i for i in range(self._chunk_count()) if i not in self._received]

    def is_complete(self) -> bool:
        return self._bytes_received == self.total_size

    def progress(self) -> float:
        if self.total_size == 0:
            return 100.0
        return 100.0 * self._bytes_received / self.total_size

    def get_file(self) -> bytes:
        if not self.is_complete():
            raise RuntimeError("download incomplete, missing chunks: %s" % self.missing_chunks())
        return bytes(self._buffer)

    def __str__(self) -> str:
        return "MultipartDownloader(%d/%d bytes, %.1f%%)" % (
            self._bytes_received,
            self.total_size,
            self.progress(),
        )


def download(payload: bytes, chunk_size: int, order):
    downloader = MultipartDownloader(len(payload), chunk_size)
    for index in order:
        offset = index * chunk_size
        if downloader.receive_chunk(index, payload[offset:offset + chunk_size]):
            print("stored chunk %d -> %s" % (index, downloader))
        else:
            print("duplicate chunk %d ignored" % index)
    return downloader.get_file()


def main() -> None:
    payload = bytes((i * 7) % 256 for i in range(100))
    restored = download(payload, 50, [1, 1, 0])
    print("restored %d bytes, identical: %s" % (len(restored), restored == payload))


if __name__ == "__main__":
    main()

