import math


class Paginator:
    """Sequential navigator over a large in-memory dataset."""

    def __init__(self, data: list, page_size: int):
        self._validate(data, page_size)
        self.data = list(data)
        self.page_size = page_size
        self.current_page = 0
        self._cache = {}

    @staticmethod
    def _validate(data, page_size):
        if not isinstance(data, list):
            raise TypeError("data must be a list")
        if not isinstance(page_size, int) or page_size < 1:
            raise ValueError("page_size must be a positive integer")

    def _load(self, index: int) -> list:
        start = index * self.page_size
        return self.data[start:start + self.page_size]

    def get_current_page(self) -> list:
        if self.current_page not in self._cache:
            self._cache[self.current_page] = self._load(self.current_page)
        return self._cache[self.current_page]

    def next_page(self) -> bool:
        if self.current_page + 1 >= self.get_total_pages():
            return False
        self.current_page += 1
        return True

    def prev_page(self) -> bool:
        if self.current_page == 0:
            return False
        self.current_page -= 1
        return True

    def get_total_pages(self) -> int:
        return math.ceil(len(self.data) / self.page_size)

    def _describe(self) -> str:
        items = self.get_current_page()
        return "page {}/{}: {}".format(
            self.current_page + 1, self.get_total_pages(),
            ", ".join(str(item) for item in items))

    def report(self) -> str:
        """Walk forward through every page, then back to the first one."""
        lines = [self._describe()]
        while self.next_page():
            lines.append(self._describe())
        while self.prev_page():
            lines.append(self._describe())
        return "\n".join(lines)


def paginate(data: list, page_size: int) -> list:
    """Split data into pages using a Paginator, from first to last."""
    pager = Paginator(data, page_size)
    pages = [pager.get_current_page()]
    while pager.next_page():
        pages.append(pager.get_current_page())
    return pages


