class TicTacToe:
    """Tracks the state of a 3x3 tic-tac-toe game."""

    _SIZE = 3

    def __init__(self):
        self._board = [["" for _ in range(self._SIZE)] for _ in range(self._SIZE)]
        self._current_player = "X"
        self._move_count = 0

    def get_current_player(self) -> str:
        return self._current_player

    def play(self, row: int, col: int) -> str:
        self._validate_cell(row, col)
        if self._board[row][col]:
            return "Invalid"
        self._board[row][col] = self._current_player
        self._move_count += 1
        if self._is_winning_mark(self._current_player):
            return "{} wins".format(self._current_player)
        if self._move_count == 9:
            return "Draw"
        self._swap_player()
        return "Next"

    def render(self) -> str:
        rows = ["|".join(cell or " " for cell in line) for line in self._board]
        return "\n-+-+-\n".join(rows)

    def _validate_cell(self, row: int, col: int) -> None:
        for value in (row, col):
            if not isinstance(value, int) or not 0 <= value < self._SIZE:
                raise ValueError("coordinates must be integers in 0..2, got ({}, {})".format(row, col))

    def _lines(self):
        for index in range(self._SIZE):
            yield self._board[index]
            yield [self._board[r][index] for r in range(self._SIZE)]
        yield [self._board[i][i] for i in range(self._SIZE)]
        yield [self._board[i][self._SIZE - 1 - i] for i in range(self._SIZE)]

    def _is_winning_mark(self, mark: str) -> bool:
        return any(all(cell == mark for cell in line) for line in self._lines())

    def _swap_player(self) -> None:
        self._current_player = "O" if self._current_player == "X" else "X"


def run_game(moves):
    """Feed a sequence of (row, col) moves into a fresh game and report it."""
    game = TicTacToe()
    log = []
    for row, col in moves:
        player = game.get_current_player()
        result = game.play(row, col)
        log.append("{} -> ({}, {}): {}".format(player, row, col, result))
        if result.endswith("wins") or result == "Draw":
            break
    return game, log


def main():
    scenarios = {
        "X takes the top row": [(0, 0), (1, 1), (0, 1), (2, 2), (0, 2)],
        "full board draw": [(0, 0), (0, 1), (0, 2), (1, 1), (1, 0), (2, 2), (1, 2), (2, 0), (2, 1)],
    }
    for title, moves in scenarios.items():
        game, log = run_game(moves)
        print(title)
        print("\n".join(log))
        print(game.render())
        print("next to move: {}\n".format(game.get_current_player()))


if __name__ == "__main__":
    main()

