from contextlib import contextmanager


class ConnectionPool:
    """Manage a fixed set of reusable database connection identifiers."""

    def __init__(self, max_connections: int):
        self._validate_max(max_connections)
        self._max = max_connections
        self._available = {f"conn-{i}" for i in range(1, max_connections + 1)}
        self._in_use = set()

    @staticmethod
    def _validate_max(max_connections):
        if not isinstance(max_connections, int) or isinstance(max_connections, bool):
            raise TypeError("max_connections must be an int")
        if max_connections < 1:
            raise ValueError("max_connections must be at least 1")

    @staticmethod
    def _id_index(conn_id):
        return int(conn_id.split("-")[1])

    def _validate_release(self, conn_id):
        if conn_id in self._in_use:
            return
        if conn_id in self._available:
            raise ValueError(f"{conn_id} has already been released")
        raise ValueError(f"unknown connection id: {conn_id!r}")

    def acquire(self) -> str:
        if not self._available:
            raise RuntimeError("no connections available")
        conn_id = min(self._available, key=self._id_index)
        self._available.remove(conn_id)
        self._in_use.add(conn_id)
        return conn_id

    def release(self, conn_id: str):
        self._validate_release(conn_id)
        self._in_use.discard(conn_id)
        self._available.add(conn_id)

    def get_stats(self) -> dict:
        return {
            "available": len(self._available),
            "in_use": len(self._in_use),
            "max": self._max,
        }

    @contextmanager
    def lease(self):
        conn_id = self.acquire()
        try:
            yield conn_id
        finally:
            self.release(conn_id)

    def report(self) -> str:
        stats = self.get_stats()
        return "in_use={in_use}/{max} available={available}".format(**stats)


def main():
    pool = ConnectionPool(3)
    first = pool.acquire()
    second = pool.acquire()
    print("acquired:", first, second)
    print(pool.report())

    with pool.lease() as third:
        print("leased:", third)
        try:
            pool.acquire()
        except RuntimeError as exc:
            print("acquire failed:", exc)
    print("after lease:", pool.report())

    pool.release(second)
    try:
        pool.release(second)
    except ValueError as exc:
        print("release failed:", exc)
    print("final stats:", pool.get_stats())


if __name__ == "__main__":
    main()

