class LogAggregator:
    """Collect log messages and release them in fixed-size batches."""

    def __init__(self, batch_size: int):
        if not isinstance(batch_size, int) or batch_size < 1:
            raise ValueError("batch_size must be a positive integer")
        self.batch_size = batch_size
        self._pending = []
        self._counts = {}

    def _normalize_level(self, level: str) -> str:
        if not isinstance(level, str) or not level.strip():
            raise ValueError("level must be a non-empty string")
        return level.strip().upper()

    def _render(self, level: str, message: str) -> str:
        return "[{}] {}".format(level, message)

    def _release(self) -> list:
        released = self._pending
        self._pending = []
        return released

    def log(self, level: str, message: str) -> list:
        normalized = self._normalize_level(level)
        self._pending.append(self._render(normalized, message))
        self._counts[normalized] = self._counts.get(normalized, 0) + 1
        if len(self._pending) >= self.batch_size:
            return self._release()
        return []

    def force_flush(self) -> list:
        return self._release()

    def get_counts(self) -> dict:
        return dict(self._counts)

    def report(self) -> str:
        lines = ["level counts:"]
        for level in sorted(self._counts):
            lines.append("  {:<8} {}".format(level, self._counts[level]))
        lines.append("pending: {} of {}".format(len(self._pending), self.batch_size))
        return "\n".join(lines)


def run_stream(aggregator: LogAggregator, entries) -> list:
    """Feed (level, message) pairs into an aggregator, returning emitted batches."""
    batches = []
    for level, message in entries:
        batch = aggregator.log(level, message)
        if batch:
            batches.append(batch)
    tail = aggregator.force_flush()
    if tail:
        batches.append(tail)
    return batches


def main():
    entries = [
        ("info", "service starting"),
        ("debug", "config loaded"),
        ("warning", "disk usage at 81%"),
        ("info", "listening on port 8080"),
        ("error", "upstream timeout"),
        ("info", "retrying upstream"),
        ("error", "upstream refused"),
    ]
    aggregator = LogAggregator(batch_size=3)
    for index, batch in enumerate(run_stream(aggregator, entries), start=1):
        print("batch {}:".format(index))
        for line in batch:
            print("   " + line)
    print(aggregator.report())
    print("total logged:", sum(aggregator.get_counts().values()))


if __name__ == "__main__":
    main()

