def format_status(status):
    return "hunger={hunger:3d}  energy={energy:3d}  happiness={happiness:3d}".format(**status)


class VirtualPet:
    """A simulated pet whose needs evolve through a small state machine."""

    _MIN = 0
    _MAX = 100

    def __init__(self):
        self._stats = {"hunger": 50, "energy": 50, "happiness": 50}
        self._history = []
        self._actions = {
            "feed": self.feed,
            "play": self.play,
            "sleep": self.sleep,
            "tick": self.tick,
        }

    def _clamp(self, value):
        return max(self._MIN, min(self._MAX, value))

    def _apply(self, action, **deltas):
        for name, delta in deltas.items():
            self._stats[name] = self._clamp(self._stats[name] + delta)
        self._history.append((action, dict(self._stats)))

    def feed(self):
        self._apply("feed", hunger=-20, energy=5)

    def play(self):
        self._apply("play", happiness=20, hunger=10, energy=-15)

    def sleep(self):
        self._apply("sleep", energy=30, hunger=10)

    def tick(self):
        self._apply("tick", hunger=5, happiness=-5)

    def get_status(self) -> dict:
        return dict(self._stats)

    def perform(self, action):
        if action not in self._actions:
            raise ValueError("unknown action: {!r}".format(action))
        self._actions[action]()
        return self.get_status()

    def mood(self) -> str:
        if self._stats["hunger"] >= 80:
            return "starving"
        if self._stats["energy"] <= 20:
            return "exhausted"
        if self._stats["happiness"] >= 70:
            return "delighted"
        return "content"

    def report(self) -> str:
        lines = ["step  action    " + "stats"]
        for step, (action, snapshot) in enumerate(self._history, start=1):
            lines.append("{:>4}  {:<9} {}".format(step, action, format_status(snapshot)))
        lines.append("final mood: {} after {} action(s)".format(self.mood(), len(self._history)))
        return "\n".join(lines)


def main():
    pet = VirtualPet()
    print("start       " + format_status(pet.get_status()))
    for action in ["play", "play", "tick", "feed", "tick", "sleep", "feed", "play"]:
        status = pet.perform(action)
        print("{:<11} {}".format(action, format_status(status)))
    print(pet.report())


if __name__ == "__main__":
    main()

