            best_id, _, best_priority = self._tasks[best]
            if priority > best_priority or (priority == best_priority and task_id < best_id):
                best = index
        return best

    def add_task(self, name: str, priority: int):
        clean_name, clean_priority = self._validate(name, priority)
        self._tasks.append((self._take_id(), clean_name, clean_priority))

    def execute_next(self) -> str:
        index = self._best_index()
        if index is None:
            return None
        _, name, _ = self._tasks.pop(index)
        return name

    def clear(self):
        self._tasks.clear()

    def pending(self):
        return [name for _, name, _ in self._tasks]

    def __len__(self):
