class TaskQueue:
    """A priority queue of pending jobs, oldest-first on priority ties."""

    def __init__(self):
        self.tasks = []
        self.next_id = 0

    def validate(self, name, priority):
        if not isinstance(name, str) or not name.strip():
            raise ValueError("task name must be a non-empty string")
        if isinstance(priority, bool) or not isinstance(priority, int):
            raise TypeError("priority must be an integer")
        return name.strip(), priority

    def take_id(self):
        task_id = self.next_id
        self.next_id += 1
        return task_id

    def best_index(self):
        best = None
        for index, (task_id, _, priority) in enumerate(self.tasks):
            if best is None:
                best = index
                continue
            best_id, _, best_priority = self.tasks[best]
            if priority > best_priority or (priority == best_priority and task_id < best_id):
                best = index
        return best

    def add_task(self, name: str, priority: int):
        clean_name, clean_priority = self.validate(name, priority)
        self.tasks.append((self.take_id(), clean_name, clean_priority))

    def execute_next(self) -> str:
        index = self.best_index()
        if index is None:
            return None
        _, name, _ = self.tasks.pop(index)
        return name

    def clear(self):
