class JSONLexer:
    """Sequential tokenizer for a simplified subset of JSON."""

    _WHITESPACE = " \t\r\n"
    _STRUCTURAL = "{}[]:,"

    def __init__(self, text: str):
        self.text = text
        self.pos = 0

    def _skip_whitespace(self) -> None:
        while self.pos < len(self.text) and self.text[self.pos] in self._WHITESPACE:
            self.pos += 1

    def _read_string(self) -> str:
        start = self.pos
        self.pos += 1
        while self.pos < len(self.text) and self.text[self.pos] != '"':
            self.pos += 1
        if self.pos >= len(self.text):
            raise ValueError("unterminated string literal at offset %d" % start)
        self.pos += 1
        return self.text[start:self.pos]

    def _read_number(self) -> str:
        start = self.pos
        while self.pos < len(self.text) and self.text[self.pos].isdigit():
            self.pos += 1
        return self.text[start:self.pos]

    def next_token(self) -> str:
        self._skip_whitespace()
        if self.pos >= len(self.text):
            return None
        char = self.text[self.pos]
        if char == '"':
            return self._read_string()
        if char.isdigit():
            return self._read_number()
        if char in self._STRUCTURAL:
            self.pos += 1
            return char
        raise ValueError("unexpected character %r at offset %d" % (char, self.pos))

    def has_more(self) -> bool:
        probe = self.pos
        while probe < len(self.text) and self.text[probe] in self._WHITESPACE:
            probe += 1
        return probe < len(self.text)


def tokenize(text: str) -> list:
    lexer = JSONLexer(text)
    tokens = []
    while lexer.has_more():
        tokens.append(lexer.next_token())
    return tokens


class TokenReport:
    """Accumulates token-kind statistics over several tokenized documents."""

    def __init__(self):
        self._counts = {}

    def _classify(self, token: str) -> str:
        if token.startswith('"'):
            return "string"
        if token[0].isdigit():
            return "number"
        return "structural"

    def add_all(self, tokens: list) -> None:
        for token in tokens:
            kind = self._classify(token)
            previous = self._counts.get(kind, 0)
            self._counts[kind] = previous + 1

    def render(self) -> str:
        parts = ["%s=%d" % pair for pair in sorted(self._counts.items())]
        return ", ".join(parts)


def main():
    samples = ['{"a": 1}', '[1, 2, {"b": 34}]', '{ "key" : "value" , "n": 7 }']
    report = TokenReport()
    for sample in samples:
        tokens = tokenize(sample)
        print("%-32s -> %s" % (sample, " ".join(tokens)))
        report.add_all(tokens)
    print("totals: " + report.render())


if __name__ == "__main__":
    main()

