class CoffeeMachine:
    """Tracks the ingredient reserves and the used-puck waste bin of a machine."""

    _RECIPES = {
        'espresso': {'water': 30, 'beans': 15, 'milk': 0},
        'americano': {'water': 120, 'beans': 15, 'milk': 0},
        'latte': {'water': 30, 'beans': 15, 'milk': 100},
    }
    _WASTE_LIMIT = 10

    def __init__(self):
        self.water = 0
        self.beans = 0
        self.milk = 0
        self.waste = 0

    def _recipe_for(self, drink_type):
        try:
            return self._RECIPES[drink_type]
        except KeyError:
            raise ValueError("Unknown drink: {}".format(drink_type))

    def _amounts(self):
        return {'water': self.water, 'beans': self.beans, 'milk': self.milk}

    def _has_ingredients(self, recipe):
        available = self._amounts()
        return all(available[name] >= needed for name, needed in recipe.items())

    def _deduct(self, recipe):
        self.water -= recipe['water']
        self.beans -= recipe['beans']
        self.milk -= recipe['milk']

    def fill(self, water, beans, milk):
        for amount in (water, beans, milk):
            if amount < 0:
                raise ValueError("Cannot fill a negative amount")
        self.water += water
        self.beans += beans
        self.milk += milk

    def empty_waste(self):
        self.waste = 0

    def brew(self, drink_type):
        recipe = self._recipe_for(drink_type)
        if self.waste >= self._WASTE_LIMIT:
            raise ValueError("Empty waste")
        if not self._has_ingredients(recipe):
            raise ValueError("Insufficient ingredients")
        self._deduct(recipe)
        self.waste += 1
        return "{} ready".format(drink_type)

    def _report(self):
        return "water={}ml beans={}g milk={}ml waste={} pucks".format(
            self.water, self.beans, self.milk, self.waste)

    def __str__(self):
        return "CoffeeMachine({})".format(self._report())


if __name__ == '__main__':
    machine = CoffeeMachine()
    machine.fill(1000, 200, 500)
    print(machine)
    for order in ['espresso', 'americano', 'latte', 'latte', 'latte', 'latte', 'latte']:
        try:
            print(machine.brew(order))
        except ValueError as err:
            print("{} refused: {}".format(order, err))
    print(machine)
    machine.empty_waste()
    machine.fill(0, 0, 200)
    print(machine.brew('latte'))
    print(machine)

