class BrowserHistory:
    """Simulate the navigation of a single browser tab."""

    def __init__(self, homepage):
        self._active = self._normalize(homepage)
        self._back_stack = []
        self._forward_stack = []

    def _normalize(self, url):
        if not isinstance(url, str):
            raise TypeError("url must be a string")
        cleaned = url.strip()
        if not cleaned:
            raise ValueError("url must not be empty")
        if "://" not in cleaned:
            cleaned = "https://" + cleaned
        return cleaned

    def _clamp(self, steps):
        if not isinstance(steps, int) or isinstance(steps, bool):
            raise TypeError("steps must be an integer")
        if steps < 0:
            raise ValueError("steps must not be negative")
        return steps

    def _shift(self, source, sink, steps):
        remaining = self._clamp(steps)
        while remaining and source:
            sink.append(self._active)
            self._active = source.pop()
            remaining -= 1
        return self._active

    def visit(self, url):
        self._back_stack.append(self._active)
        self._active = self._normalize(url)
        self._forward_stack.clear()
        return self._active

    def back(self, steps):
        return self._shift(self._back_stack, self._forward_stack, steps)

    def forward(self, steps):
        return self._shift(self._forward_stack, self._back_stack, steps)

    def current(self):
        return self._active

    def _trail(self, stack):
        if not stack:
            return "-"
        return " > ".join(entry.split("://", 1)[1] for entry in stack)

    def summary(self):
        return "back[{}] :: {} :: forward[{}]".format(
            self._trail(self._back_stack),
            self._active,
            self._trail(list(reversed(self._forward_stack))),
        )


if __name__ == "__main__":
    tab = BrowserHistory("example.com/home")
    for site in ("news.example.com", "docs.example.com/intro", "shop.example.com/cart"):
        print("visit   ->", tab.visit(site))
    print(tab.summary())

    print("back 2  ->", tab.back(2))
    print("fwd 1   ->", tab.forward(1))
    print(tab.summary())

    print("visit   ->", tab.visit("mail.example.com"))
    print("fwd 3   ->", tab.forward(3))
    print("back 10 ->", tab.back(10))
    print("current ->", tab.current())
    print(tab.summary())

