class LoyaltyProgram:
    """Track customer point balances, lifetime totals and loyalty tiers."""

    _TIERS = ((5000, "Platinum"), (1000, "Gold"), (0, "Silver"))

    def __init__(self):
        self._balances = {}
        self._lifetime = {}
        self._tiers = {}

    def _register(self, customer_id):
        if customer_id not in self._balances:
            self._balances[customer_id] = 0
            self._lifetime[customer_id] = 0
            self._tiers[customer_id] = "Silver"

    def _tier_for(self, lifetime_points):
        for threshold, name in self._TIERS:
            if lifetime_points >= threshold:
                return name

    @staticmethod
    def _check_points(points):
        if not isinstance(points, int) or isinstance(points, bool):
            raise TypeError("points must be an integer")
        if points < 0:
            raise ValueError("points must not be negative")
        return points

    def add_points(self, customer_id, points):
        self._check_points(points)
        self._register(customer_id)
        self._balances[customer_id] += points
        total = self._lifetime[customer_id] + points
        self._lifetime[customer_id] = total
        self._tiers[customer_id] = self._tier_for(total)
        return self._balances[customer_id]

    def redeem(self, customer_id, points):
        self._check_points(points)
        if self._balances.get(customer_id, 0) < points:
            return False
        self._balances[customer_id] -= points
        return True

    def get_status(self, customer_id):
        balance = self._balances.get(customer_id, 0)
        return balance, self._tiers.get(customer_id, "Silver")

    def lifetime_points(self, customer_id):
        return self._lifetime.get(customer_id, 0)

    def report(self):
        lines = []
        for customer_id in sorted(self._balances):
            balance, tier = self.get_status(customer_id)
            lines.append(
                "{:<10} balance={:>6}  lifetime={:>6}  tier={}".format(
                    customer_id, balance, self.lifetime_points(customer_id), tier
                )
            )
        return "\n".join(lines)


def main():
    program = LoyaltyProgram()
    program.add_points("alice", 5200)
    program.add_points("bob", 800)
    program.add_points("bob", 450)
    program.add_points("carol", 300)

    print("alice redeems 200:", program.redeem("alice", 200))
    print("carol redeems 500:", program.redeem("carol", 500))
    print("dave status:", program.get_status("dave"))
    print(program.report())


if __name__ == "__main__":
    main()

