class Thermostat:
    """A simple HVAC thermostat with a deadband around the target temperature."""

    _FAN_MODES = ("auto", "on", "circulate")
    _TEMP_LIMITS = (40.0, 95.0)

    def __init__(self, target_temp):
        self.target = self._validate_temp(target_temp)
        self._current = 72.0
        self._hvac = "off"
        self._fan = "auto"
        self._history = []

    def _validate_temp(self, temp):
        try:
            value = float(temp)
        except (TypeError, ValueError):
            raise ValueError("temperature must be numeric, got %r" % (temp,))
        low, high = self._TEMP_LIMITS
        if not low <= value <= high:
            raise ValueError("temperature %.1f outside %.1f-%.1f" % (value, low, high))
        return value

    def _validate_fan(self, mode):
        normalized = str(mode).strip().lower()
        if normalized not in self._FAN_MODES:
            raise ValueError("unknown fan mode %r" % (mode,))
        return normalized

    def _evaluate_mode(self):
        delta = self._current - self.target
        if abs(delta) <= DEADBAND:
            self._hvac = "off"
        elif delta >= SWING:
            self._hvac = "cool"
        elif delta <= -SWING:
            self._hvac = "heat"

    def set_target(self, temp):
        self.target = self._validate_temp(temp)
        self._evaluate_mode()

    def set_fan(self, mode):
        self._fan = self._validate_fan(mode)

    def sensor_update(self, current_temp):
        self._current = self._validate_temp(current_temp)
        self._evaluate_mode()
        self._history.append((self._current, self._hvac))
        return self._hvac

    def get_state(self):
        return {
            "temp": self._current,
            "target": self.target,
            "hvac": self._hvac,
            "fan": self._fan,
        }

    def _format_row(self, index, temp, mode):
        return "%2d  %6.1fF  target %5.1fF  -> %-4s" % (index, temp, self.target, mode)

    def report(self):
        rows = [self._format_row(i, t, m) for i, (t, m) in enumerate(self._history, 1)]
        return "\n".join(rows)


if __name__ == "__main__":
    stat = Thermostat(70.0)
    stat.set_fan("circulate")
    for reading in (72.0, 74.5, 73.0, 70.4, 69.8, 67.5, 64.0, 70.2):
        stat.sensor_update(reading)
    print(stat.report())
    print("final state:", stat.get_state())
    stat.set_target(78.0)
    print("after retarget:", stat.get_state())
    print("last cycle:", stat.sensor_update(75.0))

