class ParkingGarage:
    """A small parking garage with per-hour billing."""

    def __init__(self, total_spots, hourly_rate):
        if total_spots < 0:
            raise ValueError("total_spots must be non-negative")
        if hourly_rate < 0:
            raise ValueError("hourly_rate must be non-negative")
        self.total_spots = total_spots
        self.hourly_rate = hourly_rate
        self._available = total_spots
        self._entries = {}
        self._revenue = 0

    def _normalize(self, plate):
        if not isinstance(plate, str):
            raise TypeError("plate must be a string")
        cleaned = plate.strip().upper().replace(" ", "")
        if not cleaned:
            raise ValueError("plate must not be empty")
        return cleaned

    def _fee_for(self, entry_hour, exit_hour):
        return (exit_hour - entry_hour) * self.hourly_rate

    def enter(self, plate, entry_hour):
        key = self._normalize(plate)
        if self._available <= 0 or key in self._entries:
            return False
        self._entries[key] = entry_hour
        self._available -= 1
        return True

    def exit(self, plate, exit_hour):
        key = self._normalize(plate)
        entry_hour = self._entries.get(key)
        if entry_hour is None or exit_hour < entry_hour:
            return None
        fee = self._fee_for(entry_hour, exit_hour)
        del self._entries[key]
        self._available += 1
        self._revenue += fee
        return fee

    def get_stats(self):
        return (self._available, self._revenue)

    def occupancy_report(self):
        occupied = self.total_spots - self._available
        lines = ["Occupied {0}/{1} spots".format(occupied, self.total_spots)]
        for key in sorted(self._entries):
            lines.append("  {0} since hour {1}".format(key, self._entries[key]))
        lines.append("Revenue collected: {0}".format(self._revenue))
        return "\n".join(lines)


def main():
    garage = ParkingGarage(total_spots=2, hourly_rate=3)
    print(garage.enter("abc-123", 8))
    print(garage.enter(" xyz 789 ", 9))
    print(garage.enter("new-000", 10))
    print(garage.enter("ABC123", 11))
    print(garage.occupancy_report())
    print(garage.exit("ABC-123", 12))
    print(garage.exit("XYZ789", 8))
    print(garage.exit("ghost-1", 13))
    print(garage.get_stats())
    print(garage.occupancy_report())


if __name__ == "__main__":
    main()

