import sys


class BowlingScorer:
    """Incremental ten pin bowling scorer."""

    MAX_FRAMES = 10

    def __init__(self):
        self._frame = 1
        self._frame_rolls = []
        self._frame_scores = []
        self._bonuses = []
        self._strike = False
        self._spare = False

    def roll(self, pins):
        self._validate(pins)
        self._apply_bonus(pins)
        if self._frame > self.MAX_FRAMES:
            return
        self._frame_rolls.append(pins)
        if self._frame_complete():
            self._record_frame()
            self._advance_frame()

    def total(self):
        return sum(self._frame_scores)

    def scorecard(self):
        lines = []
        running = 0
        for number, score in enumerate(self._frame_scores, start=1):
            running += score
            lines.append("Frame {:>2}: {:>3} pts (running {:>3})".format(number, score, running))
        if self._frame_rolls:
            lines.append("Frame {:>2}: open, rolls so far {}".format(self._frame, self._frame_rolls))
        return "\n".join(lines)

    def _validate(self, pins):
        if not isinstance(pins, int):
            raise TypeError("a roll must be an integer, got {!r}".format(pins))
        if not 0 <= pins <= 10:
            raise ValueError("a roll must knock down 0 to 10 pins, got {}".format(pins))
        if len(self._frame_rolls) == 1 and self._frame_rolls[0] + pins > 10:
            raise ValueError("frame {} cannot exceed 10 pins".format(self._frame))

    def _apply_bonus(self, pins):
        still_pending = []
        for index, remaining in self._bonuses:
            self._frame_scores[index] += pins
            if remaining > 1:
                still_pending.append((index, remaining - 1))
        self._bonuses = still_pending

    def _frame_complete(self):
        return self._frame_rolls[0] == 10 or len(self._frame_rolls) == 2

    def _record_frame(self):
        knocked = sum(self._frame_rolls)
        self._strike = len(self._frame_rolls) == 1
        self._spare = knocked == 10 and not self._strike
        self._frame_scores.append(knocked)

    def _advance_frame(self):
        last = len(self._frame_scores) - 1
        if self._strike:
            self._bonuses.append((last, 2))
        elif self._spare:
            self._bonuses.append((last, 1))
        self._frame += 1
        self._frame_rolls = []


def play(rolls):
    scorer = BowlingScorer()
    for pins in rolls:
        scorer.roll(pins)
    return scorer


def bowling(rolls):
    return play(rolls).total()


def main(argv):
    words = argv[1:] or ["10", "7", "3", "4", "5"]
    scorer = play([int(word) for word in words])
    print(scorer.scorecard())
    print("Total score: {}".format(scorer.total()))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

