class CashMachine:
    """A small ATM that dispenses 20/50/100 bills and enforces daily limits."""

    DAILY_LIMIT = 500
    DENOMINATIONS = (100, 50, 20)

    def __init__(self, twenties=50, fifties=50, hundreds=50):
        self._bills = {20: twenties, 50: fifties, 100: hundreds}
        self._daily = {}
        self._locked = []
        self._strikes = {}

    def _plan_bills(self, amount):
        """Return the bill mix using the fewest notes, or None if impossible."""
        for hundreds in range(min(amount // 100, self._bills[100]), -1, -1):
            rest_after_hundreds = amount - hundreds * 100
            for fifties in range(min(rest_after_hundreds // 50, self._bills[50]), -1, -1):
                rest = rest_after_hundreds - fifties * 50
                twenties, remainder = divmod(rest, 20)
                if remainder == 0 and twenties <= self._bills[20]:
                    return {100: hundreds, 50: fifties, 20: twenties}
        return None

    def _within_limit(self, account, amount):
        return self._daily.get(account, 0) + amount <= self.DAILY_LIMIT

    def _register_strike(self, account):
        """Count an invalid request and lock the account after the third one."""
        self._strikes[account] = self._strikes.get(account, 0) + 1
        if self._strikes[account] >= 3 and account not in self._locked:
            self._locked.append(account)

    def _dispense(self, plan):
        for value, count in plan.items():
            self._bills[value] -= count
        return sum(value * count for value, count in plan.items())

    def withdraw(self, account, amount):
        """Dispense `amount` for `account`, or return None if denied."""
        if account in self._locked:
            return None
        if not isinstance(amount, int) or amount <= 0 or not self._within_limit(account, amount):
            self._register_strike(account)
            return None
        plan = self._plan_bills(amount)
        if plan is None:
            self._register_strike(account)
            return None
        self._daily[account] = self._daily.get(account, 0) + amount
        return self._dispense(plan)

    def report(self):
        lines = ["%s: %d withdrawn today" % (name, total)
                 for name, total in sorted(self._daily.items())]
        for name in sorted(self._locked):
            lines.append("%s: LOCKED" % name)
        return "\n".join(lines)


def atm(requests):
    machine = CashMachine()
    dispensed = []
    for request in requests:
        action, account, amount = request
        if action != "withdraw":
            continue
        handed_out = machine.withdraw(account, amount)
        if handed_out is not None:
            dispensed.append(handed_out)
    return dispensed


def main():
    machine = CashMachine()
    transcript = [("withdraw", "bob", 120), ("withdraw", "bob", 400),
                  ("withdraw", "alice", 30), ("withdraw", "alice", 10),
                  ("withdraw", "alice", -50), ("withdraw", "alice", 100)]
    print(atm(transcript))
    for action, account, amount in transcript:
        machine.withdraw(account, amount)
    print(machine.report())


if __name__ == "__main__":
    main()

