        if name in self.quantities:
            left = self.quantities[name] - int(quantity)
            if left > 0:
                self.quantities[name] = left
            else:
                del self.quantities[name]
                del self.prices[name]

    def set_discount(self, percentage):
        percentage = float(percentage)
        if 0.0 <= percentage <= 100.0:
            self.discount_pct = percentage

    def set_tax(self, rate):
        self.tax_rate = max(0.0, float(rate))

    def total(self):
        payable = self.discounted(self.subtotal())
        return round(payable + self.tax_on(payable), 2)

    def room_for(self, name, quantity):
        return min(quantity, self.stock_limit - self.quantities.get(name, 0))

    def subtotal(self):
        return sum(count * self.prices[name]
                   for name, count in self.quantities.items())

    def discounted(self, amount):
        return amount * (1.0 - self.discount_pct / 100.0)

    def tax_on(self, amount):
        return amount * self.tax_rate


def cart(actions):
    checkout = Checkout()
    for action in actions:
        verb = action[0]
        if verb == "add":
            checkout.add(action[1], action[2], action[3])
        elif verb == "remove":
            checkout.remove(action[1], action[2])
        elif verb == "discount":
            checkout.set_discount(action[1])
        elif verb == "tax":
            checkout.set_tax(action[1])
        else:
            raise ValueError("unknown action: {0!r}".format(verb))
    return float(checkout.total())


def main():
    basket = [("add", "shirt", 2, 20.0), ("discount", 10)]
    print("%.2f" % cart(basket))
    mixed = [("add", "mug", 4, 7.5), ("remove", "mug", 1),
             ("discount", 25), ("tax", 0.08)]
    print("%.2f" % cart(mixed))


if __name__ == "__main__":
    main()

