class AssemblyLine:
    """Tracks widget production, machine heat and operator shifts."""

    MIN_QUALITY = 6
    HEAT_PER_WIDGET = 10
    TEMP_THRESHOLD = 20
    WIDGETS_PER_SHIFT = 4
    SHIFTS = ("day", "swing", "night")

    def __init__(self):
        self._successful = 0
        self._defective = 0
        self._temperature = 0
        self._shift_index = 0
        self._log = []

    def _validate(self, quality):
        if isinstance(quality, bool) or not isinstance(quality, int):
            raise TypeError("raw material quality must be an integer: %r" % (quality,))
        if quality < 0:
            raise ValueError("raw material quality cannot be negative: %d" % quality)

    def _heat(self):
        self._temperature += self.HEAT_PER_WIDGET

    def _is_overheated(self):
        return self._temperature > self.TEMP_THRESHOLD

    def _cool(self):
        self._temperature = 0

    def _classify(self, quality):
        if self._is_overheated() or quality < self.MIN_QUALITY:
            return "defective"
        return "successful"

    def _record(self, quality, grade):
        if grade == "successful":
            self._successful += 1
        else:
            self._defective += 1
        self._log.append((quality, grade, self._temperature, self.current_shift()))

    def _advance_shift(self):
        if len(self._log) % self.WIDGETS_PER_SHIFT == 0:
            self._shift_index = (self._shift_index + 1) % len(self.SHIFTS)

    def current_shift(self):
        return self.SHIFTS[self._shift_index]

    def produce(self, quality):
        self._validate(quality)
        self._heat()
        grade = self._classify(quality)
        self._record(quality, grade)
        if self._is_overheated():
            self._cool()
        self._advance_shift()
        return grade

    def totals(self):
        return (self._successful, self._defective, self._temperature)

    def report(self):
        header = "quality grade       temp shift"
        rows = ["%7d %-11s %4d %s" % entry for entry in self._log]
        good, bad, temp = self.totals()
        summary = "%d successful, %d defective, final temperature %d" % (good, bad, temp)
        return "\n".join([header] + rows + [summary])


def assembly(events):
    line = AssemblyLine()
    for quality in events:
        line.produce(quality)
    return line.totals()


def main():
    batch = [5, 6, 2, 8, 9]
    detailed = AssemblyLine()
    for quality in batch:
        detailed.produce(quality)
    print(detailed.report())
    print("assembly(%r) -> %r" % (batch, assembly(batch)))


if __name__ == "__main__":
    main()

