import sys


class CoffeeRoaster:
    """Simulates a small drum roaster working on a single batch of green beans."""

    ROOM_TEMP = 20.0
    FIRST_CRACK = 196.0
    BATCH_GRAMS = 250.0
    TICK = 0.25

    def __init__(self):
        self._batch = self.BATCH_GRAMS
        self._temp = self.ROOM_TEMP
        self._elapsed = 0.0
        self._crack_time = None
        self._tray = None

    def _check_crack(self):
        if self._crack_time is None and self._temp >= self.FIRST_CRACK:
            self._crack_time = self._elapsed
        return self._crack_time is not None

    def _apply_heat(self, degrees):
        if degrees < 0:
            raise ValueError("heat increment must be non-negative")
        self._temp += float(degrees)
        self._check_crack()

    def _pass_time(self, minutes):
        if minutes < 0:
            raise ValueError("waiting time must be non-negative")
        remaining = float(minutes)
        while remaining > 0:
            dt = min(self.TICK, remaining)
            remaining -= dt
            self._elapsed += dt
            if self._check_crack():
                rate = 1.5 + 0.02 * (self._temp - self.FIRST_CRACK)
                self._batch -= self.BATCH_GRAMS * rate * dt / 100.0
            self._temp -= dt

    def _transfer_to_tray(self):
        self._tray = self._batch
        self._temp = self.ROOM_TEMP

    def _roast_level(self):
        if self._crack_time is None:
            return "green"
        loss = (self.BATCH_GRAMS - self._tray) / self.BATCH_GRAMS * 100.0
        if loss >= 20.0:
            return "burnt"
        if loss >= 15.0:
            return "medium"
        return "light"

    def run(self, steps):
        for step in steps:
            if self._tray is not None:
                raise ValueError("beans are already in the cooling tray")
            command = step[0]
            if command == "heat":
                self._apply_heat(step[1])
            elif command == "wait":
                self._pass_time(step[1])
            elif command == "drop":
                self._transfer_to_tray()
            else:
                raise ValueError("unknown roasting step: %r" % (command,))
        if self._tray is None:
            self._pass_time(1.0)
            self._transfer_to_tray()
        return self._roast_level()


def roaster(steps):
    return CoffeeRoaster().run(steps)


def parse_steps(tokens):
    steps = []
    index = 0
    while index < len(tokens):
        word = tokens[index].lower()
        if word == "drop":
            steps.append((word,))
            index += 1
        elif word in ("heat", "wait"):
            if index + 1 >= len(tokens):
                raise ValueError("%s needs a numeric argument" % word)
            steps.append((word, float(tokens[index + 1])))
            index += 2
        else:
            raise ValueError("unknown roasting step: %r" % (tokens[index],))
    return steps


def main(argv):
    if len(argv) < 2:
        print("usage: %s heat 200 wait 10 drop" % argv[0])
        return 1
    print(roaster(parse_steps(argv[1:])))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

