            value = int(value)
            if value < 0:
                raise ValueError("%s value cannot be negative: %d" % (action, value))
            parsed.append((action, value))
        return parsed

    def _wind_safe(self):
        return self._wind < self._STOP_WIND

    def _throttle(self):
        self._mode = "slow" if self._wind >= self._SLOW_WIND else "normal"

    def _board(self):
        free = self._SEATS - self._chairs[0]
        boarding = min(free, self._queue)
        self._chairs[0] += boarding
        self._queue -= boarding

    def _unload(self):
        self._delivered += self._chairs[-1]
        self._chairs[-1] = 0

    def _advance(self):
        self._unload()
        self._chairs = [0] + self._chairs[:-1]

    def _step(self):
        self._tick += 1
        if not self._wind_safe():
            return
        if self._mode == "slow" and self._tick % 2 == 0:
            return
        self._board()
        self._advance()

    def _summary(self):
        stranded = self._queue + sum(self._chairs)
        return "wind %d km/h, motor %s, %d dropped at the top, %d still waiting" % (
            self._wind, self._mode, self._delivered, stranded)

    def report(self):
        return self._summary()

    def run(self, conditions):
        for action, value in self._parse(conditions):
            if action == "wind":
                self._wind = value
                self._throttle()
            else:
                self._queue += value
            self._step()
        while self._wind_safe() and (self._queue or any(self._chairs)):
