class TollLane:
    """One automated toll lane: cash drawer, pass reader and a physical barrier."""

    RATE_PER_AXLE = 2.50

    def __init__(self):
        self._cash_total = 0.0
        self._passes = []
        self._violator_plates = []
        self._barrier_open = False

    def _check_axles(self, axles):
        if not isinstance(axles, int) or axles < 1:
            raise ValueError("a vehicle must have at least one axle")

    def _axle_toll(self, axles):
        self._check_axles(axles)
        return round(axles * self.RATE_PER_AXLE, 2)

    def _open_barrier(self):
        self._barrier_open = True

    def _close_barrier(self):
        self._barrier_open = False

    def _log_plate(self, plate, axles):
        self._violator_plates.append((plate, self._axle_toll(axles)))

    def take_cash(self, axles, amount):
        self._check_axles(axles)
        if amount < 0:
            raise ValueError("cash payment cannot be negative")
        self._cash_total += amount
        self._open_barrier()
        self._close_barrier()

    def scan_pass(self, axles, tag):
        self._passes.append((tag, self._axle_toll(axles)))
        self._open_barrier()
        self._close_barrier()

    def record_runaway(self, axles, plate):
        self._close_barrier()
        self._log_plate(plate, axles)

    @property
    def revenue(self):
        billed = sum(entry[1] for entry in self._passes)
        return round(self._cash_total + billed, 2)

    @property
    def violator_count(self):
        return len(self._violator_plates)

    def summary(self):
        lines = ["revenue={0:.2f} violators={1}".format(self.revenue,
                                                        self.violator_count)]
        for plate, owed in self._violator_plates:
            lines.append("  unpaid {0} owes {1:.2f}".format(plate, owed))
        return "\n".join(lines)


def tollbooth(vehicles):
    lane = TollLane()
    for kind, axles, extra in vehicles:
        if kind == "cash":
            lane.take_cash(axles, extra)
        elif kind == "pass":
            lane.scan_pass(axles, extra)
        elif kind == "run":
            lane.record_runaway(axles, extra)
        else:
            raise ValueError("unknown event type: {0!r}".format(kind))
    return lane.revenue, lane.violator_count


def main():
    lane = TollLane()
    lane.take_cash(2, 5.00)
    lane.record_runaway(4, "ABC-1234")
    lane.scan_pass(3, "TAG-77")
    print(lane.summary())


if __name__ == "__main__":
    main()

