import re


class BaggageSorter:
    """Routes bags into destination bins while watching the conveyor belt."""

    _BARCODE = re.compile(r"^(?:[A-Z]{2,3})?0*(\d+)$")
    _BURST_LIMIT = 3
    _MAX_SPEED = 3

    def __init__(self, base_speed=1):
        self._bins = {}
        self._order = []
        self._speed = base_speed
        self._mishandled = 0
        self._scan_log = []
        self._burst = 0

    def _decode(self, barcode):
        match = self._BARCODE.match(str(barcode).strip().upper())
        if match is None:
            return None
        return int(match.group(1))

    def _allocate(self, flight, weight):
        if flight not in self._bins:
            self._bins[flight] = 0
            self._order.append(flight)
        self._bins[flight] += weight

    def _adjust_speed(self):
        self._burst += 1
        if self._burst > self._BURST_LIMIT and self._speed < self._MAX_SPEED:
            self._speed += 1
            self._burst = 0

    def scan(self, barcode, weight):
        self._scan_log.append(str(barcode))
        flight = self._decode(barcode)
        if flight is None or not isinstance(weight, (int, float)) or weight <= 0:
            self._mishandled += 1
            return
        self._allocate(flight, weight)
        self._adjust_speed()

    def delay(self, minutes):
        self._burst = max(0, self._burst - int(minutes))
        if minutes >= 5 and self._speed > 1:
            self._speed -= 1

    def run(self, bags):
        for event in bags:
            kind = str(event[0]).strip().lower()
            if kind == "scan":
                self.scan(event[1], event[2])
            elif kind == "delay":
                self.delay(event[1])
            else:
                raise ValueError("unknown conveyor event: %r" % (event[0],))
        return self.totals()

    def totals(self):
        return [(flight, self._bins[flight]) for flight in self._order]

    def report(self):
        lines = ["belt speed: %d" % self._speed,
                 "barcodes scanned: %d" % len(self._scan_log),
                 "mishandled bags: %d" % self._mishandled]
        for flight, weight in self.totals():
            lines.append("flight %d -> %g kg" % (flight, weight))
        return "\n".join(lines)


def sorter(bags):
    return BaggageSorter().run(bags)


if __name__ == "__main__":
    manifest = [("scan", "BA0001", 20), ("scan", "BA0001", 15),
                ("scan", "LH0221", 23), ("scan", "LH0221", 18),
                ("delay", 6), ("scan", "221", 7), ("scan", "TORN-LABEL", 9)]
    print(sorter(manifest))
    belt = BaggageSorter(base_speed=2)
    belt.run(manifest)
    print(belt.report())

