from collections import Counter

RECIPES = {
    "sourdough": {"flour": 100.0, "yeast": 1.0, "water": 65.0},
    "rye": {"flour": 90.0, "yeast": 2.0, "water": 70.0},
    "baguette": {"flour": 80.0, "yeast": 1.5, "water": 55.0},
    "brioche": {"flour": 120.0, "yeast": 3.0, "water": 40.0},
}


class DoughStation:
    def __init__(self):
        self._stock = {"flour": 0.0, "yeast": 0.0, "water": 0.0}
        self._requests = []

    def _ratio(self, bread):
        recipe = RECIPES.get(bread)
        if recipe is None:
            raise ValueError("unknown bread type: %r" % (bread,))
        return recipe

    def _scale(self, bread, loaves):
        if loaves < 0:
            raise ValueError("loaf count must not be negative")
        return {name: amount * loaves for name, amount in self._ratio(bread).items()}

    def _deduct(self, needed):
        for ingredient, amount in needed.items():
            self._stock[ingredient] = max(0.0, self._stock[ingredient] - amount)

    def restock(self, ingredient, amount):
        if ingredient not in self._stock:
            raise ValueError("cannot store %r in bulk" % (ingredient,))
        if amount < 0:
            raise ValueError("restock amount must not be negative")
        self._stock[ingredient] += amount

    def bake(self, bread, loaves):
        needed = self._scale(bread, loaves)
        self._requests.extend([bread] * int(loaves))
        self._deduct(needed)

    def run(self, orders):
        for order in orders:
            if len(order) != 3:
                raise ValueError("each order needs an action, a target and an amount")
            action, target, amount = order
            if action == "restock":
                self.restock(target, amount)
            elif action == "bake":
                self.bake(target, amount)
            else:
                raise ValueError("unknown action: %r" % (action,))

    def totals(self):
        return tuple(round(self._stock[name], 2) for name in ("flour", "yeast", "water"))

    def summary(self):
        counts = Counter(self._requests)
        if not counts:
            return "no loaves requested"
        lines = ["%s: %d loaf/loaves" % (bread, n) for bread, n in sorted(counts.items())]
        return "\n".join(lines)


def baker(orders):
    station = DoughStation()
    station.run(orders)
    return station.totals()


def main():
    print(baker([("restock", "flour", 1000), ("bake", "sourdough", 2)]))
    station = DoughStation()
    station.run([
        ("restock", "flour", 5000),
        ("restock", "yeast", 60),
        ("restock", "water", 3000),
        ("bake", "sourdough", 4),
        ("bake", "rye", 3),
        ("bake", "brioche", 2),
    ])
    print(station.summary())
    print("remaining flour/yeast/water: %s" % (station.totals(),))


if __name__ == "__main__":
    main()

