ROWS = 6
SEATS_PER_ROW = 4


class RollerCoaster:
    """Operates a single train: queue -> rows -> locked restraints -> dispatch."""

    def __init__(self, rows=ROWS, seats_per_row=SEATS_PER_ROW):
        self.rows = rows
        self.seats_per_row = seats_per_row
        self._queue = []
        self._seated = []
        self._restraints = []
        self._cycles = 0

    def arrive(self, size):
        if not isinstance(size, int) or size < 1:
            raise ValueError("group size must be a positive integer: %r" % (size,))
        self._queue.append(size)

    def _place(self, rows, group):
        for index, filled in enumerate(rows):
            if self.seats_per_row - filled >= group:
                rows[index] = filled + group
                return True
        if sum(self.seats_per_row - filled for filled in rows) < group:
            return False
        remaining = group
        for index, filled in enumerate(rows):
            taken = min(self.seats_per_row - filled, remaining)
            rows[index] = filled + taken
            remaining -= taken
            if remaining == 0:
                break
        return True

    def _fill_rows(self):
        rows = [0] * self.rows
        boarded = []
        for group in self._queue:
            if not self._place(rows, group):
                break
            boarded.append(group)
        return boarded

    def lock(self):
        boarded = self._fill_rows()
        self._seated = boarded
        del self._queue[:len(boarded)]
        self._restraints = [True] * sum(boarded)

    def _all_locked(self):
        return bool(self._restraints) and all(self._restraints)

    def _clear_train(self):
        riders = sum(self._seated)
        self._seated = []
        self._restraints = []
        return riders

    def dispatch(self):
        if not self._all_locked():
            return 0
        self._cycles += 1
        return self._clear_train()

    def summary(self):
        return "%d cycle(s) run, %d passenger(s) still waiting" % (
            self._cycles, sum(self._queue))


def simulate(events):
    coaster = RollerCoaster()
    total = 0
    for event in events:
        action = event[0]
        if action == "arrive":
            coaster.arrive(event[1])
        elif action == "lock":
            coaster.lock()
        elif action == "dispatch":
            total += coaster.dispatch()
        else:
            raise ValueError("unknown event: %r" % (action,))
    return coaster, total


def ride(events):
    return simulate(events)[1]


def parse_events(lines):
    events = []
    for line in lines:
        parts = line.split()
        if not parts:
            continue
        events.append((parts[0], int(parts[1])) if len(parts) > 1 else (parts[0],))
    return events


def main():
    import sys
    coaster, total = simulate(parse_events(sys.stdin))
    print(total)
    print(coaster.summary())


if __name__ == "__main__":
    main()

