        self.seats_per_row = seats_per_row
        self.queue = []
        self.seated = []
        self.restraints = []
        self.cycles = 0

    def arrive(self, size):
        if not isinstance(size, int) or size < 1:
            raise ValueError("group size must be a positive integer: %r" % (size,))
        self.queue.append(size)

    def place(self, rows, group):
        for index, filled in enumerate(rows):
            if self.seats_per_row - filled >= group:
                rows[index] = filled + group
                return True
        if sum(self.seats_per_row - filled for filled in rows) < group:
            return False
        remaining = group
        for index, filled in enumerate(rows):
            taken = min(self.seats_per_row - filled, remaining)
            rows[index] = filled + taken
            remaining -= taken
            if remaining == 0:
                break
        return True

    def fill_rows(self):
        rows = [0] * self.rows
        boarded = []
        for group in self.queue:
            if not self.place(rows, group):
                break
            boarded.append(group)
        return boarded

    def lock(self):
        boarded = self.fill_rows()
        self.seated = boarded
        del self.queue[:len(boarded)]
        self.restraints = [True] * sum(boarded)

    def all_locked(self):
        return bool(self.restraints) and all(self.restraints)

    def clear_train(self):
        riders = sum(self.seated)
        self.seated = []
        self.restraints = []
        return riders

    def dispatch(self):
        if not self.all_locked():
            return 0
        self.cycles += 1
        return self.clear_train()

    def summary(self):
        return "%d cycle(s) run, %d passenger(s) still waiting" % (
            self.cycles, sum(self.queue))


def simulate(events):
    coaster = RollerCoaster()
    total = 0
    for event in events:
        action = event[0]
        if action == "arrive":
            coaster.arrive(event[1])
        elif action == "lock":
            coaster.lock()
        elif action == "dispatch":
            total += coaster.dispatch()
        else:
            raise ValueError("unknown event: %r" % (action,))
    return coaster, total


def ride(events):
    return simulate(events)[1]


def parse_events(lines):
    events = []
    for line in lines:
        parts = line.split()
        if not parts:
            continue
        events.append((parts[0], int(parts[1])) if len(parts) > 1 else (parts[0],))
    return events


def main():
    import sys
    coaster, total = simulate(parse_events(sys.stdin))
    print(total)
    print(coaster.summary())


if __name__ == "__main__":
    main()

