class EscapeRoom:
    """A three-lock escape room whose state is driven by player actions."""

    _PENALTY = 5
    _HINT_COST = 3

    def __init__(self, total_minutes=60):
        self._time_left = total_minutes
        self._solutions = ("onetwothreefour", "fivesixseveneight", "nineteneleventwelve")
        self._locks = [False, False, False]
        self._codes = []
        self._hints = []
        self._door_open = False

    def _normalize(self, raw):
        return "".join(str(raw).lower().split())

    def _spend(self, minutes):
        self._time_left = max(0, self._time_left - int(minutes))

    def _validate(self, code):
        for index, solution in enumerate(self._solutions):
            if solution == code and not self._locks[index]:
                return index
        return -1

    def _unlock(self, index):
        self._locks[index] = True
        self._release_door()

    def _release_door(self):
        if all(self._locks) and self._time_left > 0:
            self._door_open = True

    def _guess(self, raw):
        code = self._normalize(raw)
        self._codes.append(code)
        index = self._validate(code)
        if index < 0:
            self._spend(self._PENALTY)
            return
        self._unlock(index)

    def _reveal(self):
        for index, solution in enumerate(self._solutions):
            if not self._locks[index]:
                self._hints.append("lock %d starts with '%s'" % (index + 1, solution[:4]))
                break
        self._spend(self._HINT_COST)

    def apply(self, action):
        verb = str(action[0]).lower()
        if self._time_left <= 0:
            return
        if verb == "guess":
            self._guess(action[1])
        elif verb == "hint":
            self._reveal()
        elif verb == "wait":
            self._spend(action[1])
        else:
            raise ValueError("unknown action: %r" % (action[0],))

    def escaped(self):
        return self._door_open and self._time_left > 0

    def report(self):
        opened = sum(1 for lock in self._locks if lock)
        lines = ["locks opened: %d/3" % opened,
                 "codes tried: %s" % (", ".join(self._codes) or "none"),
                 "hints used: %s" % (", ".join(self._hints) or "none"),
                 "minutes left: %d" % self._time_left,
                 "door: %s" % ("open" if self._door_open else "closed")]
        return "\n".join(lines)


def escaperoom(actions):
    room = EscapeRoom()
    for action in actions:
        room.apply(action)
    return room.escaped()


def main():
    attempt = [("guess", "one two three four"), ("hint",), ("guess", "five six seven eight")]
    print(escaperoom(attempt))
    full = attempt + [("wait", 10), ("guess", "nine ten eleven twelve")]
    print(escaperoom(full))
    room = EscapeRoom()
    for action in full:
        room.apply(action)
    print(room.report())


if __name__ == "__main__":
    main()

