class LightingController:
    """Tracks ambient light, pedestrians and pole brightness to score energy savings."""

    FULL_BRIGHTNESS = 100
    MIN_ACTIVE_BRIGHTNESS = 20
    AMBIENT_DIM_FACTOR = 0.4
    SENSOR_RADIUS = 1
    _KINDS = ("ambient", "pedestrian", "clear")

    def __init__(self):
        self._ambient = 0
        self._pedestrians = {}
        self._brightness = {}
        self._saved = 0

    def run(self, events):
        for event in events:
            kind, value = self._parse(event)
            if kind == "ambient":
                self._ambient = value
            elif kind == "pedestrian":
                self._add_pedestrian(value)
            else:
                self._clear_pole(value)
            self._refresh()
            self._accrue()
        return self._saved

    def report(self):
        lit = sorted(p for p, b in self._brightness.items() if b > 0)
        poles = len(self._brightness)
        return ("ambient={0} poles={1} lit={2} saved={3}"
                .format(self._ambient, poles, lit, self._saved))

    def _parse(self, event):
        if len(event) != 2:
            raise ValueError("each event needs a keyword and a value: {0!r}".format(event))
        kind, value = event
        if kind not in self._KINDS:
            raise ValueError("unknown event keyword: {0!r}".format(kind))
        value = int(value)
        if kind == "ambient" and not 0 <= value <= 100:
            raise ValueError("ambient level out of range: {0}".format(value))
        return kind, value

    def _add_pedestrian(self, pole):
        self._pedestrians[pole] = self._pedestrians.get(pole, 0) + 1
        self._brightness.setdefault(pole, 0)

    def _clear_pole(self, pole):
        self._pedestrians.pop(pole, None)
        self._brightness.setdefault(pole, 0)

    def _should_light(self, pole):
        span = range(-self.SENSOR_RADIUS, self.SENSOR_RADIUS + 1)
        return any((pole + offset) in self._pedestrians for offset in span)

    def _target_brightness(self, pole):
        if not self._should_light(pole):
            return 0
        dimmed = self.FULL_BRIGHTNESS - self.AMBIENT_DIM_FACTOR * self._ambient
        return int(max(self.MIN_ACTIVE_BRIGHTNESS, dimmed))

    def _refresh(self):
        for pole in self._brightness:
            self._brightness[pole] = self._target_brightness(pole)

    def _accrue(self):
        baseline = self.FULL_BRIGHTNESS * len(self._brightness)
        self._saved += baseline - sum(self._brightness.values())


def streetlights(events):
    return LightingController().run(events)


def main():
    example = [("ambient", 50), ("pedestrian", 5)]
    print("example saved:", streetlights(example))

    night = [("ambient", 10), ("pedestrian", 3), ("pedestrian", 4),
             ("clear", 3), ("ambient", 90), ("pedestrian", 7)]
    controller = LightingController()
    print("night saved:", controller.run(night))
    print(controller.report())


if __name__ == "__main__":
    main()

