    "basic": (6, 17),
    "plus": (5, 22),
    "premium": (0, 24),
}


class GymFloor:
    """Tracks members, occupancy and refused entries for a single gym floor."""

    def __init__(self, max_capacity=30):
        self.max_capacity = max_capacity
        self._members = {}
        self._occupants = set()
        self._denials = []

    def register(self, name, tier):
        if tier not in TIER_WINDOWS:
            raise ValueError("unknown membership tier: %r" % (tier,))
        self._members[name] = tier

    def _tier_allows(self, name, hour):
        start, end = TIER_WINDOWS[self._members[name]]
        return start <= hour < end

    def _has_room(self):
        return len(self._occupants) < self.max_capacity

    def _record_entry(self, name):
        self._occupants.add(name)

    def _record_denial(self, name, hour, reason):
        self._denials.append((name, hour, reason))

    def enter(self, name, hour):
        if not 0 <= hour < 24:
            raise ValueError("hour out of range: %r" % (hour,))
        if name not in self._members:
            self._record_denial(name, hour, "not registered")
            return False
        if not self._tier_allows(name, hour):
            self._record_denial(name, hour, "%s tier barred at this hour" % self._members[name])
            return False
        if not self._has_room():
            self._record_denial(name, hour, "facility at capacity")
            return False
        self._record_entry(name)
        return True

    def leave(self, name):
        self._occupants.discard(name)

    def occupancy(self):
        return len(self._occupants)

    def denied_count(self):
        return len(self._denials)

    def denial_report(self):
        return "\n".join(
            "%s denied at %02d:00 - %s" % (name, hour, reason)
            for name, hour, reason in self._denials
        )


def apply_swipes(floor, swipes):
    for swipe in swipes:
        action = swipe[0]
        if action == "register":
            floor.register(swipe[1], swipe[2])
        elif action == "enter":
            floor.enter(swipe[1], swipe[2])
        elif action == "leave":
            floor.leave(swipe[1])
        else:
            raise ValueError("unknown swipe action: %r" % (action,))
    return floor


def gym(swipes):
    return apply_swipes(GymFloor(), swipes).denied_count()


def main():
    swipes = [
        ("register", "bob", "basic"),
        ("register", "ada", "premium"),
        ("enter", "bob", 18),
        ("enter", "ada", 18),
        ("enter", "eve", 9),
        ("enter", "bob", 9),
        ("leave", "ada"),
    ]
    floor = apply_swipes(GymFloor(max_capacity=2), swipes)
    print("denied entries:", gym(swipes))
    print("currently inside:", floor.occupancy())
    print(floor.denial_report())


