        self.rudder = self.rudder_for(turn, self.tacking)
        self.heading = target
        self.wind_angle = wind
        self.log.append((target, wind, turn, self.rudder, self.tacking))
        return self.rudder

    def run(self, instructions):
        return [self.step(item) for item in instructions]

    def report(self):
        lines = ["heading  wind  turn  rudder  mode"]
        for target, wind, turn, rudder, tacking in self.log:
            mode = "tacking" if tacking else "cruising"
            lines.append("%7d %5d %5d %7d  %s" % (target, wind, turn, rudder, mode))
        return "\n".join(lines)


def navigate(instructions):
    pilot = SailboatAutopilot()
    return pilot.run(instructions)


