class CombatSimulator:
    """Resolves a stream of combat actions for a single character."""

    def __init__(self, armor=5):
        self.health = 100
        self.max_stamina = 50
        self.stamina = self.max_stamina
        self.armor = armor
        self._guarded = False
        self._log = []

    def _mitigate(self, raw):
        return max(0, raw - self.armor - int(raw * 0.1))

    def _block_cost(self, raw):
        return max(1, raw // 2 + self.armor // 5)

    def _is_dead(self):
        if self.health <= 0:
            self.health = 0
            return True
        return False

    def _attack(self, raw):
        if self._guarded:
            self._guarded = False
            self._log.append("blocked an attack of %d" % raw)
            return
        damage = self._mitigate(raw)
        self.health -= damage
        self._log.append("took %d damage" % damage)

    def _block(self, raw):
        cost = self._block_cost(raw)
        if cost > self.stamina:
            self._log.append("failed to block, %d stamina needed" % cost)
            return
        self.stamina -= cost
        self._guarded = True
        self._log.append("raised a guard for %d stamina" % cost)

    def _rest(self, raw):
        before = self.stamina
        self.stamina = min(self.max_stamina, self.stamina + raw)
        self._log.append("recovered %d stamina" % (self.stamina - before))

    def resolve(self, actions):
        handlers = {"attack": self._attack, "block": self._block, "rest": self._rest}
        for kind, value in actions:
            if kind not in handlers:
                raise ValueError("unknown action type: %r" % (kind,))
            handlers[kind](abs(int(value)))
            if self._is_dead():
                self._log.append("collapsed")
                break
        return self.health, self.stamina

    def narrate(self):
        return "; ".join(self._log)


def fight(actions):
    return CombatSimulator().resolve(actions)


def format_report(health, stamina):
    state = "alive" if health > 0 else "defeated"
    return "health=%d stamina=%d (%s)" % (health, stamina, state)


def main():
    skirmish = [("attack", 20), ("block", 30), ("attack", 40), ("rest", 25)]
    print(format_report(*fight(skirmish)))
    rout = CombatSimulator()
    print(format_report(*rout.resolve([("attack", 200), ("rest", 50)])))
    print(rout.narrate())


if __name__ == "__main__":
    main()

