class LandscapeController:
    """Evaluates soil sensor events for three irrigation zones."""

    _CRITICAL_MOISTURE = 30.0
    _ABSORPTION_PER_MINUTE = 2.0

    def __init__(self, baseline_minutes=20):
        self._baseline = float(baseline_minutes)
        self._levels = {"A": 45.0, "B": 45.0, "C": 45.0}
        self._forecast = "unknown"
        self._log = []

    def _validate(self, event):
        try:
            zone, moisture, rain = event
        except (TypeError, ValueError):
            raise ValueError("each sensor event needs (zone, moisture, rain)")
        if zone not in self._levels:
            raise ValueError("unknown zone: %r" % (zone,))
        moisture = float(moisture)
        rain = float(rain)
        if not 0.0 <= moisture <= 100.0:
            raise ValueError("moisture percentage out of range: %r" % (moisture,))
        if not 0.0 <= rain <= 100.0:
            raise ValueError("rain probability out of range: %r" % (rain,))
        return zone, moisture, rain

    def _sync(self, zone, reading):
        stored = self._levels[zone]
        self._levels[zone] = max(stored, reading)
        return self._levels[zone]

    def _is_critical(self, level):
        return level < self._CRITICAL_MOISTURE

    def _scale_duration(self, rain):
        factor = max(0.0, 1.0 - rain / 100.0)
        return round(self._baseline * factor, 1)

    def _update_forecast(self, rain):
        if rain >= 60.0:
            self._forecast = "rain likely"
        elif rain >= 25.0:
            self._forecast = "showers possible"
        else:
            self._forecast = "clear"

    def _absorb(self, zone, minutes):
        stored = self._levels[zone]
        gain = minutes * self._ABSORPTION_PER_MINUTE
        self._levels[zone] = min(100.0, stored + gain)

    def run(self, sensors):
        durations = []
        for event in sensors:
            zone, moisture, rain = self._validate(event)
            level = self._sync(zone, moisture)
            self._update_forecast(rain)
            minutes = self._scale_duration(rain) if self._is_critical(level) else 0.0
            self._absorb(zone, minutes)
            self._log.append((zone, level, minutes))
            durations.append(minutes)
        return durations

    def report(self):
        lines = ["forecast: " + self._forecast]
        for zone, level, minutes in self._log:
            final = self._levels[zone]
            lines.append("zone %s: %.1f%% -> water %.1f min (now %.1f%%)"
                         % (zone, level, minutes, final))
        return "\n".join(lines)


def irrigate(sensors):
    controller = LandscapeController()
    return controller.run(sensors)


if __name__ == "__main__":
    readings = [("A", 22, 10), ("B", 55, 40), ("C", 18, 70), ("A", 26, 0)]
    print(irrigate(readings))
    long_cycle = LandscapeController(baseline_minutes=25)
    long_cycle.run(readings)
    print(long_cycle.report())

