import math


class ObservatoryTracker:
    """Tracks a dish's pointing state and the thermal load of its motors."""

    AMBIENT = 20.0
    MAX_MOTOR_TEMP = 90.0
    COOLDOWN_SECONDS = 30.0
    HEAT_PER_DEGREE = 0.6

    def __init__(self, start_az=0.0, start_el=0.0):
        self._azimuth, self._elevation = self._normalize((start_az, start_el))
        self._temperature = self.AMBIENT

    def _normalize(self, target):
        raw_az, raw_el = target
        el = float(raw_el)
        if not -90.0 <= el <= 90.0:
            raise ValueError("elevation %r outside [-90, 90]" % (el,))
        return float(raw_az) % 360.0, el

    def _azimuth_delta(self, goal_az):
        raw = (goal_az - self._azimuth) % 360.0
        return raw if raw <= 180.0 else 360.0 - raw

    def _separation(self, goal_az, goal_el):
        d_az = math.radians(self._azimuth_delta(goal_az))
        e1, e2 = math.radians(self._elevation), math.radians(goal_el)
        cos_sep = math.sin(e1) * math.sin(e2) + math.cos(e1) * math.cos(e2) * math.cos(d_az)
        return math.degrees(math.acos(max(-1.0, min(1.0, cos_sep))))

    def _absorb_heat(self, distance):
        self._temperature += self.HEAT_PER_DEGREE * distance

    def _cooldown(self):
        self._temperature = self.AMBIENT
        return self.COOLDOWN_SECONDS

    def slew(self, target):
        goal_az, goal_el = self._normalize(target)
        distance = self._separation(goal_az, goal_el)
        self._azimuth, self._elevation = goal_az, goal_el
        self._absorb_heat(distance)
        elapsed = distance
        if self._temperature > self.MAX_MOTOR_TEMP:
            elapsed += self._cooldown()
        return elapsed


def align(targets):
    tracker = ObservatoryTracker()
    return [tracker.slew(target) for target in targets]


def format_report(targets, times):
    lines = []
    for (az, el), seconds in zip(targets, times):
        marker = "cooldown" if seconds > 180.0 else ""
        lines.append("az=%7.2f el=%6.2f -> %8.2f s %s" % (az, el, seconds, marker))
    lines.append("total: %.2f s over %d moves" % (sum(times), len(times)))
    return "\n".join(lines)


def main():
    targets = [(120.0, 30.0), (350.0, 75.0), (10.0, 5.0), (200.0, 60.0)]
    print(format_report(targets, align(targets)))


if __name__ == "__main__":
    main()

