def _size_of(path):
    return 64 + 8 * len(path)


class RemoteSyncAgent:
    """Simulates a remote file system and applies local changes to it."""

    VALID_ACTIONS = ("create", "modify", "delete")

    def __init__(self, remote_state=None):
        self._remote = dict(remote_state or {})
        self._bytes = 0
        self._skipped = 0
        self._errors = []

    def _validate(self, op):
        try:
            action = op["action"]
            path = op["path"]
        except (TypeError, KeyError):
            raise ValueError("malformed operation: %r" % (op,))
        if action not in self.VALID_ACTIONS:
            raise ValueError("unknown action %r for %r" % (action, path))
        return action, path, op.get("timestamp", 0)

    def _exists(self, path):
        return path in self._remote

    def _is_newer(self, path, timestamp):
        return timestamp > self._remote[path]

    def _transfer(self, path):
        sent = _size_of(path)
        self._bytes += sent
        return sent

    def _skip(self, reason):
        self._errors.append(reason)
        self._skipped += 1

    def apply(self, op):
        try:
            action, path, timestamp = self._validate(op)
        except ValueError as exc:
            self._skip(str(exc))
            return
        if action == "create":
            if self._exists(path):
                self._skip("already present remotely: %s" % path)
            else:
                self._remote[path] = timestamp
                self._transfer(path)
        elif action == "modify":
            if not self._exists(path):
                self._skip("missing remotely, cannot modify: %s" % path)
            elif not self._is_newer(path, timestamp):
                self._skip("remote copy is up to date: %s" % path)
            else:
                self._remote[path] = timestamp
                self._transfer(path)
        elif not self._exists(path):
            self._skip("missing remotely, cannot delete: %s" % path)
        else:
            del self._remote[path]

    def totals(self):
        return self._bytes, self._skipped

    def report(self):
        lines = ["remote files: %d" % len(self._remote)]
        for path in sorted(self._remote):
            lines.append("  %s @ %s" % (path, self._remote[path]))
        lines.append("bytes transferred: %d" % self._bytes)
        for error in self._errors:
            lines.append("  ! " + error)
        return "\n".join(lines)


def synchronize(operations):
    agent = RemoteSyncAgent()
    for op in operations:
        agent.apply(op)
    print(agent.report())
    return agent.totals()


if __name__ == "__main__":
    changes = [
        {"action": "create", "path": "docs/readme.md", "timestamp": 100},
        {"action": "modify", "path": "docs/readme.md", "timestamp": 150},
        {"action": "modify", "path": "docs/readme.md", "timestamp": 120},
        {"action": "create", "path": "src/main.py", "timestamp": 200},
        {"action": "delete", "path": "src/old.py", "timestamp": 210},
        {"action": "rename", "path": "src/main.py", "timestamp": 220},
        {"action": "delete", "path": "src/main.py", "timestamp": 230},
    ]
    print("result: %s" % (synchronize(changes),))

