class AuctionHouse:
    """Runs an online auction: tracks leading bids, history and reserve prices."""

    def __init__(self, reserve_prices=None):
        self.reserves = {}
        self.highest_bid = {}
        self.leading = {}
        self.bid_log = []
        self.load(reserve_prices or {})

    def load(self, reserve_prices):
        for item, price in reserve_prices.items():
            self.reserves[str(item)] = float(price)

    def reserve_for(self, item):
        return self.reserves.get(item, 0.0)

    @staticmethod
    def unpack(offer):
        if isinstance(offer, dict):
            return offer["bidder"], offer["item"], float(offer["amount"])
        bidder, item, amount = offer
        return bidder, item, float(amount)

    def accepts(self, item, amount):
        return amount > self.reserve_for(item) and amount > self.highest_bid.get(item, 0.0)

    def log(self, bidder, item, amount, accepted):
        self.bid_log.append({"bidder": bidder, "item": item,
                              "amount": amount, "accepted": accepted})

    def record(self, bidder, item, amount):
        self.highest_bid[item] = amount
        self.leading[item] = bidder

    def evaluate(self, bids):
        for offer in bids:
            bidder, item, amount = self.unpack(offer)
            accepted = self.accepts(item, amount)
            if accepted:
                self.record(bidder, item, amount)
            self.log(bidder, item, amount, accepted)
        return [[self.leading[item], self.highest_bid[item]] for item in sorted(self.leading)]

    def bid_history(self):
        return list(self.bid_log)

    def summary(self):
        lines = []
        for item in sorted(self.reserves):
            reserve = self.reserve_for(item)
            if item in self.leading:
                lines.append("%s: sold to %s for $%.2f (reserve $%.2f)"
                             % (item, self.leading[item], self.highest_bid[item], reserve))
            else:
                lines.append("%s: unsold, reserve $%.2f not met" % (item, reserve))
        return "\n".join(lines)


def main():
