class HotelReservationSystem:
    """Tracks room stock, guest assignments, maintenance and revenue."""

    MAINTENANCE_NIGHTS = 1

    def __init__(self, inventory):
        self._cache = {}
        self._available = self._load(inventory)
        self.assignments = {}
        self.maintenance = []
        self.revenue = 0.0

    def _load(self, inventory):
        pools = {}
        for room_type, count in inventory.items():
            key = str(room_type).strip().lower()
            if int(count) < 0:
                raise ValueError("room count cannot be negative: %r" % (count,))
            pools[key] = ["%s-%03d" % (key[:3].upper(), i + 1) for i in range(int(count))]
        return pools

    def _normalize(self, booking):
        name = str(booking["guest"]).strip()
        room_type = str(booking["room_type"]).strip().lower()
        nights = int(booking["nights"])
        rate = float(booking["price_per_night"])
        if not name or nights <= 0 or rate < 0:
            raise ValueError("invalid booking request for %r" % (name or "<unnamed>",))
        return name, room_type, nights, rate

    def _take_room(self, room_type):
        pool = self._available.get(room_type)
        if not pool:
            return None
        return pool.pop(0)

    def _charge(self, nights, rate):
        key = (nights, rate)
        if key not in self._cache:
            self._cache[key] = round(nights * rate, 2)
        return self._cache[key]

    def _send_to_maintenance(self, room, nights):
        self.maintenance.append({
            "room": room,
            "starts_after_night": nights,
            "duration": self.MAINTENANCE_NIGHTS,
        })

    def reserve(self, bookings):
        confirmed = []
        for booking in bookings:
            name, room_type, nights, rate = self._normalize(booking)
            room = self._take_room(room_type)
            if room is None:
                continue
            self.assignments[name] = room
            self.revenue = round(self.revenue + self._charge(nights, rate), 2)
            self._send_to_maintenance(room, nights)
            confirmed.append(name)
        return self.revenue, confirmed

    def _format_line(self, guest, room):
        return "  %-10s -> %s" % (guest, room)

    def report(self):
        lines = ["Revenue: %.2f" % self.revenue]
        for guest, room in self.assignments.items():
            lines.append(self._format_line(guest, room))
        lines.append("Rooms in maintenance: %d" % len(self.maintenance))
        for room_type, pool in sorted(self._available.items()):
            lines.append("  %s still free: %d" % (room_type, len(pool)))
        return "\n".join(lines)


def main():
    hotel = HotelReservationSystem({"suite": 1, "double": 2})
    requests = [
        {"guest": "Alice", "room_type": "suite", "nights": 3, "price_per_night": 200.0},
        {"guest": "Bob", "room_type": "suite", "nights": 2, "price_per_night": 200.0},
        {"guest": "Cleo", "room_type": "double", "nights": 4, "price_per_night": 90.5},
    ]
    revenue, guests = hotel.reserve(requests)
    print("Total revenue: %.2f" % revenue)
    print("Confirmed guests: %s" % ", ".join(guests))
    print(hotel.report())


if __name__ == "__main__":
    main()

