class Auditorium:
    """Seat assignment bookkeeping for a single movie theater auditorium."""

    def __init__(self, rows, cols):
        self._validate_dimensions(rows, cols)
        self.rows = rows
        self.cols = cols
        self.occupied = set()
        self.tickets_sold = 0
        self.turned_away = []
        self._cache = {}

    @staticmethod
    def _validate_dimensions(rows, cols):
        if not isinstance(rows, int) or not isinstance(cols, int):
            raise TypeError("rows and cols must be integers")
        if rows <= 0 or cols <= 0:
            raise ValueError("auditorium must have at least one seat")

    def _normalize(self, groups):
        for entry in groups:
            if isinstance(entry, dict):
                name, size = entry["name"], entry["size"]
            else:
                name, size = entry
            if not isinstance(size, int) or size <= 0:
                raise ValueError("group %r must have a positive size" % (name,))
            yield name, size

    def _longest_free_run(self, row):
        if row not in self._cache:
            best = run = 0
            for col in range(self.cols):
                run = 0 if (row, col) in self.occupied else run + 1
                best = max(best, run)
            self._cache[row] = best
        return self._cache[row]

    def _find_block(self, row, size):
        run = 0
        for col in range(self.cols):
            run = 0 if (row, col) in self.occupied else run + 1
            if run == size:
                return col - size + 1
        return None

    def _occupy(self, row, start, size):
        for col in range(start, start + size):
            self.occupied.add((row, col))
        self._cache.pop(row, None)

    def book(self, groups):
        for name, size in self._normalize(groups):
            placed = False
            for row in range(self.rows):
                if self._longest_free_run(row) < size:
                    continue
                start = self._find_block(row, size)
                if start is not None:
                    self._occupy(row, start, size)
                    self.tickets_sold += size
                    placed = True
                    break
            if not placed:
                self.turned_away.append(name)
        return self.tickets_sold, len(self.turned_away)

    def _format_row(self, row):
        seats = ("#" if (row, col) in self.occupied else "." for col in range(self.cols))
        return "Row %2d: %s" % (row + 1, "".join(seats))

    def seating_chart(self):
        return "\n".join(self._format_row(row) for row in range(self.rows))


def main():
    hall = Auditorium(4, 6)
    sold, refused = hall.book([("Alvarez", 4), {"name": "Bao", "size": 6},
                               ("Chen", 3), ("Dubois", 5), ("Eriksen", 2)])
    print(hall.seating_chart())
    print("tickets sold: %d, groups turned away: %d" % (sold, refused))
    print("unaccommodated:", ", ".join(hall.turned_away) or "none")

    small = Auditorium(2, 4)
    print(small.book([("Fischer", 5)]))


if __name__ == "__main__":
    main()

