from collections import deque


class PrinterSpooler:
    """Manage a networked printer: ink, paper, waiting queue and print history."""

    def __init__(self, ink=100, paper=50):
        self.ink = ink
        self.paper = paper
        self.queue = deque()
        self.history = []
        self._rejections = {}

    def _normalize(self, job):
        """Turn a raw request into a (name, pages, color) triple."""
        if isinstance(job, dict):
            name = job["name"]
            pages = job["pages"]
            color = job.get("color", False)
        else:
            name, pages, color = job
        pages = int(pages)
        if pages <= 0:
            raise ValueError("job %r must have a positive page count" % (name,))
        return str(name), pages, bool(color)

    def _cost(self, pages, color):
        """Ink and paper needed for a job of the given size."""
        return pages * (2 if color else 1), pages

    def _can_print(self, ink_needed, paper_needed):
        return self.ink >= ink_needed and self.paper >= paper_needed

    def _defer(self, name, pages, color, ink_needed):
        """Queue a job that cannot run yet and remember why."""
        self.queue.append((name, pages, color))
        if self.ink < ink_needed:
            self._rejections[name] = "ink"
        else:
            self._rejections[name] = "paper"

    def spool(self, jobs):
        for job in jobs:
            name, pages, color = self._normalize(job)
            ink_needed, paper_needed = self._cost(pages, color)
            if self._can_print(ink_needed, paper_needed):
                self.ink -= ink_needed
                self.paper -= paper_needed
                self.history.append(name)
            else:
                self._defer(name, pages, color, ink_needed)
        return self.paper, len(self.queue)

    def retry(self):
        """Re-spool everything waiting; jobs that still fail go back in line."""
        pending = list(self.queue)
        self.queue.clear()
        return self.spool(pending)

    def report(self):
        lines = ["ink=%d paper=%d" % (self.ink, self.paper),
                 "printed: " + (", ".join(self.history) or "(none)")]
        for name, pages, color in self.queue:
            lines.append("waiting: %s (%d pages, %s) - out of %s"
                         % (name, pages, "color" if color else "mono",
                            self._rejections[name]))
        return "\n".join(lines)


def main():
    spooler = PrinterSpooler(ink=15, paper=40)
    paper_left, waiting = spooler.spool([
        ("report.pdf", 10, True),
        ("memo.txt", 5, False),
        {"name": "flyer.png", "pages": 4, "color": True},
    ])
    print("after first batch: paper=%d waiting=%d" % (paper_left, waiting))
    print(spooler.report())
    print("after retry: paper=%d waiting=%d" % spooler.retry())
    print(spooler.report())


if __name__ == "__main__":
    main()

