class WalletLedger:
    """Digital wallet ledger with pending transfers and blocked funds."""

    DEPOSIT = "deposit"
    INITIATE = "initiate"
    RESOLVE = "resolve"

    def __init__(self, opening=0.0):
        self._balance = float(opening)
        self._blocked = 0.0
        self._pending = {}
        self._history = []

    @staticmethod
    def _parse(command):
        if isinstance(command, dict):
            return command["op"], float(command["amount"]), command["id"]
        op, amount, txid = command
        return op, float(amount), txid

    def _validate(self, op, amount):
        if op not in (self.DEPOSIT, self.INITIATE, self.RESOLVE):
            raise ValueError("unknown operation: %r" % (op,))
        if amount <= 0:
            raise ValueError("amount must be positive, got %r" % (amount,))

    def _credit(self, amount, txid):
        self._balance += amount
        self._history.append(txid)

    def _block(self, amount, txid):
        if amount > self._balance:
            return
        self._balance -= amount
        self._blocked += amount
        self._pending[txid] = amount

    def _release(self, amount, txid):
        if txid not in self._pending:
            return
        del self._pending[txid]
        self._blocked -= amount
        self._history.append(txid)

    def execute(self, commands):
        handlers = {
            self.DEPOSIT: self._credit,
            self.INITIATE: self._block,
            self.RESOLVE: self._release,
        }
        for command in commands:
            op, amount, txid = self._parse(command)
            self._validate(op, amount)
            handlers[op](amount, txid)
        return self._balance, self._blocked

    def report(self):
        lines = ["available: %.2f" % self._balance,
                 "blocked:   %.2f" % self._blocked]
        for txid, amount in self._pending.items():
            lines.append("  pending %s -> %.2f" % (txid, amount))
        lines.append("completed: " + (", ".join(self._history) or "none"))
        return "\n".join(lines)


def main():
    ledger = WalletLedger()
    available, reserved = ledger.execute([
        ("deposit", 100, "d1"),
        ("initiate", 40, "t1"),
        ("deposit", 25, "d2"),
        ("initiate", 500, "t2"),
        {"op": "initiate", "amount": 15, "id": "t3"},
        ("resolve", 40, "t1"),
    ])
    print("available=%.2f blocked=%.2f" % (available, reserved))
    print(ledger.report())


if __name__ == "__main__":
    main()

