from collections import deque


class GateScheduler:
    """Assigns arriving planes to terminal gates over a timeline of events."""

    TICK = "tick"

    def __init__(self, gates):
        self._available = set(gates)
        self._occupied = {}
        self._boarded = 0
        self._delayed = deque()

    def _validate(self, event):
        if not isinstance(event, (tuple, list)) or len(event) != 2:
            raise ValueError("each event must be a (flight, duration) pair")
        flight, duration = event
        if not isinstance(duration, int) or isinstance(duration, bool):
            raise ValueError("duration must be an integer: %r" % (duration,))
        if flight != self.TICK and duration <= 0:
            raise ValueError("arriving flight %r needs a positive duration" % (flight,))

    def _release(self, gate):
        del self._occupied[gate]
        self._available.add(gate)
        self._boarded += 1

    def _advance_time(self):
        for gate in list(self._occupied):
            self._occupied[gate] -= 1
            if self._occupied[gate] <= 0:
                self._release(gate)

    def _assign(self, flight, duration):
        gate = min(self._available)
        self._available.discard(gate)
        self._occupied[gate] = duration
        return gate

    def _enqueue(self, flight):
        self._delayed.append(flight)

    def schedule(self, flights):
        for event in flights:
            self._validate(event)
            flight, duration = event
            if flight == self.TICK:
                self._advance_time()
            elif self._available:
                self._assign(flight, duration)
            else:
                self._enqueue(flight)
        return self._boarded, len(self._delayed)

    def report(self):
        lines = ["boarded: %d" % self._boarded]
        for gate in sorted(self._occupied):
            lines.append("gate %s busy for %d more tick(s)" % (gate, self._occupied[gate]))
        for gate in sorted(self._available):
            lines.append("gate %s free" % (gate,))
        if self._delayed:
            lines.append("delayed: " + ", ".join(str(f) for f in self._delayed))
        return "\n".join(lines)


def main():
    single = GateScheduler(["A1"])
    print(single.schedule([("AZ100", 2), ("AZ200", 3)]))
    print(single.report())
    print("---")
    busy = GateScheduler(["B1", "B2"])
    events = [("LH1", 1), ("LH2", 2), ("LH3", 1),
              ("tick", 0), ("tick", 0), ("LH4", 1), ("tick", 0)]
    print(busy.schedule(events))
    print(busy.report())


if __name__ == "__main__":
    main()

