class VirtualClassRegistry:
    """Manages student registrations, waiting lists and tuition for virtual classes."""

    def __init__(self, capacities):
        self._capacity = dict(capacities)
        self._enrolled = {course: [] for course in self._capacity}
        self._waitlist = {course: [] for course in self._capacity}
        self._tuition_total = 0.0

    def _parse(self, form):
        try:
            student = form["student"]
            course = form["course"]
            fee = float(form.get("fee", 0.0))
            action = str(form.get("action", "enroll")).lower()
        except (TypeError, KeyError) as exc:
            raise ValueError("malformed registration form: {}".format(form)) from exc
        if action not in ("enroll", "drop"):
            raise ValueError("unsupported action: {!r}".format(action))
        if course not in self._capacity:
            raise KeyError("unknown course: {!r}".format(course))
        return student, course, fee, action

    def _has_seat(self, course):
        return len(self._enrolled[course]) < self._capacity[course]

    def _waiting_count(self):
        return sum(len(names) for names in self._waitlist.values())

    def enroll(self, requests):
        for form in requests:
            student, course, fee, action = self._parse(form)
            if action == "enroll":
                if self._has_seat(course):
                    self._enrolled[course].append(student)
                    self._tuition_total += fee
                else:
                    self._waitlist[course].append(student)
            elif student in self._enrolled[course]:
                self._enrolled[course].remove(student)
        return self._tuition_total, self._waiting_count()

    def roster(self, course):
        if course not in self._enrolled:
            raise KeyError("unknown course: {!r}".format(course))
        return list(self._enrolled[course])

    def report(self):
        lines = ["Tuition collected: ${:.2f}".format(self._tuition_total)]
        for course in sorted(self._capacity):
            lines.append(
                "{}: {}/{} enrolled [{}] | waiting: {}".format(
                    course,
                    len(self._enrolled[course]),
                    self._capacity[course],
                    ", ".join(self._enrolled[course]) or "-",
                    ", ".join(self._waitlist[course]) or "-",
                )
            )
        return "\n".join(lines)


def main():
    registry = VirtualClassRegistry({"Algebra": 2, "Poetry": 3})
    forms = [
        {"student": "Ana", "course": "Algebra", "fee": 100, "action": "enroll"},
        {"student": "Ben", "course": "Algebra", "fee": 100, "action": "enroll"},
        {"student": "Cleo", "course": "Algebra", "fee": 100, "action": "enroll"},
        {"student": "Ana", "course": "Algebra", "fee": 100, "action": "drop"},
        {"student": "Dan", "course": "Poetry", "fee": 80, "action": "enroll"},
    ]
    collected, waiting = registry.enroll(forms)
    print("Collected: {:.2f}, waitlisted: {}".format(collected, waiting))
    print("Algebra roster:", registry.roster("Algebra"))
    print(registry.report())


if __name__ == "__main__":
    main()

