class PlacementEngine:
    """Pairs job seekers with open employment positions and tracks earned fees."""

    def __init__(self):
        self.candidates = {}
        self.jobs = {}
        self.placements = 0
        self.earnings = 0.0
        self._cache = {}
        self._aliases = None

    def _load(self):
        if self._aliases is None:
            self._aliases = {
                "py": "python",
                "js": "javascript",
                "golang": "go",
                "postgres": "postgresql",
                "c sharp": "c#",
            }
        return self._aliases

    def _canon(self, skills):
        key = tuple(skills)
        if key not in self._cache:
            table = self._load()
            cleaned = (str(s).strip().lower() for s in key)
            self._cache[key] = frozenset(table.get(s, s) for s in cleaned if s)
        return self._cache[key]

    def _parse(self, action):
        kind = str(action["type"]).strip().lower()
        if kind not in ("job", "candidate"):
            raise ValueError("unknown activity type: %r" % (action["type"],))
        name = str(action["name"]).strip()
        if not name:
            raise ValueError("activity is missing a name")
        return kind, name, action.get("skills") or [], float(action.get("fee") or 0.0)

    def _add_posting(self, name, skills, fee):
        self.jobs[name] = (self._canon(skills), fee)

    def _add_profile(self, name, skills):
        self.candidates[name] = self._canon(skills)

    def _find_pair(self):
        for job_name, (required, _fee) in self.jobs.items():
            for candidate_name, owned in self.candidates.items():
                if required <= owned:
                    return candidate_name, job_name
        return None

    def _settle(self, candidate_name, job_name):
        _required, fee = self.jobs.pop(job_name)
        del self.candidates[candidate_name]
        self.placements += 1
        self.earnings += fee

    def _scan(self):
        pair = self._find_pair()
        while pair is not None:
            self._settle(*pair)
            pair = self._find_pair()

    def match(self, actions):
        for action in actions:
            kind, name, skills, fee = self._parse(action)
            if kind == "job":
                self._add_posting(name, skills, fee)
            else:
                self._add_profile(name, skills)
            self._scan()
        return self.placements, self.earnings

    def summary(self):
        return "placements=%d earned=$%.2f open_jobs=%d waiting_candidates=%d" % (
            self.placements, self.earnings, len(self.jobs), len(self.candidates))


def main():
    stream = [
        {"type": "job", "name": "Backend Dev", "skills": ["Python", "SQL"], "fee": 500},
        {"type": "candidate", "name": "Ada", "skills": ["py", "postgres"], "fee": 0},
        {"type": "candidate", "name": "Bob", "skills": ["Python", "SQL", "Go"], "fee": 0},
        {"type": "job", "name": "Platform Eng", "skills": ["golang"], "fee": 750.5},
        {"type": "job", "name": "Designer", "skills": ["Figma"], "fee": 300},
    ]
    engine = PlacementEngine()
    print(engine.match(stream))
    print(engine.summary())


if __name__ == "__main__":
    main()

