class RewardProgram:
    _TIERS = ("basic", "silver", "gold")
    _MID_THRESHOLD = 1000
    _TOP_THRESHOLD = 5000

    def __init__(self):
        self.balances = {}
        self.tiers = {}
        self.bonuses = []
        self.total_issued = 0.0

    def _tier_of(self, customer):
        return self.tiers.setdefault(customer, self._TIERS[0])

    def _multiplier(self, customer):
        if self._tier_of(customer) == self._TIERS[2]:
            return 1.5
        return 1.0

    def _award(self, customer, amount):
