class CourierNetwork:
    def __init__(self, capacities):
        self.capacities = dict(capacities)
        self.hub_loads = {hub: 0 for hub in self.capacities}
        self.in_transit = []
        self.delivered = 0
        self._rejections = {}

    def _capacity_of(self, hub):
        if hub not in self.capacities:
            raise KeyError("unknown hub: %s" % hub)
        return self.capacities[hub]

    def _normalize(self, shipment):
        if isinstance(shipment, dict):
            event = shipment["event"]
            package = shipment["package"]
            hub = shipment["hub"]
            size = shipment["size"]
        else:
            event, package, hub, size = shipment
        size = int(size)
        if size < 0:
            raise ValueError("negative package size for %s" % package)
        return str(event).lower(), package, hub, size

    def _dispatch(self, package, hub, size):
        limit = self._capacity_of(hub)
        current = self.hub_loads.get(hub, 0)
        if current + size <= limit:
            self.hub_loads[hub] = current + size
        else:
            self.in_transit.append(package)
            self._rejections[hub] = self._rejections.get(hub, 0) + 1

    def _deliver(self, hub, size):
        self._capacity_of(hub)
        self.hub_loads[hub] = self.hub_loads.get(hub, 0) - size
        self.delivered += 1

    def route(self, shipments):
        for shipment in shipments:
            event, package, hub, size = self._normalize(shipment)
            if event == "dispatch":
                self._dispatch(package, hub, size)
            elif event == "delivery":
                self._deliver(hub, size)
            else:
                raise ValueError("unsupported event: %s" % event)
        return self.delivered, len(self.in_transit)

    def report(self):
        lines = ["delivered=%d in_transit=%d" % (self.delivered, len(self.in_transit))]
        for hub in sorted(self.capacities):
            lines.append(
                "  %-8s %4d/%-4d overflows=%d"
                % (hub, self.hub_loads.get(hub, 0), self._capacity_of(hub),
                   self._rejections.get(hub, 0))
            )
        if self.in_transit:
            lines.append("  pending: " + ", ".join(str(p) for p in self.in_transit))
        return "\n".join(lines)


def main():
    network = CourierNetwork({"north": 100, "south": 50, "depot": 20})
    shipments = [
        ("dispatch", "PKG-1", "north", 60),
        ("dispatch", "PKG-2", "south", 40),
        ("dispatch", "PKG-3", "depot", 35),
        {"event": "dispatch", "package": "PKG-4", "hub": "north", "size": 30},
        ("delivery", "PKG-1", "north", 60),
        ("delivery", "PKG-2", "south", 40),
    ]
    delivered, pending = network.route(shipments)
    print("result:", delivered, pending)
    print(network.report())


if __name__ == "__main__":
    main()

