import re
from collections import Counter


class Moderator:
    """Inspects chat messages, tracks strikes per user and bans repeat offenders."""

    _FORBIDDEN = ("spam", "scam", "hack")
    _STRIKE_LIMIT = 3

    def __init__(self):
        self._strikes = Counter()
        self._banned = set()
        self._filtered = 0

    def _normalize(self, message):
        return re.sub(r"[^a-z0-9]+", " ", message.lower())

    def _find_forbidden(self, message):
        text = self._normalize(message)
        return [word for word in self._FORBIDDEN if word in text]

    def _add_strike(self, username):
        self._strikes[username] += 1
        count = self._strikes[username]
        if count >= self._STRIKE_LIMIT:
            self._banned.add(username)
        return count

    def review(self, username, message):
        if username in self._banned:
            self._filtered += 1
            return "blocked"
        if not self._find_forbidden(message):
            return "allowed"
        self._filtered += 1
        if self._add_strike(username) >= self._STRIKE_LIMIT:
            return "blocked"
        return "warned"

    def report(self):
        lines = ["filtered messages: %d" % self._filtered]
        for username in sorted(self._strikes):
            status = "banned" if username in self._banned else "active"
            lines.append("%s: %d strike(s), %s" % (username, self._strikes[username], status))
        return "\n".join(lines)


def _validate(messages):
    for index, entry in enumerate(messages):
        if len(entry) != 2:
            raise ValueError("entry %d must be a (username, message) pair" % index)
        username, message = entry
        if not isinstance(username, str) or not isinstance(message, str):
            raise TypeError("entry %d must contain two strings" % index)


def moderate(messages):
    _validate(messages)
    moderator = Moderator()
    return [moderator.review(username, message) for username, message in messages]


def main():
    chat = [
        ("alice", "check out this scam offer"),
        ("bob", "hello everyone"),
        ("alice", "another scam link here"),
        ("carol", "how do I hack this puzzle?"),
        ("alice", "last scam, promise"),
        ("alice", "am I still here?"),
        ("bob", "buy cheap SPAM now!"),
    ]
    actions = moderate(chat)
    for (username, message), action in zip(chat, actions):
        print("%-6s %-9s %s" % (username, action, message))

    moderator = Moderator()
    for username, message in chat:
        moderator.review(username, message)
    print(moderator.report())


if __name__ == "__main__":
    main()

