class Drivetrain:
    """A three-by-seven drivetrain that tracks gear positions and wear."""

    _LIMITS = {"front": 3, "rear": 7}
    _COSTS = {"front": 2, "rear": 1}
    _DIRECTIONS = {"up": 1, "down": -1}

    def __init__(self):
        self._position = {"front": 1, "rear": 1}
        self._wear = 0

    def _parse(self, command):
        pieces = command.split()
        if len(pieces) != 2:
            raise ValueError("malformed command: %r" % command)
        part, direction = pieces
        if part not in self._LIMITS or direction not in self._DIRECTIONS:
            raise ValueError("unknown command: %r" % command)
        return part, direction

    def _shift(self, part, direction):
        target = self._position[part] + self._DIRECTIONS[direction]
        if 1 <= target <= self._LIMITS[part]:
            self._position[part] = target
            self._wear += self._COSTS[part]

    def _ratio(self):
        return round(self._position["front"] / self._position["rear"], 2)

    def execute(self, command):
        part, direction = self._parse(command)
        self._shift(part, direction)
        return self._ratio()

    def _describe(self):
        return "front %d/%d, rear %d/%d" % (
            self._position["front"], self._LIMITS["front"],
            self._position["rear"], self._LIMITS["rear"],
        )

    def summary(self):
        return "%s | wear %d | ratio %.2f" % (self._describe(), self._wear, self._ratio())


def ride(commands):
    bike = Drivetrain()
    return [bike.execute(command) for command in commands]


def report(commands):
    bike = Drivetrain()
    lines = ["%-11s -> %.2f" % (command, bike.execute(command)) for command in commands]
    lines.append(bike.summary())
    return lines


def main():
    route = [
        "front up", "rear up", "rear up", "front up", "front up",
        "rear down", "rear up", "rear up", "rear up", "rear up", "rear up",
    ]
    print(ride(route))
    for line in report(route):
        print(line)


if __name__ == "__main__":
    main()

