class HourlyTemperatureAggregator:
    """Streams (hour, temperature) readings and folds them into hourly averages."""

    def __init__(self):
        self._active_hour = None
        self._total = 0.0
        self._count = 0
        self._hours = []
        self._averages = []
        self._highest = None
        self._lowest = None

    def add(self, reading):
        hour, temperature = self._validate(reading)
        if self._active_hour is None:
            self._reset(hour)
        elif hour != self._active_hour:
            self._finalize()
            self._reset(hour)
        self._total += temperature
        self._count += 1
        self._track_extremes(temperature)

    def close(self):
        if self._count:
            self._finalize()
        return list(self._averages)

    @staticmethod
    def _validate(reading):
        hour, temperature = reading
        if not isinstance(hour, int) or isinstance(hour, bool):
            raise TypeError("hour must be an integer, got %r" % (hour,))
        if not 0 <= hour <= 23:
            raise ValueError("hour out of range: %d" % hour)
        return hour, float(temperature)

    def _reset(self, hour):
        self._active_hour = hour
        self._total = 0.0
        self._count = 0

    def _finalize(self):
        self._hours.append(self._active_hour)
        self._averages.append(self._total / self._count)

    def _track_extremes(self, temperature):
        if self._highest is None or temperature > self._highest:
            self._highest = temperature
        if self._lowest is None or temperature < self._lowest:
            self._lowest = temperature

    def _format_row(self, index):
        return "hour %02d: %.2f" % (self._hours[index], self._averages[index])

    def summary(self):
        rows = [self._format_row(i) for i in range(len(self._averages))]
        rows.append("min %.2f / max %.2f" % (self._lowest, self._highest))
        return "\n".join(rows)


def process(measurements):
    aggregator = HourlyTemperatureAggregator()
    for reading in measurements:
        aggregator.add(reading)
    return aggregator.close()


def report(measurements):
    aggregator = HourlyTemperatureAggregator()
    for reading in measurements:
        aggregator.add(reading)
    aggregator.close()
    return aggregator.summary()


def main():
    samples = [(1, 20.0), (1, 22.0), (2, 19.0), (2, 23.5), (3, 17.25)]
    print(process(samples))
    print(report(samples))


if __name__ == "__main__":
    main()

