import sys


class NutrientRegulator:
    """Keeps a hydroponic tank at the target acidity and nutrient level."""

    TARGET_ACIDITY = 6.0
    TARGET_NUTRIENTS = 500
    ACIDITY_LIMIT = 6.5
    NUTRIENT_FLOOR = 400
    ACID_DOSE = 10
    FERTILIZER_DOSE = 20

    def __init__(self, acid=1000, fertilizer=1000):
        self._inventory = {"acid": acid, "fertilizer": fertilizer}
        self._cycles = 0

    def _validate(self, reading):
        if not isinstance(reading, (tuple, list)) or len(reading) != 2:
            raise ValueError("each reading must be a (acidity, nutrients) pair")
        acidity, nutrients = reading
        if isinstance(acidity, bool) or not isinstance(acidity, (int, float)):
            raise TypeError("acidity must be a number")
        if isinstance(nutrients, bool) or not isinstance(nutrients, int):
            raise TypeError("nutrient concentration must be an integer")
        return float(acidity), nutrients

    def _take(self, tank, amount):
        if self._inventory[tank] < amount:
            return False
        self._inventory[tank] -= amount
        return True

    def _correct_acidity(self, acidity):
        if acidity > self.ACIDITY_LIMIT and self._take("acid", self.ACID_DOSE):
            return "dispensed acid"
        return None

    def _correct_nutrients(self, nutrients):
        if nutrients < self.NUTRIENT_FLOOR and self._take("fertilizer", self.FERTILIZER_DOSE):
            return "dispensed fertilizer"
        return None

    def _describe(self, actions):
        if not actions:
            return "no action"
        return " and ".join(actions)

    def process(self, reading):
