import sys


class NutrientRegulator:
    """Keeps a hydroponic tank at the target acidity and nutrient level."""

    TARGET_ACIDITY = 6.0
    TARGET_NUTRIENTS = 500
    ACIDITY_LIMIT = 6.5
    NUTRIENT_FLOOR = 400
    ACID_DOSE = 10
    FERTILIZER_DOSE = 20

    def __init__(self, acid=1000, fertilizer=1000):
        self.inventory = {"acid": acid, "fertilizer": fertilizer}
        self.cycles = 0

    def validate(self, reading):
        if not isinstance(reading, (tuple, list)) or len(reading) != 2:
            raise ValueError("each reading must be a (acidity, nutrients) pair")
        acidity, nutrients = reading
        if isinstance(acidity, bool) or not isinstance(acidity, (int, float)):
            raise TypeError("acidity must be a number")
        if isinstance(nutrients, bool) or not isinstance(nutrients, int):
            raise TypeError("nutrient concentration must be an integer")
        return float(acidity), nutrients

    def take(self, tank, amount):
        if self.inventory[tank] < amount:
            return False
        self.inventory[tank] -= amount
        return True

    def correct_acidity(self, acidity):
        if acidity > self.ACIDITY_LIMIT and self.take("acid", self.ACID_DOSE):
            return "dispensed acid"
        return None

    def correct_nutrients(self, nutrients):
        if nutrients < self.NUTRIENT_FLOOR and self.take("fertilizer", self.FERTILIZER_DOSE):
            return "dispensed fertilizer"
        return None

    def describe(self, actions):
        if not actions:
            return "no action"
        return " and ".join(actions)

    def process(self, reading):
        acidity, nutrients = self.validate(reading)
        actions = [
            action
            for action in (self.correct_acidity(acidity), self.correct_nutrients(nutrients))
            if action is not None
        ]
        if actions:
            self.cycles += 1
        return self.describe(actions)

