ALIGN_SYNONYMS = {
    "l": "left", "left": "left", "<": "left",
    "c": "center", "center": "center", "centre": "center", "^": "center",
    "r": "right", "right": "right", ">": "right",
}


class MarkdownTable:
    """Render raw string rows as an aligned markdown table."""

    MIN_WIDTH = 3

    def __init__(self, default_alignment="left"):
        self._default = self._canonical(default_alignment)
        self._widths = []
        self._aligns = []

    @staticmethod
    def _canonical(alignment):
        key = str(alignment).strip().lower()
        if key not in ALIGN_SYNONYMS:
            raise ValueError("unknown alignment: %r" % (alignment,))
        return ALIGN_SYNONYMS[key]

    def _normalize(self, rows):
        if not rows:
            raise ValueError("at least one row is required")
        table = []
        for row in rows:
            if isinstance(row, str):
                raise TypeError("each row must be a list of cell values")
            table.append([str(cell) for cell in row])
        columns = max(len(row) for row in table)
        for row in table:
            row.extend([""] * (columns - len(row)))
        return table

    def _measure(self, table):
        self._widths = [self.MIN_WIDTH] * len(table[0])
        for row in table:
            for index, cell in enumerate(row):
                if len(cell) > self._widths[index]:
                    self._widths[index] = len(cell)

    def _resolve_alignments(self, alignments):
        given = list(alignments or [])
        self._aligns = [self._canonical(a) for a in given]
        missing = len(self._widths) - len(self._aligns)
        if missing < 0:
            raise ValueError("more alignments than columns")
        self._aligns.extend([self._default] * missing)

    def _pad(self, text, index):
        width = self._widths[index]
        align = self._aligns[index]
        if align == "right":
            return text.rjust(width)
        if align == "center":
            return text.center(width)
        return text.ljust(width)

    def _render_row(self, cells):
        padded = [self._pad(cell, i) for i, cell in enumerate(cells)]
        return "| " + " | ".join(padded) + " |"

    def _separator(self):
        parts = []
        for width, align in zip(self._widths, self._aligns):
            if align == "center":
                parts.append(":" + "-" * (width - 2) + ":")
            elif align == "right":
                parts.append("-" * (width - 1) + ":")
            else:
                parts.append(":" + "-" * (width - 1))
        return "| " + " | ".join(parts) + " |"

    def format(self, rows, alignments=None):
        table = self._normalize(rows)
        self._measure(table)
        self._resolve_alignments(alignments)
        lines = [self._render_row(table[0]), self._separator()]
        lines.extend(self._render_row(row) for row in table[1:])
        return "\n".join(lines)


def main():
    data = [
        ["Language", "Released", "Typing"],
        ["Python", "1991", "dynamic"],
        ["Rust", "2015", "static"],
        ["C", "1972", "static"],
    ]
    table = MarkdownTable()
    print(table.format(data, ["left", "right", "center"]))


if __name__ == "__main__":
    main()

