NOTE_NAMES = ("C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B")
DIRECTIONS = ("up", "down", "alternate")


def pitch_name(pitch):
    return "{}{}".format(NOTE_NAMES[pitch % 12], pitch // 12 - 1)


def format_sequence(pitches):
    return " ".join(pitch_name(p) for p in pitches)


class Arpeggiator:
    def __init__(self, direction="up"):
        if direction not in DIRECTIONS:
            raise ValueError("unknown direction: {!r}".format(direction))
        self.direction = direction
        self._notes = ()
        self._index = 0
        self._delta = 1
        self._cache = {}

    def _sort_notes(self, chord):
        key = tuple(chord)
        if key not in self._cache:
            for pitch in chord:
                if not isinstance(pitch, int) or isinstance(pitch, bool):
                    raise TypeError("chord must contain integer pitches")
            self._cache[key] = tuple(sorted(set(chord)))
        return self._cache[key]

    def _load(self, chord):
        self._notes = self._sort_notes(chord)
        self._delta = -1 if self.direction == "down" else 1
        self._index = len(self._notes) - 1 if self.direction == "down" else 0

    def _reverse(self):
        self._delta = -self._delta

    def _advance(self):
        count = len(self._notes)
        if count < 2:
            return
        if self.direction == "alternate":
            target = self._index + self._delta
            if target < 0 or target >= count:
                self._reverse()
            self._index += self._delta
        else:
            self._index = (self._index + self._delta) % count

    @property
    def active_notes(self):
        return list(self._notes)

    @property
    def position(self):
        return self._index

    def arpeggiate(self, chord, ticks):
        if ticks < 0:
            raise ValueError("ticks must be non-negative")
        self._load(chord)
        if not self._notes:
            return []
        played = []
        for _tick in range(ticks):
            played.append(self._notes[self._index])
            self._advance()
        return played


def main():
    c_major = [60, 64, 67]
    for direction in DIRECTIONS:
        player = Arpeggiator(direction)
        first = player.arpeggiate(c_major, 4)
        second = player.arpeggiate(c_major, 6)
        print("{:>9}: {} | {}".format(direction, format_sequence(first),
                                      format_sequence(second)))
        print("           notes={} final position={}".format(
            player.active_notes, player.position))


if __name__ == "__main__":
    main()

