from itertools import zip_longest


class TypingSession:
    """Tracks one typing-test attempt against a fixed prompt."""

    def __init__(self, prompt):
        prompt = prompt.strip()
        if not prompt:
            raise ValueError("prompt must contain at least one character")
        self.prompt = prompt
        self._elapsed = 0.0
        self._correct = 0
        self._errors = 0

    @staticmethod
    def _unpack(session):
        if isinstance(session, dict):
            return session["typed"], float(session["seconds"])
        typed, seconds = session
        return typed, float(seconds)

    def _align(self, typed):
        return list(zip_longest(self.prompt, typed, fillvalue=None))

    def _mismatches(self, pairs):
        return [i for i, (expected, actual) in enumerate(pairs) if expected != actual]

    def _gross_wpm(self, typed):
        minutes = self._elapsed / 60.0
        return (len(typed) / 5.0) / minutes

    def _net_wpm(self, typed):
        minutes = self._elapsed / 60.0
        return max(0.0, self._gross_wpm(typed) - self._errors / minutes)

    def evaluate(self, session):
        typed, seconds = self._unpack(session)
        if seconds <= 0:
            raise ValueError("session duration must be positive")
        self._elapsed = seconds
        pairs = self._align(typed)
        bad = self._mismatches(pairs)
        self._errors = len(bad)
        self._correct = len(pairs) - self._errors
        accuracy = 100.0 * self._correct / len(pairs)
        return round(self._net_wpm(typed), 2), round(accuracy, 2)

    def report(self):
        return (
            "elapsed {:.1f}s | correct {} | errors {} | net {:.2f} wpm".format(
                self._elapsed, self._correct, self._errors, 0.0
                if not self._elapsed else self._net_wpm(self.prompt)
            )
        )

    def mistake_summary(self, session):
        typed, _seconds = self._unpack(session)
        pairs = self._align(typed)
        lines = []
        for i in self._mismatches(pairs):
            expected, actual = pairs[i]
            lines.append(
                "pos {}: expected {!r}, got {!r}".format(
                    i, expected or "", actual or ""
                )
            )
        return lines


def main():
    prompt = "the quick brown fox jumps over the lazy dog"
    tracker = TypingSession(prompt)

    perfect = {"typed": prompt, "seconds": 60}
    print("perfect:", tracker.evaluate(perfect))
    print(tracker.report())

    sloppy = ("the quikc brown fox jumps over the lasy dog!", 75)
    print("sloppy:", tracker.evaluate(sloppy))
    for line in tracker.mistake_summary(sloppy):
        print("  ", line)


if __name__ == "__main__":
    main()

