class SequenceAligner:
    """Local (Smith-Waterman style) aligner for genetic strings."""

    _ALPHABET = frozenset("ACGT")

    def __init__(self, match=2, mismatch=-1, gap=-1):
        self.match = match
        self.mismatch = mismatch
        self.gap = gap
        self._matrix = []
        self._pointers = {}
        self._best = (0, 0, 0)
        self._cache = {}

    def _validate(self, sequences):
        if len(sequences) != 2:
            raise ValueError("align() expects exactly two sequences")
        for seq in sequences:
            if not seq:
                raise ValueError("sequences must not be empty")
            unknown = set(seq) - self._ALPHABET
            if unknown:
                raise ValueError("unknown bases: %s" % "".join(sorted(unknown)))

    def _score(self, top_base, left_base):
        return self.match if top_base == left_base else self.mismatch

    def _initialize(self, top, left):
        self._matrix = [[0] * (len(top) + 1) for _ in range(len(left) + 1)]
        self._pointers = {}
        self._best = (0, 0, 0)

    def _fill(self, top, left):
        for i in range(1, len(left) + 1):
            for j in range(1, len(top) + 1):
                diagonal = self._matrix[i - 1][j - 1] + self._score(top[j - 1], left[i - 1])
                upwards = self._matrix[i - 1][j] + self.gap
                leftwards = self._matrix[i][j - 1] + self.gap
                cell = max(diagonal, upwards, leftwards, 0)
                self._matrix[i][j] = cell
                if cell == diagonal:
                    self._pointers[(i, j)] = "D"
                elif cell == upwards:
                    self._pointers[(i, j)] = "U"
                else:
                    self._pointers[(i, j)] = "L"
                if cell > self._best[0]:
                    self._best = (cell, i, j)

    def _backtrack(self, top, left):
        _, i, j = self._best
        top_row, left_row = [], []
        while i > 0 and j > 0 and self._matrix[i][j] > 0:
            move = self._pointers[(i, j)]
            if move == "D":
                top_row.append(top[j - 1])
                left_row.append(left[i - 1])
                i, j = i - 1, j - 1
            elif move == "U":
                top_row.append("-")
                left_row.append(left[i - 1])
                i -= 1
            else:
                top_row.append(top[j - 1])
                left_row.append("-")
                j -= 1
        return "".join(reversed(top_row)), "".join(reversed(left_row))

    def align(self, sequences):
        key = tuple(seq.upper() for seq in sequences)
        if key not in self._cache:
            self._validate(key)
            top, left = key
            self._initialize(top, left)
            self._fill(top, left)
            self._cache[key] = self._backtrack(top, left)
        return self._cache[key]

    def identity(self, sequences):
        top, left = self.align(sequences)
        same = sum(1 for a, b in zip(top, left) if a == b)
        return same / len(top)


def main():
    aligner = SequenceAligner()
    pairs = [("GATTACA", "GATTACA"), ("GATTACA", "GATACA"), ("ACGTACGT", "ACGTTCGT")]
    for pair in pairs:
        top, left = aligner.align(pair)
        print("%s vs %s" % pair)
        print("  " + top)
        print("  " + left)
        print("  identity: %.1f%%" % (100.0 * aligner.identity(pair)))


if __name__ == "__main__":
    main()

