    def initialize(self, top, left):
        self.matrix = [[0] * (len(top) + 1) for _ in range(len(left) + 1)]
        self.pointers = {}
        self.best = (0, 0, 0)

    def fill(self, top, left):
        for i in range(1, len(left) + 1):
            for j in range(1, len(top) + 1):
                diagonal = self.matrix[i - 1][j - 1] + self.score(top[j - 1], left[i - 1])
                upwards = self.matrix[i - 1][j] + self.gap
                leftwards = self.matrix[i][j - 1] + self.gap
                cell = max(diagonal, upwards, leftwards, 0)
                self.matrix[i][j] = cell
                if cell == diagonal:
                    self.pointers[(i, j)] = "D"
                elif cell == upwards:
                    self.pointers[(i, j)] = "U"
                else:
                    self.pointers[(i, j)] = "L"
                if cell > self.best[0]:
                    self.best = (cell, i, j)

    def backtrack(self, top, left):
        _, i, j = self.best
        top_row, left_row = [], []
        while i > 0 and j > 0 and self.matrix[i][j] > 0:
            move = self.pointers[(i, j)]
            if move == "D":
                top_row.append(top[j - 1])
                left_row.append(left[i - 1])
                i, j = i - 1, j - 1
            elif move == "U":
                top_row.append("-")
                left_row.append(left[i - 1])
                i -= 1
            else:
                top_row.append(top[j - 1])
                left_row.append("-")
                j -= 1
        return "".join(reversed(top_row)), "".join(reversed(left_row))

    def align(self, sequences):
        key = tuple(seq.upper() for seq in sequences)
        if key not in self.cache:
            self.validate(key)
            top, left = key
            self.initialize(top, left)
            self.fill(top, left)
            self.cache[key] = self.backtrack(top, left)
        return self.cache[key]

    def identity(self, sequences):
        top, left = self.align(sequences)
        same = sum(1 for a, b in zip(top, left) if a == b)
        return same / len(top)


def main():
    aligner = SequenceAligner()
    pairs = [("GATTACA", "GATTACA"), ("GATTACA", "GATACA"), ("ACGTACGT", "ACGTTCGT")]
    for pair in pairs:
        top, left = aligner.align(pair)
        print("%s vs %s" % pair)
        print("  " + top)
        print("  " + left)
        print("  identity: %.1f%%" % (100.0 * aligner.identity(pair)))


if __name__ == "__main__":
    main()

