import heapq


class GridNavigator:
    """A* state machine that walks a terrain-cost grid from top-left to bottom-right."""

    IMPASSABLE = 10 ** 6

    def __init__(self):
        self._open = []
        self._closed = set()
        self._came_from = {}
        self._cost = {}
        self._rows = 0
        self._cols = 0

    def _reset(self, grid):
        if not grid or not grid[0]:
            raise ValueError("grid must contain at least one cell")
        width = len(grid[0])
        if any(len(row) != width for row in grid):
            raise ValueError("grid rows must all have the same length")
        self._rows = len(grid)
        self._cols = width
        self._open = []
        self._closed = set()
        self._came_from = {}
        self._cost = {}

    def _heuristic(self, node, goal):
        return abs(node[0] - goal[0]) + abs(node[1] - goal[1])

    def _neighbors(self, node):
        row, col = node
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = row + dr, col + dc
            if 0 <= nr < self._rows and 0 <= nc < self._cols:
                yield (nr, nc)

    def _relax(self, current, neighbor, grid, goal):
        tentative = self._cost[current] + grid[neighbor[0]][neighbor[1]]
        if tentative < self._cost.get(neighbor, float("inf")):
            self._cost[neighbor] = tentative
            self._came_from[neighbor] = current
            heapq.heappush(self._open, (tentative + self._heuristic(neighbor, goal), neighbor))

    def _trace(self, goal):
        path = [goal]
        while path[-1] in self._came_from:
            path.append(self._came_from[path[-1]])
        path.reverse()
        return path

    def navigate(self, grid):
        self._reset(grid)
        start = (0, 0)
        goal = (self._rows - 1, self._cols - 1)
        self._cost[start] = grid[0][0]
        heapq.heappush(self._open, (self._heuristic(start, goal), start))
        while self._open:
            _, current = heapq.heappop(self._open)
            if current == goal:
                return self._trace(goal)
            if current in self._closed:
                continue
            self._closed.add(current)
            for neighbor in self._neighbors(current):
                if neighbor not in self._closed:
                    self._relax(current, neighbor, grid, goal)
        return []

    def total_cost(self, grid, path):
        return sum(grid[r][c] for r, c in path)


def render(grid, path):
    marked = set(path)
    lines = []
    for r, row in enumerate(grid):
        lines.append(" ".join("*" if (r, c) in marked else str(v) for c, v in enumerate(row)))
    return "\n".join(lines)


def main():
    wall = GridNavigator.IMPASSABLE
    terrain = [
        [1, 1, 1, 1, 1],
        [1, wall, wall, wall, 1],
        [1, 1, 1, wall, 1],
        [wall, wall, 1, wall, 1],
        [1, 1, 1, 1, 1],
    ]
    navigator = GridNavigator()
    route = navigator.navigate(terrain)
    print(render(terrain, route))
    print("path:", route)
    print("cost:", navigator.total_cost(terrain, route))


if __name__ == "__main__":
    main()

