class CircularDependencyError(Exception):
    """Raised when the dependency graph cannot be linearised."""


class DependencyResolver:
    """Kahn-style topological sort over package dependency pairs."""

    def __init__(self, pairs):
        self._graph = {}
        self._pending = {}
        self._resolved = set()
        self._load(pairs)

    def _load(self, pairs):
        for pair in pairs:
            package, dependency = self._validate(pair)
            self._register(package)
            self._register(dependency)
            if package not in self._graph[dependency]:
                self._graph[dependency].add(package)
                self._pending[package] += 1

    def _validate(self, pair):
        items = tuple(pair)
        if len(items) != 2:
            raise ValueError("each relationship must be a (package, dependency) pair")
        package, dependency = items
        if package == dependency:
            raise CircularDependencyError("%s depends on itself" % package)
        return package, dependency

    def _register(self, name):
        if name not in self._graph:
            self._graph[name] = set()
            self._pending[name] = 0

    def _ready(self):
        return sorted(name for name, count in self._pending.items()
                      if count == 0 and name not in self._resolved)

    def _release(self, name):
        self._resolved.add(name)
        for dependent in sorted(self._graph[name]):
            self._pending[dependent] -= 1

    def _cycle_report(self):
        stuck = sorted(name for name in self._graph if name not in self._resolved)
        return "circular dependency among: " + ", ".join(stuck)

    def order(self):
        build_order = []
        queue = self._ready()
        while queue:
            name = queue.pop(0)
            build_order.append(name)
            self._release(name)
            queue.extend(n for n in self._ready() if n not in queue)
        if len(build_order) != len(self._graph):
            raise CircularDependencyError(self._cycle_report())
        return build_order


def resolve(packages):
    return DependencyResolver(packages).order()


def format_sequence(order):
    return "\n".join("%2d. %s" % (index, name)
                     for index, name in enumerate(order, start=1))


def main():
    relationships = [
        ("webframework", "corelib"),
        ("templating", "corelib"),
        ("blogapp", "webframework"),
        ("blogapp", "templating"),
    ]
    print("Installation sequence:")
    print(format_sequence(resolve(relationships)))
    try:
        resolve([("alpha", "beta"), ("beta", "alpha")])
    except CircularDependencyError as error:
        print("Rejected broken graph: %s" % error)


if __name__ == "__main__":
    main()

