class BoardState:
    """Tracks a chess board and validates sequences of simple piece moves."""

    _INITIAL = ("rnbqkbnr", "pppppppp", "........", "........",
                "........", "........", "PPPPPPPP", "RNBQKBNR")

    def __init__(self):
        self._grid = [list(row) for row in self._INITIAL]
        self._turn = "w"
        self._kings = {"w": (7, 4), "b": (0, 4)}

    def _parse(self, square):
        text = str(square).strip().lower()
        if len(text) != 2 or text[0] not in "abcdefgh" or text[1] not in "12345678":
            raise ValueError("bad algebraic square: %r" % (square,))
        return 8 - int(text[1]), ord(text[0]) - ord("a")

    def _color(self, piece):
        return "w" if piece.isupper() else "b"

    def _path_clear(self, src, dst):
        dr, dc = dst[0] - src[0], dst[1] - src[1]
        step_r = (dr > 0) - (dr < 0)
        step_c = (dc > 0) - (dc < 0)
        row, col = src[0] + step_r, src[1] + step_c
        while (row, col) != dst:
            if self._grid[row][col] != ".":
                return False
            row += step_r
            col += step_c
        return True

    def _geometry(self, piece, src, dst):
        dr, dc = dst[0] - src[0], dst[1] - src[1]
        kind = piece.lower()
        target = self._grid[dst[0]][dst[1]]
        if kind == "p":
            ahead = -1 if piece.isupper() else 1
            home = 6 if piece.isupper() else 1
            if dc == 0 and target == ".":
                if dr == ahead:
                    return True
                return (dr == 2 * ahead and src[0] == home
                        and self._grid[src[0] + ahead][src[1]] == ".")
            return abs(dc) == 1 and dr == ahead and target != "."
        if kind == "n":
            return sorted((abs(dr), abs(dc))) == [1, 2]
        if kind == "b":
            return abs(dr) == abs(dc) and self._path_clear(src, dst)
        if kind == "r":
            return (dr == 0) != (dc == 0) and self._path_clear(src, dst)
        if kind == "q":
            return (abs(dr) == abs(dc) or (dr == 0) != (dc == 0)) and self._path_clear(src, dst)
        return max(abs(dr), abs(dc)) == 1

    def _attacked(self, square, by_color):
        for row in range(8):
            for col in range(8):
                piece = self._grid[row][col]
                if piece != "." and self._color(piece) == by_color:
                    if self._geometry(piece, (row, col), square):
                        return True
        return False

    def _leaves_king_attacked(self, src, dst):
        piece = self._grid[src[0]][src[1]]
        captured = self._grid[dst[0]][dst[1]]
        saved_king = self._kings[self._turn]
        self._grid[src[0]][src[1]] = "."
        self._grid[dst[0]][dst[1]] = piece
        if piece.lower() == "k":
            self._kings[self._turn] = dst
        enemy = "b" if self._turn == "w" else "w"
        exposed = self._attacked(self._kings[self._turn], enemy)
        self._grid[src[0]][src[1]] = piece
        self._grid[dst[0]][dst[1]] = captured
        self._kings[self._turn] = saved_king
        return exposed

    def validate(self, moves):
        for pair in moves:
            try:
                src = self._parse(pair[0])
                dst = self._parse(pair[1])
            except (ValueError, IndexError, TypeError):
                return False
            piece = self._grid[src[0]][src[1]]
            if piece == "." or self._color(piece) != self._turn or src == dst:
                return False
            target = self._grid[dst[0]][dst[1]]
            if target != "." and self._color(target) == self._turn:
                return False
            if not self._geometry(piece, src, dst):
                return False
            if self._leaves_king_attacked(src, dst):
                return False
            self._grid[src[0]][src[1]] = "."
            self._grid[dst[0]][dst[1]] = piece
            if piece.lower() == "k":
                self._kings[self._turn] = dst
            self._turn = "b" if self._turn == "w" else "w"
        return True


def main():
    print(BoardState().validate([("e2", "e4"), ("g8", "f6")]))
    print(BoardState().validate([("e2", "e5")]))
    print(BoardState().validate([("c1", "f4")]))


if __name__ == "__main__":
    main()

