import heapq
from collections import Counter


class _Node:
    def __init__(self, weight, char=None, left=None, right=None):
        self.weight = weight
        self.char = char
        self.left = left
        self.right = right

    def is_leaf(self):
        return self.left is None and self.right is None


class HuffmanCompressor:
    def __init__(self):
        self._freq = Counter()
        self._root = None
        self._codes = {}

    def _count_frequencies(self, text):
        self._freq = Counter(text)
        return self._freq

    def _build_queue(self):
        queue = []
        for order, (char, weight) in enumerate(sorted(self._freq.items())):
            heapq.heappush(queue, (weight, order, _Node(weight, char)))
        return queue

    def _merge_nodes(self, queue):
        order = len(queue)
        while len(queue) > 1:
            left_weight, _, left = heapq.heappop(queue)
            right_weight, _, right = heapq.heappop(queue)
            merged = _Node(left_weight + right_weight, left=left, right=right)
            heapq.heappush(queue, (merged.weight, order, merged))
            order += 1
        self._root = queue[0][2] if queue else None
        return self._root

    def _assign_codes(self, node, prefix=""):
        if node is None:
            return
        if node.is_leaf():
            self._codes[node.char] = prefix or "0"
            return
        self._assign_codes(node.left, prefix + "0")
        self._assign_codes(node.right, prefix + "1")

    def encode(self, text):
        self._count_frequencies(text)
        self._codes = {}
        self._assign_codes(self._merge_nodes(self._build_queue()))
        return "".join(self._codes[char] for char in text)

    def decode(self, bits):
        if self._root is None:
            return ""
        if self._root.is_leaf():
            return self._root.char * len(bits)
