import heapq
from collections import Counter


class _Node:
    def __init__(self, weight, char=None, left=None, right=None):
        self.weight = weight
        self.char = char
        self.left = left
        self.right = right

    def is_leaf(self):
        return self.left is None and self.right is None


class HuffmanCompressor:
    def __init__(self):
        self.freq = Counter()
        self.root = None
        self.codes = {}

    def count_frequencies(self, text):
        self.freq = Counter(text)
        return self.freq

    def build_queue(self):
        queue = []
        for order, (char, weight) in enumerate(sorted(self.freq.items())):
            heapq.heappush(queue, (weight, order, _Node(weight, char)))
        return queue

    def merge_nodes(self, queue):
        order = len(queue)
        while len(queue) > 1:
            left_weight, _, left = heapq.heappop(queue)
            right_weight, _, right = heapq.heappop(queue)
            merged = _Node(left_weight + right_weight, left=left, right=right)
            heapq.heappush(queue, (merged.weight, order, merged))
            order += 1
        self.root = queue[0][2] if queue else None
        return self.root

    def assign_codes(self, node, prefix=""):
        if node is None:
            return
        if node.is_leaf():
            self.codes[node.char] = prefix or "0"
            return
        self.assign_codes(node.left, prefix + "0")
        self.assign_codes(node.right, prefix + "1")

    def encode(self, text):
        self.count_frequencies(text)
        self.codes = {}
        self.assign_codes(self.merge_nodes(self.build_queue()))
        return "".join(self.codes[char] for char in text)

    def decode(self, bits):
        if self.root is None:
            return ""
        if self.root.is_leaf():
            return self.root.char * len(bits)
        chars, node = [], self.root
        for bit in bits:
            node = node.left if bit == "0" else node.right
            if node.is_leaf():
                chars.append(node.char)
                node = self.root
        return "".join(chars)

    def report(self):
        lines = []
        for char, code in sorted(self.codes.items(), key=lambda kv: (len(kv[1]), kv[0])):
            lines.append("%r freq=%-3d code=%s" % (char, self.freq[char], code))
        return "\n".join(lines)


def main():
    sample = "aeiou aeiou aeiou banana queue idea ooze"
    compressor = HuffmanCompressor()
    bits = compressor.encode(sample)
    print(compressor.report())
    print("bits:", bits)
    print("original bits: %d, compressed bits: %d" % (len(sample) * 8, len(bits)))
    print("roundtrip ok:", compressor.decode(bits) == sample)


