        for letter in word:
            if letter not in node.children:
                node.children[letter] = _Node()
            node = node.children[letter]
        node.is_word = True

    def _load(self, words):
        added = False
        for raw in words:
            word = raw.strip().lower()
            if word and word not in self._loaded:
                self._insert(word)
                self._loaded.add(word)
                added = True
        if added:
            self._cache.clear()

    def _contains(self, word):
        node = self._root
        for letter in word:
            node = node.children.get(letter)
            if node is None:
                return False
        return node.is_word

    def _search(self, node, target, index, budget, prefix, found):
        if index == len(target):
            if node.is_word:
                found.add(prefix)
            if budget:
                for letter, child in node.children.items():
                    if child.is_word:
                        found.add(prefix + letter)
