        if exact is not None:
            self._search(exact, target, index + 1, budget, prefix + letter, found)
        if budget:
            for other, child in node.children.items():
                if other != letter:
                    self._search(child, target, index + 1, 0, prefix + other, found)
                self._search(child, target, index, 0, prefix + other, found)
            self._search(node, target, index + 1, 0, prefix, found)
            if index + 1 < len(target):
                swapped = node.children.get(target[index + 1])
                if swapped is not None:
                    tail = swapped.children.get(letter)
                    if tail is not None:
                        moved = prefix + target[index + 1] + letter
                        self._search(tail, target, index + 2, 0, moved, found)

