import re


class FormulaEngine:
    """Evaluates a grid of interconnected arithmetic formulas."""

    _TOKEN = re.compile(r"\d+(?:\.\d+)?|[A-Za-z]+\d+|[+\-*/]")
    _REF = re.compile(r"[A-Za-z]+\d+\Z")

    def __init__(self):
        self._sources = {}
        self._cache = {}
        self._evaluating = set()

    @staticmethod
    def _normalize(coord):
        return str(coord).strip().upper()

    def _load(self, cells):
        self._sources = {self._normalize(coord): str(content) for coord, content in cells}
        self._cache.clear()
        self._evaluating.clear()

    def _tokenize(self, text):
        tokens = self._TOKEN.findall(text)
        if "".join(tokens) != re.sub(r"\s+", "", text):
            raise ValueError("unparsable expression: %r" % text)
        if not tokens or len(tokens) % 2 == 0:
            raise ValueError("malformed expression: %r" % text)
        return tokens

    def _resolve(self, token):
        if self._REF.match(token):
            return self._value_of(token)
        return float(token)

    @staticmethod
    def _apply(left, op, right):
        if op == "+":
            return left + right
        if op == "-":
            return left - right
        if op == "*":
            return left * right
        if right == 0:
            raise ZeroDivisionError("division by zero in formula")
        return left / right

    def _reduce(self, tokens):
        values = [self._resolve(tokens[0])]
        operators = []
        for index in range(1, len(tokens), 2):
            operator = tokens[index]
            right = self._resolve(tokens[index + 1])
            if operator in "*/":
                values[-1] = self._apply(values[-1], operator, right)
            else:
                operators.append(operator)
                values.append(right)
        total = values[0]
        for operator, value in zip(operators, values[1:]):
            total = self._apply(total, operator, value)
        return total

    def _compute(self, text):
        body = text.strip().lstrip("=").strip()
        if not body:
            return 0.0
        return self._reduce(self._tokenize(body))

    def _value_of(self, coord):
        key = self._normalize(coord)
        if key in self._cache:
            return self._cache[key]
        if key in self._evaluating:
            raise ValueError("circular reference at %s" % key)
        self._evaluating.add(key)
        try:
            value = self._compute(self._sources.get(key, ""))
        finally:
            self._evaluating.discard(key)
        self._cache[key] = value
        return value

    def evaluate(self, cells):
        self._load(cells)
        return [self._value_of(entry[0]) for entry in cells]


def format_value(value):
    return str(int(value)) if float(value).is_integer() else "%.4g" % value


def report(cells):
    values = FormulaEngine().evaluate(cells)
    width = max(len(str(entry[0])) for entry in cells)
    return [
        "%-*s %-14s = %s" % (width, coord, content, format_value(value))
        for (coord, content), value in zip(cells, values)
    ]


def main():
    grid = [
        ("A1", "3"),
        ("A2", "4"),
        ("B1", "=A1+A2"),
        ("B2", "=B1*2-A1"),
        ("C1", "=B2/3+A2*A1"),
        ("C2", "=C1+B1+A1"),
    ]
    for line in report(grid):
        print(line)


if __name__ == "__main__":
    main()

