import hashlib


class MerkleTreeBuilder:
    """Builds a Merkle tree over raw string blocks and exposes the root hash."""

    def __init__(self, algorithm="sha256"):
        self.algorithm = algorithm
        self.blocks = []
        self.leaves = []
        self.layers = []
        self._cache = {}

    def _digest(self, payload):
        if payload not in self._cache:
            hasher = hashlib.new(self.algorithm)
            hasher.update(payload.encode("utf-8"))
            self._cache[payload] = hasher.hexdigest()
        return self._cache[payload]

    def _hash_chunk(self, block):
        if not isinstance(block, str):
            raise TypeError("data blocks must be strings, got %r" % type(block).__name__)
        return self._digest("leaf:" + block)

    def _hash_pair(self, left, right):
        return self._digest("node:" + left + right)

    def _next_layer(self, layer):
        paired = []
        for index in range(0, len(layer), 2):
            left = layer[index]
            right = layer[index + 1] if index + 1 < len(layer) else left
            paired.append(self._hash_pair(left, right))
        return paired

    def _build_layers(self, layer):
        self.layers.append(layer)
        if len(layer) == 1:
            return layer[0]
        return self._build_layers(self._next_layer(layer))

    def build(self, blocks):
        if not blocks:
            raise ValueError("cannot build a tree from an empty block list")
        self.blocks = list(blocks)
        self.leaves = [self._hash_chunk(block) for block in self.blocks]
        self.layers = []
        return self._build_layers(list(self.leaves))

    def verify(self, blocks, expected_root):
        return MerkleTreeBuilder(self.algorithm).build(blocks) == expected_root

    def _describe_layer(self, depth, layer):
        label = "root" if len(layer) == 1 else "level %d" % depth
        return "%-8s %s" % (label, " ".join(h[:12] for h in layer))

    def report(self):
        if not self.layers:
            raise RuntimeError("build() must be called before report()")
        lines = ["blocks:  %s" % ", ".join(repr(b) for b in self.blocks)]
        for depth, layer in enumerate(self.layers):
            lines.append(self._describe_layer(depth, layer))
        return "\n".join(lines)


def main():
    payloads = ["alpha", "bravo", "charlie", "delta"]
    tree = MerkleTreeBuilder()
    root = tree.build(payloads)
    print(tree.report())
    print("root hash: %s" % root)
    print("verified:  %s" % tree.verify(payloads, root))
    print("tampered:  %s" % tree.verify(["alpha", "bravo", "charlie", "echo"], root))


if __name__ == "__main__":
    main()

