class LRUMemoryManager:
    """Simulates paged memory with least-recently-used replacement."""

    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be a positive number of frames")
        self.capacity = capacity
        self.faults = 0
        self._table = {}
        self._timeline = {}
        self._free_frames = list(range(capacity))
        self._cycle = 0

    def _is_loaded(self, page):
        return page in self._table

    def _touch(self, page):
        self._timeline[page] = self._cycle

    def _find_lru_page(self):
        return min(self._timeline, key=self._timeline.get)

    def _evict(self):
        victim = self._find_lru_page()
        frame = self._table.pop(victim)
        del self._timeline[victim]
        self._free_frames.append(frame)
        return victim, frame

    def _load(self, page):
        if not self._free_frames:
            self._evict()
        frame = self._free_frames.pop(0)
        self._table[page] = frame
        self._touch(page)
        return frame

    def simulate(self, accesses):
        for page in accesses:
            self._cycle += 1
            if self._is_loaded(page):
                self._touch(page)
            else:
                self.faults += 1
                self._load(page)
        return self.faults

    def frame_map(self):
        return dict(self._table)

    def report(self):
        lines = ["cycles executed: %d" % self._cycle,
                 "page faults: %d" % self.faults]
        for page, frame in sorted(self._table.items(), key=lambda kv: kv[1]):
            lines.append("  frame %d -> page %r (last used at cycle %d)"
                         % (frame, page, self._timeline[page]))
        idle = len(self._free_frames)
        if idle:
            lines.append("  %d frame(s) still free" % idle)
        return "\n".join(lines)


def main():
    trace = [1, 2, 3, 1, 4, 2, 5, 1, 2, 3, 4, 5]
    for capacity in (3, 4):
        manager = LRUMemoryManager(capacity)
        total = manager.simulate(trace)
        print("capacity %d frames: %d faults" % (capacity, total))
        print(manager.report())
        print("resident pages:", sorted(manager.frame_map()))
        print()


if __name__ == "__main__":
    main()

