        self.free_frames.append(frame)
        return victim, frame

    def load(self, page):
        if not self.free_frames:
            self.evict()
        frame = self.free_frames.pop(0)
        self.table[page] = frame
        self.touch(page)
        return frame

    def simulate(self, accesses):
        for page in accesses:
            self.cycle += 1
            if self.is_loaded(page):
                self.touch(page)
            else:
                self.faults += 1
                self.load(page)
        return self.faults

    def frame_map(self):
        return dict(self.table)

    def report(self):
        lines = ["cycles executed: %d" % self.cycle,
                 "page faults: %d" % self.faults]
        for page, frame in sorted(self.table.items(), key=lambda kv: kv[1]):
            lines.append("  frame %d -> page %r (last used at cycle %d)"
                         % (frame, page, self.timeline[page]))
        idle = len(self.free_frames)
        if idle:
            lines.append("  %d frame(s) still free" % idle)
        return "\n".join(lines)


def main():
    trace = [1, 2, 3, 1, 4, 2, 5, 1, 2, 3, 4, 5]
    for capacity in (3, 4):
        manager = LRUMemoryManager(capacity)
        total = manager.simulate(trace)
        print("capacity %d frames: %d faults" % (capacity, total))
        print(manager.report())
        print("resident pages:", sorted(manager.frame_map()))
        print()


if __name__ == "__main__":
    main()

