class MineClearing:
    """Logic for a grid based mine clearing game."""

    COVERED = "."
    FLAG = "F"
    HAZARD = "X"

    def __init__(self):
        self._rows = 0
        self._cols = 0
        self._mines = set()
        self._flags = set()
        self._revealed = set()
        self._targets = []
        self._cache = {}

    def reveal(self, commands):
        self._load(commands)
        return [self._reveal_cell(target) for target in self._targets]

    def _load(self, commands):
        self._rows = int(commands["rows"])
        self._cols = int(commands["cols"])
        if self._rows < 1 or self._cols < 1:
            raise ValueError("grid dimensions must be positive")
        self._mines = {tuple(cell) for cell in commands.get("mines", ())}
        self._flags = {tuple(cell) for cell in commands.get("flags", ())}
        self._targets = [tuple(cell) for cell in commands.get("clicks", ())]
        for cell in self._mines | self._flags | set(self._targets):
            if not self._in_bounds(cell):
                raise ValueError("cell %r lies outside the grid" % (cell,))
        self._revealed = set()
        self._cache.clear()

    def _in_bounds(self, cell):
        row, col = cell
        return 0 <= row < self._rows and 0 <= col < self._cols

    def _neighbors(self, cell):
        row, col = cell
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                candidate = (row + dr, col + dc)
                if candidate != cell and self._in_bounds(candidate):
                    yield candidate

    def _hazard_count(self, cell):
        if cell not in self._cache:
            near = [n for n in self._neighbors(cell) if n in self._mines]
            self._cache[cell] = len(near)
        return self._cache[cell]

    def _reveal_cell(self, cell):
        if cell in self._flags:
            return self.FLAG
        if cell in self._mines:
            self._revealed.add(cell)
            return self.HAZARD
        pending = [cell]
        while pending:
            current = pending.pop()
            if current in self._revealed or current in self._flags:
                continue
            self._revealed.add(current)
            if self._hazard_count(current) == 0:
                pending.extend(n for n in self._neighbors(current) if n not in self._mines)
        return str(self._hazard_count(cell))

    def render(self):
        lines = []
        for row in range(self._rows):
            cells = []
            for col in range(self._cols):
                cell = (row, col)
                if cell in self._flags:
                    cells.append(self.FLAG)
                elif cell not in self._revealed:
                    cells.append(self.COVERED)
                elif cell in self._mines:
                    cells.append(self.HAZARD)
                else:
                    cells.append(str(self._hazard_count(cell)))
            lines.append(" ".join(cells))
        return "\n".join(lines)


