class ReliableTransmitter:
    """Simulates sliding-window transmission with retransmission on timeout."""

    def __init__(self, window_size=4, timeout=3):
        self._validate_config(window_size, timeout)
        self._buffer = {}
        self._base = 0
        self._next_seq = 0
        self._window = window_size
        self._timeout_limit = timeout
        self._timer = 0
        self._sent = set()
        self._pending_acks = set()
        self._retransmits = 0
        self._log = []

    @staticmethod
    def _validate_config(window_size, timeout):
        if not isinstance(window_size, int) or window_size < 1:
            raise ValueError("window_size must be a positive integer")
        if not isinstance(timeout, int) or timeout < 1:
            raise ValueError("timeout must be a positive integer")

    def _parse_event(self, event):
        if not isinstance(event, (tuple, list)) or not event:
            raise ValueError("event must be a non-empty tuple")
        kind, args = event[0], tuple(event[1:])
        if kind == "send" and len(args) == 1:
            return kind, args[0]
        if kind == "ack" and len(args) == 1 and isinstance(args[0], int):
            return kind, args[0]
        if kind == "tick" and not args:
            return kind, None
        raise ValueError("unsupported event: %r" % (event,))

    def _queue(self, payload):
        self._buffer[self._next_seq] = payload
        self._next_seq += 1

    def _window_bounds(self):
        upper = self._base + self._window
        return self._base, min(upper, self._next_seq)

    def _flush_window(self):
        start, end = self._window_bounds()
        for seq in range(start, end):
            if seq not in self._sent:
                self._sent.add(seq)
                self._log.append(seq)

    def _handle_ack(self, seq):
        if seq < self._base or seq >= self._next_seq:
            return
        self._pending_acks.add(seq)
        if seq == self._base:
            self._advance_window()

    def _advance_window(self):
        acked = self._pending_acks
        buffered = self._buffer
        while self._base in acked:
            acked.discard(self._base)
            buffered.pop(self._base, None)
            self._base += 1
        self._timer = 0

    def _tick(self):
        self._timer += 1
        if self._timer >= self._timeout_limit:
            self._retransmit()

    def _retransmit(self):
        start, end = self._window_bounds()
        for seq in range(start, end):
            if seq not in self._pending_acks:
                self._log.append(seq)
                self._retransmits += 1
        self._timer = 0

    def transmit(self, events):
        self._log = []
        for event in events:
            kind, value = self._parse_event(event)
            if kind == "send":
                self._queue(value)
            elif kind == "ack":
                self._handle_ack(value)
            else:
                self._tick()
            self._flush_window()
        return list(self._log)

    def report(self):
        outstanding = sorted(self._buffer)
        return "base=%d next=%d outstanding=%s retransmits=%d" % (
            self._base, self._next_seq, outstanding, self._retransmits)


def main():
    channel = ReliableTransmitter(window_size=3, timeout=2)
    events = [
        ("send", "a"), ("send", "b"), ("send", "c"),
        ("ack", 1),                      # out-of-order ack, buffered
        ("tick",), ("tick",),            # ack for 0 was dropped -> retransmit
        ("ack", 0),                      # window slides past 0 and 1
        ("send", "d"), ("ack", 2), ("ack", 3),
    ]
    print("transmitted:", channel.transmit(events))
    print(channel.report())


if __name__ == "__main__":
    main()

