import random

WALL = "#"
PATH = " "


class Labyrinth:
    """Builds a perfect labyrinth with a randomized, iterative depth first search."""

    def __init__(self, width, height):
        if not isinstance(width, int) or not isinstance(height, int):
            raise TypeError("labyrinth dimensions must be integers")
        if width < 1 or height < 1:
            raise ValueError("labyrinth dimensions must be positive")
        self.width = width
        self.height = height
        self._rng = random.Random()
        self._grid = [[WALL] * (2 * width + 1) for _ in range(2 * height + 1)]
        self._stack = []
        self._visited = set()

    def _in_bounds(self, cell):
        x, y = cell
        return 0 <= x < self.width and 0 <= y < self.height

    def _unvisited_neighbors(self, cell):
        x, y = cell
        candidates = [(x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)]
        return [c for c in candidates if self._in_bounds(c) and c not in self._visited]

    def _pick(self, options):
        return self._rng.choice(options)

    def _mark(self, cell):
        x, y = cell
        self._visited.add(cell)
        self._grid[2 * y + 1][2 * x + 1] = PATH

    def _open_wall(self, current, chosen):
        wall_x = current[0] + chosen[0] + 1
        wall_y = current[1] + chosen[1] + 1
        self._grid[wall_y][wall_x] = PATH

    def _carve(self, start):
        self._mark(start)
        self._stack.append(start)
        while self._stack:
            current = self._stack[-1]
            options = self._unvisited_neighbors(current)
            if not options:
                self._stack.pop()
                continue
            chosen = self._pick(options)
            self._open_wall(current, chosen)
            self._mark(chosen)
            self._stack.append(chosen)

    def _render(self):
        return "\n".join("".join(row) for row in self._grid)

    def build(self):
        self._carve((0, 0))
        return self._render()


def generate(dimensions):
    """Return a hash-and-space drawing of a labyrinth of the given (width, height)."""
    width, height = dimensions
    return Labyrinth(width, height).build()


def main():
    print(generate((10, 10)))


if __name__ == "__main__":
    main()

