class LifeEngine:
    """Conway's Game of Life engine over a fixed rectangular board."""

    SURVIVE = (2, 3)
    BIRTH = (3,)

    def __init__(self, grid=None):
        self.grid = []
        self._rows = 0
        self._cols = 0
        if grid is not None:
            self._load(grid)

    def _load(self, grid):
        if not grid or not grid[0]:
            raise ValueError("grid must contain at least one row and column")
        width = len(grid[0])
        for row in grid:
            if len(row) != width:
                raise ValueError("all rows must share the same width")
        self.grid = [[1 if cell else 0 for cell in row] for row in grid]
        self._rows = len(self.grid)
        self._cols = width

    def _in_bounds(self, r, c):
        return 0 <= r < self._rows and 0 <= c < self._cols

    def _count_neighbors(self, r, c):
        total = 0
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if self._in_bounds(nr, nc):
                    total += self.grid[nr][nc]
        return total

    def _cell_fate(self, r, c):
        living = self._count_neighbors(r, c)
        if self.grid[r][c]:
            return 1 if living in self.SURVIVE else 0
        return 1 if living in self.BIRTH else 0

    def _advance(self):
        successor = [[self._cell_fate(r, c) for c in range(self._cols)]
                     for r in range(self._rows)]
        self.grid = successor

    def population(self):
        return sum(sum(row) for row in self.grid)

    def render(self):
        return "\n".join("".join("#" if cell else "." for cell in row)
                         for row in self.grid)

    def simulate(self, grid, steps=1):
        if steps < 0:
            raise ValueError("steps must be non-negative")
        self._load(grid)
        for _ in range(steps):
            self._advance()
        return [row[:] for row in self.grid]


def make_glider(size=8):
    board = [[0] * size for _ in range(size)]
    for r, c in ((0, 1), (1, 2), (2, 0), (2, 1), (2, 2)):
        board[r][c] = 1
    return board


def main():
    engine = LifeEngine()
    start = make_glider()
    for generation in (0, 4, 8, 12):
        engine.simulate(start, generation)
        print("generation {} (population {}):".format(generation, engine.population()))
        print(engine.render())
        print()
    return engine.grid


if __name__ == "__main__":
    main()

