import re
import sys


class RomanEngine:
    """Evaluates arithmetic written entirely in Roman numerals."""

    _OPERATIONS = {
        "+": lambda a, b: a + b,
        "-": lambda a, b: a - b,
        "*": lambda a, b: a * b,
        "/": lambda a, b: a // b,
    }

    def __init__(self):
        self._values = {
            "M": 1000, "D": 500, "C": 100,
            "L": 50, "X": 10, "V": 5, "I": 1,
        }
        self._total = 0
        self._operator = None

    def _tokenize(self, equation):
        tokens = re.findall(r"[A-Za-z]+|[-+*/]", equation)
        if "".join(tokens) != re.sub(r"\s+", "", equation):
            raise ValueError("equation contains unsupported characters")
        return tokens

    def _parse(self, letters):
        letters = letters.upper()
        digits = []
        for letter in letters:
            if letter not in self._values:
                raise ValueError("unknown numeral letter: " + letter)
            digits.append(self._values[letter])
        number = 0
        for index, digit in enumerate(digits):
            following = digits[index + 1:]
            if following and digit < max(following):
                number -= digit
            else:
                number += digit
        if self._format(number) != letters:
            raise ValueError("malformed numeral: " + letters)
        return number

    def _apply(self, value):
        operation = self._OPERATIONS[self._operator]
        self._total = operation(self._total, value)
        self._operator = None

    def _format(self, number):
        if not 1 <= number <= 3999:
            raise ValueError("value outside numeral range: %d" % number)
        letters = []
        for numeral, amount in sorted(self._values.items(), key=lambda p: -p[1]):
            while number >= amount:
                letters.append(numeral)
                number -= amount
        text = "".join(letters)
        for long_form, short_form in (("DCCCC", "CM"), ("CCCC", "CD"),
                                      ("LXXXX", "XC"), ("XXXX", "XL"),
                                      ("VIIII", "IX"), ("IIII", "IV")):
            text = text.replace(long_form, short_form)
        return text

    def evaluate(self, equation):
        tokens = self._tokenize(equation)
        if not tokens:
            raise ValueError("empty equation")
        self._total = self._parse(tokens[0])
        for token in tokens[1:]:
            if token in self._OPERATIONS:
                self._operator = token
            else:
                self._apply(self._parse(token))
        if self._operator is not None:
            raise ValueError("equation ends with an operator")
        return self._format(self._total)


def calculate(equation):
    return RomanEngine().evaluate(equation)


def main():
    equation = " ".join(sys.argv[1:]) or sys.stdin.read()
    print(calculate(equation))


