import random


class QuadTree:
    """Two dimensional spatial index tree over an axis aligned bounding box."""

    def __init__(self, bounds, capacity=4):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self.bounds = tuple(float(v) for v in bounds)
        self.capacity = capacity
        self.points = []
        self._children = ()

    def _contains(self, point):
        x, y = point
        x0, y0, x1, y1 = self.bounds
        return x0 <= x <= x1 and y0 <= y <= y1

    def _splittable(self):
        x0, y0, x1, y1 = self.bounds
        return (x1 - x0) > 1e-9 and (y1 - y0) > 1e-9

    def _subdivide(self):
        x0, y0, x1, y1 = self.bounds
        mx, my = (x0 + x1) / 2.0, (y0 + y1) / 2.0
        quadrants = ((x0, y0, mx, my), (mx, y0, x1, my),
                     (x0, my, mx, y1), (mx, my, x1, y1))
        self._children = tuple(QuadTree(q, self.capacity) for q in quadrants)
        self._redistribute()

    def _redistribute(self):
        pending, self.points = self.points, []
        for point in pending:
            self._push_down(point)

    def _push_down(self, point):
        for child in self._children:
            if child.insert(point):
                return True
        return False

    def insert(self, point):
        if not self._contains(point):
            return False
        if self._children:
            return self._push_down(point)
        self.points.append(point)
        if len(self.points) > self.capacity and self._splittable():
            self._subdivide()
        return True

    def divided_regions(self):
        if not self._children:
            return 0
        return 1 + sum(child.divided_regions() for child in self._children)

    def describe(self, indent=0):
        x0, y0, x1, y1 = self.bounds
        head = "%s[%.1f,%.1f]-[%.1f,%.1f]" % (" " * indent, x0, y0, x1, y1)
        if not self._children:
            return ["%s leaf(%d)" % (head, len(self.points))]
        lines = ["%s split" % head]
        for child in self._children:
            lines.extend(child.describe(indent + 2))
        return lines


def build_tree(points, capacity):
    xs = [p[0] for p in points]
    ys = [p[1] for p in points]
    tree = QuadTree((min(xs), min(ys), max(xs), max(ys)), capacity)
    for point in points:
        tree.insert(point)
    return tree


def partition(points, capacity=4):
    coords = [(float(x), float(y)) for x, y in points]
    if not coords:
        return 0
    return build_tree(coords, capacity).divided_regions()


def main():
    random.seed(7)
    spread = [(random.uniform(0, 100), random.uniform(0, 100)) for _ in range(20)]
    cluster = [(random.uniform(10, 11), random.uniform(10, 11)) for _ in range(60)]
    dataset = spread + cluster
    print("points:", len(dataset))
    print("divided regions (capacity 4):", partition(dataset, 4))
    print("divided regions (capacity 16):", partition(dataset, 16))
    for line in build_tree(dataset, 16).describe():
        print(line)


if __name__ == "__main__":
    main()

