DIRECTIONS = ("north", "east", "south", "west")


class LunarRover:
    """Drives a lunar rover through a list of mission instructions."""

    _ALIASES = {
        "go forward": "forward", "forward": "forward", "f": "forward",
        "go backward": "backward", "backward": "backward", "b": "backward",
        "pivot left": "left", "left": "left", "l": "left",
        "pivot right": "right", "right": "right", "r": "right",
        "gather telemetry": "telemetry", "telemetry": "telemetry", "t": "telemetry",
    }
    _COSTS = {"forward": 1, "backward": 1, "left": 0, "right": 0, "telemetry": 5}
    _STEPS = {"north": (0, 1), "east": (1, 0), "south": (0, -1), "west": (-1, 0)}

    def __init__(self):
        self._reset()

    def _reset(self):
        self._x = 0
        self._y = 0
        self._heading = "north"
        self._battery = 100
        self._log = []

    def _parse(self, command):
        key = " ".join(str(command).lower().split())
        if key not in self._ALIASES:
            raise ValueError("unknown instruction: %r" % (command,))
        return self._ALIASES[key]

    def _drain(self, action):
        cost = self._COSTS[action]
        if cost > self._battery:
            return False
        self._battery -= cost
        return True

    def _move(self, sign):
        dx, dy = self._STEPS[self._heading]
        self._x += sign * dx
        self._y += sign * dy

    def _pivot(self, action):
        offset = 1 if action == "right" else -1
        index = (DIRECTIONS.index(self._heading) + offset) % len(DIRECTIONS)
        self._heading = DIRECTIONS[index]

    def _record(self):
        self._log.append((self._x, self._y, self._heading, self._battery))

    def navigate(self, commands):
        self._reset()
        for command in commands:
            action = self._parse(command)
            if self._battery <= 0 or not self._drain(action):
                break
            if action == "forward":
                self._move(1)
            elif action == "backward":
                self._move(-1)
            elif action == "telemetry":
                self._record()
            else:
                self._pivot(action)
        return (self._x, self._y, self._heading, self._battery)

    def report(self):
        lines = ["telemetry packets: %d" % len(self._log)]
        for number, entry in enumerate(self._log, start=1):
            lines.append("  #%d at (%d, %d) facing %s, battery %d%%" % ((number,) + entry))
        return "\n".join(lines)


def main():
    rover = LunarRover()
    print(rover.navigate(["go forward", "pivot right", "go forward", "gather telemetry"]))
    print(rover.report())
    print(rover.navigate(["gather telemetry"] * 25 + ["go forward"]))
    print(rover.report())


if __name__ == "__main__":
    main()

