import math
from cmath import sqrt as _csqrt


class QuantumRegister:
    """A small state-vector simulator for a fixed number of qubits."""

    _SINGLE = {
        "H": ((1 / math.sqrt(2), 1 / math.sqrt(2)), (1 / math.sqrt(2), -1 / math.sqrt(2))),
        "X": ((0.0, 1.0), (1.0, 0.0)),
        "Z": ((1.0, 0.0), (0.0, -1.0)),
    }

    def __init__(self, qubits=3):
        self._n = qubits
        self._amps = [0j] * (1 << qubits)
        self._amps[0] = 1 + 0j

    def _validate(self, qubit):
        if not isinstance(qubit, int) or not 0 <= qubit < self._n:
            raise ValueError("qubit index %r out of range" % (qubit,))

    def _mask(self, qubit):
        self._validate(qubit)
        return 1 << (self._n - 1 - qubit)

    def _pairs(self, qubit):
        bit = self._mask(qubit)
        for base in range(len(self._amps)):
            if not base & bit:
                yield base, base | bit

    def _apply_single(self, matrix, qubit):
        (m00, m01), (m10, m11) = matrix
        for lo, hi in self._pairs(qubit):
            a, b = self._amps[lo], self._amps[hi]
            self._amps[lo] = m00 * a + m01 * b
            self._amps[hi] = m10 * a + m11 * b

    def _apply_cnot(self, control, target):
        if control == target:
            raise ValueError("control and target must differ")
        cbit = self._mask(control)
        tbit = self._mask(target)
        for index in range(len(self._amps)):
            if index & cbit and not index & tbit:
                partner = index | tbit
                self._amps[index], self._amps[partner] = self._amps[partner], self._amps[index]

    def _normalize(self):
        norm = _csqrt(sum(abs(a) ** 2 for a in self._amps)).real
        self._amps = [a / norm for a in self._amps]

    def _parse(self, instruction):
        if isinstance(instruction, str):
            parts = instruction.replace(",", " ").split()
        else:
            parts = list(instruction)
        if not parts:
            raise ValueError("empty instruction")
        return str(parts[0]).upper(), [int(p) for p in parts[1:]]

    def apply(self, instruction):
        name, qubits = self._parse(instruction)
        if name in self._SINGLE:
            if len(qubits) != 1:
                raise ValueError("%s takes exactly one qubit" % name)
            self._apply_single(self._SINGLE[name], qubits[0])
        elif name in ("CNOT", "CX"):
            if len(qubits) != 2:
                raise ValueError("CNOT takes a control and a target qubit")
            self._apply_cnot(qubits[0], qubits[1])
        else:
            raise ValueError("unknown gate %r" % name)
        self._normalize()

    def probabilities(self):
        return [round(abs(a) ** 2, 12) for a in self._amps]


def simulate(operations):
    register = QuantumRegister(3)
    for instruction in operations:
        register.apply(instruction)
    return register.probabilities()

