class AvalancheMonitor:
    """Tracks snow pack accumulation per zone and flags avalanche risk."""

    BASE_PACK = 50.0
    _SPIKE_LIMIT = 20.0
    _DEEP_PACK = 100.0
    _THAW_POINT = 0.0

    def __init__(self):
        self._packs = {}
        self._trends = {}
        self._last_temp = {}
        self._risk = {}

    def _ensure_zone(self, zone):
        if zone not in self._packs:
            self._packs[zone] = self.BASE_PACK
            self._trends[zone] = "steady"
            self._last_temp[zone] = None
            self._risk[zone] = False

    def _parse(self, entry):
        if not isinstance(entry, (tuple, list)) or len(entry) < 2:
            raise ValueError("reading must be a tuple of (zone, depth, temp)")
        zone = entry[0]
        if isinstance(entry[1], str):
            if entry[1].strip().lower() != "reset":
                raise ValueError("unknown command: %r" % (entry[1],))
            return zone, None, None
        if len(entry) < 3:
            raise ValueError("snow reading needs a temperature value")
        return zone, float(entry[1]), float(entry[2])

    def _update_trend(self, zone, temp):
        previous = self._last_temp[zone]
        if previous is None or temp == previous:
            trend = "steady"
        elif temp > previous:
            trend = "rising"
        else:
