class AvalancheMonitor:
    """Tracks snow pack accumulation per zone and flags avalanche risk."""

    BASE_PACK = 50.0
    SPIKE_LIMIT = 20.0
    DEEP_PACK = 100.0
    THAW_POINT = 0.0

    def __init__(self):
        self.packs = {}
        self.trends = {}
        self.last_temp = {}
        self.risk = {}

    def ensure_zone(self, zone):
        if zone not in self.packs:
            self.packs[zone] = self.BASE_PACK
            self.trends[zone] = "steady"
            self.last_temp[zone] = None
            self.risk[zone] = False

    def parse(self, entry):
        if not isinstance(entry, (tuple, list)) or len(entry) < 2:
            raise ValueError("reading must be a tuple of (zone, depth, temp)")
        zone = entry[0]
        if isinstance(entry[1], str):
            if entry[1].strip().lower() != "reset":
                raise ValueError("unknown command: %r" % (entry[1],))
            return zone, None, None
        if len(entry) < 3:
            raise ValueError("snow reading needs a temperature value")
        return zone, float(entry[1]), float(entry[2])

    def update_trend(self, zone, temp):
        previous = self.last_temp[zone]
        if previous is None or temp == previous:
            trend = "steady"
        elif temp > previous:
            trend = "rising"
        else:
            trend = "falling"
        self.trends[zone] = trend
        self.last_temp[zone] = temp
        return trend == "rising"

    def accumulate(self, zone, depth):
        self.packs[zone] = max(0.0, self.packs[zone] + depth)
        return self.packs[zone]

    def evaluate(self, zone, depth, temp, warming):
        pack = self.packs[zone]
        thaw = warming and temp > self.THAW_POINT and pack > self.DEEP_PACK
        if depth > self.SPIKE_LIMIT or thaw:
            self.risk[zone] = True

    def reset(self, zone):
        self.risk[zone] = False
        self.packs[zone] = self.BASE_PACK

    def monitor(self, readings):
        for entry in readings:
            zone, depth, temp = self.parse(entry)
            self.ensure_zone(zone)
            if depth is None:
                self.reset(zone)
                continue
            warming = self.update_trend(zone, temp)
            self.accumulate(zone, depth)
            self.evaluate(zone, depth, temp, warming)
        return [zone for zone, flagged in self.risk.items() if flagged]

    def report(self):
        lines = []
        for zone in sorted(self.packs):
            state = "HIGH" if self.risk[zone] else "normal"
            lines.append("Zone %s: pack=%.1fcm trend=%s risk=%s"
                         % (zone, self.packs[zone], self.trends[zone], state))
        return "\n".join(lines)


