class Submersible:
    """A robotic submersible that tracks depth, distance and photo storage."""

    _DEPTH_STEP = 10
    _FORWARD_STEP = 20
    _PHOTO_MIN_DEPTH = 50
    _MAX_DEPTH = 500

    def __init__(self, photo_capacity=50):
        self._depth = 0
        self._distance = 0
        self._remaining_photos = photo_capacity
        self._log = []

    def _normalize(self, action):
        return " ".join(str(action).strip().lower().split())

    def _can_dive(self):
        return self._depth + self._DEPTH_STEP <= self._MAX_DEPTH

    def _has_storage(self):
        return self._remaining_photos > 0

    def _record(self, action, outcome):
        self._log.append((action, outcome, self._depth, self._distance))

    def dive(self):
        if self._can_dive():
            self._depth += self._DEPTH_STEP
            self._record("dive", "descended")
        else:
            self._record("dive", "refused: maximum depth reached")

    def surface(self):
        self._depth = max(0, self._depth - self._DEPTH_STEP)
        self._record("surface", "ascended")

    def move_forward(self):
        self._distance += self._FORWARD_STEP
        self._record("move forward", "advanced")

    def take_photo(self):
        if self._depth < self._PHOTO_MIN_DEPTH:
            self._record("take photo", "refused: too shallow")
        elif not self._has_storage():
            self._record("take photo", "refused: storage full")
        else:
            self._remaining_photos -= 1
            self._record("take photo", "photo stored")

    def perform(self, action):
        handlers = {
            "dive": self.dive,
            "surface": self.surface,
            "ascend": self.surface,
            "move forward": self.move_forward,
            "forward": self.move_forward,
            "take photo": self.take_photo,
            "photo": self.take_photo,
        }
        name = self._normalize(action)
        if name not in handlers:
            raise ValueError("unknown action: %r" % (action,))
        handlers[name]()

    def state(self):
        return (self._depth, self._distance, self._remaining_photos)

    def report(self):
        return "\n".join(
            "%-12s %-28s depth=%dm dist=%dm" % entry for entry in self._log
        )


def run(actions):
    sub = Submersible()
    for action in actions:
        sub.perform(action)
    return sub


def explore(actions):
    return run(actions).state()


def main():
    sub = run(["dive", "dive", "dive", "dive", "dive", "take photo", "move forward"])
    print(sub.report())
    print("final: depth=%dm distance=%dm photos left=%d" % sub.state())


if __name__ == "__main__":
    main()

