from collections import deque


class FerryLoader:
    """Loads arriving vehicles onto a three-lane ferry, then dispatches it."""

    LANE_LENGTH = 50
    LANE_COUNT = 3

    def __init__(self, vehicles):
        self._queue = deque(self._validate(vehicles))
        self._lanes = [[] for _ in range(self.LANE_COUNT)]
        self._loaded = 0
        self._manifest = None

    @staticmethod
    def _validate(vehicles):
        checked = []
        for value in vehicles:
            if isinstance(value, bool) or not isinstance(value, int):
                raise TypeError("vehicle lengths must be integers")
            if value <= 0:
                raise ValueError("vehicle lengths must be positive")
            checked.append(value)
        return checked

    def _lane_spaces(self):
        return [self.LANE_LENGTH - sum(lane) for lane in self._lanes]

    def _roomiest_lane(self, length):
        spaces = self._lane_spaces()
        index = max(range(self.LANE_COUNT), key=lambda i: spaces[i])
        if spaces[index] < length:
            return None
        return index

    def _park(self, index, length):
        self._lanes[index].append(length)
        self._loaded += 1

    def _dispatch(self):
        self._manifest = {
            "lanes": [list(lane) for lane in self._lanes],
            "free": self._lane_spaces(),
            "loaded": self._loaded,
            "waiting": list(self._queue),
        }

    def run(self):
        while self._queue:
            index = self._roomiest_lane(self._queue[0])
            if index is None:
                break
            self._park(index, self._queue.popleft())
        self._dispatch()
        return self._loaded, len(self._queue)

    def manifest_report(self):
        if self._manifest is None:
            self.run()
        lines = []
        for number, (lane, free) in enumerate(zip(self._manifest["lanes"],
                                                  self._manifest["free"]), start=1):
            cargo = ", ".join("%dm" % length for length in lane) or "empty"
            lines.append("Lane %d: %s (%dm free)" % (number, cargo, free))
        lines.append("Departed with %d vehicle(s); %d left on the dock."
                     % (self._manifest["loaded"], len(self._manifest["waiting"])))
        return "\n".join(lines)


def board(vehicles):
    return FerryLoader(vehicles).run()


def loading_report(vehicles):
    loader = FerryLoader(vehicles)
    loader.run()
    return loader.manifest_report()


def main():
    for arrivals in ([20, 10, 30], [40, 45, 48, 12, 7]):
        print("Arrivals: %s -> %s" % (arrivals, board(arrivals)))
        print(loading_report(arrivals))
        print()


if __name__ == "__main__":
    main()

