class Outbreak:
    """Tracks the hidden cohort timers and population counts of an outbreak."""

    POPULATION = 100
    INFECTIOUS_PERIOD = 5
    CONTACTS_PER_DAY = 2

    def __init__(self):
        self._susceptible = self.POPULATION - 1
        self._cohorts = [1]
        self._immune = 0

    def _validate(self, days):
        if isinstance(days, bool) or not isinstance(days, int):
            raise TypeError("days must be an integer")
        if days < 0:
            raise ValueError("days must not be negative")
        return days

    def _active(self):
        return sum(self._cohorts)

    def _infect_new(self):
        newly = min(self._active() * self.CONTACTS_PER_DAY, self._susceptible)
        self._susceptible -= newly
        return newly

    def _advance_timers(self, newly):
        self._cohorts.insert(0, newly)
        if len(self._cohorts) > self.INFECTIOUS_PERIOD:
            self._immune += self._cohorts.pop()

    def _step(self):
        self._advance_timers(self._infect_new())

    def state(self):
        return (self._susceptible, self._active(), self._immune)

    def history(self, days):
        days = self._validate(days)
        states = [self.state()]
        while len(states) <= days:
            self._step()
            states.append(self.state())
        return states

    def final(self, days):
        return self.history(days)[-1]


class OutbreakReport:
    """Renders a day-by-day table of susceptible / infected / immune counts."""

    ROW = "{:>4} {:>12} {:>9} {:>7}"

    def __init__(self):
        self._outbreak = Outbreak()

    def _header(self):
        return self.ROW.format("day", "susceptible", "infected", "immune")

    def _format_row(self, day, state):
        return self.ROW.format(day, *state)

    def render(self, days):
        lines = [self._header()]
        for day, state in enumerate(self._outbreak.history(days)):
            lines.append(self._format_row(day, state))
        return "\n".join(lines)


def model(days):
    """Simulate the outbreak and return (susceptible, infected, immune)."""
    return Outbreak().final(days)


def main():
    print(OutbreakReport().render(10))
    print()
    print("after 2 days:", model(2))
    print("after 8 days:", model(8))


if __name__ == "__main__":
    main()

