WORD_NUMBERS = {
    "zero": 0, "one": 1, "two": 2, "three": 3, "four": 4, "five": 5,
    "six": 6, "seven": 7, "eight": 8, "nine": 9, "ten": 10,
    "eleven": 11, "twelve": 12, "fifteen": 15, "twenty": 20,
    "thirty": 30, "forty": 40,
}


class TransitSystem:
    """Tracks stop progress and passenger load for a fleet of city buses."""

    CAPACITY = 40

    def __init__(self):
        self._fleet = {}
        self._capacity = {}
        self._routes = {}

    def _register(self, bus):
        if bus not in self._fleet:
            self._fleet[bus] = 0
            self._capacity[bus] = self.CAPACITY
            self._routes[bus] = 0
        return bus

    def _parse(self, event):
        parts = event.strip().split()
        if len(parts) < 3 or parts[0].lower() != "bus":
            raise ValueError("unrecognised event: %r" % event)
        bus = parts[1]
        action = parts[2].lower()
        amount = 0
        if len(parts) > 3:
            amount = self._as_number(" ".join(parts[3:]))
        return bus, action, amount

    @staticmethod
    def _as_number(token):
        text = token.strip().lower()
        if text.isdigit():
            return int(text)
        if text in WORD_NUMBERS:
            return WORD_NUMBERS[text]
        raise ValueError("unrecognised quantity: %r" % token)

    def _advance(self, bus):
        self._routes[bus] += 1

    def _allowed_boarding(self, bus, requested):
        free_seats = self._capacity[bus] - self._fleet[bus]
        return min(requested, max(free_seats, 0))

    def _board(self, bus, requested):
        self._fleet[bus] += self._allowed_boarding(bus, requested)

    def _drop(self, bus, requested):
        self._fleet[bus] = max(self._fleet[bus] - requested, 0)

    def apply(self, event):
        bus, action, amount = self._parse(event)
        self._register(bus)
        if action == "move":
            self._advance(bus)
        elif action == "pickup":
            self._board(bus, amount)
        elif action == "drop":
            self._drop(bus, amount)
        else:
            raise ValueError("unknown action: %r" % action)

    def loads(self):
        return [self._fleet[bus] for bus in sorted(self._fleet)]

    def report(self):
        return ["bus %s: stop %d, %d aboard" % (bus, self._routes[bus], self._fleet[bus])
                for bus in sorted(self._fleet)]


def dispatch(events):
    system = TransitSystem()
    for event in events:
        system.apply(event)
    return system.loads()


def main():
    log = ["bus A move", "bus A pickup ten", "bus A drop two",
           "bus B pickup forty", "bus B pickup five", "bus B move"]
    print(dispatch(log))
    system = TransitSystem()
    for event in log:
        system.apply(event)
    for line in system.report():
        print(line)


if __name__ == "__main__":
    main()

