        self.register(bus)
        if action == "move":
            self.advance(bus)
        elif action == "pickup":
            self.board(bus, amount)
        elif action == "drop":
            self.drop(bus, amount)
        else:
            raise ValueError("unknown action: %r" % action)

    def loads(self):
        return [self.fleet[bus] for bus in sorted(self.fleet)]

    def report(self):
        return ["bus %s: stop %d, %d aboard" % (bus, self.routes[bus], self.fleet[bus])
                for bus in sorted(self.fleet)]


def dispatch(events):
    system = TransitSystem()
    for event in events:
        system.apply(event)
    return system.loads()


def main():
    log = ["bus A move", "bus A pickup ten", "bus A drop two",
           "bus B pickup forty", "bus B pickup five", "bus B move"]
    print(dispatch(log))
    system = TransitSystem()
    for event in log:
        system.apply(event)
    for line in system.report():
        print(line)


if __name__ == "__main__":
    main()

