class EruptionPredictor:
    """Predicts volcanic risk from micro-seismic amplitude readings."""

    _LEVELS = ("normal", "elevated", "critical")
    _INITIAL_BASELINE = 10
    _ANOMALY_THRESHOLD = 3

    def __init__(self):
        self._baseline = self._INITIAL_BASELINE
        self._anomalies = 0
        self._level_index = 0

    def _reset(self):
        self._baseline = self._INITIAL_BASELINE
        self._anomalies = 0
        self._level_index = 0

    def _validate(self, readings):
        if not isinstance(readings, (list, tuple)):
            raise TypeError("readings must be a list of integers")
        for value in readings:
            if isinstance(value, bool) or not isinstance(value, int):
                raise TypeError("amplitude %r is not an integer" % (value,))
            if value < 0:
                raise ValueError("amplitude %d is negative" % value)

    def _is_anomalous(self, amplitude):
        return amplitude > 2 * self._baseline

    def _escalate(self):
        if self._level_index < len(self._LEVELS) - 1:
            self._level_index += 1
        self._anomalies = 0

    def _evaluate_risk(self, amplitude):
        if self._is_anomalous(amplitude):
            self._anomalies += 1
        else:
            self._anomalies = 0
        if self._anomalies >= self._ANOMALY_THRESHOLD:
            self._escalate()

    def _update_baseline(self, amplitude):
        self._baseline = (self._baseline + amplitude) // 2

    def _current_level(self):
