DIRECTIONS = {"north": (0, 1), "south": (0, -1), "east": (1, 0), "west": (-1, 0)}


class HarvestSwarm:
    """A swarm of harvesting robots moving over a square field of crops."""

    SIZE = 10

    def __init__(self, robot_ids=(1, 2, 3)):
        self._grid = [[True] * self.SIZE for _ in range(self.SIZE)]
        self._positions = {rid: (0, 0) for rid in robot_ids}
        self._yields = {rid: 0 for rid in robot_ids}

    def _validate_coordinates(self, x, y):
        return 0 <= x < self.SIZE and 0 <= y < self.SIZE

    def _direction(self, command):
        key = str(command).strip().lower()
        if key not in DIRECTIONS:
            raise ValueError("unknown command: {!r}".format(command))
        return DIRECTIONS[key]

    def _position(self, robot_id):
        if robot_id not in self._positions:
            raise ValueError("unknown robot: {!r}".format(robot_id))
        return self._positions[robot_id]

    def _harvest_cell(self, robot_id, x, y):
        if self._grid[x][y]:
            self._grid[x][y] = False
            self._yields[robot_id] += 1

    def _move(self, robot_id, command):
        dx, dy = self._direction(command)
        x, y = self._position(robot_id)
        nx, ny = x + dx, y + dy
        if self._validate_coordinates(nx, ny):
            self._positions[robot_id] = (nx, ny)
            self._harvest_cell(robot_id, nx, ny)

    def execute(self, commands):
        for robot_id, command in commands:
            self._move(robot_id, command)

    def robot_yields(self):
        return [self._yields[rid] for rid in sorted(self._yields)]


def harvest(commands):
    swarm = HarvestSwarm()
    swarm.execute(commands)
    return swarm.robot_yields()


def parse_commands(text):
    commands = []
    for line in text.splitlines():
        fields = line.split()
        if not fields:
            continue
        if len(fields) != 2:
            raise ValueError("expected 'robot direction', got {!r}".format(line))
        commands.append((int(fields[0]), fields[1]))
    return commands


def format_yields(totals):
    return "\n".join("robot {}: {}".format(i, total) for i, total in enumerate(totals, 1))


def main():
    import sys

    print(format_yields(harvest(parse_commands(sys.stdin.read()))))


if __name__ == "__main__":
    main()

