FEED_THRESHOLD = 50
HUNGER_RATE = 10
FILTER_RATE = 2
FOOD_POLLUTION = 15
POLLUTION_LIMIT = 40


class FishFarm:
    """Automated feeder and water-filtration controller for a fish tank."""

    def __init__(self):
        self._hunger = 0
        self._pollution = 0
        self._log = []

    def _filtrate(self):
        self._pollution -= FILTER_RATE

    def _needs_flush(self):
        return self._pollution > POLLUTION_LIMIT

    def _flush(self):
        self._pollution //= 2

    def _is_hungry(self):
        return self._hunger >= FEED_THRESHOLD

    def _feed(self):
        self._hunger = 0
        self._pollution += FOOD_POLLUTION

    def _record(self, hour, event):
        entry = {"hour": hour, "event": event}
        entry["hunger"] = self._hunger
        entry["pollution"] = self._pollution
        self._log.append(entry)

    def _tick(self, hour):
        self._hunger += HUNGER_RATE
        self._filtrate()
        if self._needs_flush():
            self._flush()
            self._record(hour, "emergency flush")
        elif self._is_hungry():
            self._feed()
            self._record(hour, "feeding")
        else:
            self._record(hour, "idle")

    def run(self, hours):
        for hour in range(1, hours + 1):
            self._tick(hour)
        return self._hunger, self._pollution

    def report(self):
        lines = ["hour  event            hunger  pollution"]
        for entry in self._log:
            lines.append("{hour:>4}  {event:<15} {hunger:>7} {pollution:>10}".format(**entry))
        return "\n".join(lines)


def simulate(hours):
    if not isinstance(hours, int):
        raise TypeError("hours must be an integer")
    if hours < 0:
        raise ValueError("hours must not be negative")
    return FishFarm().run(hours)


def main():
    print("simulate(10) ->", simulate(10))
    farm = FishFarm()
    final = farm.run(30)
    print(farm.report())
    print("after 30 hours ->", final)


if __name__ == "__main__":
    main()

