class GarbageTruck:
    """A municipal garbage truck that keeps its load and odometer hidden."""

    MAX_CAPACITY = 50
    DUMP_DISTANCE = 10
    BLOCK_DISTANCE = 1

    def __init__(self):
        self._load = 0
        self._odometer = 0
        self._dumps = 0
        self._bags_taken = 0

    def _space_left(self):
        return self.MAX_CAPACITY - self._load

    def _drive(self, units):
        self._odometer += units

    def _dump_trip(self):
        self._drive(self.DUMP_DISTANCE)
        self._load = 0
        self._dumps += 1
        self._drive(self.DUMP_DISTANCE)

    def _collect(self, bags):
        while bags > 0:
            taken = min(bags, self._space_left())
            self._load += taken
            self._bags_taken += taken
            bags -= taken
            if bags > 0:
                self._dump_trip()

    def _validate(self, blocks):
        for index, bags in enumerate(blocks):
            if not isinstance(bags, int) or isinstance(bags, bool):
                raise TypeError("block %d is not an integer count" % index)
            if bags < 0:
                raise ValueError("block %d has a negative bag count" % index)

    def run(self, blocks):
        self._validate(blocks)
        for bags in blocks:
            self._collect(bags)
            self._drive(self.BLOCK_DISTANCE)
        return self._odometer

    def summary(self):
        """Describe the shift so far: bags taken, dump trips, distance."""
        return ("bags=%d dumps=%d load_on_return=%d distance=%d"
                % (self._bags_taken, self._dumps, self._load, self._odometer))


def route(blocks):
    """Return the total distance travelled while servicing every block."""
    return GarbageTruck().run(blocks)


def main(argv):
    blocks = [int(arg) for arg in argv[1:]] or [30, 30, 10]
    truck = GarbageTruck()
    distance = truck.run(blocks)
    print("route %s" % (blocks,))
    print(truck.summary())
    return distance


if __name__ == "__main__":
    import sys

    main(sys.argv)

