from collections import deque


class BuoyNetwork:
    """Tracks rolling wave-height averages per buoy and flags surge alerts."""

    WINDOW = 3
    SURGE_FACTOR = 3.0
    BASELINE = 1.0

    def __init__(self):
        self._history = {}
        self._alerts = {}

    def _queue_for(self, buoy):
        if buoy not in self._history:
            self._history[buoy] = deque([self.BASELINE] * self.WINDOW,
                                        maxlen=self.WINDOW)
            self._alerts[buoy] = False
        return self._history[buoy]

    def _rolling_average(self, buoy):
        queue = self._queue_for(buoy)
        return sum(queue) / len(queue)

    def _is_surge(self, buoy, height):
        return height > self.SURGE_FACTOR * self._rolling_average(buoy)

    def _update(self, buoy, height):
        if self._is_surge(buoy, height):
            self._alerts[buoy] = True
        self._queue_for(buoy).append(height)

    def submit(self, buoy, height):
        if not isinstance(buoy, str) or not buoy:
            raise ValueError("buoy identifier must be a non-empty string")
        try:
            height = float(height)
        except (TypeError, ValueError):
            raise ValueError("wave height must be numeric: %r" % (height,))
        if height < 0:
            raise ValueError("wave height cannot be negative: %g" % height)
        self._update(buoy, height)

    def alerting(self):
        return sorted(b for b, flagged in self._alerts.items() if flagged)

    def report(self):
        lines = []
        for buoy in sorted(self._history):
            status = "ALERT" if self._alerts[buoy] else "ok"
            lines.append("%s: avg=%.2f m [%s]"
                         % (buoy, self._rolling_average(buoy), status))
        return "\n".join(lines)


def monitor(readings):
    network = BuoyNetwork()
    for buoy, height in readings:
        network.submit(buoy, height)
    return network.alerting()


def main():
    readings = [("A", 1), ("A", 1), ("A", 5),
                ("B", 1.2), ("B", 1.1), ("B", 1.3),
                ("C", 2.0), ("C", 2.5), ("C", 9.0)]
    network = BuoyNetwork()
    for buoy, height in readings:
        network.submit(buoy, height)
    print(network.report())
    print("alerts:", network.alerting())
    print("monitor():", monitor(readings))


if __name__ == "__main__":
    main()

