MIN_BOILER = 40
MAX_BOILER = 90
START_BOILER = 60
RISE_PER_HOUR = 5
FALL_PER_HOUR = 2


class HeatingPlant:
    """Central boiler with a circulation pump serving a residential district."""

    def __init__(self):
        self._boiler = START_BOILER
        self._pump = False
        self._energy = 0
        self._history = []

    def _read(self, value):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("outside temperature must be a number, got %r" % (value,))
        return float(value)

    def _adjust_thermostat(self, outside):
        if outside < 0:
            self._pump = True
            self._boiler = min(MAX_BOILER, self._boiler + RISE_PER_HOUR)
        else:
            self._pump = False
            self._boiler = max(MIN_BOILER, self._boiler - FALL_PER_HOUR)

    def _accumulate_energy(self):
        if self._pump:
            self._energy += self._boiler

    def run(self, temperatures):
        for hour, value in enumerate(temperatures, start=1):
            outside = self._read(value)
            self._adjust_thermostat(outside)
            self._accumulate_energy()
            self._history.append((hour, outside, self._boiler, self._pump))
        return self._energy

    def hourly_report(self):
        lines = []
        for hour, outside, setpoint, pumping in self._history:
            lines.append("hour %2d | outside %6.1f | boiler %3d | pump %s"
                         % (hour, outside, setpoint, "ON" if pumping else "off"))
        lines.append("total energy consumed: %d" % self._energy)
        return "\n".join(lines)


def distribute(temperatures):
    """Return the total energy consumed over the given hourly readings."""
    plant = HeatingPlant()
