MIN_BOILER = 40
MAX_BOILER = 90
START_BOILER = 60
RISE_PER_HOUR = 5
FALL_PER_HOUR = 2


class HeatingPlant:
    """Central boiler with a circulation pump serving a residential district."""

    def __init__(self):
        self.boiler = START_BOILER
        self.pump = False
        self.energy = 0
        self.history = []

    def read(self, value):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("outside temperature must be a number, got %r" % (value,))
        return float(value)

    def adjust_thermostat(self, outside):
        if outside < 0:
            self.pump = True
            self.boiler = min(MAX_BOILER, self.boiler + RISE_PER_HOUR)
        else:
            self.pump = False
            self.boiler = max(MIN_BOILER, self.boiler - FALL_PER_HOUR)

    def accumulate_energy(self):
        if self.pump:
            self.energy += self.boiler

    def run(self, temperatures):
        for hour, value in enumerate(temperatures, start=1):
            outside = self.read(value)
            self.adjust_thermostat(outside)
            self.accumulate_energy()
            self.history.append((hour, outside, self.boiler, self.pump))
        return self.energy

    def hourly_report(self):
        lines = []
        for hour, outside, setpoint, pumping in self.history:
            lines.append("hour %2d | outside %6.1f | boiler %3d | pump %s"
                         % (hour, outside, setpoint, "ON" if pumping else "off"))
        lines.append("total energy consumed: %d" % self.energy)
        return "\n".join(lines)


def distribute(temperatures):
    """Return the total energy consumed over the given hourly readings."""
    plant = HeatingPlant()
    return plant.run(temperatures)


def main():
    plant = HeatingPlant()
    plant.run([-5, -2, 3])
    print(plant.hourly_report())
    week = [-8, -6, -1, 0, 2, 5, -3, -9, -12, 1]
    print("ten-hour district demand: %d" % distribute(week))


if __name__ == "__main__":
    main()

