class ArcheryTournament:
    """Accumulates archery shots and keeps the scoreboard as internal state."""

    def __init__(self):
        self._scores = {}
        self._hits = {}
        self._streaks = {}
        self._thresholds = ((2, 10), (5, 5), (10, 1))
        self._streak_length = 3
        self._streak_bonus = 5

    def _points_for(self, distance):
        if distance < 0:
            raise ValueError("distance from the center cannot be negative")
        for limit, points in self._thresholds:
            if distance <= limit:
                return points
        return 0

    def _update_streak(self, archer, points):
        if points != max(p for _, p in self._thresholds):
            self._streaks[archer] = 0
            return 0
        running = self._streaks.get(archer, 0) + 1
        if running == self._streak_length:
            self._streaks[archer] = 0
            return self._streak_bonus
        self._streaks[archer] = running
        return 0

    def record(self, archer, distance):
        points = self._points_for(distance)
        bonus = self._update_streak(archer, points)
        self._scores[archer] = self._scores.get(archer, 0) + points + bonus
        self._hits[archer] = self._hits.get(archer, 0) + 1
        return points + bonus

    def record_all(self, shots):
        for archer, distance in shots:
            self.record(archer, distance)

    def standings(self):
        ranked = sorted(self._scores.items(), key=lambda item: (-item[1], item[0]))
        return ranked

    def report(self):
        lines = []
        for archer, total in self.standings():
            arrows = self._hits[archer]
            noun = "arrow" if arrows == 1 else "arrows"
            lines.append("{:<10} {:>4} points ({} {})".format(archer, total, arrows, noun))
        return "\n".join(lines)


def score(shots):
    """Return the final score of the winning archer."""
    tournament = ArcheryTournament()
    tournament.record_all(shots)
    ranked = tournament.standings()
    if not ranked:
        return 0
    return ranked[0][1]


