    shots = [
        ("Alice", 1), ("Alice", 1), ("Alice", 1),
        ("Bob", 3), ("Bob", 0), ("Bob", 12), ("Bob", 8),
        ("Carol", 2), ("Carol", 2), ("Carol", 6), ("Carol", 1),
    ]
    tournament = ArcheryTournament()
    tournament.record_all(shots)
    print(tournament.report())
    print("Winning score:", score(shots))


if __name__ == "__main__":
    main()

