class MemoryManager:
    """Tracks allocated objects, their links, and the active root set."""

    def __init__(self):
        self._objects = set()
        self._links = {}
        self._roots = set()
        self._marked = set()
        self.swept_total = 0

    def allocate(self, name):
        self._objects.add(name)
        self._links.setdefault(name, set())

    def set_root(self, name):
        if name in self._objects:
            self._roots.add(name)

    def remove_root(self, name):
        self._roots.discard(name)

    def link(self, source, target):
        if source in self._objects and target in self._objects:
            self._links[source].add(target)

    def _mark(self, name):
        if name in self._marked:
            return
        self._marked.add(name)
        for child in self._links.get(name, ()):
            self._mark(child)

    def _sweep(self):
        garbage = self._objects - self._marked
        for name in garbage:
            self._objects.discard(name)
            self._links.pop(name, None)
            self._roots.discard(name)
        for remaining in self._links.values():
            remaining -= garbage
        return len(garbage)

    def _clear_marks(self):
        self._marked.clear()

    def collect(self):
        for root in self._roots:
            self._mark(root)
        collected = self._sweep()
        self._clear_marks()
        self.swept_total += collected
        return collected


def parse(command):
    parts = command.split()
    if not parts:
        raise ValueError("empty command")
    return parts[0].lower(), parts[1:]


def clean(operations):
    manager = MemoryManager()
    for command in operations:
        verb, args = parse(command)
        if verb == "allocate":
            manager.allocate(args[0])
        elif verb == "root":
            manager.set_root(args[0])
        elif verb == "unroot":
            manager.remove_root(args[0])
        elif verb == "link":
            manager.link(args[0], args[1])
        elif verb == "sweep":
            manager.collect()
        else:
            raise ValueError("unknown command: " + verb)
    return manager.swept_total


def main():
    script = [
        "allocate item",
        "root item",
        "allocate extra",
        "sweep",
        "allocate child",
        "link item child",
        "sweep",
        "unroot item",
        "sweep",
    ]
    print("objects swept:", clean(script))


