class DiskManager:
    _BLOCK = 16

    def __init__(self):
        self._root = {}
        self._cwd = []
        self._perms = {}
        self._blocks = {}
        self._next_id = 0

    def _parse(self, path):
        base = [] if path.startswith("/") else list(self._cwd)
        for part in path.split("/"):
            if part in ("", "."):
                continue
            if part == "..":
                if base:
                    base.pop()
            else:
                base.append(part)
        return base

    def _walk(self, parts):
        node = self._root
        for part in parts:
            if not isinstance(node, dict) or part not in node:
                return None
            node = node[part]
        return node

    def _key(self, parts):
        return "/" + "/".join(parts)

    def _check_access(self, parts, mode):
        return mode in self._perms.get(self._key(parts), "rw")

    def _allocate(self, file_id, data):
        chunks = [data[i:i + self._BLOCK] for i in range(0, len(data), self._BLOCK)]
        self._blocks[file_id] = chunks or [""]
        return len(data)

    def _fetch(self, file_id):
        return "".join(self._blocks[file_id])

    def mkdir(self, path):
        parts = self._parse(path)
        if not parts:
            return "error: invalid path"
        parent = self._walk(parts[:-1])
        if not isinstance(parent, dict):
            return "error: no such directory"
        if parts[-1] in parent:
            return "error: already exists"
        parent[parts[-1]] = {}
        return "ok"

    def write(self, path, data):
        parts = self._parse(path)
        if not parts:
            return "error: invalid path"
        parent = self._walk(parts[:-1])
        if not isinstance(parent, dict):
            return "error: no such directory"
        existing = parent.get(parts[-1])
        if isinstance(existing, dict):
            return "error: is a directory"
        if existing is not None and not self._check_access(parts, "w"):
            return "error: permission denied"
        if existing is None:
            self._next_id += 1
            existing = self._next_id
            parent[parts[-1]] = existing
        return self._allocate(existing, data)

    def read(self, path):
        parts = self._parse(path)
        node = self._walk(parts)
        if node is None:
            return "error: no such file"
        if isinstance(node, dict):
            return "error: is a directory"
        if not self._check_access(parts, "r"):
            return "error: permission denied"
        return self._fetch(node)

    def chmod(self, path, mode):
        parts = self._parse(path)
        if self._walk(parts) is None:
            return "error: no such file"
        self._perms[self._key(parts)] = mode
        return "ok"

    def cd(self, path):
        parts = self._parse(path)
        if not isinstance(self._walk(parts), dict):
            return "error: no such directory"
        self._cwd = parts
        return self._key(parts)

    def ls(self, path="."):
        node = self._walk(self._parse(path))
        if not isinstance(node, dict):
            return "error: no such directory"
        return sorted(node)


def execute(commands):
    manager = DiskManager()
    handlers = {
        "mkdir": manager.mkdir,
        "write": manager.write,
        "read": manager.read,
        "chmod": manager.chmod,
        "cd": manager.cd,
        "ls": manager.ls,
    }
    results = []
    for command in commands:
        op, args = command[0], command[1:]
        handler = handlers.get(op)
        if handler is None:
            results.append("error: unknown command " + str(op))
            continue
        try:
            results.append(handler(*args))
        except TypeError:
            results.append("error: bad arguments for " + op)
    return results


if __name__ == "__main__":
    for line in execute([("mkdir", "/docs"), ("cd", "/docs"),
                         ("write", "note.txt", "hello disk"), ("read", "note.txt"),
                         ("chmod", "note.txt", "r"), ("write", "note.txt", "x"),
                         ("ls", "/docs")]):
        print(line)

