class RiskAssessor:
    """Tracks per-customer spending behaviour and scores incoming transactions."""

    DAILY_LIMIT = 5000.0
    SPIKE_FACTOR = 3.0
    VELOCITY_LIMIT = 3
    FLAG_AT = 0.5

    def __init__(self):
        self._history = {}
        self._daily_totals = {}
        self._locations = {}
        self._attempts = {}

    def _normalize(self, transaction):
        user, amount, location = transaction
        amount = float(amount)
        if amount < 0:
            raise ValueError("transaction amount must not be negative")
        return user, amount, str(location)

    def _spike_ratio(self, user, amount):
        past = self._history.get(user, ())
        if not past:
            return 1.0
        average = sum(past) / len(past)
        if average <= 0:
            return 1.0
        return amount / average

    def _geographic_jump(self, user, location):
        visited = self._locations.get(user)
        if not visited:
            return False
        return location not in visited

    def _next_velocity(self, user):
        return self._attempts.get(user, 0) + 1

    def _risk_score(self, user, amount, location):
        score = 0.0
        if self._spike_ratio(user, amount) >= self.SPIKE_FACTOR:
            score += 0.5
        if self._geographic_jump(user, location):
            score += 0.3
        if self._next_velocity(user) > self.VELOCITY_LIMIT:
            score += 0.2
        if self._daily_totals.get(user, 0.0) + amount > self.DAILY_LIMIT:
            score += 0.25
        return score

    def _record(self, user, amount, location):
        self._history.setdefault(user, []).append(amount)
        self._daily_totals[user] = self._daily_totals.get(user, 0.0) + amount
        self._locations.setdefault(user, set()).add(location)
        self._attempts[user] = self._next_velocity(user)

    def screen(self, transaction):
        user, amount, location = self._normalize(transaction)
        score = self._risk_score(user, amount, location)
        self._record(user, amount, location)
        return score >= self.FLAG_AT


def evaluate(transactions):
    assessor = RiskAssessor()
    return [assessor.screen(transaction) for transaction in transactions]


def format_report(transactions, flags):
    lines = []
    for (user, amount, location), flagged in zip(transactions, flags):
        status = "FLAGGED" if flagged else "ok"
        lines.append("{:<8} {:>10.2f} {:<12} {}".format(user, float(amount), location, status))
    return "\n".join(lines)


def main():
    transactions = [
        ("alice", 40.0, "Lisbon"),
        ("alice", 3200.0, "Sofia"),
        ("bob", 120.0, "Oslo"),
        ("bob", 130.0, "Oslo"),
        ("bob", 140.0, "Oslo"),
        ("bob", 150.0, "Oslo"),
    ]
    print(format_report(transactions, evaluate(transactions)))


if __name__ == "__main__":
    main()

