        score = self.risk_score(user, amount, location)
        self.record(user, amount, location)
        return score >= self.FLAG_AT


def evaluate(transactions):
    assessor = RiskAssessor()
    return [assessor.screen(transaction) for transaction in transactions]


def format_report(transactions, flags):
    lines = []
    for (user, amount, location), flagged in zip(transactions, flags):
        status = "FLAGGED" if flagged else "ok"
        lines.append("{:<8} {:>10.2f} {:<12} {}".format(user, float(amount), location, status))
    return "\n".join(lines)


