NO_MATCH = "no match"


class BedCoordinator:
    """Coordinates bed assignment across wards, honouring severity levels."""

    def __init__(self):
        self._roster = self._load()
        self._capacity = self._capacity_limits()
        self._occupied = set()

    def _load(self):
        return {
            "cardiology": [("CARD-01", 3), ("CARD-02", 2), ("CARD-03", 1)],
            "icu": [("ICU-01", 3), ("ICU-02", 3)],
            "general": [("GEN-01", 1), ("GEN-02", 1), ("GEN-03", 2)],
            "pediatrics": [("PED-01", 2), ("PED-02", 1)],
            "neurology": [("NEU-01", 3), ("NEU-02", 2)],
        }

    def _capacity_limits(self):
        return {"cardiology": 3, "icu": 2, "general": 2, "pediatrics": 2, "neurology": 2}

    def _fallback_wards(self, ward):
        chains = {
            "cardiology": ["icu", "general"],
            "neurology": ["icu", "general"],
            "pediatrics": ["general"],
            "icu": ["cardiology", "neurology"],
            "general": ["pediatrics"],
        }
        return [w for w in chains.get(ward, []) if not self._is_full(w)]

    def _is_full(self, ward):
        beds = self._roster.get(ward, [])
        used = sum(1 for bed_id, _level in beds if bed_id in self._occupied)
        return used >= self._capacity.get(ward, 0)

    def _available(self, ward):
        if self._is_full(ward):
            return []
        return [bed for bed in self._roster.get(ward, []) if bed[0] not in self._occupied]

    def _select(self, beds, rank):
        suitable = [bed for bed in beds if bed[1] >= rank]
        if rank >= 3:
            return max(beds, key=lambda bed: bed[1])
        if suitable:
            return min(suitable, key=lambda bed: bed[1])
        return max(beds, key=lambda bed: bed[1])

    def _lock_in(self, bed):
        self._occupied.add(bed[0])
        return bed[0]

    def assign(self, ward, severity):
        key = str(ward).strip().lower()
        rank = SEVERITY_RANK.get(str(severity).strip().lower())
        if rank is None or key not in self._roster:
            return NO_MATCH
        beds = self._available(key)
        if not beds:
            for alternative in self._fallback_wards(key):
                beds = self._available(alternative)
                if beds:
                    break
        if not beds:
            return NO_MATCH
        return self._lock_in(self._select(beds, rank))


