class TaskExecutor:
    """Simulates a fixed pool of concurrent workers executing dependent tasks."""

    def __init__(self, tasks, worker_count=2):
        if worker_count < 1:
            raise ValueError("at least one worker is required")
        self._durations = {}
        self._prereqs = {}
        self._pending = []
        for name, duration, prerequisites in tasks:
            if name in self._durations:
                raise ValueError("duplicate task name: %s" % name)
            if duration < 0:
                raise ValueError("negative duration for task: %s" % name)
            self._durations[name] = duration
            self._prereqs[name] = list(prerequisites)
            self._pending.append(name)
        self._validate_prereqs()
        self._done = set()
        self._workers = [None] * worker_count
        self._clock = 0

    def _validate_prereqs(self):
        for name, prerequisites in self._prereqs.items():
            for required in prerequisites:
                if required not in self._durations:
                    raise ValueError("task %s requires unknown task %s" % (name, required))
                if required == name:
                    raise ValueError("task %s depends on itself" % name)

    def _is_ready(self, name):
        for required in self._prereqs[name]:
            if required not in self._done:
                return False
        return True

    def _assign(self):
        for index in range(len(self._workers)):
            if self._workers[index] is not None:
                continue
            chosen = None
            for name in self._pending:
                if self._is_ready(name):
                    chosen = name
                    break
            if chosen is None:
                return
            self._pending.remove(chosen)
            self._workers[index] = (chosen, self._clock + self._durations[chosen])

    def _busy_slots(self):
        return [slot for slot in self._workers if slot is not None]

    def _advance(self):
        busy = self._busy_slots()
        self._clock = min(slot[1] for slot in busy)
        for index in range(len(self._workers)):
            slot = self._workers[index]
            if slot is not None and slot[1] <= self._clock:
                self._done.add(slot[0])
                self._workers[index] = None

    def run(self):
        while self._pending or self._busy_slots():
            self._assign()
            if not self._busy_slots():
                raise ValueError("unsatisfiable prerequisites among: %s" % ", ".join(self._pending))
            self._advance()
        return self._clock


def process(tasks):
    """Return the total simulated minutes needed to run all tasks."""
    return TaskExecutor(tasks).run()

