class SessionManager:
    def __init__(self):
        self._buffers = {}
        self._expected_seq = {}
        self._completed = {}

    def _merge_fragments(self, fragments):
        sorted_frags = sorted(fragments, key=lambda x: x[0])
        merged = []
        for seq, text in sorted_frags:
            if not merged or merged[-1][0] != seq:
                merged.append((seq, text))
            elif len(text) > len(merged[-1][1]):
                merged[-1] = (seq, text)
        return merged

    def _is_contiguous(self, fragments, expected):
        if not fragments:
            return False
        current_expected = expected
        for seq, _ in fragments:
            if seq != current_expected:
                return False
            current_expected += 1
        return True

    def _flush_buffer(self, conn_id):
        fragments = self._merge_fragments(self._buffers[conn_id])
        expected = self._expected_seq[conn_id]

        if self._is_contiguous(fragments, expected):
            assembled_text = "".join(text for _, text in fragments)
            self._completed[conn_id] = assembled_text
            self._buffers[conn_id] = []
            self._expected_seq[conn_id] = expected + len(fragments)

    def process_packet(self, conn_id, seq_num, fragment):
        if conn_id not in self._buffers:
            self._buffers[conn_id] = []
            self._expected_seq[conn_id] = 0

        self._buffers[conn_id].append((seq_num, fragment))
        self._flush_buffer(conn_id)

    def get_results(self):
        return list(self._completed.values())


def assemble(packets):
    manager = SessionManager()
    for conn_id, seq_num, fragment in packets:
        manager.process_packet(conn_id, seq_num, fragment)
    return manager.get_results()

