import math


class InventoryPlanner:
    """Plans replenishment orders from observed daily sales and supplier delays."""

    def __init__(self, initial_stock=0.0, default_lead=1, alpha=0.4, safety=1.15):
        self.stock = float(initial_stock)
        self.default_lead = int(default_lead)
        self.alpha = float(alpha)
        self.safety = float(safety)
        self._history = []
        self._ema = None
        self._seasonal = [1.00, 0.95, 0.95, 1.00, 1.10, 1.25, 1.15]
        self._pipeline = {}
        self._cache = {}

    def _parse(self, entry):
        if isinstance(entry, dict):
            qty = entry.get("sales", entry.get("qty", 0.0))
            lead = entry.get("delay", entry.get("lead", self.default_lead))
        elif isinstance(entry, (int, float)):
            qty, lead = entry, self.default_lead
        else:
            qty, lead = entry
        qty = float(qty)
        lead = int(lead)
        if qty < 0:
            raise ValueError("sales quantity cannot be negative")
        if lead < 0:
            raise ValueError("supplier delay cannot be negative")
        return qty, lead

    def _record(self, qty):
        self._history.append(qty)
        if self._ema is None:
            self._ema = qty
        else:
            self._ema = self.alpha * qty + (1.0 - self.alpha) * self._ema
        self._cache.clear()

    def _season_factor(self, day):
        return self._seasonal[day % len(self._seasonal)]

    def _deseasonalised_base(self):
        weights = [self._season_factor(i) for i in range(len(self._history))]
        recent = self._ema / (sum(weights[-7:]) / len(weights[-7:]))
        return max(recent, 0.0)

    def _projected_demand(self, day, lead):
        key = (day % len(self._seasonal), lead)
        if key not in self._cache:
            base = self._deseasonalised_base()
            self._cache[key] = sum(
                base * self._season_factor(day + step) for step in range(1, lead + 1)
            )
        return self._cache[key]

    def _on_order(self):
        return sum(self._pipeline.values())

    def _receive(self, day):
        self.stock += self._pipeline.pop(day, 0.0)

    def _reorder_quantity(self, day, lead):
        target = self._projected_demand(day, lead) * self.safety
        gap = target - self.stock - self._on_order()
        return int(math.ceil(gap)) if gap > 0 else 0

    def step(self, day, entry):
        qty, lead = self._parse(entry)
        self._receive(day)
        shipped = min(self.stock, qty)
        self.stock -= shipped
        self._record(qty)
        order = self._reorder_quantity(day, lead)
        if order:
            arrival = day + max(lead, 1)
            self._pipeline[arrival] = self._pipeline.get(arrival, 0.0) + order
        return order


def predict(sales):
    planner = InventoryPlanner()
    return [planner.step(day, entry) for day, entry in enumerate(sales)]

