import hashlib


class VersionTracker:
    """Minimal content-addressable version tracker for a working directory."""

    def __init__(self, branch="main"):
        self.branch = branch
        self.working = {}
        self._cache = {}
        self._blobs = {}
        self._commits = {}
        self._heads = {branch: None}

    def _hash(self, content):
        if content not in self._cache:
            digest = hashlib.sha1(("blob " + content).encode("utf-8")).hexdigest()
            self._cache[content] = digest
            self._blobs[digest] = content
        return self._cache[content]

    def _load(self, commit_id):
        if commit_id is None:
            return {}
        return dict(self._commits[commit_id]["tree"])

    def stage(self, name, content):
        if not isinstance(name, str) or not name:
            raise ValueError("file name must be a non-empty string")
        if not isinstance(content, str):
            raise TypeError("file content must be a string")
        self.working[name] = self._hash(content)

    def _diff(self):
        parent = self._load(self._heads[self.branch])
        changed = {}
        for name, blob in self.working.items():
            if parent.get(name) != blob:
                changed[name] = blob
        for name in parent:
            if name not in self.working:
                changed[name] = None
        return changed

    def _next_id(self, message, changed):
        parts = [self.branch, str(self._heads[self.branch]), message]
        for name in sorted(changed):
            parts.append(name + ":" + str(changed[name]))
        return hashlib.sha1("\n".join(parts).encode("utf-8")).hexdigest()

    def commit(self, message):
        changed = self._diff()
        if not changed:
            return None
        commit_id = self._next_id(message, changed)
        self._commits[commit_id] = {
            "message": message,
            "parent": self._heads[self.branch],
            "branch": self.branch,
            "tree": dict(self.working),
            "changed": sorted(changed),
        }
        self._heads[self.branch] = commit_id
        return commit_id

    def log(self):
        entries = []
        current = self._heads[self.branch]
        while current is not None:
            record = self._commits[current]
            entries.append((current[:7], record["message"], record["changed"]))
            current = record["parent"]
        return entries


def commit(changes):
    tracker = VersionTracker()
    hashes = []
    for name, content in changes:
        tracker.stage(name, content)
        commit_id = tracker.commit("add " + name)
        if commit_id is not None:
            hashes.append(commit_id)
    return hashes


def main():
    tracker = VersionTracker()
    for name, content in [("a.txt", "hello"), ("b.txt", "hello"), ("a.txt", "world")]:
        tracker.stage(name, content)
        tracker.commit("update " + name)
    for short_id, message, changed in tracker.log():
        print(short_id, message, ",".join(changed))
    print(commit([("readme.md", "# project")]))


if __name__ == "__main__":
    main()

