        if commit_id is None:
            return {}
        return dict(self.commits[commit_id]["tree"])

    def stage(self, name, content):
        if not isinstance(name, str) or not name:
            raise ValueError("file name must be a non-empty string")
        if not isinstance(content, str):
            raise TypeError("file content must be a string")
        self.working[name] = self.hash(content)

    def diff(self):
        parent = self.load(self.heads[self.branch])
        changed = {}
        for name, blob in self.working.items():
            if parent.get(name) != blob:
                changed[name] = blob
        for name in parent:
            if name not in self.working:
                changed[name] = None
        return changed

    def next_id(self, message, changed):
        parts = [self.branch, str(self.heads[self.branch]), message]
        for name in sorted(changed):
            parts.append(name + ":" + str(changed[name]))
        return hashlib.sha1("\n".join(parts).encode("utf-8")).hexdigest()

    def commit(self, message):
        changed = self.diff()
        if not changed:
            return None
        commit_id = self.next_id(message, changed)
        self.commits[commit_id] = {
            "message": message,
            "parent": self.heads[self.branch],
            "branch": self.branch,
            "tree": dict(self.working),
            "changed": sorted(changed),
        }
        self.heads[self.branch] = commit_id
        return commit_id

    def log(self):
        entries = []
        current = self.heads[self.branch]
        while current is not None:
            record = self.commits[current]
            entries.append((current[:7], record["message"], record["changed"]))
            current = record["parent"]
        return entries


def commit(changes):
    tracker = VersionTracker()
    hashes = []
    for name, content in changes:
        tracker.stage(name, content)
        commit_id = tracker.commit("add " + name)
        if commit_id is not None:
            hashes.append(commit_id)
    return hashes


def main():
    tracker = VersionTracker()
    for name, content in [("a.txt", "hello"), ("b.txt", "hello"), ("a.txt", "world")]:
        tracker.stage(name, content)
        tracker.commit("update " + name)
    for short_id, message, changed in tracker.log():
        print(short_id, message, ",".join(changed))
    print(commit([("readme.md", "# project")]))


if __name__ == "__main__":
    main()

