from collections import Counter, defaultdict


class InteractionProfiler:
    """Aggregates user interactions into co-occurrence and history matrices."""

    _ACTION_WEIGHTS = {"view": 1.0, "buy": 3.0}

    def __init__(self):
        self._history = defaultdict(Counter)
        self._purchases = defaultdict(set)
        self._cooc = defaultdict(Counter)

    def add(self, user, action, product):
        weight = self._weight_of(action)
        self._update_cooc(user, product, weight)
        self._history[user][product] += weight
        if action.strip().lower() == "buy":
            self._purchases[user].add(product)

    def _weight_of(self, action):
        key = str(action).strip().lower()
        if key not in self._ACTION_WEIGHTS:
            raise ValueError("unknown action: %r" % (action,))
        return self._ACTION_WEIGHTS[key]

    def _update_cooc(self, user, product, weight):
        for other, other_weight in self._history[user].items():
            if other == product:
                continue
            strength = weight * other_weight
            self._cooc[product][other] += strength
            self._cooc[other][product] += strength

    def _affinities(self, user):
        scores = Counter()
        for product, weight in self._history[user].items():
            for neighbour, strength in self._cooc[product].items():
                scores[neighbour] += weight * strength
        return scores

    def _filter_purchased(self, user, scores):
        known = set(self._history[user]) | self._purchases[user]
        return {p: s for p, s in scores.items() if p not in known}

    def _score(self, user):
        candidates = self._filter_purchased(user, self._affinities(user))
        return sorted(candidates.items(), key=lambda item: (-item[1], item[0]))

    def users(self):
        return sorted(self._history)

    def top_product(self, user):
        ranked = self._score(user)
        return ranked[0][0] if ranked else None


def recommend(activities):
    profiler = InteractionProfiler()
    for entry in activities:
        user, action, product = entry
        profiler.add(user, action, product)
    results = []
    for user in profiler.users():
        product = profiler.top_product(user)
        if product is not None:
            results.append((user, product))
    return results


def format_recommendations(pairs):
    return "\n".join("%s -> %s" % (user, product) for user, product in pairs)


def main():
    activities = [
        ("alice", "view", "phone"),
        ("alice", "buy", "charger"),
        ("bob", "view", "phone"),
        ("bob", "buy", "phone_case"),
        ("carol", "view", "phone"),
        ("carol", "view", "phone_case"),
        ("carol", "buy", "charger"),
    ]
    print(format_recommendations(recommend(activities)))


if __name__ == "__main__":
    main()

