class Underwriter:
    """Computes motor insurance premiums from driver/vehicle risk profiles."""

    BASE_RATE = 600.0

    def __init__(self, base_rate=BASE_RATE):
        self.base_rate = base_rate
        self._age_bands = [(21, 2.40), (25, 1.85), (35, 1.20), (60, 1.00), (75, 1.35)]
        self._accident_steps = [0.0, 0.35, 0.85, 1.60]
        self._cache = {}

    def _validate(self, profile):
        if len(profile) != 3:
            raise ValueError("profile must be (age, safety_rating, accidents)")
        age, safety, accidents = profile
        if not 16 <= age <= 100:
            raise ValueError("age out of range: %r" % (age,))
        if not 1 <= safety <= 5:
            raise ValueError("safety rating must be 1..5: %r" % (safety,))
        if accidents < 0:
            raise ValueError("accident count must not be negative")
        return int(age), int(safety), int(accidents)

    def _age_multiplier(self, age):
        for limit, factor in self._age_bands:
            if age < limit:
                return factor
        return 1.75

    def _safety_discount(self, safety):
        return 1.0 - 0.06 * (safety - 1)

    def _accident_penalty(self, accidents):
        if accidents < len(self._accident_steps):
            return 1.0 + self._accident_steps[accidents]
        extra = accidents - len(self._accident_steps) + 1
        return 1.0 + self._accident_steps[-1] + 0.45 * extra

    def _compound(self, age, safety, accidents):
        premium = self.base_rate
        premium *= self._age_multiplier(age)
        premium *= self._safety_discount(safety)
        premium *= self._accident_penalty(accidents)
        if accidents and age < 25:
            premium *= 1.20
        return round(premium, 2)

    def price(self, profile):
        key = self._validate(profile)
        if key not in self._cache:
            self._cache[key] = self._compound(*key)
        return self._cache[key]


def quote(profiles):
    """Return a list of premiums, one per (age, safety_rating, accidents) tuple."""
    underwriter = Underwriter()
    return [underwriter.price(profile) for profile in profiles]


def format_report(profiles, premiums):
    lines = ["age  safety  accidents   premium"]
    for (age, safety, accidents), premium in zip(profiles, premiums):
        lines.append("%3d  %6d  %9d  %8.2f" % (age, safety, accidents, premium))
    return "\n".join(lines)


def main():
    profiles = [
        (19, 2, 2),
        (19, 2, 2),
        (23, 4, 0),
        (41, 5, 1),
        (67, 3, 0),
        (80, 3, 3),
    ]
    print(format_report(profiles, quote(profiles)))


if __name__ == "__main__":
    main()

