from itertools import chain


class FleetManager:
    """Tracks driver positions, regional demand and accumulated rider waits."""

    _REGION_SIZE = 5
    _BASE_FARE = 2.50
    _PER_BLOCK = 1.75
    _WAIT_FEE = 0.35

    def __init__(self, drivers):
        self._available = [self._coerce(d) for d in drivers]
        self._demand = {}
        self._wait_times = []

    def _coerce(self, coord):
        x, y = coord
        return (float(x), float(y))

    def _region(self, coord):
        return (int(coord[0]) // self._REGION_SIZE, int(coord[1]) // self._REGION_SIZE)

    def _grid_distance(self, origin, target):
        return abs(origin[0] - target[0]) + abs(origin[1] - target[1])

    def _record_demand(self, rider):
        key = self._region(rider)
        self._demand[key] = self._demand.get(key, 0) + 1

    def _surge(self, rider):
        requests_here = self._demand.get(self._region(rider), 0)
        return min(2.5, 1.0 + 0.25 * max(requests_here - 1, 0))

    def _closest_driver(self, rider):
        if not self._available:
            return None
        best = min(self._available, key=lambda d: self._grid_distance(rider, d))
        self._available.remove(best)
        return best

    def _pressure(self):
        if not self._wait_times:
            return 1.0
        mean_wait = sum(self._wait_times) / len(self._wait_times)
        return 1.0 + min(0.5, mean_wait / 60.0)

    def _register_wait(self, distance):
        wait = 2.0 + 1.5 * distance
        self._wait_times.append(wait)
        return wait

    def _estimate_cost(self, distance, wait, multiplier):
        fare = self._BASE_FARE + self._PER_BLOCK * distance + self._WAIT_FEE * wait
        return round(fare * multiplier, 2)

    def assign(self, rider):
        rider = self._coerce(rider)
        self._record_demand(rider)
        driver = self._closest_driver(rider)
        if driver is None:
            return None, None
        distance = self._grid_distance(rider, driver)
        multiplier = self._surge(rider) * self._pressure()
        wait = self._register_wait(distance)
        return driver, self._estimate_cost(distance, wait, multiplier)


def dispatch(requests):
    """requests: list of (rider_coord, [driver_coord, ...]) pairs."""
    fleet = FleetManager(chain.from_iterable(drivers for _, drivers in requests))
    return [fleet.assign(rider) for rider, _ in requests]


def main():
    requests = [
        ((1, 1), [(1, 2), (9, 9)]),
        ((2, 2), [(12, 3)]),
        ((3, 1), []),
        ((20, 20), [(21, 20)]),
    ]
    for (rider, _), (driver, cost) in zip(requests, dispatch(requests)):
        if driver is None:
            print(f"rider {rider}: no driver available")
        else:
            print(f"rider {rider}: driver {driver} cost ${cost:.2f}")


if __name__ == "__main__":
    main()

