import math


class SensorAnalyzer:
    """Rolling-window analyzer that flags readings deviating from the baseline."""

    WINDOW = 10
    WARMUP = 3
    THRESHOLD = 3.0
    NOISE_FLOOR = 0.5

    def __init__(self):
        self._window = []
        self._baseline = 0.0
        self._streak = 0
        self._variances = []
        self.alerts = []

    def _mean(self, values):
        return sum(values) / float(len(values))

    def _stddev(self, values):
        mu = self._mean(values)
        variance = sum((v - mu) ** 2 for v in values) / float(len(values))
        self._variances.append(variance)
        return math.sqrt(variance)

    def _smooth(self, value):
        """Pull a value back to the baseline when it only differs by noise."""
        drift = value - self._baseline
        if abs(drift) <= self.NOISE_FLOOR:
            return self._baseline
        return self._baseline + drift * 0.9

    def _update_baseline(self, value):
        self._window.append(value)
        if len(self._window) > self.WINDOW:
            self._window.pop(0)
        self._baseline = self._mean(self._window)

    def _alert(self, index, value, deviation):
        self._streak += 1
        self.alerts.append(
            {
                "index": index,
                "value": value,
                "deviation": deviation,
                "streak": self._streak,
                "baseline": self._baseline,
            }
        )

    def feed(self, index, value):
        """Consume one reading; return True when it is an anomaly."""
        if len(self._window) < self.WARMUP:
            self._update_baseline(value)
            return False
        spread = self._stddev(self._window)
        filtered = self._smooth(value)
        deviation = abs(filtered - self._baseline)
        tolerance = max(spread * self.THRESHOLD, self.NOISE_FLOOR)
        if deviation > tolerance:
            self._alert(index, value, deviation)
            return True
        self._streak = 0
        self._update_baseline(value)
        return False

    def report(self):
        peak = max((a["deviation"] for a in self.alerts), default=0.0)
        return "{0} alert(s), peak deviation {1:.2f}, mean variance {2:.2f}".format(
            len(self.alerts), peak, self._mean(self._variances) if self._variances else 0.0
        )


def monitor(readings):
    analyzer = SensorAnalyzer()
    return [i for i, value in enumerate(readings) if analyzer.feed(i, float(value))]


def main():
    series = [20.0, 20.1, 19.9, 20.2, 20.0, 19.8, 20.1, 250.0, 20.0, 20.1]
    print("anomalies at:", monitor(series))
    detector = SensorAnalyzer()
    for i, value in enumerate(series):
        detector.feed(i, value)
    print(detector.report())


if __name__ == "__main__":
    main()

