    _DEFAULT_STAY = {"small": 3.0, "large": 6.0}

    def __init__(self, small_bays=2, large_bays=2):
        self._sizes = ["small"] * small_bays + ["large"] * large_bays
        self._free_at = [0.0] * len(self._sizes)
        self._schedule = {i: [] for i in range(len(self._sizes))}
        self._maintenance = [False] * len(self._sizes)
        self._last_maint = [0] * len(self._sizes)
        self._queue = []

    def _parse(self, entry):
        if isinstance(entry, dict):
            size = str(entry["size"]).lower()
            arrival = entry["arrival"]
            duration = entry.get("duration", self._DEFAULT_STAY.get(size))
        else:
            size = str(entry[0]).lower()
            arrival = entry[1]
            duration = entry[2] if len(entry) > 2 else self._DEFAULT_STAY.get(size)
        if size not in self._DEFAULT_STAY:
            raise ValueError("unknown vessel size: %r" % size)
        return size, float(arrival), float(duration)

    def _eligible(self, size):
        return [i for i, bay in enumerate(self._sizes) if bay == "large" or size == "small"]

    def _pick(self, size, clock):
        ready = [i for i in self._eligible(size) if self._free_at[i] <= clock]
        if not ready:
            return None
        return min(ready, key=lambda i: (self._free_at[i], i))

    def _next_release(self):
        return min(self._free_at[i] for item in self._queue for i in self._eligible(item[1]))

    def _clean_time(self, index):
        pause = _SMALL_CLEAN if self._sizes[index] == "small" else _LARGE_CLEAN
        if self._maintenance[index]:
            pause += _MAINT_EXTRA
            self._maintenance[index] = False
        return pause

    def _update_maintenance(self, index):
        recent = self._schedule[index][self._last_maint[index]:]
        if sum(end - begin for begin, end in recent) >= _MAINT_LOAD:
            self._maintenance[index] = True
            self._last_maint[index] = len(self._schedule[index])

    def _assign(self, bay, start, arrival, duration):
        self._schedule[bay].append((start, start + duration))
        self._update_maintenance(bay)
        self._free_at[bay] = start + duration + self._clean_time(bay)
        return bay + 1, round(start - arrival, 2)

    def _drain(self, clock):
        berthed = {}
        still_waiting = []
        for idx, size, arrival, duration in self._queue:
            bay = self._pick(size, clock)
            if bay is None:
                still_waiting.append((idx, size, arrival, duration))
            else:
                berthed[idx] = self._assign(bay, clock, arrival, duration)
        self._queue = still_waiting
        return berthed

    def _advance(self, limit, results):
        while self._queue:
            clock = self._next_release()
            if clock > limit:
                break
            results.update(self._drain(clock))

    def process(self, arrivals):
        parsed = [self._parse(entry) for entry in arrivals]
        results = {}
        for idx in sorted(range(len(parsed)), key=lambda k: parsed[k][1]):
            size, arrival, duration = parsed[idx]
            self._advance(arrival, results)
            self._queue.append((idx, size, arrival, duration))
            results.update(self._drain(arrival))
        while self._queue:
            results.update(self._drain(self._next_release()))
        return [results[i] for i in range(len(parsed))]


def dock(arrivals):
    return _Spaceport().process(arrivals)


