def _clamp(value, low, high):
    return max(low, min(high, value))


class RevenueManager:
    """Prices cabins dynamically from booking pace and occupancy versus target."""

    _WINDOW = 7
    _SOLD_OUT_PREMIUM = 3.0

    def __init__(self, capacity, base_price, horizon=120):
        self.capacity = capacity
        self.base_price = base_price
        self.horizon = horizon
        self.booked = 0
        self._history = []
        self._cache = {}

    def _validate(self, days):
        if isinstance(days, bool) or not isinstance(days, (int, float)):
            raise TypeError("days until departure must be numeric")
        if days < 0:
            raise ValueError("days until departure cannot be negative")
        return float(days)

    def _target_occupancy(self, days):
        if days not in self._cache:
            remaining = _clamp(days / self.horizon, 0.0, 1.0)
            self._cache[days] = (1.0 - remaining) ** 1.5
        return self._cache[days]

    def _target_bookings(self, days):
        return self._target_occupancy(days) * self.capacity

    def _expected_pace(self, days):
        earlier = self._target_bookings(min(float(self.horizon), days + self._WINDOW))
        return max(0.4, self._target_bookings(days) - earlier)

    def _observed_pace(self, days):
        return sum(1 for d in self._history if d <= days + self._WINDOW)

    def _pace_factor(self, days):
        ratio = self._observed_pace(days) / self._expected_pace(days)
        return _clamp(1.0 + 0.22 * (ratio - 1.0), 0.80, 2.60)

    def _occupancy_factor(self, days):
        gap = self.booked / self.capacity - self._target_occupancy(days)
        return _clamp(1.0 + 1.10 * gap, 0.75, 1.80)

    def _late_discount(self, days):
        if days > 21:
            return 1.0
        shortfall = max(0.0, self._target_occupancy(days) - self.booked / self.capacity)
        urgency = (21.0 - days) / 21.0
        return 1.0 - min(0.40, 1.5 * shortfall * urgency)

    def _register(self, days):
        self._history.append(days)
        self.booked += 1

    def quote(self, days):
        d = self._validate(days)
        if self.booked >= self.capacity:
            return round(self.base_price * self._SOLD_OUT_PREMIUM, 2)
        offer = self.base_price
        offer *= self._pace_factor(d)
        offer *= self._occupancy_factor(d)
        offer *= self._late_discount(d)
        self._register(d)
        return round(offer, 2)

    def quote_all(self, bookings):
        return [self.quote(days) for days in bookings]


def price(bookings):
    manager = RevenueManager(capacity=20, base_price=100.0)
    return manager.quote_all(bookings)


def main():
    requests = [110, 95, 80] + [60] * 8 + [30, 28, 25, 12, 9, 5, 3]
    for days, offer in zip(requests, price(requests)):
        print("{:>4} days out -> {:>8.2f}".format(days, offer))


if __name__ == "__main__":
    main()

