class FurnaceController:
    """Simulates a forge furnace with a heating element and safety cut-out."""

    _AMBIENT_FLOOR = 20.0
    _SAFETY_LIMIT = 1500.0
    _MAX_POWER = 100.0
    _SLEW = 8.0
    _MAX_STEPS = 600

    def __init__(self):
        self._ambient = self._AMBIENT_FLOOR
        self._power = 0.0
        self._cooling = False

    def _validate(self, raw):
        if isinstance(raw, bool) or not isinstance(raw, (int, float)):
            raise TypeError("temperature targets must be numbers, got %r" % (raw,))
        target = float(raw)
        if target < self._AMBIENT_FLOOR:
            raise ValueError("target %.2f is below the ambient floor" % target)
        return target

    def _heating_rate(self):
        loss = 0.02 * (self._ambient - self._AMBIENT_FLOOR)
        return 0.6 * self._power - loss

    def _adjust_power(self, target):
        gap = target - self._ambient
        hold = (self._ambient - self._AMBIENT_FLOOR) / 30.0
        desired = min(self._MAX_POWER, max(0.0, 0.4 * gap + hold))
        delta = desired - self._power
        if delta > self._SLEW:
            delta = self._SLEW
        elif delta < -self._SLEW:
            delta = -self._SLEW
        self._power += delta

    def _trigger_emergency_cooling(self):
        self._power = 0.0
        self._cooling = True

    def _cool_step(self):
        drop = max(5.0, 0.05 * (self._ambient - self._AMBIENT_FLOOR))
        self._ambient = max(self._AMBIENT_FLOOR, self._ambient - drop)
        if self._ambient <= 0.9 * self._SAFETY_LIMIT:
            self._cooling = False

    def _settled(self, target):
        return abs(target - self._ambient) < 0.5 and abs(self._heating_rate()) < 0.5

    def step(self, target):
        if self._cooling:
            self._cool_step()
        else:
            self._adjust_power(target)
            self._ambient += self._heating_rate()
            if self._ambient >= self._SAFETY_LIMIT:
                self._trigger_emergency_cooling()
        return round(self._ambient, 2)

    def run(self, targets):
        trace = []
        for raw in targets:
            target = self._validate(raw)
            for _ in range(self._MAX_STEPS):
                trace.append(self.step(target))
                if self._settled(target):
                    break
        return trace


def smelt(temperatures):
    """Return the ambient temperature recorded at every simulation step."""
    return FurnaceController().run(temperatures)


def format_profile(trace, width=8):
    head = ", ".join("%.2f" % value for value in trace[:width])
    tail = ", ".join("%.2f" % value for value in trace[-width:])
    return "%d steps | start: %s | end: %s" % (len(trace), head, tail)


if __name__ == "__main__":
    print(format_profile(smelt([1000])))
    print(format_profile(smelt([1000, 600, 1450])))
    print(format_profile(smelt([1600])))

