import math
import re
from collections import Counter


class SearchEngine:
    """Maps words to the passage indices that contain them."""

    _PUNCTUATION = re.compile(r"[^\w\s]+")

    def __init__(self, passages, top_k=5):
        self.passages = list(passages)
        self.top_k = top_k
        self._stopwords = {
            "a", "an", "and", "are", "as", "at", "be", "by", "for", "from",
            "in", "is", "it", "of", "on", "or", "that", "the", "to", "with",
        }
        self._postings = {}
        self._doc_count = len(self.passages)
        self._term_freq = []
        self._idf_cache = {}
        self._load()

    def _strip_punctuation(self, text):
        return self._PUNCTUATION.sub(" ", text)

    def _normalize(self, word):
        return word.lower()

    def _tokenize(self, text):
        cleaned = self._strip_punctuation(text)
        words = [self._normalize(w) for w in cleaned.split()]
        return [w for w in words if w and w not in self._stopwords]

    def _load(self):
        for position, passage in enumerate(self.passages):
            counts = Counter(self._tokenize(passage))
            self._term_freq.append(counts)
            for term in counts:
                self._postings.setdefault(term, set()).add(position)

    def _document_frequency(self, term):
        return len(self._postings.get(term, ()))

    def _inverse_document_frequency(self, term):
        if term not in self._idf_cache:
            df = self._document_frequency(term)
            self._idf_cache[term] = math.log((self._doc_count + 1) / (df + 1)) + 1.0
        return self._idf_cache[term]

    def _score(self, position, terms):
        counts = self._term_freq[position]
        total = 0.0
        for term in terms:
            tf = counts.get(term, 0)
            if tf:
                total += tf * self._inverse_document_frequency(term)
        return total

    def search(self, query):
        terms = self._tokenize(query)
        candidates = set()
        for term in terms:
            candidates |= self._postings.get(term, set())
        scored = [(self._score(p, terms), p) for p in candidates]
        scored.sort(key=lambda pair: (-pair[0], pair[1]))
        return [position for _, position in scored[: self.top_k]]


def index(documents):
    if not documents:
        return []
    *passages, query = documents
    engine = SearchEngine(passages)
    return engine.search(query)


def main():
    corpus = [
        "The quick brown fox jumps over the lazy dog.",
        "A slow, green turtle naps beneath the hedge.",
        "Foxes and dogs are common; xylophones are rare.",
        "xylophone",
    ]
    print(index(corpus))
    print(index(corpus[:-1] + ["fox dog"]))


if __name__ == "__main__":
    main()

