class World:
    """A tiny physics world with a spatial hash, drag and AABB collisions."""

    def __init__(self, frames, width=200.0, height=200.0):
        self.width = float(width)
        self.height = float(height)
        self._cell_size = 16.0
        self._friction = 0.92
        self._box = (8.0, 8.0)
        self._grid = {}
        self.objects = [self._make_object(i, f) for i, f in enumerate(frames)]

    def _make_object(self, index, frame):
        values = list(frame)
        if len(values) != 4:
            raise ValueError("frame %d must hold (x, y, vx, vy)" % index)
        x, y, vx, vy = (float(v) for v in values)
        return {"x": x, "y": y, "vx": vx, "vy": vy}

    def _cell_key(self, obj):
        return (int(obj["x"] // self._cell_size), int(obj["y"] // self._cell_size))

    def _rebuild_grid(self):
        self._grid = {}
        for index, obj in enumerate(self.objects):
            self._grid.setdefault(self._cell_key(obj), []).append(index)

    def _candidate_pairs(self):
        pairs = set()
        for (cx, cy), members in self._grid.items():
            neighbours = []
            for dx in (-1, 0, 1):
                for dy in (-1, 0, 1):
                    neighbours.extend(self._grid.get((cx + dx, cy + dy), ()))
            for i in members:
                for j in neighbours:
                    if i < j:
                        pairs.add((i, j))
        return sorted(pairs)

    def _overlap(self, a, b):
        half_w, half_h = self._box[0] / 2.0, self._box[1] / 2.0
        return (abs(a["x"] - b["x"]) < 2.0 * half_w
                and abs(a["y"] - b["y"]) < 2.0 * half_h)

    def _resolve(self, a, b):
        a["vx"], b["vx"] = b["vx"], a["vx"]
        a["vy"], b["vy"] = b["vy"], a["vy"]

    def _bounce_walls(self, obj):
        half_w, half_h = self._box[0] / 2.0, self._box[1] / 2.0
        if obj["x"] < half_w or obj["x"] > self.width - half_w:
            obj["x"] = min(max(obj["x"], half_w), self.width - half_w)
            obj["vx"] = -obj["vx"]
        if obj["y"] < half_h or obj["y"] > self.height - half_h:
            obj["y"] = min(max(obj["y"], half_h), self.height - half_h)
            obj["vy"] = -obj["vy"]

    def _apply_drag(self, obj):
        obj["vx"] *= self._friction
        obj["vy"] *= self._friction

    def step(self):
        for obj in self.objects:
            obj["x"] += obj["vx"]
            obj["y"] += obj["vy"]
            self._bounce_walls(obj)
        self._rebuild_grid()
        for i, j in self._candidate_pairs():
            a, b = self.objects[i], self.objects[j]
            if self._overlap(a, b):
                self._resolve(a, b)
        for obj in self.objects:
            self._apply_drag(obj)

    def coordinates(self):
        return [(round(o["x"], 3), round(o["y"], 3)) for o in self.objects]


def animate(frames):
    world = World(frames)
    for _step in range(10):
        world.step()
    return world.coordinates()


def main():
    frames = [(40.0, 100.0, 5.0, 0.0), (80.0, 100.0, -5.0, 0.0)]
    for index, (x, y) in enumerate(animate(frames)):
        print("object %d -> x=%.3f y=%.3f" % (index, x, y))


if __name__ == "__main__":
    main()

