class AquariumDoser:
    """Automatic doser that keeps pH and calcium at reef target values."""

    PH_TARGET = 8.1
    CALCIUM_TARGET = 400.0
    PH_PER_UNIT = 0.1
    CALCIUM_PER_UNIT = 10.0
    LOG_LIMIT = 10

    def __init__(self, initial_ph, initial_calcium):
        self.ph = self._validate(initial_ph, "ph", 6.0, 9.5)
        self.calcium = self._validate(initial_calcium, "calcium", 200.0, 600.0)
        self._log = []

    @staticmethod
    def _validate(value, name, low, high):
        try:
            number = float(value)
        except (TypeError, ValueError):
            raise ValueError("%s reading must be numeric, got %r" % (name, value))
        if not low <= number <= high:
            raise ValueError("%s reading %g outside plausible range %g..%g" % (name, number, low, high))
        return number

    def _buffer_volume(self):
        deficit = self.PH_TARGET - self.ph
        if deficit <= 0:
            return 0.0
        return round(deficit / self.PH_PER_UNIT, 2)

    def _calcium_volume(self):
        deficit = self.CALCIUM_TARGET - self.calcium
        if deficit <= 0:
            return 0.0
        return round(deficit / self.CALCIUM_PER_UNIT, 2)

    def _record(self, buffer_units, calcium_units):
        self._log.append((round(self.ph, 3), round(self.calcium, 2), buffer_units, calcium_units))
        if len(self._log) > self.LOG_LIMIT:
            del self._log[0]

    def dose(self, readings):
        doses = []
        for ph_reading, calcium_reading in readings:
            self.ph = self._validate(ph_reading, "ph", 6.0, 9.5)
            self.calcium = self._validate(calcium_reading, "calcium", 200.0, 600.0)
            buffer_units = self._buffer_volume()
            calcium_units = self._calcium_volume()
            self.ph += buffer_units * self.PH_PER_UNIT
            self.calcium += calcium_units * self.CALCIUM_PER_UNIT
            self._record(buffer_units, calcium_units)
            doses.append((buffer_units, calcium_units))
        return doses

    def recent_doses(self):
        return list(self._log)

    def report(self):
        lines = ["pH     Ca     buffer  calcium"]
        for ph, calcium, buffer_units, calcium_units in self._log:
            lines.append("%-6.2f %-6.1f %-7.2f %.2f" % (ph, calcium, buffer_units, calcium_units))
        lines.append("final pH %.2f / calcium %.1f" % (self.ph, self.calcium))
        return "\n".join(lines)


def main():
    doser = AquariumDoser(8.1, 420.0)
    readings = [(7.9, 380.0), (8.0, 400.0), (8.2, 430.0), (7.7, 355.0)]
    for (buffer_units, calcium_units), reading in zip(doser.dose(readings), readings):
        print("reading %s -> buffer %.2f u, calcium %.2f u" % (reading, buffer_units, calcium_units))
    print(doser.report())


if __name__ == "__main__":
    main()

