class EggIncubator:
    """A poultry egg incubator that tracks turning and the final hatch phase."""

    HATCH_DAY = 18
    NORMAL_HUMIDITY = 55
    HATCH_HUMIDITY = 70

    def __init__(self, turning_frequency=3):
        self.day = 0
        self.turning_frequency = turning_frequency
        self.hatch_mode = False
        self.humidity = self.NORMAL_HUMIDITY
        self._elapsed_hours = 0.0
        self._history = []

    @staticmethod
    def _validate(hours):
        if isinstance(hours, bool) or not isinstance(hours, (int, float)):
            raise TypeError("interval must be a number of hours")
        if hours < 0:
            raise ValueError("interval cannot be negative")
        return float(hours)

    def _advance(self, hours):
        self._elapsed_hours += self._validate(hours)
        self.day = int(self._elapsed_hours // 24)
        return self.day

    def _should_turn(self):
        if self.hatch_mode or self.turning_frequency <= 0:
            return False
        return 1 <= self.day < self.HATCH_DAY

    def _enter_hatch_mode(self):
        if self.day >= self.HATCH_DAY and not self.hatch_mode:
            self.hatch_mode = True
            self.turning_frequency = 0
            self.humidity = self.HATCH_HUMIDITY
        return self.hatch_mode

    def step(self, hours):
        self._advance(hours)
        self._enter_hatch_mode()
        if self.hatch_mode:
            status = "hatching"
        elif self._should_turn():
            status = "turning"
        else:
            status = "resting"
        self._history.append(status)
        return status

    def summary(self):
        counts = {}
        for status in self._history:
            counts[status] = counts.get(status, 0) + 1
        breakdown = ", ".join("%s=%d" % (k, counts[k]) for k in sorted(counts))
        return "day %d | humidity %d%% | turns/day %d | %s" % (
            self.day, self.humidity, self.turning_frequency, breakdown)


def incubate(days):
    incubator = EggIncubator()
    return [incubator.step(hours) for hours in days]


def main():
    schedule = [24.0] * 21
    for index, status in enumerate(incubate(schedule), start=1):
        print("interval %2d: %s" % (index, status))

    incubator = EggIncubator(turning_frequency=5)
    for hours in schedule:
        incubator.step(hours)
    print(incubator.summary())


if __name__ == "__main__":
    main()

