class SourdoughStarter:
    """Model of a sourdough starter fed on a 1:1:1 starter/flour/water ratio."""

    BASE_PEAK_HOURS = 6.0
    BASE_TEMPERATURE_C = 24.0

    def __init__(self, weight=100.0, hydration=100.0):
        if weight <= 0:
            raise ValueError("starter weight must be positive")
        if hydration <= 0:
            raise ValueError("hydration must be positive")
        self._flour_mass = weight / (1.0 + hydration / 100.0)
        self._water_mass = weight - self._flour_mass
        self._total_mass = weight
        self._last_peak = None
        self._log = []

    @property
    def weight(self):
        return round(self._total_mass, 1)

    @property
    def hydration(self):
        return round(self._water_mass / self._flour_mass * 100.0, 1)

    @property
    def peak_hours(self):
        return self._last_peak

    def _validate_temperature(self, reading):
        if not isinstance(reading, (int, float)):
            raise TypeError("temperature readings must be numeric")
        if reading < 0 or reading > 45:
            raise ValueError("temperature %r is outside the viable range" % (reading,))
        return float(reading)

    def _feeding_amounts(self):
        """A 1:1:1 feed adds flour and water equal to the current starter weight."""
        amount = round(self._total_mass, 1)
        return amount, amount

    def _estimate_peak_hours(self, temperature):
        """Fermentation roughly doubles in speed for every 10 C above the base."""
        factor = 2.0 ** ((self.BASE_TEMPERATURE_C - temperature) / 10.0)
        return round(self.BASE_PEAK_HOURS * factor, 1)

    def _apply_feeding(self, flour, water, hours):
        self._flour_mass += flour
        self._water_mass += water
        self._total_mass = self._flour_mass + self._water_mass
        self._last_peak = hours

    def _format_cycle(self, index, temperature, cycle):
        flour, water, hours = cycle
        return "Cycle %d @ %.1f C: %.1f g flour, %.1f g water, peak in %.1f h" % (
            index, temperature, flour, water, hours)

    def feed(self, temperatures):
        results = []
        for reading in temperatures:
            temperature = self._validate_temperature(reading)
            flour, water = self._feeding_amounts()
            hours = self._estimate_peak_hours(temperature)
            self._apply_feeding(flour, water, hours)
            cycle = (flour, water, hours)
            self._log.append((temperature, cycle))
            results.append(cycle)
        return results

    def report(self):
        lines = []
        for index, (temperature, cycle) in enumerate(self._log, start=1):
            lines.append(self._format_cycle(index, temperature, cycle))
        lines.append("Final: %.1f g at %.1f%% hydration" % (self.weight, self.hydration))
        return "\n".join(lines)


def main():
    starter = SourdoughStarter(weight=100.0, hydration=100.0)
    starter.feed([24, 20, 28.5, 18])
    print(starter.report())


if __name__ == "__main__":
    main()

