class PaintDryingBooth:
    """Controls the stages of an automotive paint drying booth."""

    _STAGE_ORDER = ("flash off", "bake", "cool down")
    _STAGE_DURATIONS = {"flash off": 10.0, "bake": 30.0, "cool down": 15.0}
    _SOLVENT_LOSS = {"flash off": 4.0, "bake": 1.5, "cool down": 0.2}

    def __init__(self, initial_solvent=100.0):
        if initial_solvent < 0:
            raise ValueError("initial solvent concentration cannot be negative")
        self.stage = self._STAGE_ORDER[0]
        self.elapsed = 0.0
        self.solvent = float(initial_solvent)
        self._total = 0.0
        self._history = []

