import math


class PenstockValveController:
    """Controls a hydroelectric penstock valve to track a target flow rate."""

    MAX_STEP = 5.0
    DISCHARGE_COEFFICIENT = 0.62

    def __init__(self, target_flow, opening=0.0, pressure=0.0, tolerance=0.5):
        if target_flow < 0:
            raise ValueError("target flow rate must be non-negative")
        self.target_flow = float(target_flow)
        self.opening = self._clamp(float(opening))
        self.pressure = float(pressure)
        self.tolerance = float(tolerance)
        self._history = []

    @staticmethod
    def _clamp(value):
        return max(0.0, min(100.0, value))

    def _flow_rate(self):
        """Torricelli-style discharge through a partially open gate."""
        if self.pressure <= 0.0 or self.opening <= 0.0:
            return 0.0
        area = self.opening / 100.0
        return self.DISCHARGE_COEFFICIENT * area * math.sqrt(2.0 * self.pressure)

    def _adjustment_step(self, current_flow):
        """Signed opening change, limited to a safe increment per cycle."""
        error = self.target_flow - current_flow
        if abs(error) <= self.tolerance:
            return 0.0
        gain = self._sensitivity()
        if gain <= 0.0:
            return self.MAX_STEP if error > 0 else -self.MAX_STEP
        raw = error / gain
        return max(-self.MAX_STEP, min(self.MAX_STEP, raw))

    def _sensitivity(self):
        """Flow produced per percent of opening at the current pressure."""
        if self.pressure <= 0.0:
            return 0.0
        return self.DISCHARGE_COEFFICIENT * math.sqrt(2.0 * self.pressure) / 100.0

    def adjust(self, pressures):
        flows = []
        for reading in pressures:
            self.pressure = max(0.0, float(reading))
            step = self._adjustment_step(self._flow_rate())
            self.opening = self._clamp(self.opening + step)
            achieved = self._flow_rate()
            self._history.append((self.pressure, self.opening, achieved))
            flows.append(achieved)
        return flows

    def report(self):
        lines = ["pressure   opening   flow"]
        for pressure, opening, flow in self._history:
            lines.append("{:8.1f}  {:7.2f}%  {:6.3f}".format(pressure, opening, flow))
        return "\n".join(lines)


def main():
    readings = [0.0, 120.0, 180.0, 180.0, 150.0, 150.0, 150.0, 90.0]
    controller = PenstockValveController(target_flow=6.0, opening=10.0)
    flows = controller.adjust(readings)
    print(controller.report())
    print("final opening: {:.2f}%".format(controller.opening))
    print("flows: " + ", ".join("{:.3f}".format(f) for f in flows))


if __name__ == "__main__":
    main()

