class CiderPress:
    """Automated hydraulic cider press with pressure-driven juice extraction."""

    MIN_RATE = 0.15          # L/min below which the press pushes harder
    RATE_COEFFICIENT = 0.08  # L/min of juice per bar on fresh pulp

    def __init__(self, pulp_mass, start_pressure=1.0, max_pressure=8.0):
        if pulp_mass <= 0:
            raise ValueError("pulp_mass must be positive")
        if not 0 < start_pressure <= max_pressure:
            raise ValueError("start_pressure must be in (0, max_pressure]")
        self.pulp_mass = pulp_mass
        self.pressure = float(start_pressure)
        self.max_pressure = float(max_pressure)
        self.juice_extracted = 0.0
        self._capacity = 0.68 * pulp_mass  # litres of juice the pulp can give up
        self._history = []

    def _extraction_rate(self):
        remaining = self._capacity - self.juice_extracted
        if remaining <= 0.0:
            return 0.0
        saturation = remaining / self._capacity
        return self.RATE_COEFFICIENT * self.pressure * saturation

    def _yield_for(self, duration):
        if duration < 0:
            raise ValueError("phase duration cannot be negative")
        produced = min(self._extraction_rate() * duration,
                       self._capacity - self.juice_extracted)
        return max(produced, 0.0)

    def _needs_more_pressure(self):
        if self.pressure >= self.max_pressure:
            return False
        return self._extraction_rate() < self.MIN_RATE

    def _step_pressure(self):
        self.pressure = min(self.pressure + 1.0, self.max_pressure)

    def press(self, durations):
        totals = []
        for duration in durations:
            self.juice_extracted += self._yield_for(duration)
            if self._needs_more_pressure():
                self._step_pressure()
            self._history.append((duration, self.pressure, self.juice_extracted))
            totals.append(round(self.juice_extracted, 3))
        return totals

    def report(self):
        lines = ["phase  minutes  bar   litres"]
        for index, (duration, pressure, total) in enumerate(self._history, start=1):
            lines.append("{:>5}  {:>7}  {:>3.1f}  {:>7.3f}".format(
                index, duration, pressure, total))
        lines.append("yield: {:.1f}% of {:.1f} L available".format(
            100.0 * self.juice_extracted / self._capacity, self._capacity))
        return "\n".join(lines)


def main():
    press_machine = CiderPress(pulp_mass=120.0, start_pressure=2.0, max_pressure=7.0)
    totals = press_machine.press([10, 15, 20, 20, 30, 30, 45])
    print("cumulative litres per phase:", totals)
    print(press_machine.report())


if __name__ == "__main__":
    main()

