class CompostBioreactor:
    """Simulates an aerobic compost drum over successive hours of ambient temperature."""

    OXYGEN_THRESHOLD = 10.0
    FRESH_AIR_OXYGEN = 21.0

    def __init__(self, start_core=20.0, start_oxygen=21.0):
        self._core_temperature = float(start_core)
        self._oxygen_level = float(start_oxygen)
        self._rotation_count = 0
        self._history = []

    def _metabolic_heat(self):
        """Heat (degrees per hour) released by microbes, limited by oxygen and temperature."""
        oxygen_factor = max(self._oxygen_level, 0.0) / self.FRESH_AIR_OXYGEN
        if self._core_temperature < 5.0 or self._core_temperature > 75.0:
            activity = 0.0
        else:
            activity = 1.0 - abs(self._core_temperature - 55.0) / 50.0
        return 6.0 * oxygen_factor * activity

    def _needs_aeration(self):
        return self._oxygen_level < self.OXYGEN_THRESHOLD

    def _rotate_drum(self):
        self._rotation_count += 1
        self._oxygen_level = self.FRESH_AIR_OXYGEN

    def _consume_oxygen(self, heat):
        self._oxygen_level = max(self._oxygen_level - 1.8 * heat, 0.0)

    def _exchange_with_ambient(self, ambient, heat):
        drift = 0.15 * (float(ambient) - self._core_temperature)
        self._core_temperature = round(self._core_temperature + heat + drift, 3)

    def process(self, temperatures):
        """Run one hour per ambient reading; return the core temperature after each hour."""
        readings = []
        for ambient in temperatures:
            if not isinstance(ambient, (int, float)):
                raise TypeError("ambient temperatures must be numeric, got %r" % (ambient,))
            heat = self._metabolic_heat()
            self._consume_oxygen(heat)
            self._exchange_with_ambient(ambient, heat)
            if self._needs_aeration():
                self._rotate_drum()
            readings.append(self._core_temperature)
        self._history.extend(readings)
        return readings

    def report(self):
        if not self._history:
            return "no hours logged"
        peak = max(self._history)
        return "hours=%d peak=%.2fC final=%.2fC rotations=%d oxygen=%.1f%%" % (
            len(self._history), peak, self._history[-1],
            self._rotation_count, self._oxygen_level)


def main():
    ambient_day = [18, 19, 21, 24, 26, 27, 25, 22, 20, 19, 17, 16]
    reactor = CompostBioreactor(start_core=22.0)
    cores = reactor.process(ambient_day)
    for hour, (ambient, core) in enumerate(zip(ambient_day, cores), start=1):
        print("hour %2d  ambient %5.1fC  core %6.2fC" % (hour, ambient, core))
    print(reactor.report())


if __name__ == "__main__":
    main()

