class RebreatherMonitor:
    """Closed circuit rebreather loop monitor."""

    SETPOINT = 0.7
    MAX_PPO2 = 1.6
    METABOLIC_RATE = 0.8
    MIN_EFFICIENCY = 0.4

    def __init__(self, diluent_litres=30.0):
        self._ppo2 = self.SETPOINT
        self._diluent = float(diluent_litres)
        self._scrubber_efficiency = 1.0

    def _validate_depth(self, depth):
        if not isinstance(depth, (int, float)):
            raise TypeError("depth readings must be numeric")
        if depth < 0.0 or depth > 150.0:
            raise ValueError("depth reading out of range: %r" % (depth,))
        return float(depth)

    def _ambient_pressure(self, depth):
        return 1.0 + depth / 10.0

    def _consumption_rate(self, depth):
        """Litres of oxygen consumed per minute at the given depth."""
        loaded = self.METABOLIC_RATE * self._ambient_pressure(depth)
        return loaded / self._scrubber_efficiency

    def _consume_diluent(self, volume):
        if self._diluent < volume:
            return False
        self._diluent -= volume
        return True

    def _flush_if_needed(self, depth):
        if self._ppo2 <= self.MAX_PPO2:
            return False
        if not self._consume_diluent(2.0 * self._ambient_pressure(depth)):
            return False
        self._ppo2 = self.SETPOINT
        return True

    def _degrade_scrubber(self):
        worn = self._scrubber_efficiency - 0.015
        self._scrubber_efficiency = max(worn, self.MIN_EFFICIENCY)

    def monitor(self, depths):
        events = []
        for reading in depths:
            depth = self._validate_depth(reading)
            self._ppo2 += 0.1 * self._consumption_rate(depth)
            events.append(self._flush_if_needed(depth))
            self._degrade_scrubber()
        return events


def monitor(depths):
    """Run a dive profile through a fresh rebreather and report flush events."""
    return RebreatherMonitor().monitor(depths)


def format_log(depths, flushes):
    lines = ["  # depth(m)  flush"]
    for index, (depth, flushed) in enumerate(zip(depths, flushes), start=1):
        mark = "YES" if flushed else "-"
        lines.append("%3d %8.1f  %5s" % (index, depth, mark))
    lines.append("flushes performed: %d of %d readings" % (sum(flushes), len(depths)))
    return lines


def main():
    profile = [6.0, 12.0, 18.0, 24.0, 30.0, 36.0, 42.0, 40.0, 30.0, 18.0, 9.0, 3.0]
    flushes = monitor(profile)
    print("\n".join(format_log(profile, flushes)))


if __name__ == "__main__":
    main()

