import sys


class RowExpander:
    """Parses a knitting pattern string and expands it into single stitches."""

    MAX_ROW = 100

    _STITCHES = {"k": "knit", "p": "purl"}

    def __init__(self, pattern):
        self.pattern = pattern
        self._pos = 0
        self._count = 0

    def run(self):
        self._pos = 0
        self._count = 0
        items = self._parse_sequence(closing=False)
        row = []
        self._flatten(items, row)
        return row

    def _parse_sequence(self, closing):
        items = []
        while self._pos < len(self.pattern):
            char = self.pattern[self._pos]
            if char in " ,\t":
                self._pos += 1
            elif char == "(":
                self._pos += 1
                inner = self._parse_sequence(closing=True)
                items.append(("group", inner, self._read_number(default=None)))
            elif char == ")":
                if not closing:
                    raise ValueError("unbalanced ')' at position %d" % self._pos)
                self._pos += 1
                return items
            elif char.lower() in self._STITCHES:
                self._pos += 1
                name = self._STITCHES[char.lower()]
                items.append(("stitch", name, self._read_number(default=1)))
            else:
                raise ValueError("unexpected character %r at position %d" % (char, self._pos))
        if closing:
            raise ValueError("missing ')' at end of pattern")
        return items

    def _read_number(self, default):
        start = self._pos
        while self._pos < len(self.pattern) and self.pattern[self._pos].isdigit():
            self._pos += 1
        if self._pos == start:
            if default is None:
                raise ValueError("expected a multiplier at position %d" % start)
            return default
        return int(self.pattern[start:self._pos])

    def _flatten(self, items, out):
        for kind, payload, repeats in items:
            if kind == "stitch":
                self._push(payload, repeats, out)
            else:
                for _ in range(repeats):
                    self._flatten(payload, out)

    def _push(self, name, repeats, out):
        if self._count + repeats > self.MAX_ROW:
            raise ValueError("row would exceed %d stitches" % self.MAX_ROW)
        out.extend([name] * repeats)
        self._count += repeats


def expand(pattern):
    return RowExpander(pattern).run()


def format_row(row):
    return " ".join("%s x%d" % (name, len(list(run))) for name, run in groupby(row))


if __name__ == "__main__":
    for text in sys.argv[1:]:
        try:
            stitches = expand(text)
        except ValueError as err:
            print("%r error: %s" % (text, err))
        else:
            print("%r %d sts -> %s" % (text, len(stitches), format_row(stitches)))

