class BoardingPassDecoder:
    """Decoder for 60-character alphanumeric boarding pass strips."""

    STRIP_LENGTH = 60
    _AIRLINE_DATA = """
    AA American Airlines
    BA British Airways
    LH Lufthansa
    KL KLM Royal Dutch Airlines
    QF Qantas
    """

    def __init__(self):
        self._cache = {}
        self._airlines = None

    def _load(self):
        table = {}
        for line in self._AIRLINE_DATA.strip().splitlines():
            code, name = line.strip().split(None, 1)
            table[code] = name
        return table

    def _airline_name(self, code):
        if self._airlines is None:
            self._airlines = self._load()
        return self._airlines.get(code, code)

    def _normalize(self, strip):
        if not isinstance(strip, str):
            raise TypeError("boarding pass strip must be a string")
        text = strip.rstrip("\r\n")
        if len(text) > self.STRIP_LENGTH:
            raise ValueError("strip exceeds %d characters" % self.STRIP_LENGTH)
        return text.ljust(self.STRIP_LENGTH)

    def _split_name(self, body):
        divider = body.find("/")
        if divider == -1:
            raise ValueError("no '/' divider found in passenger name field")
        last = body[:divider].strip()
        first = body[divider + 1:].strip()
        if not last or not first:
            raise ValueError("incomplete passenger name")
        return last, first

    def _format_name(self, last, first):
        return "%s %s" % (first.title(), last.title())

    def decode(self, strip):
        if strip in self._cache:
            return self._cache[strip]
        text = self._normalize(strip)
        code = text[:2]
        if not code.isalpha():
            raise ValueError("invalid airline code: %r" % code)
        digits = text[2:6]
        if not digits.isdigit():
            raise ValueError("invalid flight number: %r" % digits)
        last, first = self._split_name(text[6:])
        result = (self._airline_name(code), int(digits), self._format_name(last, first))
        self._cache[strip] = result
        return result


_DECODER = BoardingPassDecoder()


def decode(strip):
    """Return (airline, flight number, passenger name) read from a strip."""
    return _DECODER.decode(strip)


def main():
    scans = [
        "AA1234SMITH/JOHN",
        "LH0421MUELLER/ANNA",
        "AA1234SMITH/JOHN",
        "QF0011O'BRIEN/MARY JANE",
    ]
    for raw in scans:
        airline, flight, passenger = decode(raw)
        print("%-26s flight %04d  %s" % (airline, flight, passenger))


if __name__ == "__main__":
    main()

