TAPE_CAPACITY = 90
SEEK_STEP = 10


class TapeMachine:
    """A magnetic tape deck with a spool position and recorded content."""

    _VERBS = ("play", "record", "rewind", "forward", "stop")

    def __init__(self):
        self._tape = [None] * TAPE_CAPACITY
        self._position = 0
        self._output = []
        self._mode = "idle"

    def run(self, commands):
        for raw in commands:
            verb, words = self._parse(raw)
            if verb == "record":
                self._record(words)
            elif verb == "play":
                self._play()
            elif verb == "rewind":
                self._seek(-SEEK_STEP)
            elif verb == "forward":
                self._seek(SEEK_STEP)
            else:
                self._stop()
        return list(self._output)

    def _parse(self, raw):
        tokens = raw.split()
        if not tokens:
            raise ValueError("empty command")
        verb = tokens[0].lower()
        rest = tokens[1:]
        if verb == "fast" and rest and rest[0].lower() == "forward":
            return "forward", rest[1:]
        if verb in ("ff", "fastforward"):
            verb = "forward"
        if verb not in self._VERBS:
            raise ValueError("unknown command: %s" % tokens[0])
        if verb != "record" and rest:
            raise ValueError("%s takes no arguments" % verb)
        return verb, rest

    def _record(self, words):
        if not words:
            raise ValueError("record needs at least one word")
        index = self._position
        for word in words:
            if index >= TAPE_CAPACITY:
                break
            self._tape[index] = word
            index += 1
        self._position = index
        self._mode = "record"

    def _play(self):
        index = self._position
        while index < TAPE_CAPACITY:
            word = self._tape[index]
            if word is None:
                break
            self._output.append(word)
            index += 1
        self._position = index
        self._mode = "play"

    def _seek(self, delta):
        target = self._position + delta
        self._position = max(0, min(TAPE_CAPACITY, target))
        self._mode = "seek"

    def _stop(self):
        self._mode = "idle"

    def _used_units(self):
        return sum(1 for cell in self._tape if cell is not None)

    def format_report(self):
        used = self._used_units()
        lines = ["position: %d / %d" % (self._position, TAPE_CAPACITY)]
        lines.append("recorded units: %d" % used)
        lines.append("free units: %d" % (TAPE_CAPACITY - used))
        lines.append("mode: %s" % self._mode)
        lines.append("playback: %s" % " ".join(self._output))
        return "\n".join(lines)


def simulate(commands):
    return TapeMachine().run(commands)


def main():
    script = ["record alpha beta gamma", "rewind", "play", "stop",
              "fast forward", "record delta epsilon", "rewind", "rewind", "play"]
    machine = TapeMachine()
    print(machine.run(script))
    print(machine.format_report())
    print(simulate(["record one two three", "rewind", "play"]))


if __name__ == "__main__":
    main()

