_FISH_WASTE_PER_HOUR = 0.05


class AquariumFilter:
    """Hour-by-hour model of a sponge + biological filter in a fish tank."""

    def __init__(self, **overrides):
        self._initial = self._load(overrides)
        self._cache = {0: dict(self._initial)}

    def _load(self, overrides):
        state = dict(_DEFAULTS)
        for key, value in overrides.items():
            if key not in state:
                raise KeyError("unknown water parameter: %r" % (key,))
            if value < 0:
                raise ValueError("%s cannot start negative" % key)
            state[key] = float(value)
        return state

    def _sponge(self, state):
        state["particulates"] *= 0.90

    def _biomedia(self, state):
        converted = state["ammonia"] * 0.20
        oxidised = state["nitrite"] * 0.15
        state["ammonia"] -= converted
        state["nitrite"] += converted - oxidised
        state["nitrate"] += oxidised

    def _step(self, state):
        nxt = dict(state)
        self._sponge(nxt)
        self._biomedia(nxt)
        nxt["ammonia"] += _FISH_WASTE_PER_HOUR
        return nxt

    def _extend(self, hours):
        latest = max(self._cache)
        state = self._cache[latest]
        for hour in range(latest + 1, hours + 1):
            state = self._step(state)
            self._cache[hour] = state

    def state_at(self, hours):
        if hours not in self._cache:
            self._extend(hours)
        return dict(self._cache[hours])

    def concentrations(self, hours):
        state = self.state_at(hours)
        return [state["ammonia"], state["nitrite"], state["nitrate"]]

    def _format_row(self, hours):
        state = self.state_at(hours)
        return "%4d %10.3f %10.3f %10.3f %12.2f" % (
            hours,
            state["ammonia"],
            state["nitrite"],
            state["nitrate"],
            state["particulates"],
        )

    def report(self, hours):
        header = "%4s %10s %10s %10s %12s" % ("hour", "ammonia", "nitrite", "nitrate", "particulates")
        rows = [self._format_row(hour) for hour in range(hours + 1)]
        return "\n".join([header] + rows)


_SYSTEM = AquariumFilter()


def filter(hours):
    if not isinstance(hours, int) or isinstance(hours, bool):
        raise TypeError("hours must be an integer")
    if hours < 0:
        raise ValueError("hours must not be negative")
    return _SYSTEM.concentrations(hours)


def main():
    print(_SYSTEM.report(5))
    ammonia, nitrite, nitrate = filter(5)
    print("after 5 hours -> ammonia %.3f, nitrite %.3f, nitrate %.3f" % (ammonia, nitrite, nitrate))


