class ScanFiller:
    """Turns a closed outline into a zig-zag scan-line fill."""

    def __init__(self, outline):
        self._points = tuple(tuple(point) for point in outline)
        self._segments = None
        self._bbox = None
        self._cache = {}

    def _validate(self):
        if len(self._points) < 3:
            raise ValueError("an outline needs at least three points")
        for point in self._points:
            if len(point) != 2:
                raise ValueError("outline points must be (x, y) pairs")

    def _load(self):
        if self._segments is not None:
            return
        self._validate()
        count = len(self._points)
        self._segments = [(self._points[i], self._points[(i + 1) % count])
                          for i in range(count)]
        xs = [p[0] for p in self._points]
        ys = [p[1] for p in self._points]
        self._bbox = (min(xs), min(ys), max(xs), max(ys))

    def _intersections(self, y):
        if y in self._cache:
            return self._cache[y]
        crossings = []
        for (x1, y1), (x2, y2) in self._segments:
            if y1 == y2:
                continue
