STEP = 2


class ScanFiller:
    """Turns a closed outline into a zig-zag scan-line fill."""

    def __init__(self, outline):
        self.points = tuple(tuple(point) for point in outline)
        self.segments = None
        self.bbox = None
        self.cache = {}

    def validate(self):
        if len(self.points) < 3:
            raise ValueError("an outline needs at least three points")
        for point in self.points:
            if len(point) != 2:
                raise ValueError("outline points must be (x, y) pairs")

    def load(self):
        if self.segments is not None:
            return
        self.validate()
        count = len(self.points)
        self.segments = [(self.points[i], self.points[(i + 1) % count])
                          for i in range(count)]
        xs = [p[0] for p in self.points]
        ys = [p[1] for p in self.points]
        self.bbox = (min(xs), min(ys), max(xs), max(ys))

    def intersections(self, y):
        if y in self.cache:
            return self.cache[y]
        crossings = []
        for (x1, y1), (x2, y2) in self.segments:
            if y1 == y2:
                continue
            if min(y1, y2) <= y < max(y1, y2):
                x = x1 + (y - y1) * (x2 - x1) / float(y2 - y1)
                crossings.append(round(x, 3))
        crossings.sort()
        self.cache[y] = crossings
        return crossings

    def rows(self):
        self.load()
        y = self.bbox[1]
        top = self.bbox[3]
        while y <= top:
            yield y
            y += STEP

    def stitches(self):
        path = []
        flip = False
        for y in self.rows():
            spans = self.intersections(y)
            for i in range(0, len(spans) - 1, 2):
                left, right = spans[i], spans[i + 1]
                pair = ((right, y), (left, y)) if flip else ((left, y), (right, y))
                path.extend(pair)
                flip = not flip
        return path

    def row_summary(self):
