class PaperFolder:
    """Folds a square sheet by reflecting boundary vertices across fold lines."""

    _DIRECTIONS = {"left": (-1.0, 0.0), "right": (1.0, 0.0),
                   "up": (0.0, 1.0), "down": (0.0, -1.0)}
    _EPS = 1e-9

    def __init__(self, size=100.0):
        self._cache = {}
        self.vertices = [(0.0, 0.0), (size, 0.0), (size, size), (0.0, size)]

    def _load(self, instructions):
        loaded = []
        for item in instructions:
            if len(item) == 5:
                x1, y1, x2, y2, direction = item
            elif len(item) == 3:
                (x1, y1), (x2, y2), direction = item
            else:
                raise ValueError("fold instruction must have 3 or 5 fields: %r" % (item,))
            direction = str(direction).strip().lower()
            if direction not in self._DIRECTIONS:
                raise ValueError("unknown fold direction: %r" % (direction,))
            start = (float(x1), float(y1))
            end = (float(x2), float(y2))
            if abs(start[0] - end[0]) < self._EPS and abs(start[1] - end[1]) < self._EPS:
                raise ValueError("fold line endpoints must differ: %r" % (item,))
            loaded.append((start, end, direction))
        return loaded

    def _line(self, a, b):
        key = (a, b)
        if key not in self._cache:
            dx, dy = b[0] - a[0], b[1] - a[1]
            self._cache[key] = (dx, dy, dx * dx + dy * dy)
        return self._cache[key]

    def _mirror(self, point, a, b):
        dx, dy, norm = self._line(a, b)
        t = ((point[0] - a[0]) * dx + (point[1] - a[1]) * dy) / norm
        return (2.0 * (a[0] + t * dx) - point[0], 2.0 * (a[1] + t * dy) - point[1])

    def _side(self, point, a, normal):
        return (point[0] - a[0]) * normal[0] + (point[1] - a[1]) * normal[1]

    def _intersect(self, p, q, sp, sq):
        t = sp / (sp - sq)
        return (p[0] + t * (q[0] - p[0]), p[1] + t * (q[1] - p[1]))

    def _apply(self, a, b, direction):
        normal = self._DIRECTIONS[direction]
        count = len(self.vertices)
        folded = []
        for i in range(count):
            p = self.vertices[i]
            q = self.vertices[(i + 1) % count]
            sp = self._side(p, a, normal)
            sq = self._side(q, a, normal)
            folded.append(self._mirror(p, a, b) if sp < -self._EPS else p)
            if (sp < -self._EPS and sq > self._EPS) or (sp > self._EPS and sq < -self._EPS):
                folded.append(self._intersect(p, q, sp, sq))
        self.vertices = folded

    def _bounds(self):
        xs = [v[0] for v in self.vertices]
        ys = [v[1] for v in self.vertices]
        return min(xs), min(ys), max(xs), max(ys)

    def _tidy(self, value):
        nearest = round(value)
        return int(nearest) if abs(value - nearest) < 1e-9 else round(value, 6)

    def dimensions(self, instructions):
        for a, b, direction in self._load(instructions):
            self._apply(a, b, direction)
        min_x, min_y, max_x, max_y = self._bounds()
        return (self._tidy(max_x - min_x), self._tidy(max_y - min_y))


def fold(instructions):
    return PaperFolder().dimensions(instructions)

