import sys


class GearTrain:
    """Resolves a chain of meshed gears into a speed ratio and a direction."""

    def __init__(self):
        self._cache = {}

    def _normalize(self, gears):
        items = list(gears)
        if not items:
            raise ValueError("a gear train needs at least one gear")
        normalized = []
        for item in items:
            if isinstance(item, (tuple, list)):
                pair = tuple(int(t) for t in item)
                if len(pair) != 2:
                    raise ValueError("a compound gear must have exactly two teeth counts")
                if min(pair) < 1:
                    raise ValueError("teeth counts must be positive")
                normalized.append(pair)
            else:
                teeth = int(item)
                if teeth < 1:
                    raise ValueError("teeth counts must be positive")
                normalized.append(teeth)
        return tuple(normalized)

    def _teeth_pair(self, item):
        if isinstance(item, tuple):
            return item
        return (item, item)

    def _ratio(self, driver_teeth, driven_teeth):
        return driver_teeth / driven_teeth

    def _load(self, key):
        speed = 1.0
        direction = 1
        driving = self._teeth_pair(key[0])[1]
        for item in key[1:]:
            entry, exit_teeth = self._teeth_pair(item)
            speed *= self._ratio(driving, entry)
            direction = -direction
            driving = exit_teeth
        return (speed, direction)

    def solve(self, gears):
        key = self._normalize(gears)
        if key not in self._cache:
            self._cache[key] = self._load(key)
        return self._cache[key]

    def _parse_token(self, token):
        if ":" in token:
            first, second = token.split(":", 1)
            return (int(first), int(second))
        return int(token)

    def parse(self, tokens):
        return [self._parse_token(token) for token in tokens]

    def describe(self, gears):
        speed, direction = self.solve(gears)
        sense = "clockwise" if direction > 0 else "counter-clockwise"
        return "speed x{0:.4f}, {1} ({2:+d})".format(speed, sense, direction)


_TRAIN = GearTrain()


def calculate(gears):
    return _TRAIN.solve(gears)


def main(argv):
    if len(argv) < 2:
        print("usage: {0} TEETH [TEETH ...]   (compound gear: 'entry:exit')".format(argv[0]),
              file=sys.stderr)
        return 1
    gears = _TRAIN.parse(argv[1:])
    print(_TRAIN.describe(gears))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

