import math


class ShadowCaster:
    """Computes shadows thrown by a vertical ten unit stick."""

    STICK_LENGTH = 10.0
    _POINTS = ("N", "NNE", "NE", "ENE", "E", "ESE", "SE", "SSE",
               "S", "SSW", "SW", "WSW", "W", "WNW", "NW", "NNW")

    def __init__(self):
        self._cache = {}

    def _load(self, day):
        """Sun declination (radians) for a day of the year, memoised."""
        if day not in self._cache:
            orbit = math.radians(360.0 / 365.0 * (day + 10))
            self._cache[day] = -math.radians(23.44) * math.cos(orbit)
        return self._cache[day]

    def _validate(self, latitude, day, hours):
        if not -90.0 <= latitude <= 90.0:
            raise ValueError("latitude must lie between -90 and 90 degrees")
        if not 1 <= day <= 366:
            raise ValueError("day of the year must lie between 1 and 366")
        if not hours:
            raise ValueError("at least one hour is required")
        for hour in hours:
            if not 0.0 <= hour < 24.0:
                raise ValueError("hours must lie in the range [0, 24)")

    def parse(self, parameters):
        latitude, day, hours = parameters
        hours = [float(hour) for hour in hours]
        self._validate(float(latitude), int(day), hours)
        return float(latitude), int(day), hours

    def _position(self, lat_rad, day, hour):
        decl = self._load(day)
        hour_angle = math.radians(15.0 * (hour - 12.0))
        sin_alt = (math.sin(lat_rad) * math.sin(decl)
                   + math.cos(lat_rad) * math.cos(decl) * math.cos(hour_angle))
        altitude = math.asin(max(-1.0, min(1.0, sin_alt)))
        divisor = math.cos(altitude) * math.cos(lat_rad)
        if abs(divisor) < 1e-12:
            divisor = 1e-12
        cos_az = (math.sin(decl) - sin_alt * math.sin(lat_rad)) / divisor
        azimuth = math.degrees(math.acos(max(-1.0, min(1.0, cos_az))))
        if hour_angle > 0.0:
            azimuth = 360.0 - azimuth
        return altitude, azimuth

    def cast_at(self, latitude, day, hour):
        altitude, azimuth = self._position(math.radians(latitude), day, hour)
        bearing = (azimuth + 180.0) % 360.0
        if altitude <= 0.0:
            return (0.0, bearing)
        return (self.STICK_LENGTH / math.tan(altitude), bearing)

    def _compass(self, bearing):
        index = int((bearing + 11.25) % 360.0 / 22.5)
        return self._POINTS[index]

    def _format_row(self, hour, shadow):
        length, bearing = shadow
        return "%05.2f  %8.2f  %6.1f  %-3s" % (hour, length, bearing,
                                               self._compass(bearing))

    def report(self, parameters):
        latitude, day, hours = self.parse(parameters)
        lines = ["latitude %.1f, day %d" % (latitude, day)]
        for hour in hours:
            lines.append(self._format_row(hour, self.cast_at(latitude, day, hour)))
        return "\n".join(lines)


_CASTER = ShadowCaster()


def cast(parameters):
    latitude, day, hours = _CASTER.parse(parameters)
    return [_CASTER.cast_at(latitude, day, hour) for hour in hours]


if __name__ == "__main__":
    times = [6.0, 9.0, 12.0, 15.0, 18.0, 21.0]
    print(_CASTER.report((51.5, 172, times)))
    print(cast((51.5, 172, [12.0]))[0])
    print(_CASTER.report((-33.9, 355, times)))
    print(cast((-33.9, 355, [12.0]))[0])

