import sys

NOTE_NAMES = "CDEFGAB"
PEDAL_SYMBOLS = {"b": "b", "n": "", "#": "#"}
POSITION_LABELS = {"b": "flat", "": "natural", "#": "sharp"}


class Harp:
    """A concert harp: seven pedals, seven strings, one state machine."""

    def __init__(self):
        self._pedals = {name: "" for name in NOTE_NAMES}

    def _validate_note(self, name):
        if name not in NOTE_NAMES:
            raise ValueError("no such string or pedal: {0!r}".format(name))

    def _set_pedal(self, name, symbol):
        self._pedals[name] = PEDAL_SYMBOLS[symbol]

    def _pitch(self, name):
        return name + self._pedals[name]

    def _tokenize(self, sequence):
        if isinstance(sequence, str):
            raw = sequence.replace(",", " ").split()
        else:
            raw = [str(item) for item in sequence]
        return [token.strip() for token in raw if token.strip()]

    def _parse(self, token):
