from fractions import Fraction


class FilmProjector:
    """Drive pin + slotted (Maltese cross) wheel + synchronised rotary shutter."""

    def __init__(self, fps=24, engage_degrees=90, shutter_margin=20):
        if fps <= 0:
            raise ValueError("fps must be positive")
        if not 0 < engage_degrees < 360:
            raise ValueError("engagement arc must lie between 0 and 360 degrees")
        if not 0 <= shutter_margin < 360 - engage_degrees:
            raise ValueError("shutter margin does not fit around the engagement arc")
        margin = Fraction(shutter_margin).limit_denominator(1000)
        self._period = Fraction(1000) / Fraction(fps).limit_denominator(1000)
        self._cycle = self._period.numerator
        self._engage = Fraction(engage_degrees).limit_denominator(1000)
        self._blade = self._engage + margin
        self._offset = margin / 2
        self._cache = {}
        self._frames = 0
        self._open_ms = 0
        self._elapsed = 0
        self._last_moving = False

    def _pin_angle(self, ms):
        """Angular position of the continuously rotating drive pin, in degrees."""
        return (Fraction(ms) % self._period) * 360 / self._period

    def _load(self, tick):
        """Work out wheel motion and light state for one tick of the repeating cycle."""
        angle = self._pin_angle(tick)
        moving = angle < self._engage
        shutter_angle = (angle + self._offset) % 360
        return moving, shutter_angle >= self._blade

    def _state(self, ms):
        tick = ms % self._cycle
        if tick not in self._cache:
            self._cache[tick] = self._load(tick)
        return self._cache[tick]

    def run(self, milliseconds):
        """Trace the mechanism millisecond by millisecond, returning projected frames."""
        if not isinstance(milliseconds, int) or isinstance(milliseconds, bool):
            raise TypeError("duration must be an integer number of milliseconds")
        if milliseconds < 0:
            raise ValueError("duration must not be negative")
        self._frames = 0
        self._open_ms = 0
        self._elapsed = milliseconds
        self._last_moving = False
        for ms in range(milliseconds):
            moving, light_open = self._state(ms)
            if light_open:
                self._open_ms += 1
            if self._last_moving and not moving:
                self._frames += 1
            self._last_moving = moving
        return self._frames

    def report(self):
        """One-line human readable summary of the most recent run."""
        if self._elapsed == 0:
            return "0 frames in 0 ms, shutter never opened"
        duty = 100.0 * self._open_ms / self._elapsed
        return "{} frames in {} ms, light open {:.1f}% of the time".format(
            self._frames, self._elapsed, duty)


def crank(milliseconds):
    """Number of frames a standard 24 fps projector pulls down in the given time."""
    return FilmProjector().run(milliseconds)


if __name__ == "__main__":
    print("one second at standard speed:", crank(1000), "frames")
    projector = FilmProjector()
    for duration in (1000, 500, 2000, 125):
        projector.run(duration)
        print(projector.report())
    silent = FilmProjector(fps=16)
    silent.run(1000)
    print("silent speed:", silent.report())

