import math


class SonarArray:
    """Simulates a sonar pulse and the echoes returning from a set of targets."""

    SPEED_OF_SOUND = 1500.0
    ABSORPTION = 0.0005
    MIN_DETECTABLE = 1e-9

    def __init__(self, min_detectable=None):
        self._threshold = self.MIN_DETECTABLE if min_detectable is None else float(min_detectable)
        self._cache = {}

    def _load(self, obstacles):
        """Validate and normalize the raw target list into a hashable tuple."""
        normalized = []
        for entry in obstacles:
            distance, size = entry
            distance = float(distance)
            size = float(size)
            if distance <= 0.0:
                raise ValueError("target distance must be positive: %r" % (distance,))
            if size <= 0.0:
                raise ValueError("target size must be positive: %r" % (size,))
            normalized.append((distance, size))
        return tuple(normalized)

    def _travel_time(self, distance):
        """Time for the pulse to reach the target and come back."""
        return 2.0 * distance / self.SPEED_OF_SOUND

    def _echo_strength(self, distance, size):
        """Echo power: spherical spreading loss plus absorption, scaled by target size."""
        total_path = 2.0 * distance
        return size * math.exp(-self.ABSORPTION * total_path) / (total_path ** 2)

    def scan(self, obstacles):
        targets = self._load(obstacles)
        cached = self._cache.get(targets)
        if cached is not None:
            return list(cached)
        echoes = []
        for distance, size in targets:
            strength = self._echo_strength(distance, size)
            if strength < self._threshold:
                continue
            echoes.append((self._travel_time(distance), strength))
        echoes.sort(key=lambda echo: echo[0])
        self._cache[targets] = tuple(echoes)
        return echoes

    def report(self, obstacles):
        lines = []
        for arrival, strength in self.scan(obstacles):
            lines.append("  t=%8.4f s   strength=%.6e" % (arrival, strength))
        if not lines:
            lines.append("  no detectable echoes")
        return "\n".join(lines)


_ARRAY = SonarArray()


def sound(obstacles):
    """Return [(arrival_time, echo_strength), ...] sorted by arrival time."""
    return _ARRAY.scan(obstacles)


def main():
    near_field = [(30.0, 8.0), (120.0, 2.0), (75.0, 1.0)]
    deep_field = [(4000.0, 0.5), (900.0, 3.0), (12000.0, 0.01)]
    for index, obstacles in enumerate((near_field, deep_field, near_field), start=1):
        print("Scan %d: %d detectable echo(es)" % (index, len(sound(obstacles))))
        print(_ARRAY.report(obstacles))


if __name__ == "__main__":
    main()

