import math


class KiteStringModel:
    """Models the tension in a kite string for a sequence of wind gusts."""

    AIR_DENSITY = 1.225
    DRAG_COEFF = 0.9
    LIFT_COEFF = 1.4
    BREAKING_STRAIN = 900.0

    def __init__(self, area=0.75, length=60.0):
        self.area = area
        self.length = length
        self._altitude = 2.0
        self._angle = 12.0
        self._cache = {}
        self._tensions = []
        self._snapped = False

    def _validate(self, gusts):
        speeds = []
        for raw in gusts:
            if isinstance(raw, bool) or not isinstance(raw, (int, float)):
                raise TypeError("wind speeds must be numeric, got %r" % (raw,))
            if raw < 0:
                raise ValueError("wind speed cannot be negative: %r" % (raw,))
            speeds.append(float(raw))
        return speeds

    def _update_attitude(self, speed, previous):
        delta = speed - previous
        if delta > 0:
            self._altitude = min(self.length, self._altitude + delta * 1.6)
            self._angle = min(78.0, self._angle + delta * 0.9)
        else:
            self._altitude = max(0.5, self._altitude + delta * 1.1)
            self._angle = max(5.0, self._angle + delta * 0.6)

    def _forces(self, speed):
        key = (round(speed, 3), round(self._angle, 2))
        if key not in self._cache:
            theta = math.radians(self._angle)
            pressure = 0.5 * self.AIR_DENSITY * speed * speed * self.area
            drag = pressure * self.DRAG_COEFF * math.cos(theta)
            lift = pressure * self.LIFT_COEFF * math.sin(theta)
            self._cache[key] = (drag, lift)
        return self._cache[key]

    def _tension(self, speed):
        drag, lift = self._forces(speed)
        resultant = math.hypot(drag, lift)
        leverage = 1.0 + self._altitude / self.length
        return resultant * leverage

    def _step(self, speed, previous):
        self._update_attitude(speed, previous)
        load = self._tension(speed)
        if load >= self.BREAKING_STRAIN:
            self._tensions.append(self.BREAKING_STRAIN)
            self._snapped = True
        else:
            self._tensions.append(load)

    def run(self, gusts):
        previous = 0.0
        for speed in self._validate(gusts):
            self._step(speed, previous)
            if self._snapped:
                break
            previous = speed
        return max(self._tensions) if self._tensions else 0.0

    def report(self):
        state = "snapped" if self._snapped else "intact"
        return "%d steps, string %s, altitude %.1f m, angle %.1f deg" % (
            len(self._tensions), state, self._altitude, self._angle)


def test(gusts):
    return KiteStringModel().run(gusts)


def main():
    profiles = {
        "breezy": [3, 5, 8, 6, 4, 7, 9, 5],
        "gusty": [4, 9, 14, 11, 18, 12, 6],
        "hurricane": [5, 8, 120],
    }
    for name, gusts in profiles.items():
        model = KiteStringModel()
        peak = model.run(gusts)
        print("%-10s peak tension %8.2f N  (%s)" % (name, peak, model.report()))


if __name__ == "__main__":
    main()

