import math


class BoomerangFlight:
    """Discrete time simulation of a spinning boomerang's return flight."""

    GRAVITY = 9.81
    TURN_COEFF = 0.0015
    LIFT_COEFF = 0.04
    VELOCITY_DRAG = 0.03
    SPIN_DRAG = 0.03

    def __init__(self, parameters):
        self.params = self.validate(parameters)
        self.cache = None

    def validate(self, parameters):
        if not isinstance(parameters, dict):
            raise TypeError("parameters must be a dict")
        defaults = {"velocity": None, "spin": None, "wind": 0.0, "dt": 0.05, "height": 1.5}
        cleaned = {}
        for key, fallback in defaults.items():
            value = parameters.get(key, fallback)
            if value is None:
                raise ValueError("missing required parameter: %s" % key)
            cleaned[key] = float(value)
        if cleaned["velocity"] <= 0.0 or cleaned["spin"] <= 0.0:
            raise ValueError("velocity and spin must be positive")
        if cleaned["dt"] <= 0.0 or cleaned["height"] <= 0.0:
            raise ValueError("dt and height must be positive")
        return cleaned

    def turn_rate(self, velocity, spin):
        return self.TURN_COEFF * velocity * spin

    def vertical_accel(self, velocity, spin):
        return self.LIFT_COEFF * velocity * spin - self.GRAVITY

    def apply_drag(self, velocity, spin, dt):
        return velocity * max(0.0, 1.0 - self.VELOCITY_DRAG * dt), spin * max(0.0, 1.0 - self.SPIN_DRAG * dt)

    def step(self, state):
        x, y, altitude, heading, velocity, spin, climb = state
        dt = self.params["dt"]
        heading += self.turn_rate(velocity, spin) * dt
        x += (velocity * math.cos(heading) + self.params["wind"]) * dt
        y += velocity * math.sin(heading) * dt
        climb += self.vertical_accel(velocity, spin) * dt
        altitude += climb * dt
        velocity, spin = self.apply_drag(velocity, spin, dt)
        return (x, y, altitude, heading, velocity, spin, climb)

    def simulate(self):
        if self.cache is None:
            state = (0.0, 0.0, self.params["height"], 0.0,
                     self.params["velocity"], self.params["spin"], 0.0)
            points = [(0.0, 0.0)]
            while state[2] > 0.0:
                state = self.step(state)
                points.append((round(state[0], 3), round(state[1], 3)))
            self.cache = points
        return self.cache

    def path(self):
        return list(self.simulate())

    def summary(self):
        points = self.path()
        duration = (len(points) - 1) * self.params["dt"]
        farthest = max(math.hypot(px, py) for px, py in points)
        landing = math.hypot(*points[-1])
        return ("steps=%d  flight time=%.2fs  max range=%.2fm  distance from thrower=%.2fm"
                % (len(points), duration, farthest, landing))


def throw(parameters):
    return BoomerangFlight(parameters).path()


if __name__ == "__main__":
    calm = {"velocity": 25.0, "spin": 10.0, "wind": 0.0}
    flight = BoomerangFlight(calm)
    print(flight.summary())
    for x, y in flight.path()[::40]:
        print("  %8.2f %8.2f" % (x, y))
    breezy_landing = throw(dict(calm, wind=2.5))[-1]
    print("landing point with a 2.5 m/s wind: %.2f, %.2f" % breezy_landing)

