"""Track the physical state of a yo-yo through a string-trick routine."""


class YoYo:
    """A yo-yo whose spin, string wrap and mount layers evolve with each move."""

    _MAX_WRAP = 100
    _BIND_THRESHOLD = 30.0

    def __init__(self):
        self._spin = 0.0
        self._wrap = self._MAX_WRAP
        self._mounts = 0
        self._log = []

    @property
    def spin_speed(self):
        return round(self._spin, 1)

    @property
    def string_wrap(self):
        return self._wrap

    @property
    def mount_state(self):
        return self._mounts

    def perform(self, move):
        name = self._parse(move)
        self._validate(name)
        {"throw": self._throw, "bind": self._bind,
         "mount": self._mount, "dismount": self._dismount}[name]()
        self._apply_friction()
        self._log.append(name)

    def report(self):
        return "{0} after {1} move(s): spin {2:.0f}%, {3} cm wrapped, {4} mount layer(s)".format(
            self._spin_phrase(), len(self._log), self._spin, self._wrap, self._mounts)

    def _parse(self, move):
        if not isinstance(move, str):
            raise TypeError("a move must be given as a string, got %r" % (move,))
        name = move.strip().lower()
        if name not in ("throw", "bind", "mount", "dismount"):
            raise ValueError("unknown move: %r" % (move,))
        return name

    def _validate(self, name):
        if name == "throw" and self._spin > 0:
            raise ValueError("cannot throw a yo-yo that is already spinning")
        if name == "bind" and self._spin <= 0:
            raise ValueError("cannot bind a stationary yo-yo")
        if name == "bind" and self._spin < self._BIND_THRESHOLD:
            raise ValueError("spin too low to bind: %.0f%%" % self._spin)
        if name == "mount" and self._spin <= 0:
            raise ValueError("cannot mount a stationary yo-yo")
        if name == "dismount" and self._mounts == 0:
            raise ValueError("nothing is mounted")

    def _throw(self):
        self._wrap = 0
        self._spin = 100.0

    def _bind(self):
        self._wrap = self._MAX_WRAP
        self._mounts = 0
        self._spin = 0.0

    def _mount(self):
        self._mounts += 1

    def _dismount(self):
        self._mounts -= 1

    def _apply_friction(self):
        drag = 2.0 + 5.0 * self._mounts
        self._spin = max(0.0, self._spin - drag)

    def _spin_phrase(self):
        if self._spin > 0:
            return "spinning on string"
        if self._wrap == self._MAX_WRAP:
            return "returned to hand"
        return "dead on the string"


