import math


class PinballTable:
    """A simple pinball table simulated with fixed time steps."""

    WIDTH = 100.0
    HEIGHT = 200.0
    BALL_RADIUS = 2.0
    DT = 0.005
    GRAVITY = -120.0
    BUMPER_BOOST = 20.0
    FLIPPER_SPEED = 95.0
    FLIPPER_TOP = 25.0
    MAX_TIME = 60.0
    ZONES = {"left": (5.0, 45.0), "right": (55.0, 95.0)}

    def __init__(self, actions):
        self._bumpers = [(30.0, 140.0, 10.0), (70.0, 140.0, 10.0),
                         (50.0, 95.0, 12.0), (20.0, 60.0, 8.0), (80.0, 60.0, 8.0)]
        self._pos = [50.0, 190.0]
        self._vel = [40.0, 0.0]
        self._hits = 0
        self._schedule = self._parse(actions)
        self._pending = 0

    @staticmethod
    def _parse(actions):
        parsed = []
        for moment, side in actions:
            label = str(side).lower()
            if label not in PinballTable.ZONES:
                raise ValueError("unknown flipper: %r" % (side,))
            when = float(moment)
            if when < 0.0:
                raise ValueError("flipper time must not be negative")
            parsed.append((when, label))
        parsed.sort()
        return parsed

    def _fire_due(self, now):
        while self._pending < len(self._schedule) and self._schedule[self._pending][0] <= now:
            self._flip(self._schedule[self._pending][1])
            self._pending += 1

    def _flip(self, side):
        low, high = self.ZONES[side]
        if self._pos[1] <= self.FLIPPER_TOP and low <= self._pos[0] <= high:
            self._vel[1] = self.FLIPPER_SPEED
            self._vel[0] += 12.0 if side == "left" else -12.0

    def _integrate(self):
        self._vel[1] += self.GRAVITY * self.DT
        self._pos[0] += self._vel[0] * self.DT
        self._pos[1] += self._vel[1] * self.DT

    def _bounce_walls(self):
        if self._pos[0] < self.BALL_RADIUS:
            self._pos[0] = 2.0 * self.BALL_RADIUS - self._pos[0]
            self._vel[0] = -self._vel[0]
        elif self._pos[0] > self.WIDTH - self.BALL_RADIUS:
            self._pos[0] = 2.0 * (self.WIDTH - self.BALL_RADIUS) - self._pos[0]
            self._vel[0] = -self._vel[0]
        if self._pos[1] > self.HEIGHT - self.BALL_RADIUS:
            self._pos[1] = 2.0 * (self.HEIGHT - self.BALL_RADIUS) - self._pos[1]
            self._vel[1] = -self._vel[1]

    def _check_bumpers(self):
        for bx, by, radius in self._bumpers:
            dx = self._pos[0] - bx
            dy = self._pos[1] - by
            dist = math.hypot(dx, dy)
            reach = radius + self.BALL_RADIUS
            if 0.0 < dist < reach:
                nx, ny = dx / dist, dy / dist
                approach = self._vel[0] * nx + self._vel[1] * ny
                if approach < 0.0:
                    self._vel[0] += (-2.0 * approach + self.BUMPER_BOOST) * nx
                    self._vel[1] += (-2.0 * approach + self.BUMPER_BOOST) * ny
                    self._hits += 1
                self._pos[0] = bx + nx * reach
                self._pos[1] = by + ny * reach

    def play(self):
        clock = 0.0
        while clock < self.MAX_TIME and self._pos[1] > 0.0:
            self._fire_due(clock)
            self._integrate()
            self._bounce_walls()
            self._check_bumpers()
            clock += self.DT
        return self._hits


def launch(actions):
    return PinballTable(actions).play()

