import math


class FountainSpray:
    """Simulates droplets emitted by a programmable fountain nozzle."""

    _GRAVITY = 9.81
    _EMIT_INTERVAL = 0.1
    _STEP = 0.001

    def __init__(self, sequence):
        self._schedule = self._normalise(sequence)
        self._cache = {}

    @staticmethod
    def _normalise(sequence):
        events = []
        for time, angle, pressure in sequence:
            time, angle, pressure = float(time), float(angle), float(pressure)
            if time < 0.0:
                raise ValueError("event times must not be negative")
            if not -90.0 <= angle <= 90.0:
                raise ValueError("tilt angle must lie between -90 and 90 degrees")
            if pressure < 0.0:
                raise ValueError("pressure must not be negative")
            events.append((time, angle, pressure))
        if not events:
            raise ValueError("sequence must contain at least one event")
        events.sort(key=lambda event: event[0])
        return events

    def _settings_at(self, moment):
        key = round(moment, 3)
        if key not in self._cache:
            current = self._schedule[0][1:]
            for time, angle, pressure in self._schedule:
                if time > moment:
                    break
                current = (angle, pressure)
            self._cache[key] = current
        return self._cache[key]

    def _emission_times(self):
        start = self._schedule[0][0]
        end = self._schedule[-1][0]
        count = int(round((end - start) / self._EMIT_INTERVAL)) + 1
        return [start + index * self._EMIT_INTERVAL for index in range(count)]

    def _launch_velocity(self, angle, pressure):
        speed = math.sqrt(2.0 * pressure)
        radians = math.radians(angle)
        return speed * math.cos(radians), speed * math.sin(radians)

    def _fly(self, vx, vy):
        if vy <= 0.0:
            return 0.0, 0.0
        x, y, peak = 0.0, 0.0, 0.0
        while True:
            peak = max(peak, y)
            next_y = y + vy * self._STEP
            if next_y < 0.0:
                x += vx * self._STEP * (y / (y - next_y))
                return peak, x
            x += vx * self._STEP
            y = next_y
            vy -= self._GRAVITY * self._STEP

    def run(self):
        peak_height, furthest = 0.0, 0.0
        for moment in self._emission_times():
            angle, pressure = self._settings_at(moment)
            height, distance = self._fly(*self._launch_velocity(angle, pressure))
            peak_height = max(peak_height, height)
            furthest = max(furthest, distance)
        return round(peak_height, 3), round(furthest, 3)


def spray(sequence):
    return FountainSpray(sequence).run()


if __name__ == "__main__":
    print("vertical shot:", spray([(0.0, 90.0, 200.0), (1.0, 90.0, 200.0)]))
    print("mixed arcs:", spray([(0.0, 45.0, 50.0), (0.5, 60.0, 80.0), (1.5, 30.0, 120.0)]))

