import sys


class Cauldron:
    """A cauldron that tracks volume, temperature and toxicity."""

    _EFFECTS = {
        "fireweed": (1, 50, 0),
        "icecap": (1, -20, 0),
        "snake venom": (1, 0, 5),
    }

    def __init__(self):
        self._volume = 0
        self._temperature = 20
        self._toxicity = 0

    def _effect_of(self, ingredient):
        key = " ".join(str(ingredient).lower().split()).replace("_", " ")
        if key not in self._EFFECTS:
            raise ValueError("unknown ingredient: %r" % (ingredient,))
        return self._EFFECTS[key]

    def add(self, ingredient):
        delta_volume, delta_temperature, delta_toxicity = self._effect_of(ingredient)
        self._volume += delta_volume
        self._temperature += delta_temperature
        self._toxicity += delta_toxicity
        self._react()

    def _react(self):
        if self._temperature > 100:
            self._volume -= 1
            self._toxicity += 2
        elif self._temperature < 0:
            self._toxicity = 0

    def state(self):
        return [self._volume, self._temperature, self._toxicity]

    def _status(self):
        if self._temperature > 100:
            return "boiling"
        if self._temperature < 0:
            return "frozen"
        return "stable"

    def report(self):
        lines = ["volume: %d" % self._volume,
                 "temperature: %d" % self._temperature,
                 "toxicity: %d" % self._toxicity,
                 "status: %s" % self._status()]
        return "\n".join(lines)


def brew(ingredients):
    cauldron = Cauldron()
    for ingredient in ingredients:
        cauldron.add(ingredient)
    return cauldron.state()


