import sys


class Cauldron:
    """A cauldron that tracks volume, temperature and toxicity."""

    EFFECTS = {
        "fireweed": (1, 50, 0),
        "icecap": (1, -20, 0),
        "snake venom": (1, 0, 5),
    }

    def __init__(self):
        self.volume = 0
        self.temperature = 20
        self.toxicity = 0

    def effect_of(self, ingredient):
        key = " ".join(str(ingredient).lower().split()).replace("_", " ")
        if key not in self.EFFECTS:
            raise ValueError("unknown ingredient: %r" % (ingredient,))
        return self.EFFECTS[key]

    def add(self, ingredient):
        delta_volume, delta_temperature, delta_toxicity = self.effect_of(ingredient)
        self.volume += delta_volume
        self.temperature += delta_temperature
        self.toxicity += delta_toxicity
        self.react()

    def react(self):
        if self.temperature > 100:
            self.volume -= 1
            self.toxicity += 2
        elif self.temperature < 0:
            self.toxicity = 0

    def state(self):
        return [self.volume, self.temperature, self.toxicity]

    def status(self):
        if self.temperature > 100:
            return "boiling"
        if self.temperature < 0:
            return "frozen"
        return "stable"

    def report(self):
        lines = ["volume: %d" % self.volume,
                 "temperature: %d" % self.temperature,
                 "toxicity: %d" % self.toxicity,
                 "status: %s" % self.status()]
        return "\n".join(lines)


def brew(ingredients):
    cauldron = Cauldron()
    for ingredient in ingredients:
        cauldron.add(ingredient)
    return cauldron.state()


def brew_with_report(ingredients):
    cauldron = Cauldron()
    for ingredient in ingredients:
        cauldron.add(ingredient)
    return cauldron.state(), cauldron.report()


def main(argv):
    recipe = argv[1:] or ["fireweed", "fireweed", "icecap"]
    try:
        result, report = brew_with_report(recipe)
    except ValueError as error:
        print("error: %s" % error)
        return 1
    print("recipe: %s" % ", ".join(recipe))
    print("result: %s" % result)
    print(report)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

