class HotTub:
    """A very small hot tub controller: users, pump and water temperature."""

    START_TEMPERATURE = 30
    UNPUMPED_CEILING = 35

    def __init__(self):
        self._users = 0
        self._pump = False
        self._temperature = self.START_TEMPERATURE
        self._handlers = {
            "enter": self._enter,
            "leave": self._leave,
            "heat": self._heat,
            "cool": self._cool,
        }

    def _enter(self):
        # Fresh water only chills the tub when it is already circulating.
        if self._pump:
            self._temperature -= 1
        self._users += 1
        self._pump = True

    def _leave(self):
        if self._users == 0:
            raise ValueError("nobody is in the tub")
        self._users -= 1
        if self._users == 0:
            self._pump = False

    def _heat(self):
        if self._pump:
            self._temperature += 5
        elif self._temperature < self.UNPUMPED_CEILING:
            self._temperature = min(self.UNPUMPED_CEILING, self._temperature + 5)

    def _cool(self):
        self._temperature -= 2

    def apply(self, event):
        handler = self._handlers.get(event)
        if handler is None:
            raise ValueError("unknown event: %r" % (event,))
        handler()

    def state(self):
        return (self._temperature, self._pump)

    def report(self):
        status = "running" if self._pump else "off"
        return "%d degrees, pump %s, %d user(s)" % (
