class Drum:
    """A churn drum tracking viscosity, temperature and motor speed."""

    def __init__(self):
        self.viscosity = 0
        self.temperature = 0
        self.speed = 10
        self._handlers = self._load()

    def _load(self):
        return {
            "freeze": self._freeze,
            "spin": self._spin,
            "thicken": self._thicken,
        }

    def _freeze(self):
        self.temperature -= 5

    def _spin(self):
        if self.temperature < -10:
            self.viscosity += 2
        else:
            self.viscosity -= 1

    def _thicken(self):
        self.speed += 5
        self.temperature += 2

    def _overheated(self):
        return self.speed > 20 and self.viscosity > 10

    def apply(self, action):
        handler = self._handlers.get(action)
        if handler is None:
            raise ValueError("unknown action: {!r}".format(action))
        handler()
        if self._overheated():
            self.speed = 0


class ChurnEngine:
    """Runs action sequences, remembering results of sequences seen before."""

    def __init__(self):
        self._cache = {}

    def run(self, actions):
        key = tuple(actions)
        if key not in self._cache:
            self._cache[key] = self._simulate(key)
        return self._cache[key]

    def _simulate(self, key):
        drum = Drum()
        for action in key:
            drum.apply(action)
        return (drum.viscosity, drum.speed)


_ENGINE = ChurnEngine()


def churn(actions):
    return _ENGINE.run(actions)


def summarize(sequences):
    lines = []
    for actions in sequences:
        viscosity, speed = churn(actions)
        lines.append("{:<40} -> viscosity={:>3} speed={:>3}".format(
            ",".join(actions), viscosity, speed))
    return lines


def main():
    sequences = [
        ["freeze", "freeze", "freeze", "spin", "spin", "thicken"],
        ["spin", "spin", "thicken", "thicken"],
        ["freeze"] * 4 + ["spin"] * 6 + ["thicken", "thicken", "thicken"],
    ]
    for line in summarize(sequences):
        print(line)
    thickest = max(sequences, key=lambda actions: churn(actions)[0])
    print("thickest batch: {} from {} actions".format(
        churn(thickest), len(thickest)))


if __name__ == "__main__":
    main()

