class TurretController:
    """Simulates the elevation/rotation motor of a hydraulic turret."""

    _ACTIONS = ("elevate", "depress", "rotate", "lock")
    _MAX_ELEVATION = 50
    _MIN_ELEVATION = 0
    _ROTATION_MIN_ELEVATION = 20
    _LOW_POWER_THRESHOLD = 10

    def __init__(self):
        self._elevation = 0
        self._angle = 0
        self._locked = 0
        self._pressure = 50
        self._handlers = {
            "elevate": self._elevate,
            "depress": self._depress,
            "rotate": self._rotate,
            "lock": self._lock,
        }

    def _validate(self, commands):
        if not isinstance(commands, (list, tuple)):
            raise TypeError("commands must be a list or tuple of strings")
        cleaned = []
        for raw in commands:
            if not isinstance(raw, str):
                raise TypeError("each command must be a string, got %r" % (raw,))
            name = raw.strip().lower()
            if name not in self._ACTIONS:
                raise ValueError("unknown command: %r" % (raw,))
            cleaned.append(name)
        return cleaned

    def _step(self):
        if self._pressure < self._LOW_POWER_THRESHOLD:
            return 5
        return 10

    def _elevate(self):
        self._elevation = min(self._MAX_ELEVATION, self._elevation + self._step())

    def _depress(self):
        self._elevation = max(self._MIN_ELEVATION, self._elevation - self._step())

    def _rotate(self):
        if self._elevation >= self._ROTATION_MIN_ELEVATION and self._locked == 0:
            self._angle = (self._angle + 90) % 360

    def _lock(self):
        self._locked = 1

    def run(self, commands):
        for name in self._validate(commands):
            self._handlers[name]()
            self._pressure -= 1
        return (self._elevation, self._angle, self._pressure)

    def summary(self):
        mode = "low power" if self._pressure < self._LOW_POWER_THRESHOLD else "nominal"
        return "elevation=%d angle=%d pressure=%d locked=%d mode=%s" % (
            self._elevation, self._angle, self._pressure, self._locked, mode)


def traverse(commands):
    """Run the command list on a fresh turret and return (elevation, angle, pressure)."""
    return TurretController().run(commands)


def report(commands):
    """Run the command list and return a human readable state description."""
    turret = TurretController()
    turret.run(commands)
    return turret.summary()


def main():
    runs = [
        ["elevate", "elevate", "rotate", "lock"],
        ["elevate"] * 8 + ["rotate", "depress"],
        ["elevate", "elevate", "lock", "rotate"],
        ["elevate", "depress", "depress"] * 15,
    ]
    for commands in runs:
        print(traverse(commands), "|", report(commands))


if __name__ == "__main__":
    main()

