class RockTumbler:
    """Simulates a rock tumbler that polishes rocks through successive grit stages."""

    SMOOTHNESS_TARGET = 50
    FINAL_STAGE = 4
    DAILY_HOUR_LIMIT = 10
    WEAR_PENALTY = 2

    def __init__(self):
        self._stage = 1
        self._speed = 30
        self._smoothness = 0
        self._log = []

    def _is_done(self):
        return self._stage >= self.FINAL_STAGE

    def _run_hour(self):
        self._smoothness += 1
        if self._smoothness >= self.SMOOTHNESS_TARGET:
            self._stage += 1
            self._smoothness = 0

    def _apply_belt_wear(self, hours):
        if hours > self.DAILY_HOUR_LIMIT:
            self._speed -= self.WEAR_PENALTY

    def run_day(self, hours):
        if hours < 0:
            raise ValueError("daily hours cannot be negative: %r" % (hours,))
        whole_hours = int(hours)
        if not self._is_done():
            for _ in range(whole_hours):
                self._run_hour()
                if self._is_done():
                    break
            self._apply_belt_wear(whole_hours)
        self._log.append((whole_hours, self._stage, self._speed, self._smoothness))

    def state(self):
        return (self._stage, self._speed)

    def report(self):
        lines = ["day  hours  grit  speed  smoothness"]
        for day, entry in enumerate(self._log, start=1):
            lines.append("%3d  %5d  %4d  %5d  %10d" % ((day,) + entry))
        status = "done" if self._is_done() else "still tumbling"
        lines.append("final: grit %d, speed %d (%s)" % (self._stage, self._speed, status))
        return "\n".join(lines)


def run_schedule(days):
    tumbler = RockTumbler()
    for hours in days:
        tumbler.run_day(hours)
    return tumbler


def tumble(days):
    return run_schedule(days).state()


def main():
    for schedule in ([12, 12, 12, 12, 12], [8] * 7, [20] * 12):
        tumbler = run_schedule(schedule)
        print("schedule:", schedule)
        print(tumbler.report())
        print("result:", tumbler.state())
        print()


if __name__ == "__main__":
    main()

