from numbers import Real


class SurgeEngine:
    """Simulates a pump surge sequence, tracking flow rate and motor wear."""

    PERFECT_RHYTHM = 5
    WEAR_LIMIT = 10
    SHUTDOWN_WEAR = 3

    def __init__(self, pulses):
        self.pulses = self._validate(pulses)
        self._flow = 0
        self._wear = 0
        self._synchronized = False
        self._events = []

    @staticmethod
    def _validate(pulses):
        checked = []
        for pulse in pulses:
            if isinstance(pulse, bool) or not isinstance(pulse, Real):
                raise TypeError("pulse durations must be numbers, got %r" % (pulse,))
            if pulse < 0:
                raise ValueError("pulse durations must not be negative: %r" % (pulse,))
            checked.append(pulse)
        return checked

    def _gain(self, pulse):
        return pulse * 2 if self._synchronized else pulse

    def _shutdown(self):
        self._flow = 0
        self._synchronized = False
        self._events.append("forced shutdown: wear reached %d" % self._wear)

    def run(self):
        for index, pulse in enumerate(self.pulses):
            self._flow += self._gain(pulse)
            self._events.append("pulse %d (%s) -> flow %s" % (index, pulse, self._flow))
            if pulse == self.PERFECT_RHYTHM:
                self._synchronized = True
                self._events.append("perfect rhythm: synchronized mode on")
            if pulse > self.WEAR_LIMIT:
                self._wear += 1
                self._events.append("overlong pulse: wear now %d" % self._wear)
            if self._wear >= self.SHUTDOWN_WEAR:
                self._shutdown()
        return self._flow, self._wear

    def _mode_label(self):
        return "synchronized" if self._synchronized else "free-running"

    def report(self):
        lines = ["log:"]
        lines.extend("  " + event for event in self._events)
        lines.append("final flow %s, wear %d, mode %s"
                     % (self._flow, self._wear, self._mode_label()))
        return "\n".join(lines)


def surge(pulses):
    engine = SurgeEngine(pulses)
    return engine.run()


def main():
    samples = [[5, 6, 11], [], [11, 12, 13, 4], [5, 11, 11, 2, 11, 5, 3]]
    for sample in samples:
        print("%-26s -> %s" % (sample, surge(sample)))
    detailed = SurgeEngine(samples[-1])
    detailed.run()
    print()
    print(detailed.report())


if __name__ == "__main__":
    main()

