            self.events.append("pulse %d (%s) -> flow %s" % (index, pulse, self.flow))
            if pulse == self.PERFECT_RHYTHM:
                self.synchronized = True
                self.events.append("perfect rhythm: synchronized mode on")
            if pulse > self.WEAR_LIMIT:
                self.wear += 1
                self.events.append("overlong pulse: wear now %d" % self.wear)
            if self.wear >= self.SHUTDOWN_WEAR:
                self.shutdown()
        return self.flow, self.wear

    def mode_label(self):
        return "synchronized" if self.synchronized else "free-running"

    def report(self):
        lines = ["log:"]
        lines.extend("  " + event for event in self.events)
        lines.append("final flow %s, wear %d, mode %s"
                     % (self.flow, self.wear, self.mode_label()))
        return "\n".join(lines)


def surge(pulses):
    engine = SurgeEngine(pulses)
    return engine.run()


def main():
    samples = [[5, 6, 11], [], [11, 12, 13, 4], [5, 11, 11, 2, 11, 5, 3]]
    for sample in samples:
        print("%-26s -> %s" % (sample, surge(sample)))
    detailed = SurgeEngine(samples[-1])
    detailed.run()
    print()
    print(detailed.report())


if __name__ == "__main__":
    main()

