RECIPES = {
    "gin and tonic": {"spirit": 50, "mixer": 150, "syrup": 0},
    "rum punch": {"spirit": 40, "mixer": 100, "syrup": 20},
    "mojito": {"spirit": 45, "mixer": 120, "syrup": 15},
    "sweet soda": {"spirit": 0, "mixer": 180, "syrup": 25},
}


class DrinkDispenser:
    """A three-tank dispenser that mixes drinks into a single cup."""

    CAPACITY = {"spirit": 700, "mixer": 2000, "syrup": 400}

    def __init__(self, spirit=700, mixer=2000, syrup=400):
        self._levels = {"spirit": spirit, "mixer": mixer, "syrup": syrup}
        self._cup_present = False
        self._log = []

    def place_cup(self):
        self._cup_present = True

    def take_cup(self):
        self._cup_present = False

    def _has_ingredients(self, recipe):
        return all(self._levels[tank] >= amount for tank, amount in recipe.items())

    def _open_valves(self, recipe):
        poured = 0
        for tank, amount in recipe.items():
            self._levels[tank] -= amount
            poured += amount
        return poured

    def _stir(self, volume):
        self._log.append("stirred %d ml" % volume)

    def serve(self, name):
        recipe = RECIPES.get(str(name).strip().lower())
        if recipe is None or not self._cup_present:
            return False
        if not self._has_ingredients(recipe):
            return False
        volume = self._open_valves(recipe)
        self._stir(volume)
        return True

    def report(self):
        tanks = ", ".join(
            "%s %d/%d ml" % (tank, self._levels[tank], self.CAPACITY[tank])
            for tank in ("spirit", "mixer", "syrup")
        )
        return "%s | %d drink(s) mixed" % (tanks, len(self._log))


def mix(requests):
    dispenser = DrinkDispenser()
    results = []
    for request in requests:
        dispenser.place_cup()
        served = dispenser.serve(request)
        results.append(served)
        dispenser.take_cup()
    print(dispenser.report())
    return results


def main():
    orders = [
        "gin and tonic",
        "Mojito",
        "espresso martini",
        "sweet soda",
        "rum punch",
    ]
    outcomes = mix(orders)
    for order, ok in zip(orders, outcomes):
        print("%-18s %s" % (order, "served" if ok else "refused"))


if __name__ == "__main__":
    main()

