class MailSortingBelt:
    """Models a belt that weighs parcels, bins them and throttles its motor."""

    WEIGHT_LIMIT = 50.0
    HEAVY_THRESHOLD = 30.0
    BASE_SPEED = 100
    MIN_SPEED = 40

    def __init__(self):
        self.accepted = 0
        self.rejected = 0
        self.speed = self.BASE_SPEED
        self._heavy_streak = 0
        self._bins = {"small": [], "medium": [], "large": []}

    def _validate(self, weight):
        try:
            value = float(weight)
        except (TypeError, ValueError):
            raise ValueError("parcel weight must be numeric: %r" % (weight,))
        if value < 0:
            raise ValueError("parcel weight must not be negative: %r" % (weight,))
        return value

    def _exceeds_limit(self, weight):
        return weight > self.WEIGHT_LIMIT

    def _is_heavy(self, weight):
        return weight >= self.HEAVY_THRESHOLD

    def _bin_for(self, weight):
        if weight < 5.0:
            return "small"
        if weight < self.HEAVY_THRESHOLD:
            return "medium"
        return "large"

    def _adjust_speed(self, heavy):
        if heavy:
            self._heavy_streak += 1
            if self._heavy_streak >= 2:
                self.speed = max(self.MIN_SPEED, self.speed - 10)
        else:
            self._heavy_streak = 0
            self.speed = min(self.BASE_SPEED, self.speed + 5)

    def run(self, weights):
        for raw in weights:
            weight = self._validate(raw)
            if self._exceeds_limit(weight):
                self.rejected += 1
            else:
                self._bins[self._bin_for(weight)].append(weight)
                self.accepted += 1
            self._adjust_speed(self._is_heavy(weight))
        return self.accepted, self.rejected

    def report(self):
        lines = ["accepted=%d rejected=%d speed=%d" % (self.accepted, self.rejected, self.speed)]
        for name in ("small", "medium", "large"):
            parcels = self._bins[name]
            total = sum(parcels)
            lines.append("  %-6s count=%d total=%.1f" % (name, len(parcels), total))
        return "\n".join(lines)


def sort(weights):
    belt = MailSortingBelt()
    return belt.run(weights)


def main():
    batches = [
        [1.2, 4.9, 12.0, 55.0, 31.5, 40.0, 60.1, 2.0],
        [70.0, 80.0, 90.0],
        [],
    ]
    for batch in batches:
        print(batch, "->", sort(batch))
    detailed = MailSortingBelt()
    detailed.run(batches[0])
    print(detailed.report())


if __name__ == "__main__":
    main()

