import sys

MAX_BLADE_HEIGHT = 25.0
MIN_BLADE_HEIGHT = 1.0
START_FIBER_LENGTH = 2.60
START_WATER_PCT = 95.0
MIN_WATER_PCT = 90.0
EVAPORATION_PER_MINUTE = 1.8
MAX_CHOP_RATIO = 0.06


class PulpBeater:
    """A Hollander-style beater that shortens paper fibres minute by minute."""

    def __init__(self):
        self._water_pct = START_WATER_PCT
        self._fiber_length = START_FIBER_LENGTH
        self._blade_height = MAX_BLADE_HEIGHT

    @staticmethod
    def _validated(minutes):
        if isinstance(minutes, bool) or not isinstance(minutes, int):
            raise TypeError("minutes must be an integer")
        if minutes < 0:
            raise ValueError("minutes must not be negative")
        return minutes

    def _lower_blades(self):
        """Bring the roll one unit closer to the bed plate."""
        self._blade_height = max(MIN_BLADE_HEIGHT, self._blade_height - 1.0)

    def _evaporate(self):
        self._water_pct -= EVAPORATION_PER_MINUTE

    def _inject_water(self):
        """Top the vat up so the stock never dries below ninety percent."""
        if self._water_pct < MIN_WATER_PCT:
            self._water_pct = MIN_WATER_PCT

    def _severity(self):
        span = MAX_BLADE_HEIGHT - MIN_BLADE_HEIGHT
        return (MAX_BLADE_HEIGHT - self._blade_height) / span

    def _chop(self):
        """Cut the fibres; the lower the blades sit, the finer the cut."""
        ratio = MAX_CHOP_RATIO * (0.2 + 0.8 * self._severity())
        self._fiber_length -= self._fiber_length * ratio

    def run(self, minutes):
        for _ in range(self._validated(minutes)):
            self._lower_blades()
            self._evaporate()
            self._inject_water()
            self._chop()
        return self._fiber_length


def beat(minutes):
    """Run a beater for `minutes` minutes and return the final fibre length."""
    beater = PulpBeater()
    return beater.run(minutes)


def format_length(length):
    return "{0:.4f} mm".format(length)


def main(argv):
    minutes = int(argv[1]) if len(argv) > 1 else 60
    print("after {0} minutes: {1}".format(minutes, format_length(beat(minutes))))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

