def _validate_duration(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError("cooking time must be a number, got %r" % (value,))
    if value <= 0:
        raise ValueError("cooking time must be positive, got %r" % (value,))
    return float(value)


class DeepFryer:
    TARGET_TEMP = 350
    AMBIENT_TEMP = 70
    HEAT_RATE = 25
    IDLE_LOSS = 30
    MAINTENANCE_LIMIT = 100
    MAINTENANCE_TIME = 15

    def __init__(self):
        self._oil_temp = self.AMBIENT_TEMP
        self._heater_on = False
        self._usage_minutes = 0.0
        self._basket_lowered = False
        self._log = []

    def _preheat(self):
        self._heater_on = True
        minutes = 0
        while self._oil_temp < self.TARGET_TEMP:
            self._oil_temp = min(self.TARGET_TEMP, self._oil_temp + self.HEAT_RATE)
            minutes += 1
        return float(minutes)

    def _lower_basket(self):
        self._basket_lowered = True

    def _raise_basket(self):
        self._basket_lowered = False

    def _disable_heater(self):
        self._heater_on = False
        self._oil_temp = max(self.AMBIENT_TEMP, self._oil_temp - self.IDLE_LOSS)

    def _maintenance(self):
        self._oil_temp = self.AMBIENT_TEMP
        self._usage_minutes = 0.0
        self._log.append("maintenance: oil drained and replaced")
        return float(self.MAINTENANCE_TIME)

    def cook(self, minutes):
        minutes = _validate_duration(minutes)
        elapsed = self._preheat()
        self._lower_basket()
        self._usage_minutes += minutes
        elapsed += minutes
        self._raise_basket()
        self._disable_heater()
        self._log.append("cooked %.1f min (elapsed %.1f)" % (minutes, elapsed))
        if self._usage_minutes > self.MAINTENANCE_LIMIT:
            elapsed += self._maintenance()
        return elapsed

    def report(self):
        lines = ["Deep fryer report:"]
        lines.extend("  " + entry for entry in self._log)
        lines.append("  oil at %d F, basket %s, heater %s, usage %.1f min" % (
            self._oil_temp,
            "down" if self._basket_lowered else "up",
            "on" if self._heater_on else "off",
            self._usage_minutes,
        ))
        return "\n".join(lines)


def fry(durations):
    fryer = DeepFryer()
    return sum(fryer.cook(duration) for duration in durations)


def main():
    batches = [4, 12.5, 30, 45, 20, 6]
    fryer = DeepFryer()
    for batch in batches:
        fryer.cook(batch)
    print(fryer.report())
    print("total operational time: %.1f min" % fry(batches))


if __name__ == "__main__":
    main()

