NOMINAL_SPEED = 0.50
MAX_SPEED = 0.75
CRAWL_SPEED = 0.15
EMPTY_LOAD = 5.0
IDLE_LIMIT = 5
TORQUE_LIMIT = 60.0


class EscalatorRegulator:
    """Regulates escalator step speed from the passenger load of each step."""

    def __init__(self, nominal=NOMINAL_SPEED):
        self._velocity = float(nominal)
        self._torque = 0.0
        self._empty_steps = 0
        self._previous_load = 0.0

    def _validate(self, load):
        if isinstance(load, bool) or not isinstance(load, (int, float)):
            raise TypeError("load weights must be numeric, got %r" % (load,))
        weight = float(load)
        if weight < 0.0:
            raise ValueError("load weight cannot be negative: %r" % (load,))
        return weight

    def _demanded_torque(self, weight):
        return 0.12 * weight + 4.0 * self._velocity

    def _accelerate(self, delta):
        headroom = max(0.3, 1.0 - self._torque / TORQUE_LIMIT)
        gain = (0.02 + 0.004 * delta) * headroom
        self._velocity = min(MAX_SPEED, self._velocity + gain)

    def _brake(self, drop):
        damping = min(0.35, 0.006 * drop)
        self._velocity = max(CRAWL_SPEED, self._velocity - damping)

    def _crawl(self):
        self._velocity = max(CRAWL_SPEED, self._velocity - 0.05)

    def step(self, load):
        """Advance one discrete time step and return the resulting speed."""
        weight = self._validate(load)
        self._torque = self._demanded_torque(weight)
        if weight > self._previous_load:
            self._accelerate(weight - self._previous_load)
        elif weight < 0.5 * self._previous_load:
            self._brake(self._previous_load - weight)
        if weight <= EMPTY_LOAD:
            self._empty_steps += 1
        else:
            self._empty_steps = 0
        if self._empty_steps > IDLE_LIMIT:
            self._crawl()
        self._previous_load = weight
        return round(self._velocity, 3)


def regulate(loads):
    """Return the list of step speeds recorded for the given load sequence."""
    regulator = EscalatorRegulator()
    return [regulator.step(load) for load in loads]


