    lines = ["step  load(kg)  speed(m/s)"]
    for index, (load, speed) in enumerate(zip(loads, speeds), start=1):
        lines.append("%4d  %8.1f  %10.3f" % (index, float(load), speed))
    return "\n".join(lines)


