class RecordPress:
    """Hydraulic record press with internally managed heat, pressure and clamp."""

    _PLATE_TARGET_C = 160.0
    _AMBIENT_C = 20.0
    _RELEASE_C = 45.0
    _HEAT_RATE = 4.0          # degrees per second
    _COOL_RATE = 9.5          # degrees per second with water injection
    _PRESSURE_RATE = 120.0    # bar per second of ram travel
    _BAR_PER_GRAM = 3.2
    _HOLD_SECONDS = 20.0
    _CLAMP_SECONDS = 1.5

    def __init__(self):
        self._temp = self._AMBIENT_C
        self._pressure = 0.0
        self._clamped = False
        self._cache = {}

    def _validate_weight(self, weight):
        if not isinstance(weight, (int, float)) or isinstance(weight, bool):
            raise TypeError("record weight must be numeric")
        if weight <= 0:
            raise ValueError("record weight must be positive")

    def _warm(self):
        deficit = self._PLATE_TARGET_C - self._temp
        self._temp = self._PLATE_TARGET_C
        return deficit / self._HEAT_RATE

    def _compress(self, weight):
        target = weight * self._BAR_PER_GRAM
        travel = abs(target - self._pressure) / self._PRESSURE_RATE
        self._pressure = target
        self._clamped = True
        return travel + self._CLAMP_SECONDS

    def _hold(self):
        return self._HOLD_SECONDS

    def _cool(self):
        span = self._temp - self._RELEASE_C
        self._temp = self._RELEASE_C
        self._pressure = 0.0
        self._clamped = False
        return span / self._COOL_RATE

    def cycle(self, weight):
        self._validate_weight(weight)
        key = (round(float(weight), 4), round(self._temp, 4))
        cached = self._cache.get(key)
        if cached is None:
            elapsed = self._warm() + self._compress(weight) + self._hold() + self._cool()
            self._cache[key] = (elapsed, self._temp)
        else:
            elapsed, self._temp = cached
            self._pressure = 0.0
            self._clamped = False
        return elapsed


def press(weights):
    """Manufacture one record per entry in weights; return total seconds."""
    machine = RecordPress()
    return round(sum(machine.cycle(w) for w in weights), 3)


def format_report(weights):
    total = press(weights)
    return "{0} records, {1:.1f} g total -> {2:.3f} s".format(
        len(weights), float(sum(weights)), total)


def main():
    batches = [[140, 140, 140], [180, 200, 180, 140], []]
    for batch in batches:
        print(format_report(batch))


if __name__ == "__main__":
    main()

