class PotteryWheel:
    """A motorized throwing wheel that tracks speed, motor strain and clay integrity."""

    MAX_RPM = 320.0

    def __init__(self, clay_mass=2.0, radius=0.09):
        self.clay_mass = clay_mass
        self.radius = radius
        self._rpm = 0.0
        self._strain = 0.0
        self._integrity = 100.0

    def _adjust_speed(self, pressure):
        """Ramp the wheel toward the speed requested by the pedal, with motor lag."""
        target = self.MAX_RPM * pressure
        self._rpm += (target - self._rpm) * 0.55
        if self._rpm > self.MAX_RPM:
            self._rpm = self.MAX_RPM
        self._strain += abs(target - self._rpm) / 100.0
        self._strain *= 0.9
        return self._rpm

    def _centrifugal_force(self):
        """F = m * omega^2 * r, with omega derived from the current rpm."""
        omega = self._rpm * 2.0 * 3.141592653589793 / 60.0
        return self.clay_mass * omega * omega * self.radius

    def _counter_force(self, force):
        """Potter's hands push back; a strained motor wobbles and helps less."""
        grip = 0.82 - min(self._strain, 0.5) * 0.4
        return force * grip

    def _safe_threshold(self):
        """Safe rpm falls as the clay loses integrity and the motor heats up."""
        return self.MAX_RPM * (self._integrity / 100.0) * (1.0 - min(self._strain, 0.6) * 0.5)

    def pedal(self, pressure):
        """Apply one pedal pressure step; returns False once the clay collapses."""
        if not 0.0 <= pressure <= 1.0:
            raise ValueError("pedal pressure must be between 0.0 and 1.0")
        self._adjust_speed(pressure)
        force = self._centrifugal_force()
        net = force - self._counter_force(force)
        self._integrity -= net / self.clay_mass
        if self._integrity < 0.0:
            self._integrity = 0.0
        return self._rpm <= self._safe_threshold() and self._integrity > 0.0

    def report(self):
        return "rpm={:6.1f}  strain={:4.2f}  integrity={:5.1f}".format(
            self._rpm, self._strain, self._integrity
        )


def spin(pressures):
    """Throw a pot using the given sequence of pedal pressures.

    Returns True if the pot survived the whole session, False if it collapsed.
    """
    wheel = PotteryWheel()
    for pressure in pressures:
        if not wheel.pedal(pressure):
            return False
    return True


def describe_session(pressures):
    """Run a session step by step and build a human-readable log."""
    wheel = PotteryWheel()
    lines = []
    for step, pressure in enumerate(pressures, start=1):
        alive = wheel.pedal(pressure)
        lines.append("step {:2d} pedal={:4.2f}  {}".format(step, pressure, wheel.report()))
        if not alive:
            lines.append("clay collapsed at step {}".format(step))
            break
    else:
        lines.append("pot survived")
    return "\n".join(lines)


def main():
    gentle = [0.1, 0.2, 0.3, 0.3, 0.25, 0.2, 0.1]
    reckless = [0.4, 0.9, 1.0, 1.0, 0.8]
    for name, session in (("gentle", gentle), ("reckless", reckless)):
        print("--- {} session: survived={} ---".format(name, spin(session)))
        print(describe_session(session))


if __name__ == "__main__":
    main()

