class TorpedoTube:
    """A single torpedo tube with strictly ordered internal launch routines."""

    MAX_DEPTH = 300.0

    def __init__(self):
        self._inner_door = "open"
        self._outer_door = "closed"
        self._water_level = 0.0
        self._pressure = 1.0
        self._target_pressure = 1.0
        self._launched = []

    def _parse(self, command):
        if isinstance(command, dict):
            payload = command.get("payload")
            depth = command.get("depth")
        elif isinstance(command, str) and "@" in command:
            payload, _, raw_depth = command.partition("@")
            try:
                depth = float(raw_depth)
            except ValueError:
                return None
        else:
            return None
        if not payload or depth is None:
            return None
        depth = float(depth)
        if depth < 0.0 or depth > self.MAX_DEPTH:
            return None
        return payload.strip(), depth

    def _lock_inner_door(self):
        if self._water_level > 0.0:
            return False
        self._inner_door = "locked"
        return True

    def _flood_chamber(self):
        if self._inner_door != "locked":
            return False
        self._water_level = 100.0
        return True

    def _equalize(self, depth):
        if self._water_level < 100.0:
            return False
        self._target_pressure = 1.0 + depth / 10.0
        self._pressure = self._target_pressure
        return True

    def _open_outer_door(self):
        if abs(self._pressure - self._target_pressure) > 1e-9:
            return False
        self._outer_door = "open"
        return True

    def _expel(self, payload):
        if self._outer_door != "open":
            return False
        self._launched.append(payload)
        return True

    def _reset(self):
        self._outer_door = "closed"
        self._water_level = 0.0
        self._pressure = 1.0
        self._inner_door = "open"

    def fire(self, command):
        order = self._parse(command)
        if order is None:
            self._reset()
            return False
        payload, depth = order
        stages = (self._lock_inner_door(), self._flood_chamber(),
                  self._equalize(depth), self._open_outer_door(),
                  self._expel(payload))
        self._reset()
        return all(stages)

    def completed(self):
        return len(self._launched)

    def manifest(self):
        return list(self._launched)


def launch(commands):
    tube = TorpedoTube()
    for command in commands:
        tube.fire(command)
    return tube.completed()


def main():
    orders = [{"payload": "Mk48 ADCAP", "depth": 60},
              "Mk54@120.5",
              {"payload": "Harpoon", "depth": 900},
              {"depth": 40},
              "Tomahawk@0"]
    tube = TorpedoTube()
    for order in orders:
        status = "LAUNCHED" if tube.fire(order) else "ABORTED"
        print("%-9s %s" % (status, order))
    print("manifest:", ", ".join(tube.manifest()))
    print("successful launches:", launch(orders))


if __name__ == "__main__":
    main()

