DAMAGE_BY_LOCATION = {"head": 100, "torso": 50, "limb": 25}
POINTS_BY_LOCATION = {"head": 10, "torso": 5, "limb": 2}


class Arena:
    """Tracks health, points and base control for a two-team match."""

    TEAMS = ("red", "blue")
    START_HEALTH = 100
    ELIMINATION_BONUS = 5
    BASE_THRESHOLD = 3
    BASE_BONUS = 25

    def __init__(self):
        self._health = {}
        self._points = {team: 0 for team in self.TEAMS}
        self._zones = {}

    def _team_of(self, player):
        parts = str(player).split("_")
        if len(parts) != 2 or parts[0] not in self.TEAMS:
            raise ValueError("unknown player id: %r" % (player,))
        return parts[0]

    def _is_alive(self, player):
        return self._health.setdefault(player, self.START_HEALTH) > 0

    def _deduct(self, player, location):
        if location not in DAMAGE_BY_LOCATION:
            raise ValueError("unknown tag location: %r" % (location,))
        remaining = self._health[player] - DAMAGE_BY_LOCATION[location]
        self._health[player] = max(remaining, 0)
        return remaining <= 0

    def _award(self, team, amount):
        self._points[team] += amount

    def _claim_zone(self, team, zone):
        counters = self._zones.setdefault(zone, {name: 0 for name in self.TEAMS})
        counters[team] += 1
        if counters[team] >= self.BASE_THRESHOLD:
            counters[team] = 0
            self._award(team, self.BASE_BONUS)

    def resolve(self, event):
