DAMAGE_BY_LOCATION = {"head": 100, "torso": 50, "limb": 25}
POINTS_BY_LOCATION = {"head": 10, "torso": 5, "limb": 2}


class Arena:
    """Tracks health, points and base control for a two-team match."""

    TEAMS = ("red", "blue")
    START_HEALTH = 100
    ELIMINATION_BONUS = 5
    BASE_THRESHOLD = 3
    BASE_BONUS = 25

    def __init__(self):
        self.health = {}
        self.points = {team: 0 for team in self.TEAMS}
        self.zones = {}

    def team_of(self, player):
        parts = str(player).split("_")
        if len(parts) != 2 or parts[0] not in self.TEAMS:
            raise ValueError("unknown player id: %r" % (player,))
        return parts[0]

    def is_alive(self, player):
        return self.health.setdefault(player, self.START_HEALTH) > 0

    def deduct(self, player, location):
        if location not in DAMAGE_BY_LOCATION:
            raise ValueError("unknown tag location: %r" % (location,))
        remaining = self.health[player] - DAMAGE_BY_LOCATION[location]
        self.health[player] = max(remaining, 0)
        return remaining <= 0

    def award(self, team, amount):
        self.points[team] += amount

    def claim_zone(self, team, zone):
        counters = self.zones.setdefault(zone, {name: 0 for name in self.TEAMS})
        counters[team] += 1
        if counters[team] >= self.BASE_THRESHOLD:
            counters[team] = 0
            self.award(team, self.BASE_BONUS)

    def resolve(self, event):
        attacker_team = self.team_of(event["attacker"])
        target = event["target"]
        if self.team_of(target) == attacker_team:
            raise ValueError("friendly fire is not a scoring event")
        if not self.is_alive(target):
            return
        eliminated = self.deduct(target, event["location"])
        gained = POINTS_BY_LOCATION[event["location"]]
        if eliminated:
            gained += self.ELIMINATION_BONUS
        self.award(attacker_team, gained)
        zone = event.get("zone")
        if zone is not None:
            self.claim_zone(attacker_team, zone)

    def totals(self):
        return [self.points[team] for team in self.TEAMS]


def score(events):
    arena = Arena()
    for event in events:
        arena.resolve(event)
    return arena.totals()


def format_report(scores):
    return " | ".join(
        "%s: %d" % (team, value) for team, value in zip(Arena.TEAMS, scores)
    )


