class CombineHarvester:
    """Simulates the grain handling chain of a self-propelled combine."""

    TANK_CAPACITY = 9000.0
    BASE_DRUM_SPEED = 450.0
    MAX_DRUM_SPEED = 1250.0
    SPIKE_THRESHOLD = 15.0
    CHAFF_FRACTION = 0.28
    FAN_MAX_SPEED = 1000.0

    def __init__(self):
        self._tank = 0.0
        self._collected = 0.0
        self._drum_speed = self.BASE_DRUM_SPEED
        self._peak_drum_speed = self.BASE_DRUM_SPEED
        self._fan_speed = 0.0
        self._previous_inflow = 0.0

    @staticmethod
    def _validate(point):
        if isinstance(point, bool) or not isinstance(point, (int, float)):
            raise TypeError("crop yield data points must be numbers")
        if point < 0:
            raise ValueError("crop yield data points cannot be negative")
        return float(point)

    def _fill_tank(self, amount):
        self._tank += amount
        while self._tank >= self.TANK_CAPACITY:
            self._collected += self.TANK_CAPACITY
            self._tank -= self.TANK_CAPACITY

    def _adjust_drum(self, amount):
        inflow_delta = amount - self._previous_inflow
        self._previous_inflow = amount
        if inflow_delta > self.SPIKE_THRESHOLD:
            boosted = self._drum_speed + 4.0 * inflow_delta
            self._drum_speed = min(self.MAX_DRUM_SPEED, boosted)
        else:
            self._drum_speed = max(self.BASE_DRUM_SPEED, self._drum_speed - 12.0)
        self._peak_drum_speed = max(self._peak_drum_speed, self._drum_speed)

    def _engage_fan(self, amount):
        chaff = amount * self.CHAFF_FRACTION
        load = 300.0 + 20.0 * chaff + 0.3 * (self._drum_speed - self.BASE_DRUM_SPEED)
        self._fan_speed = min(self.FAN_MAX_SPEED, load)
        cleared = min(self._tank, chaff * (self._fan_speed / self.FAN_MAX_SPEED))
        self._tank -= cleared
        return cleared

    def process(self, point):
        amount = self._validate(point)
        self._fill_tank(amount)
        self._adjust_drum(amount)
        return self._engage_fan(amount)

    def status(self):
        return "tank={:8.2f} kg  drum={:7.1f} rpm  fan={:6.1f} rpm".format(
            self._tank, self._drum_speed, self._fan_speed)

    def totals(self):
        grain = self._collected + self._tank
        return round(grain, 3), round(self._peak_drum_speed, 1)


def harvest(yields):
    """Run the yield stream through a combine and report grain and peak drum."""
    machine = CombineHarvester()
    for point in yields:
        machine.process(point)
    return machine.totals()


def main():
    field = [12.0, 14.5, 41.0, 38.2, 70.0, 68.5, 22.0, 19.4, 95.0, 30.0]
    monitor = CombineHarvester()
    for row, point in enumerate(field, start=1):
        chaff = monitor.process(point)
        print("row {:2d}  yield={:6.2f}  chaff cleared={:6.2f}  {}".format(
            row, point, chaff, monitor.status()))
    grain, peak_drum = harvest(field)
    print("collected grain: {:.3f} kg, peak drum speed: {:.1f} rpm".format(
        grain, peak_drum))


if __name__ == "__main__":
    main()

