class Dishwasher:
    """Controller for a commercial dishwasher."""

    MAX_TEMPERATURE = 80
    IDLE_TEMPERATURE = 20
    HEAT_STEP = 15
    MIN_WASH_TEMPERATURE = 60
    DETERGENT_PER_WASH = 20
    WASH_MINUTES = 10

    def __init__(self):
        self.temperature = self.IDLE_TEMPERATURE
        self.detergent = 100
        self.phase = "idle"
        self.runtime = 0
        self._log = []

    def _record(self, message):
        self._log.append(message)

    def _heat(self):
        self.phase = "heating"
        previous = self.temperature
        self.temperature = min(self.MAX_TEMPERATURE, previous + self.HEAT_STEP)
        self._record("heat: {}C -> {}C".format(previous, self.temperature))

    def _heat_until_ready(self):
        while self.temperature < self.MIN_WASH_TEMPERATURE:
            if self.temperature >= self.MAX_TEMPERATURE:
                break
            self._heat()

    def _wash_cycle(self):
        if self.temperature < self.MIN_WASH_TEMPERATURE:
            self._heat_until_ready()
        if self.detergent < self.DETERGENT_PER_WASH:
            self._record("wash refused: only {} units of detergent".format(self.detergent))
            return
        self.phase = "washing"
        self.detergent -= self.DETERGENT_PER_WASH
        self.runtime += self.WASH_MINUTES
        self._record("wash: {}C, detergent {}, runtime {}min".format(
            self.temperature, self.detergent, self.runtime))

    def _drain(self):
        self.phase = "idle"
        self.temperature = self.IDLE_TEMPERATURE
        self._record("drain: back to idle at {}C".format(self.temperature))

    def _normalize(self, command):
        if not isinstance(command, str):
            raise TypeError("command must be a string, got {!r}".format(command))
        return command.strip().lower()

    def _handler(self, name):
        handlers = {"heat": self._heat, "wash": self._wash_cycle, "drain": self._drain}
        if name not in handlers:
            raise ValueError("unknown command: {!r}".format(name))
        return handlers[name]

    def execute(self, command):
        self._handler(self._normalize(command))()

    def run(self, commands):
        for command in commands:
            self.execute(command)
        return self.state()

    def state(self):
        return (self.temperature, self.detergent, self.runtime)

    def report(self):
        lines = list(self._log)
        lines.append("final: {}C, {} units detergent, {} minutes, phase {}".format(
            self.temperature, self.detergent, self.runtime, self.phase))
        return "\n".join(lines)


def wash(commands):
    machine = Dishwasher()
    return machine.run(commands)


def main():
    program = ["wash", "heat", "wash", "drain", "heat", "wash", "wash", "wash"]
    machine = Dishwasher()
    machine.run(program)
    print(machine.report())
    print("wash() returns:", wash(program))


if __name__ == "__main__":
    main()

