class ReverseOsmosisUnit:
    """Simulates a reverse osmosis desalination unit driven by text commands."""

    _MAX_PRESSURE = 150
    _HEALTH_THRESHOLD = 50

    def __init__(self):
        self._pressure = 100
        self._salinity = 0
        self._filter_health = 100
        self._water = 0
        self._bypass = False

    def _pump(self):
        self._pressure += 10
        self._filter_health = max(0, self._filter_health - 2)
        if self._filter_health < self._HEALTH_THRESHOLD:
            self._salinity += 5
        if not self._bypass:
            self._water += 5
        if self._pressure > self._MAX_PRESSURE:
            self._bypass = True

    def _backwash(self):
        self._pressure = max(0, self._pressure - 20)
        self._filter_health = min(100, self._filter_health + 10)

    def _reset(self):
        self._bypass = False
        self._pressure = 100

    def _dispatch(self, command):
        name = command.strip().lower()
        if name == "pump":
            self._pump()
        elif name == "backwash":
            self._backwash()
        elif name == "reset":
            self._reset()
        else:
            raise ValueError("unknown command: %r" % (command,))

    def run(self, operations):
        for command in operations:
            self._dispatch(command)
        return self._water, self._filter_health, self._salinity

    def report(self):
        return (
            "fresh water produced: {0} units\n"
            "final filter health : {1}%\n"
            "final salinity      : {2} ppm\n"
            "emergency bypass    : {3}"
        ).format(
            self._water,
            self._filter_health,
            self._salinity,
            "active" if self._bypass else "clear",
        )


def desalinate(operations):
    unit = ReverseOsmosisUnit()
    return unit.run(operations)


