    schedule = (
        ["pump"] * 6
        + ["backwash", "pump", "pump"]
        + ["reset"]
        + ["pump"] * 20
        + ["backwash", "backwash", "pump"]
    )
    unit = ReverseOsmosisUnit()
    unit.run(schedule)
    print("operations executed:", len(schedule))
    print(unit.report())


if __name__ == "__main__":
    main()

