MAX_BLOWER = 100
SOAP_PER_VEHICLE = 30
INITIAL_SOAP = 200
CONVEYOR_RUN_SPEED = 5
BRUSH_WASH_SPEED = 100


class CarWashBay:
    """Controller for a single drive-through wash bay."""

    def __init__(self):
        self.conveyor_speed = 0
        self.soap_level = INITIAL_SOAP
        self.brush_speed = 0
        self.blower_intensity = 0
        self._halted = False
        self._events = []
        self._handlers = {
            "entry": self._on_entry,
            "soap": self._on_soap,
            "rinse": self._on_rinse,
            "dry": self._on_dry,
            "stall": self._on_stall,
            "resume": self._on_resume,
        }

    def _normalize(self, reading):
        if not isinstance(reading, str):
            raise TypeError("sensor readings must be strings, got %r" % (reading,))
        return reading.strip().lower().replace(" ", "_")

    def _on_entry(self):
        self.conveyor_speed = CONVEYOR_RUN_SPEED

    def _on_soap(self):
        self.soap_level = max(0, self.soap_level - SOAP_PER_VEHICLE)
        self.brush_speed = BRUSH_WASH_SPEED

    def _on_rinse(self):
        self.brush_speed = 0

    def _on_dry(self):
        self.blower_intensity = MAX_BLOWER

    def _on_stall(self):
        self.conveyor_speed = 0
        self.brush_speed = 0
        self.blower_intensity = 0
        self._halted = True

    def _on_resume(self):
        self._halted = False
        self.conveyor_speed = CONVEYOR_RUN_SPEED

    def run(self, sensors):
        for reading in sensors:
            key = self._normalize(reading)
            handler = self._handlers.get(key)
            if handler is None:
                self._events.append("ignored:" + key)
                continue
            if self._halted and key != "resume":
                self._events.append("blocked:" + key)
                continue
            handler()
            self._events.append(key)
        return self.soap_level, self.conveyor_speed, self.blower_intensity

    def report(self):
        lines = ["sensor trace: " + " -> ".join(self._events)]
        lines.append("soap left: %d" % self.soap_level)
        lines.append("conveyor: %d  brushes: %d  blower: %d"
                     % (self.conveyor_speed, self.brush_speed, self.blower_intensity))
        if self._halted:
            lines.append("bay is halted, awaiting resume signal")
        return "\n".join(lines)


def wash(sensors):
    bay = CarWashBay()
    return bay.run(sensors)


def main():
    cycles = [
        ["entry", "soap", "rinse", "dry", "exit"],
        ["entry", "soap", "stall", "rinse", "resume", "rinse", "dry"],
    ]
    for sensors in cycles:
        bay = CarWashBay()
        bay.run(sensors)
        print(bay.report())
        print("returned:", wash(sensors))
        print("-" * 40)


if __name__ == "__main__":
