class HyperbaricChamber:
    """Control model of a medical hyperbaric chamber."""

    def __init__(self):
        self.pressure = 1
        self.oxygen = 21
        self.compression_rate = 0
        self.heart_rate = 80
        self._handlers = None
        self._log = []

    def _load(self):
        if self._handlers is None:
            self._handlers = {
                "pressurize": self._pressurize,
                "enrich": self._enrich,
                "decompress": self._decompress,
            }
        return self._handlers

