_PUMP_COMMANDS = frozenset({"pump", "pump on", "hydraulic pump", "restore pressure"})


class SwashplateController:
    """Tracks the rotor swashplate angles and the hydraulic boost pressure."""

    _LOAD_LIMIT = 15.0
    _PRESSURE_DROP = 200
    _MIN_PRESSURE = 2000
    _NOMINAL_PRESSURE = 3000

    def __init__(self):
        self.collective = 10.0
        self.lateral = 0.0
        self.longitudinal = 0.0
        self.pressure = self._NOMINAL_PRESSURE
        self._log = []

    def _is_pump(self, step):
        return isinstance(step, str) and step.strip().lower() in _PUMP_COMMANDS

    def _parse(self, step):
        """Normalise a stick movement into (collective, lateral, longitudinal)."""
        if not isinstance(step, (tuple, list)):
            raise ValueError("stick movement must be a tuple or a pump command")
        values = [float(v) for v in step]
        if len(values) == 2:
            return values[0], 0.0, values[1]
        if len(values) == 3:
            return values[0], values[1], values[2]
        raise ValueError("stick movement needs two or three components")

    def _sluggish(self):
        return self.pressure < self._MIN_PRESSURE

    def _scale(self, deltas):
        if self._sluggish():
            return tuple(d / 2.0 for d in deltas)
        return deltas

    def _load_check(self, deltas):
        if sum(abs(d) for d in deltas) > self._LOAD_LIMIT:
            self.pressure = max(0, self.pressure - self._PRESSURE_DROP)
            return True
        return False

    def _pump(self):
        self.pressure = self._NOMINAL_PRESSURE

    def apply(self, step):
        if self._is_pump(step):
            self._pump()
            self._log.append("pump: pressure restored to %d psi" % self.pressure)
            return
        commanded = self._parse(step)
        d_col, d_lat, d_lon = self._scale(commanded)
        self.collective += d_col
        self.lateral += d_lat
        self.longitudinal += d_lon
        overloaded = self._load_check((d_col, d_lat, d_lon))
        self._log.append(
            "move %s -> col %.2f lat %.2f lon %.2f at %d psi%s"
            % (tuple(commanded), self.collective, self.lateral,
               self.longitudinal, self.pressure,
               " (overload)" if overloaded else "")
        )

    def state(self):
        return (self.collective, self.longitudinal, self.pressure)

    def report(self):
        header = "sluggish controls" if self._sluggish() else "controls normal"
        return "\n".join([header] + self._log)


def pitch(inputs):
    controller = SwashplateController()
    for step in inputs:
        controller.apply(step)
    return controller.state()


def main():
    commands = [(5, 2, 3), (9, 4, 6), (-2, 0, 1), "pump", (1, 1, 1)]
    controller = SwashplateController()
    for step in commands:
        controller.apply(step)
    print(controller.report())
    print("final:", controller.state())


if __name__ == "__main__":
    main()

