BASE_FLOW = "base"
MAX_FLOW = "maximum"
RESET_COMMAND = "RESET"
OVERLOAD_THRESHOLD = 1000
CONSECUTIVE_LIMIT = 5


class Calorimeter:
    """Tracks absorbed energy, trigger rate, cooling flow and bias voltage."""

    def __init__(self):
        self._absorbed = 0
        self._triggers = 0
        self._cooling = BASE_FLOW
        self._bias = 100
        self._streak = 0
        self._overloaded = False
        self._log = []

    def _classify(self, event):
        if isinstance(event, str):
            if event.strip().upper() == RESET_COMMAND:
                return "reset", 0
            raise ValueError("unknown command: %r" % event)
        if not isinstance(event, int):
            raise ValueError("event must be an int or a command string")
        return "deposit", event

    def _absorb(self, energy):
        self._absorbed += energy
        self._triggers += 1
        self._streak += 1
        if self._streak >= CONSECUTIVE_LIMIT:
            self._cooling = MAX_FLOW

    def _overload(self, energy):
        self._bias = 0
        self._overloaded = True
        self._streak = 0
        self._log.append("overload at %d" % energy)

    def _restore(self):
        self._bias = 100
        self._overloaded = False
        self._streak = 0
        self._cooling = BASE_FLOW
        self._log.append("reset issued")

    def process(self, event):
        kind, energy = self._classify(event)
        if kind == "reset":
            self._restore()
        elif self._overloaded:
            self._log.append("ignored %d" % energy)
        else:
            self._absorb(energy)
            if energy > OVERLOAD_THRESHOLD:
                self._overload(energy)

    def state(self):
        return self._absorbed, self._bias, self._cooling

    def report(self):
        header = "absorbed=%d bias=%d cooling=%s triggers=%d" % (
            self._absorbed, self._bias, self._cooling, self._triggers)
        return "\n".join([header] + ["  " + entry for entry in self._log])


def detect(events):
    calorimeter = Calorimeter()
    for event in events:
        calorimeter.process(event)
    return calorimeter.state()


def main(argv):
    calorimeter = Calorimeter()
    for token in argv:
        calorimeter.process(token if token.strip().upper() == RESET_COMMAND else int(token))
    print(calorimeter.report())


if __name__ == "__main__":
    import sys
    main(sys.argv[1:])

