class TirePressureSystem:
    """Dynamic tire pressure system driven by a sequence of road conditions."""

    _TARGETS = {"highway": 40, "sand": 20, "mud": 25}
    _STEP = 5
    _LOAD_PER_PUMP = 10
    _LOAD_LIMIT = 50

    def __init__(self):
        self._current = 35
        self._target = 35
        self._load = 0
        self._valve = "closed"
        self._cooldown = 0

    def _normalize(self, condition):
        if not isinstance(condition, str):
            raise TypeError("each condition must be a string, got %r" % (condition,))
        return condition.strip().lower()

    def _pump(self):
        self._load += self._LOAD_PER_PUMP
        if self._load > self._LOAD_LIMIT:
            self._cooldown = 1

    def _release(self):
        self._valve = "open"
        self._load = 0

    def _apply_condition(self, condition):
        if condition in self._TARGETS:
            self._target = self._TARGETS[condition]
        elif "pump" in condition:
            self._pump()
        elif "release" in condition:
            self._release()

    def _adjust(self):
        if self._current < self._target:
            self._current = min(self._current + self._STEP, self._target)
        elif self._current > self._target:
            self._current = max(self._current - self._STEP, self._target)

    def step(self, condition):
        self._apply_condition(self._normalize(condition))
        if self._cooldown > 0:
            self._cooldown -= 1
            return
        self._adjust()

    def run(self, changes):
        for condition in changes:
            self.step(condition)
        return self.report()

    def report(self):
        return {
            "current_pressure": self._current,
            "compressor_load": self._load,
            "valve": self._valve,
        }


def inflate(changes):
    system = TirePressureSystem()
    return system.run(changes)


def format_report(state):
    return "pressure={current_pressure} psi | load={compressor_load} | valve={valve}".format(**state)


def main():
    scenarios = {
        "desert run": ["sand", "release", "sand", "sand"],
        "highway merge": ["highway", "pump", "pump", "highway"],
        "overheating pump": ["mud", "pump", "pump", "pump", "pump", "pump", "pump", "mud"],
    }
    for name, changes in scenarios.items():
        print("%-18s %s" % (name, format_report(inflate(changes))))


if __name__ == "__main__":
    main()

