    STEP = 5
    LOAD_PER_PUMP = 10
    LOAD_LIMIT = 50

    def __init__(self):
        self.current = 35
        self.target = 35
        self.load = 0
        self.valve = "closed"
        self.cooldown = 0

    def normalize(self, condition):
        if not isinstance(condition, str):
            raise TypeError("each condition must be a string, got %r" % (condition,))
        return condition.strip().lower()

    def pump(self):
        self.load += self.LOAD_PER_PUMP
        if self.load > self.LOAD_LIMIT:
            self.cooldown = 1

    def release(self):
        self.valve = "open"
        self.load = 0

    def apply_condition(self, condition):
        if condition in self.TARGETS:
            self.target = self.TARGETS[condition]
        elif "pump" in condition:
            self.pump()
        elif "release" in condition:
            self.release()

    def adjust(self):
        if self.current < self.target:
            self.current = min(self.current + self.STEP, self.target)
        elif self.current > self.target:
            self.current = max(self.current - self.STEP, self.target)

    def step(self, condition):
        self.apply_condition(self.normalize(condition))
        if self.cooldown > 0:
            self.cooldown -= 1
            return
        self.adjust()

    def run(self, changes):
        for condition in changes:
            self.step(condition)
        return self.report()

    def report(self):
        return {
            "current_pressure": self.current,
            "compressor_load": self.load,
            "valve": self.valve,
        }


def inflate(changes):
    system = TirePressureSystem()
    return system.run(changes)


def format_report(state):
    return "pressure={current_pressure} psi | load={compressor_load} | valve={valve}".format(**state)


def main():
    scenarios = {
        "desert run": ["sand", "release", "sand", "sand"],
        "highway merge": ["highway", "pump", "pump", "highway"],
        "overheating pump": ["mud", "pump", "pump", "pump", "pump", "pump", "pump", "mud"],
    }
    for name, changes in scenarios.items():
        print("%-18s %s" % (name, format_report(inflate(changes))))


if __name__ == "__main__":
    main()

