class SupersonicWindTunnel:
    """Control model of a supersonic wind tunnel test rig."""

    _GRID_TRIGGER_VELOCITY = 200

    def __init__(self):
        self._pitch = 0
        self._velocity = 0
        self._grid_deployed = False
        self._pressure = 100
        self._log = []

    def _normalize(self, command):
        name = str(command).strip().lower()
        if name not in self._dispatch():
            raise ValueError("unknown tunnel command: {!r}".format(command))
        return name

    def _dispatch(self):
        return {"spool": self._spool, "choke": self._choke, "vent": self._vent}

    def _spool(self):
        self._pitch += 10
        self._velocity += 50

    def _choke(self):
        self._pressure -= 20

    def _vent(self):
        self._velocity = 0
        self._grid_deployed = False

    def _enforce_grid(self):
        if self._velocity > self._GRID_TRIGGER_VELOCITY and not self._grid_deployed:
            self._grid_deployed = True
            self._velocity -= 20
            self._pressure += 10
            self._log.append("grid deployed automatically")

    def apply(self, command):
        name = self._normalize(command)
        self._dispatch()[name]()
        self._enforce_grid()
        self._log.append(
            "{}: pitch={} velocity={} pressure={}".format(
                name, self._pitch, self._velocity, self._pressure
            )
        )

    def run(self, commands):
        for command in commands:
            self.apply(command)
        return self.state()

    def state(self):
        status = "deployed" if self._grid_deployed else "retracted"
        return self._pitch, self._velocity, status

    def report(self):
        header = "pitch={0} velocity={1} grid={2}".format(*self.state())
        return "\n".join([header] + ["  " + entry for entry in self._log])


def modulate(commands):
    return SupersonicWindTunnel().run(commands)


def main():
    runs = [
        ["spool", "spool", "choke"],
        ["spool", "spool", "spool", "spool", "spool"],
        ["spool", "spool", "spool", "spool", "spool", "vent", "spool"],
    ]
    for commands in runs:
        print(commands, "->", modulate(commands))
    tunnel = SupersonicWindTunnel()
    tunnel.run(runs[-1])
    print(tunnel.report())


if __name__ == "__main__":
    main()

