class TunnelBoringMachine:
    """Simulates the thrust, cutterhead and muck circuits of a TBM."""

    _DEFAULT_PRESSURE = 500
    _DEFAULT_SPEED = 10
    _OVERLOAD_LIMIT = 800

    def __init__(self):
        self._pressure = self._DEFAULT_PRESSURE
        self._speed = self._DEFAULT_SPEED
        self._muck_rate = 0
        self._position = 0
        self._overloaded = False
        self._log = []
        self._handlers = self._build_handlers()

    def _build_handlers(self):
        return {
            "soft dirt": self._cut_soft,
            "hard rock": self._cut_hard,
            "maintenance": self._maintain,
        }

    def _normalize(self, stratum):
        return " ".join(str(stratum).strip().lower().split())

    def _cut_soft(self):
        self._muck_rate += 20
        self._position += 2

    def _cut_hard(self):
        self._speed -= 3
        self._pressure += 100
        self._position += 1
        self._check_overload()

    def _check_overload(self):
        if self._pressure > self._OVERLOAD_LIMIT:
            self._speed = 0
            self._muck_rate = 0
            self._overloaded = True
            self._log.append("overload at pressure {0}".format(self._pressure))

    def _maintain(self):
        self._speed = self._DEFAULT_SPEED
        self._pressure = self._DEFAULT_PRESSURE
        self._overloaded = False
        self._log.append("maintenance performed")

    def run(self, strata):
        for stratum in strata:
            name = self._normalize(stratum)
            handler = self._handlers.get(name)
            if handler is None:
                raise ValueError("unknown stratum: {0!r}".format(stratum))
            if self._overloaded and name != "maintenance":
                self._log.append("stalled in " + name)
                continue
            handler()
        return self

    def state(self):
        return (self._pressure, self._speed, self._position)

    def report(self):
        lines = ["thrust pressure: {0}".format(self._pressure)]
        lines.append("cutterhead speed: {0}".format(self._speed))
        lines.append("muck removal rate: {0}".format(self._muck_rate))
        lines.append("total shield advance: {0}".format(self._position))
        lines.extend(self._log)
        return "\n".join(lines)


def bore(strata):
    return TunnelBoringMachine().run(strata).state()


def main():
    drive = ["soft dirt", "hard rock", "hard rock", "hard rock",
             "hard rock", "soft dirt", "maintenance", "soft dirt"]
    print(bore(drive))
    print(TunnelBoringMachine().run(drive).report())


if __name__ == "__main__":
    main()

