class MRIController:
    """Controls a single MRI scanning session and tracks scanner vitals."""

    _MAX_TEMP = 80
    _COOLED_TEMP = 40
    _MIN_HELIUM = 20
    _HELIUM_PER_COOLDOWN = 10

    def __init__(self):
        self._field = 1
        self._temp = 20
        self._helium = 100
        self._resolution = 0
        self._log = []

    def _validate(self, sequences):
        if not isinstance(sequences, (list, tuple)):
            raise TypeError("sequences must be a list of pulse durations")
        for pulse in sequences:
            if isinstance(pulse, bool) or not isinstance(pulse, int):
                raise TypeError("pulse durations must be integers: %r" % (pulse,))
            if pulse < 0:
                raise ValueError("pulse durations must be non-negative: %d" % pulse)

    def _apply_pulse(self, pulse):
        self._resolution += pulse
        self._temp += pulse / 2.0

    def _overheated(self):
        return self._temp > self._MAX_TEMP

    def _cool_coils(self):
        self._helium -= self._HELIUM_PER_COOLDOWN
        self._temp = self._COOLED_TEMP
        self._log.append("cooled coils, helium down to %d%%" % self._helium)

    def _quench(self):
        self._field = 0
        self._log.append("QUENCH: field collapsed, scanning halted")

    @property
    def field_strength(self):
        return self._field

    def scan(self, sequences):
        self._validate(sequences)
        for pulse in sequences:
            if self._field == 0:
                break
            self._apply_pulse(pulse)
            if self._overheated():
                self._cool_coils()
            if self._helium < self._MIN_HELIUM:
                self._quench()
                break
        return self._resolution, self._temp, self._helium

    def report(self):
        lines = ["resolution=%g temp=%g helium=%d field=%g"
                 % (self._resolution, self._temp, self._helium, self._field)]
        lines.extend("  - " + entry for entry in self._log)
        return "\n".join(lines)


def run_session(sequences):
    controller = MRIController()
    result = controller.scan(sequences)
    return result, controller.report()


def main():
    sessions = [
        [10, 20, 30],
        [100, 100, 100, 100, 100, 100, 100, 100, 100, 50],
        [],
    ]
    for sequences in sessions:
        result, report = run_session(sequences)
        print("pulses: %s" % (sequences,))
        print("returned: %s" % (result,))
        print(report)
        print("-" * 40)


if __name__ == "__main__":
    main()

