class DeliSlicer:
    """Automated meat deli slicer with blade, carriage and safety monitoring."""

    _TEMPOS = ("stopped", "slow", "medium", "fast", "maximum")

    def __init__(self):
        self._cache = None
        self._blade_speed = "zero"
        self._tempo = 0
        self._slices = 0
        self._guard_locked = True
        self._previous = None
        self._changes = 0

    def _load(self):
        table = {}
        for alias in ("power on", "power-on", "power up", "start"):
            table[alias] = "power"
        for alias in ("thick", "thick cut", "coarse"):
            table[alias] = "thick"
        for alias in ("thin", "thin cut", "fine"):
            table[alias] = "thin"
        return table

    def _vocabulary(self):
        if self._cache is None:
            self._cache = self._load()
        return self._cache

    def _normalize(self, request):
        key = " ".join(str(request).lower().split())
        return self._vocabulary().get(key)

    def _power_on(self):
        self._blade_speed = "high"
        self._tempo = self._TEMPOS.index("medium")

    def _shift_tempo(self, step):
        bounded = min(max(self._tempo + step, 0), len(self._TEMPOS) - 1)
        self._tempo = bounded

    def _overheat(self):
        self._blade_speed = "zero"
        self._guard_locked = False
        self._tempo = 0
        self._changes = 0

    def _track(self, command):
        if self._previous is not None and command != self._previous:
            self._changes += 1
        else:
            self._changes = 0
        self._previous = command
        if self._changes >= 3:
            self._overheat()

    def _cut(self, command):
        if self._blade_speed != "high":
            return
        if command == "thick":
            self._slices += 1
            self._shift_tempo(-1)
        else:
            self._slices += 2
            self._shift_tempo(1)

    def handle(self, request):
        command = self._normalize(request)
        if command is None:
            raise ValueError("unknown slicer setting: %r" % (request,))
        if command == "power":
            self._power_on()
        else:
            self._track(command)
            self._cut(command)

    def report(self):
        return {
            "slices": self._slices,
            "blade_speed": self._blade_speed,
            "carriage_tempo": self._TEMPOS[self._tempo],
            "safety_guard": "engaged" if self._guard_locked else "disengaged",
        }


def slice(requests):
    if not isinstance(requests, (list, tuple)):
        raise TypeError("requests must be a list of thickness settings")
    slicer = DeliSlicer()
    for request in requests:
        slicer.handle(request)
    return slicer.report()


def format_report(state):
    return ("slices=%(slices)d blade=%(blade_speed)s tempo=%(carriage_tempo)s "
            "guard=%(safety_guard)s" % state)


def main():
    orders = [
        ["power on", "thick", "thin", "thin", "thick"],
        ["power on", "thick", "thin", "thick", "thin", "thick"],
    ]
    for order in orders:
        print(format_report(slice(order)))


if __name__ == "__main__":
    main()

