FULL_PRESSURE = 100
PUMP_COMMAND = "PUMP"
FLAP_REFERENCE_SPEED = 200
SPEED_STEP = 20
ANGLE_STEP = 10


class TrailingEdgeFlapSystem:
    """Trailing edge flap control with hydraulic asymmetry protection."""

    _COST_PER_STEP = 6
    _ASYMMETRY_LIMIT = 10

    def __init__(self):
        self.flap_angle = 0
        self.left_pressure = FULL_PRESSURE
        self.right_pressure = FULL_PRESSURE
        self.asymmetry_lock = False
        self._cache = {}
        self._log = []

    def _validated(self, airspeeds):
        for item in airspeeds:
            if isinstance(item, bool) or not isinstance(item, (int, str)):
                raise TypeError("commands must be integers or the pump string")
            if isinstance(item, str):
                if item.strip().upper() != PUMP_COMMAND:
                    raise ValueError("unknown command: %r" % item)
                yield PUMP_COMMAND
            else:
                yield item

    def _target_angle(self, airspeed):
        if airspeed not in self._cache:
            steps = max(0, (FLAP_REFERENCE_SPEED - airspeed) // SPEED_STEP)
            self._cache[airspeed] = steps * ANGLE_STEP
        return self._cache[airspeed]

    def _affordable_steps(self, steps):
        available = min(self.left_pressure, self.right_pressure)
        return min(steps, available // self._COST_PER_STEP)

    def _consume(self, steps):
        draw = steps * self._COST_PER_STEP
        self.left_pressure -= draw
        self.right_pressure -= draw

    def _check_asymmetry(self):
        if abs(self.left_pressure - self.right_pressure) > self._ASYMMETRY_LIMIT:
            self.asymmetry_lock = True
            self._log.append("asymmetry lock engaged at %d deg" % self.flap_angle)

    def _extend_to(self, target):
