FULL_PRESSURE = 100
PUMP_COMMAND = "PUMP"
FLAP_REFERENCE_SPEED = 200
SPEED_STEP = 20
ANGLE_STEP = 10


class TrailingEdgeFlapSystem:
    """Trailing edge flap control with hydraulic asymmetry protection."""

    COST_PER_STEP = 6
    ASYMMETRY_LIMIT = 10

    def __init__(self):
        self.flap_angle = 0
        self.left_pressure = FULL_PRESSURE
        self.right_pressure = FULL_PRESSURE
        self.asymmetry_lock = False
        self.cache = {}
        self.log = []

    def validated(self, airspeeds):
        for item in airspeeds:
            if isinstance(item, bool) or not isinstance(item, (int, str)):
                raise TypeError("commands must be integers or the pump string")
            if isinstance(item, str):
                if item.strip().upper() != PUMP_COMMAND:
                    raise ValueError("unknown command: %r" % item)
                yield PUMP_COMMAND
            else:
                yield item

    def target_angle(self, airspeed):
        if airspeed not in self.cache:
            steps = max(0, (FLAP_REFERENCE_SPEED - airspeed) // SPEED_STEP)
            self.cache[airspeed] = steps * ANGLE_STEP
        return self.cache[airspeed]

    def affordable_steps(self, steps):
        available = min(self.left_pressure, self.right_pressure)
        return min(steps, available // self.COST_PER_STEP)

    def consume(self, steps):
        draw = steps * self.COST_PER_STEP
        self.left_pressure -= draw
        self.right_pressure -= draw

    def check_asymmetry(self):
        if abs(self.left_pressure - self.right_pressure) > self.ASYMMETRY_LIMIT:
            self.asymmetry_lock = True
            self.log.append("asymmetry lock engaged at %d deg" % self.flap_angle)

    def extend_to(self, target):
        if self.asymmetry_lock or target <= self.flap_angle:
            return
        steps = self.affordable_steps((target - self.flap_angle) // ANGLE_STEP)
        if steps:
            self.flap_angle += steps * ANGLE_STEP
            self.consume(steps)
            self.log.append("flaps extended to %d deg" % self.flap_angle)
            self.check_asymmetry()

    def pump(self):
        self.left_pressure = FULL_PRESSURE
        self.right_pressure = FULL_PRESSURE
        self.asymmetry_lock = False
        self.log.append("hydraulics equalized and refilled")

    def adjust(self, airspeeds):
        for command in self.validated(airspeeds):
            if command == PUMP_COMMAND:
                self.pump()
            else:
                self.extend_to(self.target_angle(command))
        return self.flap_angle, self.left_pressure, self.asymmetry_lock

    def report(self):
        lines = list(self.log)
        lines.append("final: angle=%d deg left=%d right=%d lock=%s" % (
            self.flap_angle, self.left_pressure,
            self.right_pressure, self.asymmetry_lock))
        return "\n".join(lines)


def main():
    system = TrailingEdgeFlapSystem()
    angle, left, lock = system.adjust([220, 190, 170, 150, PUMP_COMMAND, 130, 90])
    print(system.report())
    print("returned:", (angle, left, lock))


