class MovingHeadLight:
    """An intelligent moving head fixture with pan/tilt motors and a color wheel."""

    PAN_LIMIT = 50

    def __init__(self):
        self.pan = 0
        self.tilt = 0
        self.color = "white"
        self.shutter = "open"
        self._frozen = False
        self._cache = None

    def _load(self):
        self._cache = {
            "red": self._cue_red,
            "blue": self._cue_blue,
            "blackout": self._cue_blackout,
            "home": self._cue_home,
        }

    def _handlers(self):
        if self._cache is None:
            self._load()
        return self._cache

    def _check_limit(self):
        if abs(self.pan) > self.PAN_LIMIT:
            self._frozen = True
            self.shutter = "closed"

    def _cue_red(self):
        self.color = "red"
        self.pan -= 10
        self._check_limit()

    def _cue_blue(self):
        self.color = "blue"
        self.tilt += 15

    def _cue_blackout(self):
        self.shutter = "closed"
        self.pan = 0
        self.tilt = 0

    def _cue_home(self):
        self._frozen = False
        self.pan = 0
        self.tilt = 0
        self.shutter = "open"
        self.color = "white"

    def apply(self, cue):
        if not isinstance(cue, str):
            raise TypeError("cues must be strings, got %r" % (cue,))
        name = cue.strip().lower()
        handler = self._handlers().get(name)
        if handler is None:
            raise ValueError("unknown cue: %s" % cue)
        if self._frozen and name != "home":
            return
        handler()

    def run(self, cues):
        for cue in cues:
            self.apply(cue)


def illuminate(cues):
    rig = MovingHeadLight()
    rig.run(cues)
    return rig.pan, rig.tilt, rig.shutter


