        ["red"] * 6 + ["blue"],
        ["red"] * 6 + ["home", "blue", "blue"],
        ["red", "blue", "blackout", "blue"],
    ]
    for show in shows:
        print(", ".join(show), "->", illuminate(show))


if __name__ == "__main__":
    main()

