class MineCart:
    """A stateful mine cart descending a steep track segment by segment."""

    BRAKE_THRESHOLD = 20.0
    HEAT_LIMIT = 50.0
    PAD_WEAR = 2.0
    HEAT_PER_BRAKE = 15.0

    def __init__(self):
        self._speed = 0.0
        self._pad = 100.0
        self._heat = 0.0
        self._history = []

    def _validated(self, segments):
        for index, slope in enumerate(segments):
            if isinstance(slope, bool) or not isinstance(slope, (int, float)):
                raise TypeError("segment %d is not a slope number: %r" % (index, slope))
            yield float(slope)

    def _brakes_available(self):
        return self._pad > 0

    def _brake_reduction(self):
        if self._heat > self.HEAT_LIMIT:
            return 5.0
        return 10.0

    def _engage_brakes(self):
        self._speed -= self._brake_reduction()
        self._pad -= self.PAD_WEAR
        self._heat += self.HEAT_PER_BRAKE

    def descend(self, segments):
        for slope in self._validated(segments):
            self._speed += slope
            if self._speed > self.BRAKE_THRESHOLD and self._brakes_available():
                self._engage_brakes()
            self._history.append(self._speed)
        return list(self._history)

    def status_report(self):
        lines = ["segment %2d: speed %6.1f" % (i + 1, s)
                 for i, s in enumerate(self._history)]
        lines.append("final speed : %6.1f" % self._speed)
        lines.append("pad left    : %6.1f" % self._pad)
        lines.append("shoe heat   : %6.1f" % self._heat)
        if not self._brakes_available():
            lines.append("WARNING: brakes have failed")
        elif self._heat > self.HEAT_LIMIT:
            lines.append("WARNING: shoes overheated, braking degraded")
        return "\n".join(lines)


def descend(segments):
    """Return the cart speed at the end of each track segment."""
    return MineCart().descend(segments)


def main():
    print(descend([5, 20, 15]))
    cart = MineCart()
    speeds = cart.descend([12] * 40)
    print("peak speed:", max(speeds))
    print(cart.status_report())


if __name__ == "__main__":
    main()

