START_ALTITUDE = 10000
ACCELERATION = 10
BASE_TERMINAL_VELOCITY = 120
SPREAD_PER_SECOND = 20
PULL = "pull"


class Skydive:
    """A skydiver falling from START_ALTITUDE with a deployable canopy."""

    def __init__(self):
        self._altitude = START_ALTITUDE
        self._speed = 0
        self._spread = 0
        self._canopy = False
        self._log = []

    def _terminal_velocity(self):
        return max(0, BASE_TERMINAL_VELOCITY - self._spread)

    def _tick(self):
        """Advance the body state by one second of falling."""
        self._speed = min(self._speed + ACCELERATION, self._terminal_velocity())
        if self._canopy:
            self._spread += SPREAD_PER_SECOND

    def _record(self, event):
        self._log.append({
            "event": event,
            "speed": self._speed,
            "spread": self._spread,
            "altitude": self._altitude,
        })

    def _parse(self, action):
        """Return the seconds to fall, or None when the action is a canopy pull."""
        if isinstance(action, str):
            if action.strip().lower() != PULL:
                raise ValueError("unknown action: %r" % (action,))
            return None
        if isinstance(action, bool) or not isinstance(action, (int, float)):
            raise ValueError("unknown action: %r" % (action,))
        if action < 0:
            raise ValueError("cannot fall for %r seconds" % (action,))
        return action

    def _fall(self, seconds):
        for _ in range(int(seconds)):
            self._tick()
        self._altitude -= self._speed * seconds
        self._record("%gs" % (seconds,))

    def _open_canopy(self):
        self._canopy = True
        self._record(PULL)

    def run(self, actions):
        for action in actions:
            seconds = self._parse(action)
            if seconds is None:
                self._open_canopy()
            else:
                self._fall(seconds)
                if self._altitude <= 0:
                    break
        return self._altitude

    def report(self):
        template = "{event:>6}  speed={speed:5.0f}  canopy={spread:4.0f}%  altitude={altitude:8.0f}"
        return "\n".join(template.format(**entry) for entry in self._log)


def descend(actions):
    return Skydive().run(actions)


def main():
    jump = Skydive()
    final = jump.run([10, PULL, 5])
    print(jump.report())
    print("landed at" if final <= 0 else "still airborne at", final)
    print("long freefall ends at", descend([20, 70]))


if __name__ == "__main__":
    main()

