class SiegeTrebuchet:
    """A stateful siege trebuchet that performs test swings before a real launch."""

    START_COUNTERWEIGHT = 500
    START_SLING_LENGTH = 10
    STRESS_DIVISOR = 10
    BALLAST_LOSS = 5

    def __init__(self):
        self._counterweight = self.START_COUNTERWEIGHT
        self._sling_length = self.START_SLING_LENGTH
        self._pivot_stress = 0
        self._log = []

    def _normalise(self, adjustments):
        payloads = []
        for index, raw in enumerate(adjustments):
            if isinstance(raw, bool) or not isinstance(raw, (int, float)):
                raise TypeError("payload %d is not a number: %r" % (index, raw))
            payloads.append(float(raw))
        return payloads

    def _compute_stress(self, payload):
        return payload * self._sling_length / self.STRESS_DIVISOR

    def _swing(self, payload):
        stress = self._compute_stress(payload)
        self._pivot_stress = stress
        if stress > self._counterweight:
            self._sling_length -= 1
            succeeded = False
        else:
            self._counterweight -= self.BALLAST_LOSS
            succeeded = True
        self._log.append((payload, stress, succeeded))
        return succeeded

    def fire_all(self, adjustments):
        payloads = self._normalise(adjustments)
        return sum(1 for payload in payloads if self._swing(payload))

    def state(self):
        return {
            "counterweight": self._counterweight,
            "sling_length": self._sling_length,
            "pivot_stress": self._pivot_stress,
        }

    def _format_entry(self, position, entry):
        payload, stress, succeeded = entry
        verdict = "HIT" if succeeded else "JAM"
        return "%2d. payload=%8.2f stress=%8.2f %s" % (position, payload, stress, verdict)

    def report(self):
        lines = [self._format_entry(i, entry) for i, entry in enumerate(self._log, 1)]
        final = self.state()
        lines.append(
            "final: counterweight=%.2f sling=%d stress=%.2f"
            % (final["counterweight"], final["sling_length"], final["pivot_stress"])
        )
        return "\n".join(lines)


def launch(adjustments):
    """Return the number of successful test swings for the given payload weights."""
    trebuchet = SiegeTrebuchet()
    return trebuchet.fire_all(adjustments)


def main():
    payloads = [300, 600, 400]
    engine = SiegeTrebuchet()
    successes = engine.fire_all(payloads)
    print(engine.report())
    print("successful swings: %d" % successes)
    print("launch() agrees: %s" % (launch(payloads) == successes))


if __name__ == "__main__":
    main()

