class Sandglass:
    """A stateful hour glass whose neck clogs when run for too long at once."""

    CAPACITY = 100
    NECK_LIMIT = 50

    def __init__(self):
        self.upper = self.CAPACITY
        self.lower = 0
        self.clogged = False
        self.log = []

    def validate(self, interval):
        if isinstance(interval, bool) or not isinstance(interval, int):
            raise TypeError("intervals must be whole numbers of seconds")
        if interval < 0:
            raise ValueError("an interval cannot be negative")
        return interval

    def tap(self):
        self.clogged = False

    def flow(self, seconds):
        moved = min(seconds, self.upper)
        self.upper -= moved
        self.lower += moved
        return moved

    def record(self, interval, moved):
        self.log.append((interval, moved, self.clogged))

    def describe(self, entry):
        interval, moved, clogged = entry
        state = "clogged" if clogged else "open"
        return "{:>4}s -> {:>3} units moved (neck {})".format(interval, moved, state)

    def run(self, intervals):
        for raw in intervals:
            interval = self.validate(raw)
            if interval == 0:
                self.tap()
                moved = 0
            elif self.clogged:
                moved = 0
            else:
                moved = self.flow(interval)
                if interval > self.NECK_LIMIT:
                    self.clogged = True
            self.record(interval, moved)
        return self.lower

    def report(self):
        lines = [self.describe(entry) for entry in self.log]
        lines.append("upper={} lower={}".format(self.upper, self.lower))
        return lines


def measure(intervals):
    """Run a fresh sandglass over the given intervals and return the lower volume."""
    return Sandglass().run(intervals)


def main():
    schedule = [60, 10, 0, 5]
    glass = Sandglass()
    print("lower sand:", glass.run(schedule))
    for line in glass.report():
        print(line)
    print("stateless call:", measure(schedule))
    print("long soak:", measure([120, 30, 0, 200]))


if __name__ == "__main__":
    main()

