import sys

DECAY_PER_MINUTE = 5
PITCH_FACTOR = 2
HEAT_THRESHOLD = 50
SEIZE_HEAT = 100


class MechanicalSiren:
    """A hand-cranked warning siren with rotor inertia, pitch and bearing heat."""

    def __init__(self):
        self._inertia = 0
        self._heat = 0
        self._seized = False
        self._log = []

    def _spin(self, effort):
        self._inertia = max(0, self._inertia + effort - DECAY_PER_MINUTE)
        return self._inertia

    def _accrue_heat(self):
        if self._inertia > HEAT_THRESHOLD:
            self._heat += self._inertia - HEAT_THRESHOLD
        if self._heat >= SEIZE_HEAT:
            self._seized = True

    def _advance(self, effort):
        if self._seized:
            pitch = 0
        else:
            pitch = self._spin(effort) * PITCH_FACTOR
            self._accrue_heat()
        self._log.append((effort, self._inertia, self._heat, pitch))
        return pitch

    def run(self, efforts):
        return [self._advance(effort) for effort in efforts]

    def report(self):
        header = "min  effort  inertia   heat   pitch"
        rows = [header, "-" * len(header)]
        for minute, entry in enumerate(self._log, start=1):
            rows.append("%3d  %6g  %7g  %5g  %6g" % ((minute,) + entry))
        if self._seized:
            rows.append("bearings seized after %g total heat" % self._heat)
        return "\n".join(rows)


def crank(efforts):
    """Return the pitch produced for each minute of cranking."""
    return MechanicalSiren().run(efforts)


def parse_efforts(tokens):
    efforts = []
    for position, token in enumerate(tokens, start=1):
        try:
            efforts.append(float(token))
        except ValueError:
            raise SystemExit("minute %d: %r is not a number" % (position, token))
    return efforts


def main(argv):
    efforts = parse_efforts(argv[1:])
    if not efforts:
        raise SystemExit("usage: %s EFFORT [EFFORT ...]" % argv[0])
    siren = MechanicalSiren()
    siren.run(efforts)
    print(siren.report())


if __name__ == "__main__":
    main(sys.argv)

