import sys


class BinocularSystem:
    """A stateful binocular optical system with two diopter rings and a bridge."""

    _MAX_SPREAD = 3

    def __init__(self):
        self.left = 0
        self.right = 0
        self.bridge = 90
        self._distorted = False
        self._history = []
        self._actions = {
            "left": self._adjust_left,
            "right": self._adjust_right,
            "center": self._adjust_center,
        }

    def _validate(self, command):
        if not isinstance(command, str):
            raise TypeError("adjustment must be a string, got %r" % (command,))
        key = command.strip().lower()
        if key not in self._actions:
            raise ValueError("unknown adjustment: %r" % (command,))
        return key

    def _adjust_left(self):
        if not self._distorted:
            self.left += 1

    def _adjust_right(self):
        if not self._distorted:
            self.right += 1

    def _adjust_center(self):
        if not self._distorted:
            self.left += 2
            self.right += 2
        self.bridge -= 5

    def _update_distortion(self):
        if abs(self.left - self.right) > self._MAX_SPREAD:
            self._distorted = True

    def apply(self, command):
        key = self._validate(command)
        self._actions[key]()
        self._update_distortion()
        self._history.append(key)

    def run(self, adjustments):
        for command in adjustments:
            self.apply(command)

    def total_diopters(self):
        return self.left + self.right

    def _format_state(self):
        return "left=%d right=%d bridge=%d" % (self.left, self.right, self.bridge)

    def report(self):
        applied = ", ".join(self._history) if self._history else "none"
        status = "distorted" if self._distorted else "clear"
        return "\n".join([
            "applied: " + applied,
            "state: " + self._format_state(),
            "status: " + status,
            "total: %d" % self.total_diopters(),
        ])


def focus(adjustments):
    system = BinocularSystem()
    system.run(adjustments)
    return system.total_diopters()


def main(argv):
    adjustments = argv[1:] if len(argv) > 1 else sys.stdin.read().split()
    system = BinocularSystem()
    system.run(adjustments)
    print(system.report())
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

