class Bellows:
    """A leather bellows feeding air into a blacksmith forge."""

    _CAPACITY = 20
    _COOLING = 10
    _GAIN_PER_AIR = 2
    _ABSORPTION = 10

    def __init__(self):
        self._volume = self._CAPACITY
        self._ember = 500
        self._metal = 0

    def _intake(self, distance):
        """Refill the chamber, push `distance` out of it and return the air moved."""
        if isinstance(distance, bool) or not isinstance(distance, int):
            raise TypeError("push distance must be an integer, got %r" % (distance,))
        if distance < 0:
            raise ValueError("push distance must not be negative: %d" % distance)
        self._volume = self._CAPACITY
        self._volume -= min(distance, self._CAPACITY)
        return self._CAPACITY - self._volume

    def _burn(self, air):
        """Stoke the embers with the pushed air, cool them, then heat the metal."""
        self._ember += self._GAIN_PER_AIR * air - self._COOLING
        self._metal += self._ember // self._ABSORPTION
        return self._metal

    def stroke(self, distance):
        """Perform one stroke and return the resulting metal heat."""
        return self._burn(self._intake(distance))

    def run(self, strokes):
        return [self.stroke(distance) for distance in strokes]

    def status(self):
        return "volume=%d ember=%d metal=%d" % (self._volume, self._ember, self._metal)


_FORGE = Bellows()


def pump(strokes):
    """Process a list of push distances, returning metal heat after each stroke."""
    return _FORGE.run(strokes)


def forge_status():
    """Current chamber volume, ember temperature and metal heat."""
    return _FORGE.status()


def main():
    print("metal heat after each stroke:", pump([10, 15]))
    print("forge:", forge_status())


if __name__ == "__main__":
    main()

