class PoolRobot:
    """An automatic pool cleaning robot with battery, filter and depth state."""

    MAX_BATTERY = 100
    FILTER_LIMIT = 100
    RECHARGE_TURNS = 3
    BACKWASH_TURNS = 5
    BACKWASH_RATE = 20

    def __init__(self, depth=0):
        self.battery = self.MAX_BATTERY
        self.filter_dirt = 0
        self.depth = depth
        self._recharge_left = 0
        self._backwash_left = 0
        self._history = []

    def _validate(self, actions):
        pairs = []
        for item in actions:
            distance, dirt = item
            if not isinstance(distance, int) or not isinstance(dirt, int):
                raise TypeError("each action must be a pair of integers")
            if dirt < 0:
                raise ValueError("dirt encountered cannot be negative")
            pairs.append((distance, dirt))
        return pairs

    def _spend(self, units):
        self.battery = max(0, self.battery - units)

    def _move(self, distance):
        self.depth = max(0, self.depth + distance)
        self._spend(abs(distance))

    def _suck(self, dirt):
        self.filter_dirt += dirt
        self._spend(2 * dirt)

    def _battery_low(self):
        return self.battery < self.MAX_BATTERY * 0.1

    def _charge(self):
        self.battery = self.MAX_BATTERY
        self._recharge_left -= 1

    def _drain(self):
        self.filter_dirt = max(0, self.filter_dirt - self.BACKWASH_RATE)
        self._backwash_left -= 1

    def _step(self, distance, dirt):
        if self._backwash_left > 0:
            self._drain()
            return "backwashing"
        if self._recharge_left > 0:
            self._charge()
            return "recharging"
        self._move(distance)
        self._suck(dirt)
        if self.filter_dirt >= self.FILTER_LIMIT:
            self._backwash_left = self.BACKWASH_TURNS
            return "cleaning, backwash queued"
        if self._battery_low():
            self._recharge_left = self.RECHARGE_TURNS
            return "cleaning, recharge queued"
        return "cleaning"

    def clean(self, actions):
        for distance, dirt in self._validate(actions):
            mode = self._step(distance, dirt)
            self._history.append((mode, self.battery, self.filter_dirt))
        return self.battery, self.filter_dirt

    def report(self):
        lines = ["turn  mode                       battery  filter"]
        for turn, (mode, battery, dirt) in enumerate(self._history, 1):
            lines.append("{:4d}  {:<26}{:7d}{:8d}".format(turn, mode, battery, dirt))
        lines.append("resting depth: {}".format(self.depth))
        return "\n".join(lines)


def clean(actions):
    return PoolRobot().clean(actions)


if __name__ == "__main__":
    plan = [(5, 12), (3, 20), (8, 9), (2, 30), (4, 25), (6, 15),
            (7, 5), (-3, 18), (5, 10), (9, 22), (1, 4), (6, 8)]
    robot = PoolRobot(depth=2)
    battery, filter_dirt = robot.clean(plan)
    print(robot.report())
    print("final battery: {}, final filter: {}".format(battery, filter_dirt))
    print("stateless run:", clean(plan))

