import random

MAX_POSITION = 50
MAX_GRIP = 10.0


class ClawMachine:
    """Simulates the claw, its drop cycle and its fluctuating grip strength."""

    def __init__(self, payout_rate=0.75, seed=None):
        self._rng = random.Random(seed)
        self._payout = self._validate_rate(payout_rate)
        self._cache = {}
        self._grip = MAX_GRIP
        self.position = 0
        self.depth = 0
        self.attempts = 0
        self.retrieved = 0

    def _validate_rate(self, rate):
        if not isinstance(rate, (int, float)):
            raise TypeError("payout_rate must be numeric")
        if not 0.0 <= rate <= 1.0:
            raise ValueError("payout_rate must lie between 0 and 1")
        return float(rate)

    def _load(self, residue):
        """Build the weight of the item sitting on a given position class."""
        return round(2.0 * residue + self._rng.uniform(0.0, 0.5), 2)

    def _item_weight(self, position):
        residue = position % 5
        if residue not in self._cache:
            self._cache[residue] = self._load(residue)
        return self._cache[residue]

    def _fluctuate(self):
        ceiling = MAX_GRIP * self._payout
        self._grip = max(0.0, min(ceiling, self._grip + self._rng.uniform(-1.5, 1.5)))
        return self._grip

    def _decay(self):
        self._grip = max(0.0, self._grip - 0.2)

    def _normalize(self, inputs):
        commands = []
        for char in str(inputs).upper():
            if char in "LRD":
                commands.append(char)
            elif not char.isspace():
                raise ValueError("unknown command: %r" % char)
        return commands

    def move(self, step):
        self.position = max(0, min(MAX_POSITION, self.position + step))

    def drop(self):
        self.depth = MAX_POSITION // 5
        self.attempts += 1
        weight = self._item_weight(self.position)
        grabbed = self._fluctuate() >= weight
        self.depth = 0
        if grabbed:
            self.retrieved += 1
        self._decay()
        return grabbed

    def play(self, inputs):
        for command in self._normalize(inputs):
            if command == "L":
                self.move(-1)
            elif command == "R":
                self.move(1)
            else:
                self.drop()
        return self.retrieved

    def summary(self):
        return "pos=%d attempts=%d retrieved=%d grip=%.2f" % (
            self.position, self.attempts, self.retrieved, self._grip)


def play(inputs, payout_rate=0.75, seed=2026):
    return ClawMachine(payout_rate, seed).play(inputs)


def main():
    scripts = [("RRRD RRD LD", 0.95), ("RRRRRDDDD", 0.50), ("DDLLDRRRRD", 0.80)]
    for script, rate in scripts:
        machine = ClawMachine(rate, seed=7)
        total = machine.play(script)
        print("%-12s rate=%.2f -> %d item(s) | %s" % (script, rate, total, machine.summary()))
    print("default machine on 'RRRDDRRD' ->", play("RRRDDRRD"))


if __name__ == "__main__":
    main()

