MAX_POSITION = 50
MAX_GRIP = 10.0


class ClawMachine:
    """Simulates the claw, its drop cycle and its fluctuating grip strength."""

    def __init__(self, payout_rate=0.75, seed=None):
        self.rng = random.Random(seed)
        self.payout = self.validate_rate(payout_rate)
        self.cache = {}
        self.grip = MAX_GRIP
        self.position = 0
        self.depth = 0
        self.attempts = 0
        self.retrieved = 0

    def validate_rate(self, rate):
        if not isinstance(rate, (int, float)):
            raise TypeError("payout_rate must be numeric")
        if not 0.0 <= rate <= 1.0:
            raise ValueError("payout_rate must lie between 0 and 1")
        return float(rate)

    def load(self, residue):
        """Build the weight of the item sitting on a given position class."""
        return round(2.0 * residue + self.rng.uniform(0.0, 0.5), 2)

    def item_weight(self, position):
        residue = position % 5
        if residue not in self.cache:
            self.cache[residue] = self.load(residue)
        return self.cache[residue]

    def fluctuate(self):
        ceiling = MAX_GRIP * self.payout
        self.grip = max(0.0, min(ceiling, self.grip + self.rng.uniform(-1.5, 1.5)))
        return self.grip

    def decay(self):
        self.grip = max(0.0, self.grip - 0.2)

    def normalize(self, inputs):
        commands = []
        for char in str(inputs).upper():
            if char in "LRD":
                commands.append(char)
            elif not char.isspace():
                raise ValueError("unknown command: %r" % char)
        return commands

    def move(self, step):
        self.position = max(0, min(MAX_POSITION, self.position + step))

    def drop(self):
        self.depth = MAX_POSITION // 5
        self.attempts += 1
        weight = self.item_weight(self.position)
        grabbed = self.fluctuate() >= weight
        self.depth = 0
        if grabbed:
            self.retrieved += 1
        self.decay()
        return grabbed

    def play(self, inputs):
        for command in self.normalize(inputs):
            if command == "L":
                self.move(-1)
            elif command == "R":
                self.move(1)
            else:
                self.drop()
        return self.retrieved

    def summary(self):
        return "pos=%d attempts=%d retrieved=%d grip=%.2f" % (
            self.position, self.attempts, self.retrieved, self.grip)


def play(inputs, payout_rate=0.75, seed=2026):
    return ClawMachine(payout_rate, seed).play(inputs)


def main():
    scripts = [("RRRD RRD LD", 0.95), ("RRRRRDDDD", 0.50), ("DDLLDRRRRD", 0.80)]
    for script, rate in scripts:
        machine = ClawMachine(rate, seed=7)
        total = machine.play(script)
        print("%-12s rate=%.2f -> %d item(s) | %s" % (script, rate, total, machine.summary()))
    print("default machine on 'RRRDDRRD' ->", play("RRRDDRRD"))


if __name__ == "__main__":
    main()

