MAX_CAPACITY = 400
POSITIONS = 12
MOMENTUM_THRESHOLD = 900
BALANCE_STEPS = 3


class FerrisWheel:
    """A twelve gondola Ferris wheel that loads groups one position at a time."""

    def __init__(self, positions=POSITIONS):
        self._gondolas = [0] * positions
        self._bottom = 0
        self._momentum = 0
        self._skipped = []

    def load_groups(self, groups):
        for group in self._validate(groups):
            self._advance()
            self._load(group)
            self._momentum += self._imbalance()
            if self._momentum > MOMENTUM_THRESHOLD:
                self._balance()
        return list(self._gondolas)

    def report(self):
        lines = ["gondola weights (from boarding position):"]
        for offset, weight in enumerate(self._ordered()):
            lines.append("  +{0:<2} {1:>4} kg".format(offset, weight))
        lines.append("boarding position: {0}".format(self._bottom))
        lines.append("momentum: {0}".format(self._momentum))
        if self._skipped:
            lines.append("refused groups: " + ", ".join(str(w) for w in self._skipped))
        return "\n".join(lines)

    def _validate(self, groups):
        clean = []
        for group in groups:
            if isinstance(group, bool) or not isinstance(group, int):
                raise TypeError("group weights must be integers, got {0!r}".format(group))
            if group < 0:
                raise ValueError("group weight cannot be negative: {0}".format(group))
            clean.append(group)
        return clean

    def _advance(self, steps=1):
        self._bottom = (self._bottom + steps) % len(self._gondolas)

    def _load(self, group):
        if group > MAX_CAPACITY:
            self._skipped.append(group)
        else:
            self._gondolas[self._bottom] += group

    def _ordered(self):
        size = len(self._gondolas)
        return [self._gondolas[(self._bottom + i) % size] for i in range(size)]

    def _imbalance(self):
        ring = self._ordered()
        half = len(ring) // 2
        return abs(sum(ring[:half]) - sum(ring[half:]))

    def _balance(self):
        self._advance(BALANCE_STEPS)
        self._momentum = 0


def rotate(groups):
    return FerrisWheel().load_groups(groups)


def main():
    queue = [120, 340, 95, 410, 200, 60, 380, 150, 275, 90, 430, 310, 75, 220]
    wheel = FerrisWheel()
    print("final weights:", wheel.load_groups(queue))
    print(wheel.report())
    print("single pass:", rotate([100, 500, 200]))


if __name__ == "__main__":
    main()

