class ReceiptPrinter:
    """Mechanical model of a thermal receipt printer."""

    WIDTH = 24
    INK_PER_CHAR = 0.4
    HEAT_PER_CHAR = 1.5
    MAX_HEAT = 60.0
    MIN_INK = 15.0
    FULL_INK = 100.0
    RIBBON_ADVANCE_LINES = 3

    def __init__(self, paper_lines=120):
        self._paper = paper_lines
        self._ink = self.FULL_INK
        self._heat = 0.0
        self._output = []
        self._cache = {}

    def _validate(self, items):
        checked = []
        for entry in items:
            name, price = entry
            if not isinstance(name, str):
                raise TypeError("item name must be a string, got %r" % (name,))
            if not isinstance(price, int) or price < 0:
                raise ValueError("price must be a non-negative integer, got %r" % (price,))
            checked.append((name, price))
        return checked

    def _format(self, name, price):
        line = self._cache.get((name, price))
        if line is None:
            tag = "%d.%02d" % divmod(price, 100)
            room = self.WIDTH - len(tag) - 1
            line = name[:room].ljust(room + 1) + tag
            self._cache[(name, price)] = line
        return line

    def _feed(self, text):
        if self._paper <= 0:
            raise RuntimeError("paper roll exhausted")
        self._paper -= 1
        self._output.append(text)

    def _cool(self):
        self._heat = 0.0
        self._feed("")
        return 1

    def _load(self):
        self._ink = self.FULL_INK
        for _ in range(self.RIBBON_ADVANCE_LINES):
            self._feed("")
        return self.RIBBON_ADVANCE_LINES

    def _print_line(self, text):
        extra = 0
        if self._heat > self.MAX_HEAT:
            extra += self._cool()
        if self._ink < self.MIN_INK:
            extra += self._load()
        self._feed(text)
        self._ink -= self.INK_PER_CHAR * len(text)
        self._heat += self.HEAT_PER_CHAR * len(text)
        return extra + 1

    def run(self, items):
        blocks = [self._print_line("*** RECEIPT ***".center(self.WIDTH))]
        total = 0
        for name, price in self._validate(items):
            total += price
            blocks.append(self._print_line(self._format(name, price)))
        blocks.append(self._print_line(self._format("TOTAL", total)))
        return blocks

    def receipt(self):
        return list(self._output)

    def status(self):
        return "paper=%d lines  ink=%.1f%%  heat=%.1f" % (self._paper, self._ink, self._heat)


def transact(items):
    return ReceiptPrinter().run(items)


def main():
    basket = [("Espresso", 250), ("Espresso", 250), ("Croissant", 320),
              ("Orange Juice", 480), ("Blueberry Muffin", 295), ("Espresso", 250)]
    print("paper per block:", transact(basket))
    printer = ReceiptPrinter()
    print("total paper:", sum(printer.run(basket)))
    for line in printer.receipt():
        print("|" + line.ljust(ReceiptPrinter.WIDTH) + "|")
    print(printer.status())


if __name__ == "__main__":
    main()

