class AirHockeyTable:
    """Simulates the fan motor, plenum chamber and air filter of a table."""

    IDLE_RPM = 2400
    NOMINAL_MAX_RPM = 4200
    DEGRADED_MAX_RPM = 3400
    FILTER_THRESHOLD = 60.0
    IMPACT_THRESHOLD = 5
    RPM_PER_FORCE = 90
    WEAR_PER_FORCE = 0.8
    COOLDOWN_RPM = 150

    def __init__(self):
        self._rpm = self.IDLE_RPM
        self._filter = 100.0

    def _ceiling(self):
        """Maximum reachable fan speed for the current filter cleanliness."""
        if self._filter < self.FILTER_THRESHOLD:
            return self.DEGRADED_MAX_RPM
        return self.NOMINAL_MAX_RPM

    def _boost(self, force):
        self._rpm = min(self._rpm + self.RPM_PER_FORCE * force, self._ceiling())
        self._filter = max(0.0, self._filter - self.WEAR_PER_FORCE * force)

    def _cool(self):
        stabilized = max(self.IDLE_RPM, self._rpm - self.COOLDOWN_RPM)
        self._rpm = min(stabilized, self._ceiling())

    def _pressure(self):
        """Plenum pressure in kPa, throttled by the clogged filter."""
        return round(self._rpm * 0.0021 * (0.55 + self._filter / 200.0), 3)

    def _validate(self, events):
        if not isinstance(events, (list, tuple)):
            raise TypeError("events must be a list or tuple of impact forces")
        for force in events:
            if isinstance(force, bool) or not isinstance(force, int):
                raise TypeError("impact force must be an int, got %r" % (force,))
            if force < 0:
                raise ValueError("impact force cannot be negative: %d" % force)

    def step(self, force):
        if force > self.IMPACT_THRESHOLD:
            self._boost(force)
        else:
            self._cool()
        return self._pressure()

    def run(self, events):
        self._validate(events)
        return [self.step(force) for force in events]

    def report(self):
        return "fan %d rpm | filter %.1f%% | ceiling %d rpm | plenum %.3f kPa" % (
            self._rpm, self._filter, self._ceiling(), self._pressure())


def blow(events):
    """Return the plenum pressure recorded after each puck impact event."""
    return AirHockeyTable().run(events)


def main():
    table = AirHockeyTable()
    sessions = (
        ("warm-up", [0, 0, 3, 0, 2]),
        ("rally", [9, 12, 8, 0, 14, 11, 0, 0, 7]),
        ("slam-fest", [20] * 12),
    )
    for name, events in sessions:
        readings = table.run(events)
        print("%-10s %s" % (name, readings))
        print("%-10s %s" % ("", table.report()))


if __name__ == "__main__":
    main()

