class BungeePlatform:
    """Tracks cord elasticity, micro tears and elongation across successive jumps."""

    ABSOLUTE_MAX_STRETCH = 62.0
    TEAR_SAFETY_LIMIT = 40

    def __init__(self, cord_length=30.0, elasticity=1.0):
        self.cord_length = cord_length
        self.elasticity = elasticity
        self.tears = 0
        self.elongation = cord_length
        self.total_rebounds = 0
        self.rejected = []
        self._cache = {}
        self._config = self._load()

    def _load(self):
        return {
            "reference_weight": 75.0,
            "stretch_factor": 0.95,
            "tear_divisor": 12.0,
            "damping": 0.62,
            "min_amplitude": 0.05,
        }

    def _stretch_key(self, weight):
        return (round(weight, 3), round(self.elasticity, 6))

    def _max_elongation(self, weight):
        key = self._stretch_key(weight)
        if key not in self._cache:
            cfg = self._config
            ratio = weight / cfg["reference_weight"]
            span = self.cord_length * cfg["stretch_factor"] * ratio / self.elasticity
            self._cache[key] = self.cord_length + span
        return self._cache[key]

    def _rebound(self, peak):
        amplitude = peak - self.cord_length
        cycles = 0
        while amplitude > self._config["min_amplitude"]:
            amplitude *= self._config["damping"]
            cycles += 1
        self.elongation = self.cord_length + amplitude
        return cycles

    def _accumulate_tears(self, weight):
        self.tears += max(1, int(weight / self._config["tear_divisor"]))
        if self.tears >= self.TEAR_SAFETY_LIMIT:
            self._degrade()

    def _degrade(self):
        self.elasticity = round(self.elasticity * 0.95, 6)
        self.tears -= self.TEAR_SAFETY_LIMIT
        self._cache.clear()

    def single_jump(self, weight):
        if weight <= 0:
            raise ValueError("jumper weight must be positive: %r" % (weight,))
        peak = self._max_elongation(weight)
        if peak > self.ABSOLUTE_MAX_STRETCH:
            self.rejected.append((weight, round(peak, 2)))
            return None
        self.total_rebounds += self._rebound(peak)
        self._accumulate_tears(weight)
        return round(peak, 2)

    def report(self):
        return ("elasticity=%.4f tears=%d elongation=%.2fm rebounds=%d rejected=%d"
                % (self.elasticity, self.tears, self.elongation,
                   self.total_rebounds, len(self.rejected)))


PLATFORM = BungeePlatform()


def jump(weights):
    return [e for e in (PLATFORM.single_jump(w) for w in weights) if e is not None]


if __name__ == "__main__":
    print(jump([60, 75, 75, 90, 110, 75, 140, 200, 68]))
    print(PLATFORM.report())
    for weight, peak in PLATFORM.rejected:
        print("rejected %.0fkg (would stretch to %.2fm)" % (weight, peak))

