_BASE_RPM_TABLE = {0.25: 1000, 0.50: 1400, 0.75: 1800, 1.00: 2200}


class SnowblowerController:
    """Tracks chute angle, impeller speed and snow intake of a robotic snowblower."""

    _MAX_IMPELLER_RPM = 3600
    _CLOG_CYCLES = 3
    _INTAKE_RATE = 0.60

    def __init__(self):
        self._chute_angle = 0.0
        self._impeller_rpm = 0
        self._cleared_volume = 0.0
        self._clog_timer = 0
        self._cache = {}
        self._profile = self._load()

    def _load(self):
        return sorted(_BASE_RPM_TABLE.items())

    @staticmethod
    def _validate(density, wind_direction):
        if not 0.0 < density <= 1.0:
            raise ValueError("snow density must lie in (0.0, 1.0]")
        if not 0.0 <= wind_direction < 360.0:
            raise ValueError("wind direction must lie in [0.0, 360.0)")

    def _required_rpm(self, density):
        key = round(density, 2)
        if key not in self._cache:
            base = self._profile[-1][1]
            for upper, rpm in self._profile:
                if key <= upper:
                    base = rpm
                    break
            self._cache[key] = int(base * (1.0 + key))
        return self._cache[key]

    def _aim_chute(self, wind_direction):
        self._chute_angle = (wind_direction + 180.0) % 360.0

    def _start_clearing(self):
        self._clog_timer = self._CLOG_CYCLES
        self._impeller_rpm = 0

    def _servicing(self):
        if self._clog_timer > 0:
            self._clog_timer -= 1
            return True
        return False

    def _ingest(self, density):
        volume = self._INTAKE_RATE * (1.0 - 0.35 * density)
        self._cleared_volume += volume
        return volume

    def cycle(self, density, wind_direction):
        self._validate(density, wind_direction)
        if self._servicing():
            return 0.0
        self._aim_chute(wind_direction)
        needed = self._required_rpm(density)
        if needed > self._MAX_IMPELLER_RPM:
            self._start_clearing()
            return 0.0
        self._impeller_rpm = needed
        return self._ingest(density)

    def status(self):
        return {"chute": round(self._chute_angle, 1), "rpm": self._impeller_rpm,
                "clearing": self._clog_timer, "total": round(self._cleared_volume, 3)}

    @property
    def total_cleared(self):
        return self._cleared_volume


def clear(conditions):
    blower = SnowblowerController()
    for density, wind_direction in conditions:
