class SewingMachine:
    """Tracks upper thread tension, bobbin supply and needle sharpness."""

    TENSION_LIMIT = 100.0
    BOBBIN_CAPACITY = 220.0

    def __init__(self, spool=4000.0):
        self.spool = spool
        self.stitches_made = 0
        self.rethreads = 0
        self.windings = 0
        self._bobbin = self.BOBBIN_CAPACITY
        self._dullness = 0.0
        self._cache = {}

    def _validate(self, thickness):
        if not isinstance(thickness, int):
            raise TypeError("fabric thickness must be an integer: %r" % (thickness,))
        if thickness < 0:
            raise ValueError("fabric thickness cannot be negative: %d" % thickness)
        return thickness

    def _tension(self, thickness):
        key = (thickness, round(self._dullness, 1))
        if key not in self._cache:
            self._cache[key] = 8.0 + 6.0 * thickness + 0.8 * thickness * self._dullness
        return self._cache[key]

    def _load(self):
        amount = min(self.BOBBIN_CAPACITY, self.spool)
        self.spool -= amount
        self._bobbin = amount
        self.windings += 1

    def _rethread(self):
        self.rethreads += 1
        self._dullness = 0.0

    def _consume(self, thickness):
        self._bobbin -= 1.0 + 0.4 * thickness

    def _wear(self, thickness):
        self._dullness += 0.05 * thickness

    def _step(self, thickness):
        if self._bobbin <= 0.0:
            self._load()
            return 5
        if self._tension(thickness) > self.TENSION_LIMIT:
            self._rethread()
            return 2
        self._consume(thickness)
        self._wear(thickness)
        self.stitches_made += 1
        return 0

    def run(self, stitches):
        index = 0
        while index < len(stitches):
            skipped = self._step(self._validate(stitches[index]))
            index += 1 + skipped
        return self.stitches_made

    def report(self):
        return ("stitches=%d rethreads=%d windings=%d bobbin=%.1f spool=%.1f dullness=%.2f"
                % (self.stitches_made, self.rethreads, self.windings,
                   self._bobbin, self.spool, self._dullness))


def sew(stitches):
    return SewingMachine().run(stitches)


def main():
    batches = {
        "light hem": [1] * 40,
        "denim seam": [4, 5, 6, 7, 8] * 12,
        "mixed load": [2, 9, 3, 12, 1, 6, 14, 2, 5, 11] * 8,
    }
    for name, batch in batches.items():
        machine = SewingMachine()
        total = machine.run(batch)
        print("%-12s -> %3d successful stitches | %s" % (name, total, machine.report()))
    print("quick call: sew([3, 3, 15, 3]) =", sew([3, 3, 15, 3]))


if __name__ == "__main__":
    main()

