class ChainsawGovernor:
    """Closed-loop governor for a two-stroke chainsaw engine."""

    TARGET_RPM = 9000.0
    MAX_RPM = 13500.0
    STALL_RPM = 2500.0
    OIL_CAPACITY = 100.0
    RESTART_CYCLES = 4

    def __init__(self):
        self._rpm = self.TARGET_RPM
        self._throttle = 0.5
        self._oil = self.OIL_CAPACITY
        self._restart_left = 0

    def _adjust_throttle(self, load):
        error = (self.TARGET_RPM - self._rpm) / self.TARGET_RPM
        demand = self._throttle + 0.8 * error + 0.02 * load
        self._throttle = min(1.0, max(0.15, demand))

    def _burn_oil(self):
        used = 0.4 + 2.6 * self._throttle ** 2
        self._oil = max(0.0, self._oil - used)

    def _friction(self):
        return 3000.0 if self._oil <= 0.0 else 0.0

    def _spin(self, load):
        gain = (self._throttle * self.MAX_RPM - self._rpm) * 0.45
        drag = 400.0 * load + self._friction()
        self._rpm = max(0.0, self._rpm + gain - drag)

    def _begin_restart(self):
        self._restart_left = self.RESTART_CYCLES
        self._rpm = 0.0
        self._throttle = 0.15

    def _tick_restart(self):
        self._restart_left -= 1
        if self._restart_left == 0:
            self._rpm = self.TARGET_RPM * 0.7
            self._throttle = 0.4

    def _depth(self, load):
        speed = max(0.0, (self._rpm - 3000.0) / 6000.0)
        return round(speed * 2.0 / (1.0 + load / 5.0), 3)

    def step(self, load):
        if self._restart_left > 0:
            self._tick_restart()
            return 0.0
        self._adjust_throttle(load)
        self._burn_oil()
        self._spin(load)
        if self._rpm < self.STALL_RPM:
            self._begin_restart()
            return 0.0
        return self._depth(load)

    def run(self, loads):
        return [self.step(load) for load in loads]

    def status(self):
        return {"rpm": round(self._rpm, 1), "oil": round(self._oil, 1),
                "throttle": round(self._throttle, 2)}


def validated(loads):
    clean = []
    for value in loads:
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("wood resistance values must be numbers")
        if value < 0:
            raise ValueError("wood resistance cannot be negative")
        clean.append(float(value))
    return clean


def cut(loads):
    return ChainsawGovernor().run(validated(loads))


def summarize(loads):
    clean = validated(loads)
    governor = ChainsawGovernor()
    depths = governor.run(clean)
    idle = sum(1 for d in depths if d == 0.0)
    report = ["cycle %2d: load %5.1f -> depth %.3f" % (i + 1, clean[i], depths[i])
              for i in range(len(depths))]
    report.append("total depth %.3f over %d cycles (%d idle)"
                  % (sum(depths), len(depths), idle))
    report.append("final state: %s" % governor.status())
    return depths, "\n".join(report)


if __name__ == "__main__":
    sample = [2, 3, 8, 12, 14, 14, 5, 4, 4, 6, 9, 11, 13, 13, 13, 2, 2, 3, 3, 3]
    print(summarize(sample)[1])

