class SafetyBlockSystem:
    """Tracks brake pad wear, pneumatic pressure and downstream block occupancy."""

    MAX_PRESSURE = 100.0
    PAD_NEW = 12.0
    SAFE_EXIT_SPEED = 12.0

    def __init__(self):
        self._pressure = self.MAX_PRESSURE
        self._pad = self.PAD_NEW
        self._occupied_until = 0
        self._fault = False
        self._log = []

    def _efficiency(self):
        return max(0.15, self._pad / self.PAD_NEW)

    def _refill(self):
        self._pressure = min(self.MAX_PRESSURE, self._pressure + 9.0)

    def _required_pressure(self, speed):
        return 5.0 + speed * 1.8

    def _wear_pads(self, speed):
        self._pad = max(0.0, self._pad - speed * 0.02)

    def _reserve_downstream(self, index, exit_speed):
        self._occupied_until = index + (2 if exit_speed == 0.0 else 1)

    def admit(self, index, speed):
        if self._fault:
            raise RuntimeError("block system is in emergency fault state")
        self._refill()
        if index >= self._occupied_until:
            self._reserve_downstream(index, speed)
            self._log.append("train %d: clear block, rolls through at %.2f" % (index, speed))
            return speed
        needed = self._required_pressure(speed)
        available = self._pressure * self._efficiency()
        self._wear_pads(speed)
        if available >= needed:
            self._pressure -= needed
            exit_speed = 0.0
            note = "held at brake run (%.1f kPa used)" % needed
        else:
            exit_speed = round(speed * (1.0 - available / needed), 2)
            self._pressure = 0.0
            note = "insufficient pressure, only %.1f kPa of %.1f kPa" % (available, needed)
        if exit_speed > self.SAFE_EXIT_SPEED:
            self._fault = True
            note += " -> EMERGENCY FAULT"
        self._reserve_downstream(index, exit_speed)
        self._log.append("train %d: blocked at %.2f, exits at %.2f; %s; pad %.2f mm"
                         % (index, speed, exit_speed, note, self._pad))
        return exit_speed

    def faulted(self):
        return self._fault

    def report(self):
        tail = "FAULT: operations halted" if self._fault else "status: operating normally"
        return "\n".join(self._log + [tail])


def brake(trains, system=None):
    speeds = []
    for entry in trains:
        if not isinstance(entry, (int, float)) or isinstance(entry, bool) or entry < 0:
            raise ValueError("train speeds must be non-negative numbers, got %r" % (entry,))
        speeds.append(float(entry))
    system = system or SafetyBlockSystem()
    exits = []
    for index, speed in enumerate(speeds):
        exits.append(system.admit(index, speed))
        if system.faulted():
            break
    return exits


def main():
    system = SafetyBlockSystem()
    print(brake([30, 45, 50, 62, 70, 55], system))
    print(system.report())


if __name__ == "__main__":
    main()

