import random


class MechanicalBull:
    """Hydraulic bull whose pitch, yaw and fluid temperature evolve each second."""

    MAX_PITCH = 60.0
    MAX_YAW = 100.0
    OVERHEAT_AT = 95.0
    COOLED_AT = 70.0
    RIDE_LIMIT = 300

    def __init__(self):
        self._rng = random.Random()
        self._pitch = 0.0
        self._yaw = 0.0
        self._temp = 20.0
        self._overheated = False

    @staticmethod
    def _clamp(value, high):
        return max(0.0, min(high, value))

    def _heat(self, skill):
        self._temp += 0.35 + 0.05 * skill
        if self._temp >= self.OVERHEAT_AT:
            self._overheated = True

    def _cool(self):
        self._temp -= 1.4
        if self._temp <= self.COOLED_AT:
            self._overheated = False

    def _reset_motion(self):
        self._pitch = 0.0
        self._yaw = self._rng.uniform(0.0, 10.0)

    def _step(self, skill):
        previous_pitch = self._pitch
        if self._overheated:
            self._pitch = self._clamp(self._pitch + self._rng.uniform(-4.0, 1.0), 0.4 * self.MAX_PITCH)
            self._yaw = self._clamp(self._yaw + self._rng.uniform(-7.0, 2.0), 0.4 * self.MAX_YAW)
            self._cool()
        else:
            self._pitch = self._clamp(self._pitch + self._rng.uniform(-9.0, 12.0), self.MAX_PITCH)
            self._yaw = self._clamp(self._yaw + self._rng.uniform(-4.0, 14.0), self.MAX_YAW)
            self._heat(skill)
        return previous_pitch - self._pitch

    def _is_throw(self, pitch_drop, skill):
        if pitch_drop < 12.0 or self._yaw < 0.95 * self.MAX_YAW:
            return False
        return self._rng.random() > min(0.85, skill / 12.0)

    def fluid_temperature(self):
        return round(self._temp, 1)

    def ride(self, skill):
        self._reset_motion()
        for second in range(1, self.RIDE_LIMIT + 1):
            pitch_drop = self._step(skill)
            if self._is_throw(pitch_drop, skill):
                return second
        return self.RIDE_LIMIT


def buck(riders):
    if not isinstance(riders, (list, tuple)):
        raise TypeError("riders must be a list of integer skill levels")
    for skill in riders:
        if not isinstance(skill, int) or isinstance(skill, bool):
            raise TypeError("skill levels must be integers")
        if skill < 0:
            raise ValueError("skill levels must be non-negative")
    bull = MechanicalBull()
    return [bull.ride(skill) for skill in riders]


def format_report(riders, durations):
    lines = ["skill  seconds"]
    for skill, seconds in zip(riders, durations):
        lines.append("{:>5}  {:>7}".format(skill, seconds))
    return "\n".join(lines)


if __name__ == "__main__":
