class DynamoHub:
    """Models the generator, voltage regulator and buffer capacitor of a dynamo hub."""

    CUT_IN_SPEED = 5.0
    OVERHEAT_SPEED = 45.0
    HEAT_LIMIT = 30.0
    CAPACITY = 100.0
    DISCHARGE_RATE = 12.0
    COOLDOWN_SEGMENTS = 3

    def __init__(self):
        self._charge = 0.0
        self._heat = 0.0
        self._cooldown = 0

    def _update_regulator(self, speed):
        """Heat up or cool down the regulator; return True if the bulb blows."""
        if speed > self.OVERHEAT_SPEED:
            self._heat += speed - self.OVERHEAT_SPEED
        else:
            self._heat = max(0.0, self._heat - 5.0)
        if self._heat > self.HEAT_LIMIT:
            self._heat = 0.0
            self._cooldown = self.COOLDOWN_SEGMENTS
            return True
        return False

    def _charge_capacitor(self, output):
        self._charge = min(self.CAPACITY, self._charge + output * 0.05)

    def _discharge_capacitor(self):
        draw = min(self._charge, self.DISCHARGE_RATE)
        self._charge -= draw
        return draw

    def step(self, speed):
        """Advance the simulation by one speed segment and return the brightness (0-100)."""
        if self._cooldown > 0:
            self._cooldown -= 1
            self._heat = max(0.0, self._heat - 10.0)
            return 0
        if self._update_regulator(speed):
            return 0
        if speed >= self.CUT_IN_SPEED:
            output = min(100.0, (speed - self.CUT_IN_SPEED) * 6.0)
            self._charge_capacitor(output)
            return int(round(output))
        draw = self._discharge_capacitor()
        return int(round(draw / self.DISCHARGE_RATE * 40.0))

    def capacitor_level(self):
        return round(self._charge, 1)

    def ride(self, speeds):
        """Validate and run a whole ride, returning one brightness per segment."""
        levels = []
        for speed in speeds:
            if isinstance(speed, bool) or not isinstance(speed, (int, float)):
                raise TypeError("speeds must contain numbers, got %r" % (speed,))
            if speed < 0:
                raise ValueError("speed cannot be negative: %r" % (speed,))
            levels.append(self.step(float(speed)))
        return levels


def pedal(speeds):
    """Return the brightness level of the lamp for every speed (km/h) in speeds."""
    return DynamoHub().ride(speeds)


def describe(level):
    if level == 0:
        return "dark"
    if level < 40:
        return "dim"
    if level < 80:
        return "bright"
    return "full"


def main():
    ride = [0, 4, 12, 22, 30, 0, 0, 0, 0, 0, 0, 0, 0, 50, 52, 20, 18, 25]
    hub = DynamoHub()
    levels = hub.ride(ride)
    for speed, level in zip(ride, levels):
        print("%5.1f km/h -> %3d%% (%s)" % (speed, level, describe(level)))
    print("capacitor left: %.1f units, average brightness: %.1f%%"
          % (hub.capacitor_level(), sum(levels) / len(levels)))


if __name__ == "__main__":
    main()

