MAX_EXTENSION = 12.0


class PrimaryMirrorActuators:
    """Simulates a 50-element primary mirror actuator array."""

    COUNT = 50

    def __init__(self, calibration_offset=0.05, baseline_temperature=20.0):
        self._extensions = [0.0] * self.COUNT
        self._coefficients = [1.0e-3 * (1.0 + (i % 7) * 0.05) for i in range(self.COUNT)]
        self._offset = calibration_offset
        self._baseline = baseline_temperature
        self._limit_exceeded = False
        self._factor_cache = {}

    def _thermal_factor(self, temperature):
        key = round(temperature, 3)
        if key not in self._factor_cache:
            drift = key - 20.0
            self._factor_cache[key] = 1.0 + 0.002 * drift - 0.00005 * drift * drift
        return self._factor_cache[key]

    def _update_baseline(self, temperature_change):
        self._baseline += temperature_change
        return self._baseline

    def _required_adjustment(self, index, tilt_error):
        half = (self.COUNT - 1) / 2.0
        lever = (index - half) / half
        return -tilt_error * lever * 0.5 + self._offset

    def _apply(self, temperature_change, tilt_error):
        temperature = self._update_baseline(temperature_change)
        factor = self._thermal_factor(temperature)
        for index in range(self.COUNT):
            adjustment = self._required_adjustment(index, tilt_error)
            thermal = self._coefficients[index] * (temperature - 20.0)
            self._extensions[index] += (adjustment + thermal) * factor

    def _check_limits(self):
        for extension in self._extensions:
            if abs(extension) > MAX_EXTENSION:
                self._limit_exceeded = True
                return True
        return False

    def _safety_retraction(self):
        for index in range(self.COUNT):
            self._extensions[index] *= 0.25
        self._offset *= 0.5

    def step(self, temperature_change, tilt_error):
        self._apply(temperature_change, tilt_error)
        if self._check_limits():
            self._safety_retraction()
        return sum(self._extensions) / self.COUNT

    @property
    def faulted(self):
        return self._limit_exceeded


def align(readings):
    array = PrimaryMirrorActuators()
    positions = []
    for reading in readings:
        temperature_change, tilt_error = reading
        positions.append(array.step(float(temperature_change), float(tilt_error)))
    return positions


def parse_readings(text):
    readings = []
    for line in text.splitlines():
        parts = line.replace(",", " ").split()
        if len(parts) == 2:
            readings.append((float(parts[0]), float(parts[1])))
    return readings


if __name__ == "__main__":
    import sys

    for number, position in enumerate(align(parse_readings(sys.stdin.read())), 1):
        print("reading {:>3}: mean extension = {:+.6f} um".format(number, position))

