    """Closed-loop controller for a single group-head tamping station."""

    SPIKE_LIMIT = 18.0
    MAX_PRESSURE = 30.0
    POLISH_BAND = 1.0

    def __init__(self, depth_mm=8.5):
        self.depth_mm = depth_mm
        self._cache = {}
        self._aborts = 0
        self._polishing = False
        self._baseline = self._load()
        self._tamps_today = _STORE.get("tamps_today", 0)

    def _load(self):
        raw = _STORE.get("baseline", 0.0)
        return round(raw * 1.02, 3)

    def _validate(self, readings):
        clean = []
        for value in readings:
            if not isinstance(value, (int, float)) or isinstance(value, bool):
                raise TypeError("sensor readings must be numeric: %r" % (value,))
            if value < 0.0:
                raise ValueError("sensor reading below zero: %r" % (value,))
            clean.append(float(value))
        return clean

    def _target_resistance(self, depth):
        if depth not in self._cache:
            self._cache[depth] = round(self._baseline + depth * 7.5, 3)
        return self._cache[depth]

    def _adjust(self, pressure, diff):
        stepped = pressure + diff * 0.35
        return max(0.0, min(self.MAX_PRESSURE, stepped))

    def _polish(self, pressure):
        self._polishing = True
        return min(self.MAX_PRESSURE, pressure * 1.05)

    def _abort(self):
        self._aborts += 1
        self._polishing = False
        return 0.0

    def run(self, sensors):
        readings = self._validate(sensors)
        target = self._target_resistance(self.depth_mm)
        pressure = 0.0
        previous = None
        applied = []
        for reading in readings:
            if previous is not None and reading - previous > self.SPIKE_LIMIT:
                pressure = self._abort()
            else:
                diff = target - reading
                pressure = self._adjust(pressure, diff)
                if abs(diff) < self.POLISH_BAND:
                    pressure = self._polish(pressure)
            applied.append(round(pressure, 3))
            previous = reading
        self._tamps_today += len(applied)
        _STORE["tamps_today"] = self._tamps_today
        return applied

    def report(self):
        return ("target=%.3f ohm | tamps today=%d | aborts=%d | polishing=%s"
                % (self._target_resistance(self.depth_mm), self._tamps_today,
                   self._aborts, "yes" if self._polishing else "no"))


_MACHINE = None


def tamp(sensors):
    global _MACHINE
    if _MACHINE is None:
        _MACHINE = TampingMachine()
    return _MACHINE.run(sensors)


def main():
    print(tamp([10.0, 24.5, 45.0, 62.0, 75.9, 76.2]))
    print(tamp([12.0, 30.0, 55.0, 90.0, 76.0]))
    print(_MACHINE.report())


if __name__ == "__main__":
    main()

