UV_THRESHOLD = 0.55
HOPPER_CAPACITY = 12
SIZE_TOLERANCE = 1.5


class BanknoteCounter:
    """Logic controller for a high-speed banknote counter."""

    def __init__(self, hopper_capacity=HOPPER_CAPACITY, uv_threshold=UV_THRESHOLD):
        self._specs = self._load()
        self._cache = {}
        self._bins = {denom: 0 for _, denom in self._specs}
        self._hopper = 0
        self._capacity = hopper_capacity
        self._threshold = uv_threshold
        self._suspects = 0
        self._jams = 0
        self._jammed = False
        self.reject_tray = []
        self.accepted = []

    def _load(self):
        return [(120.0, 5), (127.0, 10), (134.0, 20), (141.0, 50), (148.0, 100)]

    def _parse(self, note):
        if isinstance(note, dict):
            return float(note["length"]), float(note["uv"])
        length, uv = note
        return float(length), float(uv)

    def _identify(self, length):
        key = round(length, 1)
        if key not in self._cache:
            match = None
            for spec_length, denom in self._specs:
                if abs(spec_length - length) <= SIZE_TOLERANCE:
                    match = denom
                    break
            self._cache[key] = match
        return self._cache[key]

    def _divert(self, note, reason):
        self.reject_tray.append((note, reason))

    def _empty_hopper(self):
        self._hopper = 0

    def _clear_jam(self):
        self._jams += 1
        self._jammed = False

    def process(self, note):
        length, uv = self._parse(note)
        denom = self._identify(length)
        if denom is None:
            self._jammed = True
            self._divert(note, "unrecognised size")
            self._clear_jam()
            return None
        if uv < self._threshold:
            self._suspects += 1
            self._divert(note, "counterfeit suspect")
            return None
        if self._hopper >= self._capacity:
            self._divert(note, "hopper full")
            self._empty_hopper()
            return None
        self._bins[denom] += 1
        self._hopper += 1
        self.accepted.append(denom)
        return denom

    def run(self, notes):
        for note in notes:
            self.process(note)
        return list(self.accepted)

    def report(self):
        counts = ", ".join("%d:%d" % (d, self._bins[d]) for d in sorted(self._bins))
        total = sum(d * n for d, n in self._bins.items())
        return "bins[%s] total=%d suspects=%d jams=%d rejected=%d" % (
            counts, total, self._suspects, self._jams, len(self.reject_tray))


def sort(notes):
    return BanknoteCounter().run(notes)


def main():
    batch = [(120.2, 0.81), (148.0, 0.30), (133.6, 0.72), (99.0, 0.90),
             {"length": 141.4, "uv": 0.64}, (127.0, 0.58), (148.1, 0.77)]
    machine = BanknoteCounter()
    print("accepted:", machine.run(batch))
    print(machine.report())


if __name__ == "__main__":
    main()

