TANK_CAPACITY = 800.0
RESERVE_LITRES = 40.0
HOT_TARGET_C = 60.0
TICK_SECONDS = 60.0


class IceResurfacer:
    """Simulates the water, blade and travel systems of a rink resurfacer."""

    def __init__(self, tank_litres=TANK_CAPACITY):
        self.water = float(tank_litres)
        self.depth = 0.0
        self.wash_temp = HOT_TARGET_C
        self.distance = 0.0
        self._cache = {}

    def run(self, actions):
        readings = []
        for speed, ice_temp in self._normalize(actions):
            readings.append(self.step(speed, ice_temp))
        return readings

    def _normalize(self, actions):
        pairs = []
        for index, action in enumerate(actions):
            try:
                speed, ice_temp = action
            except (TypeError, ValueError):
                raise ValueError("action %d must be a (speed, ice_temp) pair" % index)
            speed = float(speed)
            if speed < 0.0:
                raise ValueError("action %d has a negative speed" % index)
            pairs.append((speed, float(ice_temp)))
        return pairs

    def step(self, speed, ice_temp):
        travelled = speed * TICK_SECONDS
        depth = self._depth_for_temp(ice_temp)
        needed = self._flow_rate(depth) * travelled
        dispensed = self._draw(needed)
        if dispensed < needed - 1e-9:
            depth = 0.0
        self._update_wash_temp(dispensed, ice_temp)
        self.depth = depth
        self.distance += travelled
        return (round(self.water, 2), round(self.depth, 3))

    def _depth_for_temp(self, ice_temp):
        key = round(ice_temp, 1)
        if key not in self._cache:
            self._cache[key] = self._compute_depth(key)
        return self._cache[key]

    def _compute_depth(self, ice_temp):
        raw = 0.55 + (ice_temp + 6.0) * 0.09
        return max(0.3, min(1.6, round(raw, 3)))

    def _flow_rate(self, depth):
        return 0.0006 + 0.0009 * depth

    def _draw(self, litres):
        available = max(0.0, self.water - RESERVE_LITRES)
        taken = min(litres, available)
        self.water -= taken
        return taken

    def _update_wash_temp(self, litres, ice_temp):
        cooled = self.wash_temp - 0.004 * litres * (self.wash_temp - ice_temp)
        self.wash_temp = round(cooled + (HOT_TARGET_C - cooled) * 0.15, 2)


def resurface(actions):
    return IceResurfacer().run(actions)


def format_log(rows):
    lines = ["pass  water(L)  blade(mm)"]
    for number, (water, depth) in enumerate(rows, start=1):
        lines.append("%4d  %8.2f  %9.3f" % (number, water, depth))
    if rows:
        lines.append("used: %.2f L" % (TANK_CAPACITY - rows[-1][0]))
    return "\n".join(lines)


def main():
    plan = [(4.0, -5.5)] * 4 + [(6.0, -3.0)] * 6 + [(5.0, -8.0)] * 8
    print(format_log(resurface(plan)))


if __name__ == "__main__":
    main()

