class CentrifugalPeeler:
    """A centrifugal drum peeler with abrasive lining, water jets and a waste bin."""

    MAX_WASTE_KG = 40.0
    MIN_LINING_PCT = 15.0

    def __init__(self, drum_capacity=25.0):
        self.drum_capacity = float(drum_capacity)
        self._speed = 0.0
        self._lining = 100.0
        self._waste = 0.0
        self._water_used = 0.0
        self._services = 0

    def _normalise(self, batch):
        if isinstance(batch, dict):
            weight, minutes = batch["weight"], batch.get("minutes", 1.0)
        else:
            weight, minutes = batch
        weight, minutes = float(weight), float(minutes)
        if weight <= 0.0 or minutes <= 0.0:
            raise ValueError("batch weight and processing time must be positive")
        return min(weight, self.drum_capacity), minutes

    def _target_speed(self, weight):
        load = weight / self.drum_capacity
        return 1450.0 - 500.0 * load

    def _water_flow(self, weight):
        return 1.8 * weight + 0.25 * (self._speed / 100.0)

    def _abrade(self, weight, minutes):
        wear = 0.045 * weight * minutes * (self._speed / 1000.0)
        self._lining = max(0.0, self._lining - wear)

    def _collect_waste(self, weight):
        smoothness = (100.0 - self._lining) / 400.0
        self._waste += weight * 0.14 * (1.0 + smoothness)

    def _needs_service(self):
        return self._waste >= self.MAX_WASTE_KG or self._lining <= self.MIN_LINING_PCT

    def _service(self):
        self._waste = 0.0
        if self._lining <= self.MIN_LINING_PCT:
            self._lining = 100.0
        self._services += 1

    def run_batch(self, batch):
        weight, minutes = self._normalise(batch)
        self._speed = self._target_speed(weight)
        self._water_used += self._water_flow(weight) * minutes
        self._abrade(weight, minutes)
        self._collect_waste(weight)
        if self._needs_service():
            self._service()
        return [round(self._water_used, 2), round(100.0 - self._lining, 2)]

    def summary(self):
        return {
            "water_litres": round(self._water_used, 2),
            "waste_kg": round(self._waste, 2),
            "maintenance_cycles": self._services,
        }


def peel(batches):
    machine = CentrifugalPeeler()
    return [machine.run_batch(batch) for batch in batches]


def report(batches):
    machine = CentrifugalPeeler()
    lines = []
    for index, batch in enumerate(batches, start=1):
        water, wear = machine.run_batch(batch)
        lines.append("batch {0}: water={1} L, wear={2} %".format(index, water, wear))
    info = machine.summary()
    lines.append("maintenance cycles: {0}".format(info["maintenance_cycles"]))
    lines.append("waste in bin: {0} kg".format(info["waste_kg"]))
    return "\n".join(lines)


if __name__ == "__main__":
    load = [(12.0, 3.0), (25.0, 4.5), {"weight": 30.0, "minutes": 6.0}, (8.5, 2.0)]
    print(peel(load))
    print(report(load))

