class MaglevJunction:
    """Control logic for a single magnetic levitation track junction."""

    HEAVY_LOAD = 80.0
    RESERVE_MAX = 100.0
    MOVE_COST = 7.5
    MIN_POWER = 20.0
    HEAT_PER_MOVE = 12.0
    TEMP_LIMIT = 60.0
    IDLE_TEMP = 20.0
    MAINTENANCE_INTERVAL = 10

    def __init__(self):
        self._position = "MAIN"
        self._locked = True
        self._temperature = self.IDLE_TEMP
        self._moves = 0
        self._power = self.RESERVE_MAX
        self._log = []

    def _required_position(self, weight):
        return "SIDING" if weight >= self.HEAVY_LOAD else "MAIN"

    def _recharge(self):
        self._power = self.RESERVE_MAX
        self._log.append("power reserve replenished from the trackside supply")

    def _unlock(self):
        if self._power < self.MIN_POWER:
            self._recharge()
        self._locked = False

    def _engage_lock(self):
        self._locked = True

    def _cool_down(self):
        self._temperature = self.IDLE_TEMP
        self._log.append("cooling sequence complete")

    def _check_maintenance(self):
        if self._moves % self.MAINTENANCE_INTERVAL == 0:
            self._log.append("maintenance required after %d moves" % self._moves)

    def _move_to(self, target):
        self._position = target
        self._power = max(0.0, self._power - self.MOVE_COST)
        self._temperature += self.HEAT_PER_MOVE
        self._moves += 1
        if self._temperature > self.TEMP_LIMIT:
            self._cool_down()
        self._check_maintenance()

    def admit(self, weight):
        target = self._required_position(weight)
        if target != self._position:
            self._unlock()
            self._move_to(target)
            self._engage_lock()
        return round(self._power, 2)

    def report(self):
        return list(self._log)


def route(trains):
    junction = MaglevJunction()
    levels = []
    for weight in trains:
        if isinstance(weight, bool) or not isinstance(weight, (int, float)):
            raise ValueError("train weight must be a number, got %r" % (weight,))
        if weight <= 0:
            raise ValueError("train weight must be positive, got %r" % (weight,))
        levels.append(junction.admit(float(weight)))
    for entry in junction.report():
        print("[junction] " + entry)
    return levels


if __name__ == "__main__":
    approaching = [40, 95, 30, 120, 60, 88, 91, 25, 140, 12, 99, 45, 130, 20]
    reserves = route(approaching)
    for train_weight, reserve in zip(approaching, reserves):
        print("train %6.1ft -> reserve %6.2f%%" % (train_weight, reserve))

