import math
from collections import deque


class Exoskeleton:
    """Lower body exoskeleton stabilizer with joint, balance and power tracking."""

    CRITICAL_BALANCE = 0.45
    STEEP_ANGLE = 18.0
    WEIGHTS = (0.5, 0.3, 0.2)

    def __init__(self, battery=100.0):
        self.left_tension = 0.5
        self.right_tension = 0.5
        self.balance = 1.0
        self.battery = float(battery)
        self.fatigue = 0.0
        self._recent = deque(maxlen=3)
        self._braces = 0

    def _normalize(self, steps):
        angles = []
        for raw in steps:
            try:
                angle = float(raw)
            except (TypeError, ValueError):
                raise ValueError("terrain angle %r is not numeric" % (raw,))
            if not math.isfinite(angle):
                raise ValueError("terrain angle must be finite")
            angles.append(max(-60.0, min(60.0, angle)))
        return angles

    def _adjust_tensions(self, angle):
        lean = angle / 60.0
        self.left_tension = min(1.0, max(0.05, 0.5 + lean * 0.45))
        self.right_tension = min(1.0, max(0.05, 0.5 - lean * 0.45))

    def _step_score(self, angle):
        skew = abs(self.left_tension - self.right_tension)
        raw = 1.0 - abs(angle) / 90.0 - skew * 0.35 - self.fatigue * 0.02
        return min(1.0, max(0.0, raw))

    def _recalc_balance(self, angle):
        self._recent.appendleft(self._step_score(angle))
        total = 0.0
        divisor = 0.0
        for weight, score in zip(self.WEIGHTS, self._recent):
            total += weight * score
            divisor += weight
        self.balance = total / divisor

    def _drain_battery(self, extra=0.0):
        load = (self.left_tension + self.right_tension) * 0.35 + 0.15 + extra
        self.battery = max(0.0, self.battery - load)

    def _accumulate_fatigue(self, angle):
        if abs(angle) >= self.STEEP_ANGLE:
            self.fatigue += (abs(angle) - self.STEEP_ANGLE) / 40.0 + 0.1

    def _brace(self):
        self._braces += 1
        self.left_tension = 1.0
        self.right_tension = 1.0
        self._drain_battery(extra=2.0)
        self.balance = min(1.0, self.balance + 0.2)

    def run(self, steps):
        history = []
        for angle in self._normalize(steps):
            self._adjust_tensions(angle)
            self._recalc_balance(angle)
            self._drain_battery()
            self._accumulate_fatigue(angle)
            if self.balance < self.CRITICAL_BALANCE:
                self._brace()
            history.append(round(self.balance, 4))
        return history

    def report(self):
        return ("battery=%.1f%% fatigue=%.2f braces=%d balance=%.3f"
                % (self.battery, self.fatigue, self._braces, self.balance))


def stabilize(steps):
    return Exoskeleton().run(steps)


def main():
    terrain = [0, 5, -12, 25, 34, -40, 8, 2, 55, -55, 0, 3]
    suit = Exoskeleton()
    for index, score in enumerate(suit.run(terrain), start=1):
        print("step %2d angle %6.1f balance %.4f" % (index, terrain[index - 1], score))
    print(suit.report())
    print("direct call:", stabilize([10, -10, 45]))


if __name__ == "__main__":
    main()

