            text = text.lower()
        return text

    def get_char_counts(self, text):
        _counts = {}
        for _char in text:
            _counts[_char] = _counts.get(_char, 0) + 1
        return _counts

    def check_lengths(self, s1_len, s2_len):
        if not (self.min_length <= s1_len <= self.max_length and 
                self.min_length <= s2_len <= self.max_length):
            raise ValueError("String length out of bounds")
        return s1_len == s2_len

    def compare_counts(self, counts1, counts2):
        return counts1 == counts2

    def are_anagrams(self, str1, str2):
        _key = (str1, str2)
        if _key in self.cache:
            return self.cache[_key]

        _norm_str1 = self.normalize_string(str1)
        _norm_str2 = self.normalize_string(str2)

        if not self.check_lengths(len(_norm_str1), len(_norm_str2)):
            self.cache[_key] = False
            return False

        _counts1 = self.get_char_counts(_norm_str1)
        _counts2 = self.get_char_counts(_norm_str2)

        _result = self.compare_counts(_counts1, _counts2)
        self.cache[_key] = _result
        return _result

def are_anagrams(str1, str2):
